INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (16,'Досточтимый директор Криллиан!\r\n\r\nНаставник, я пишу вам затем, чтобы поведать о своей нынешней жизни. Прислушавшись к вашему совету, я покинул наш любимый Штормград в поисках знаний. Во время своих странствий я побывал во многих местах, но решил остановиться в славном городке Луноречье. С приближением жатвы поля Западного Края становятся особенно красивы...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Досточтимый директор Криллиан!\r\n\r\nНаставник, я пишу вам затем, чтобы поведать о своей нынешней жизни. Прислушавшись к вашему совету, я покинул наш любимый Штормград в поисках знаний. Во время своих странствий я побывал во многих местах, но решил остановиться в славном городке Луноречье. С приближением жатвы поля Западного Края становятся особенно красивы...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (17,'Прибыв в этот городок, я уже через несколько дней стал учить местных детишек с близлежащих ферм. Уроки проходили так успешно, что местный глава города поручил мне организацию школы, и строительство здания уже началось! Я прошел от Серебряного бора до Штормграда, и вот сейчас живу в Луноречье – кто бы мог подумать, что я обойду чуть ли не пол-Азерота?\r\n\r\nС наилучшими пожеланиями,\r\n\r\nСталван Мистмантл') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прибыв в этот городок, я уже через несколько дней стал учить местных детишек с близлежащих ферм. Уроки проходили так успешно, что местный глава города поручил мне организацию школы, и строительство здания уже началось! Я прошел от Серебряного бора до Штормграда, и вот сейчас живу в Луноречье – кто бы мог подумать, что я обойду чуть ли не пол-Азерота?\r\n\r\nС наилучшими пожеланиями,\r\n\r\nСталван Мистмантл',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (18,'Досточтимый господин!\r\n\r\nДо меня дошли слухи, что вы ищете учителя для своих детей. Сейчас я остановился в Златоземье, в таверне "Гордость льва" – из-за произошедших в регионе событий мне пришлось покинуть пост директора школы в Луноречье. Я хотел бы стать учителем ваших детей. При необходимости вы можете поговорить с директором Академии Крилланом о моей компетентности.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Досточтимый господин!\r\n\r\nДо меня дошли слухи, что вы ищете учителя для своих детей. Сейчас я остановился в Златоземье, в таверне "Гордость льва" – из-за произошедших в регионе событий мне пришлось покинуть пост директора школы в Луноречье. Я хотел бы стать учителем ваших детей. При необходимости вы можете поговорить с директором Академии Крилланом о моей компетентности.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (19,'Я приеду, чтобы лично с вами встретиться, когда зимние ливни закончатся и по дорогам снова станет можно ездить.\r\n\r\nС уважением,\r\n\r\nСталван Мистмантл из Серебряного бора') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я приеду, чтобы лично с вами встретиться, когда зимние ливни закончатся и по дорогам снова станет можно ездить.\r\n\r\nС уважением,\r\n\r\nСталван Мистмантл из Серебряного бора',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (20,'...Джайлс, мальчик, показался мне непослушным, с его обучением, возможно, будут проблемы. А вот девочка постарше, Тиллоа, – исключительно сообразительный ребенок. Я также обратил внимание на ее пленительную красоту. Она уже превращается из подростка в женщину. Господин, кажется, в будущем году собирается выдать ее замуж... Но я что-то отвлекся. На этой неделе я отправлюсь со всем семейством в летний домик рядом с Лесопилкой Восточной Долины в Элвиннском лесе, это совсем недалеко от Красногорья. Рассчитываю там продолжить работу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','...Джайлс, мальчик, показался мне непослушным, с его обучением, возможно, будут проблемы. А вот девочка постарше, Тиллоа, – исключительно сообразительный ребенок. Я также обратил внимание на ее пленительную красоту. Она уже превращается из подростка в женщину. Господин, кажется, в будущем году собирается выдать ее замуж... Но я что-то отвлекся. На этой неделе я отправлюсь со всем семейством в летний домик рядом с Лесопилкой Восточной Долины в Элвиннском лесе, это совсем недалеко от Красногорья. Рассчитываю там продолжить работу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (21,'...какое странное и неконтролируемое чувство. Я никогда еще не чувствовал ничего подобного. Пока я занимался с Джайлсом историей, Тиллоа прогуливалась в палисаднике снаружи. Через несколько минут она вернулась к нам, положила мне в ладонь ярко-красную бегонию и так улыбнулась мне, что у меня чуть сердце не выскочило из груди...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','...какое странное и неконтролируемое чувство. Я никогда еще не чувствовал ничего подобного. Пока я занимался с Джайлсом историей, Тиллоа прогуливалась в палисаднике снаружи. Через несколько минут она вернулась к нам, положила мне в ладонь ярко-красную бегонию и так улыбнулась мне, что у меня чуть сердце не выскочило из груди...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (22,'...я более чем уверен, что она испытывает те же чувства, что и я. Она даже взяла меня за руку сегодня утром. Когда она смеется, ее глаза сверкают как бриллианты. Столько невысказанных слов между нами. Мое сердце стучит, как сумасшедшее, и огонь разливается по венам.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','...я более чем уверен, что она испытывает те же чувства, что и я. Она даже взяла меня за руку сегодня утром. Когда она смеется, ее глаза сверкают как бриллианты. Столько невысказанных слов между нами. Мое сердце стучит, как сумасшедшее, и огонь разливается по венам.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (29,'К ящику прилагается записка. В ней значится:\r\n\r\n"Вернер, грустно слышать, что в Красногорье нехватка ресурсов. Вот подковы, которые ты просил. Когда будет возможность, пришли мне 100 серебряных монет."\r\n\r\n"Или, если хочешь, можешь расплатиться брюшной чешуей детенышей черного дракона (слышал, что в Красногорье их полно). Так как ты мой друг... Четырех чешуек будет более чем достаточно. Благодарю. -- Аргус"') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К ящику прилагается записка. В ней значится:\r\n\r\n"Вернер, грустно слышать, что в Красногорье нехватка ресурсов. Вот подковы, которые ты просил. Когда будет возможность, пришли мне 100 серебряных монет."\r\n\r\n"Или, если хочешь, можешь расплатиться брюшной чешуей детенышей черного дракона (слышал, что в Красногорье их полно). Так как ты мой друг... Четырех чешуек будет более чем достаточно. Благодарю. -- Аргус"',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (30,'Господин мой!\r\n\r\nВойна близко. Злой рок стучит нам в двери.\r\n\r\nЯвляясь чиновником магистрата города Приозерье, считаю своим долгом сообщить вам о недавнем вооруженном столкновении в крайней восточной колонии Его Величества.\r\n\r\nНиже вы найдете рассказ об Озерном государстве, что лежит среди отрогов Красногорья.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Господин мой!\r\n\r\nВойна близко. Злой рок стучит нам в двери.\r\n\r\nЯвляясь чиновником магистрата города Приозерье, считаю своим долгом сообщить вам о недавнем вооруженном столкновении в крайней восточной колонии Его Величества.\r\n\r\nНиже вы найдете рассказ об Озерном государстве, что лежит среди отрогов Красногорья.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (31,'Потеря крепости Каменной Стражи стала для нас сильным ударом. Я уже сообщал ранее о союзе между орками Черной Горы и колдуном Моргантом. Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без черной магии Морганата. Храбрейшие из воинов его Величества отдали свои жизни при обороне крепости, но поражение было неминуемо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Потеря крепости Каменной Стражи стала для нас сильным ударом. Я уже сообщал ранее о союзе между орками Черной Горы и колдуном Моргантом. Эти орки сражаются с наводящим ужас неистовством, и, похоже, здесь не обошлось без черной магии Морганата. Храбрейшие из воинов его Величества отдали свои жизни при обороне крепости, но поражение было неминуемо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (32,'Странно, но Моргант отверг свое орочье войско сразу же после их жалкой победы. Чернокнижник возвел магическую башню на северо-востоке и использовал всю свою силу, чтобы создать небольшую армию гноллов из стаи Темношкуров, которые воплощают его злые замыслы. Орки и люди стали жертвами звероподобных монстров, служащих чернокнижнику. Что до того, почему Моргант предал Гат\'Илзогга, вождя Черной горы, – об этом остается только догадываться.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Странно, но Моргант отверг свое орочье войско сразу же после их жалкой победы. Чернокнижник возвел магическую башню на северо-востоке и использовал всю свою силу, чтобы создать небольшую армию гноллов из стаи Темношкуров, которые воплощают его злые замыслы. Орки и люди стали жертвами звероподобных монстров, служащих чернокнижнику. Что до того, почему Моргант предал Гат\'Илзогга, вождя Черной горы, – об этом остается только догадываться.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (33,'К несчастью, эти вонючие орки, кажется, всерьез принялись за истребление подданных Его Величества. Две недели назад клан Черной Горы устроил безжалостную резню в Приозерье. Много отважных воинов полегло в тот ужасный день. Орки пошли на штурм с таким напором и яростью, что мост через Озеро Безмолвия был разрушен до основания. Наши запасы истощены. Нечем даже перевязывать раненых.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К несчастью, эти вонючие орки, кажется, всерьез принялись за истребление подданных Его Величества. Две недели назад клан Черной Горы устроил безжалостную резню в Приозерье. Много отважных воинов полегло в тот ужасный день. Орки пошли на штурм с таким напором и яростью, что мост через Озеро Безмолвия был разрушен до основания. Наши запасы истощены. Нечем даже перевязывать раненых.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (34,'Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озер. Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя. Запасы еды и питья истощились. Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков! Враг должен быть изгнан за пределы королевства Штормград!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сейчас я прошу Его Величество помочь в эти трудные времена добрым гражданам Озер. Нам нужны люди для защиты нашей земли и боевые орудия взамен разрушенных на поле боя. Запасы еды и питья истощились. Умоляю, государь, окажите нам поддержку в защите последнего бастиона на пути ненавистных орков! Враг должен быть изгнан за пределы королевства Штормград!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (35,'Боюсь, за происходящим в Северных землях стоит более могущественное и ужасное зло, чем мы предполагали. Королевство Штормград обязано принять меры, иначе нас ждет погибель или, что хуже, мы станем послушными рабами нашего врага.\r\n\r\nПодпись,\r\n\r\nЧиновник Соломон\r\nПриозерье\r\nКоролевство Штормград') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Боюсь, за происходящим в Северных землях стоит более могущественное и ужасное зло, чем мы предполагали. Королевство Штормград обязано принять меры, иначе нас ждет погибель или, что хуже, мы станем послушными рабами нашего врага.\r\n\r\nПодпись,\r\n\r\nЧиновник Соломон\r\nПриозерье\r\nКоролевство Штормград',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (36,'Достопочтенный мировой судья Соломон!\r\n\r\nОплакиваю павших вместе с вами. Я лично доложу королю о случившемся и надеюсь, что смогу убедить его отправить в Приозерье подкрепление. Его Величество в последнее время совершенно удалился от дел, и его поступки, признаться, меня удивляют. Надеюсь, это останется между нами.\r\n\r\nИскренне ваш,\r\n\r\nГенерал Маркус Джонатан\r\nКоролевство Штормград') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Достопочтенный мировой судья Соломон!\r\n\r\nОплакиваю павших вместе с вами. Я лично доложу королю о случившемся и надеюсь, что смогу убедить его отправить в Приозерье подкрепление. Его Величество в последнее время совершенно удалился от дел, и его поступки, признаться, меня удивляют. Надеюсь, это останется между нами.\r\n\r\nИскренне ваш,\r\n\r\nГенерал Маркус Джонатан\r\nКоролевство Штормград',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (38,'Сильноплечий --\r\n\r\nОднако же нужно обладать немалой наглостью, чтобы посылать чужака обсуждать дела Братства Справедливости! Некогда тебе удалось спасти мне жизнь, а вот теперь ты подвергаешь ее серьезной опасности.\r\n\r\nОднако я перед тобой в долгу. Братство Справедливости сильнее, чем ты думаешь. Любой рудник от Западного Края до леса находится под их контролем. Кобольды и гноллы делают за них всю грязную работу. У них также есть созданные гоблинами металлические монстры, которые расхаживают по полям Западного Края и вселяют ужас в местных жителей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сильноплечий --\r\n\r\nОднако же нужно обладать немалой наглостью, чтобы посылать чужака обсуждать дела Братства Справедливости! Некогда тебе удалось спасти мне жизнь, а вот теперь ты подвергаешь ее серьезной опасности.\r\n\r\nОднако я перед тобой в долгу. Братство Справедливости сильнее, чем ты думаешь. Любой рудник от Западного Края до леса находится под их контролем. Кобольды и гноллы делают за них всю грязную работу. У них также есть созданные гоблинами металлические монстры, которые расхаживают по полям Западного Края и вселяют ужас в местных жителей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (39,'У них действует обширная подземная система. Больше, чем тебе кажется, Сильноплечий. От Пиратской бухты до Крепости Штормграда. Ты храбрый паладин, но глупец, если считаешь, что можешь победить их. Они занимаются разработкой оружия массового поражения. В общем, Каменщики знают только, как строить масштабные сооружения. Надеюсь, ты не подумал, что я о фермах и виноградниках? Я отплатил тебе за услугу. Теперь оставь меня!\r\n\r\n--В') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','У них действует обширная подземная система. Больше, чем тебе кажется, Сильноплечий. От Пиратской бухты до Крепости Штормграда. Ты храбрый паладин, но глупец, если считаешь, что можешь победить их. Они занимаются разработкой оружия массового поражения. В общем, Каменщики знают только, как строить масштабные сооружения. Надеюсь, ты не подумал, что я о фермах и виноградниках? Я отплатил тебе за услугу. Теперь оставь меня!\r\n\r\n--В',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (43,'Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нем своего врага мне неприятно. Понимаете, он был моим другом детства, и я лично наставлял его в магии Теней, надеясь, что однажды он будет работать вместе со мной. Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души!\r\n\r\nМастер Матиас Шоу\r\nГильдия убийц Штормграда') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Зная Эдвина ван Клифа всю свою жизнь, я могу сказать, что видеть в нем своего врага мне неприятно. Понимаете, он был моим другом детства, и я лично наставлял его в магии Теней, надеясь, что однажды он будет работать вместе со мной. Если ван Клиф стоит во главе Братства Справедливости, то да помилует Свет наши души!\r\n\r\nМастер Матиас Шоу\r\nГильдия убийц Штормграда',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (45,'Ну что ж, неплохо! Теперь отправляйся на восток по крутым берегам. Когда выйдешь на дорогу, ищи на обочине развалившуюся дымоходную трубу. Там ты найдешь старую бочку, а в ней следующую подсказку.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ну что ж, неплохо! Теперь отправляйся на восток по крутым берегам. Когда выйдешь на дорогу, ищи на обочине развалившуюся дымоходную трубу. Там ты найдешь старую бочку, а в ней следующую подсказку.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (46,'Вот от этой самой бочки иди прямехонько на север. Иди, пока не увидишь пустой кувшин рядом с заброшенной ветряной мельницей, стоящей на крутом берегу у моря. В том кувшине найдешь, что ищешь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вот от этой самой бочки иди прямехонько на север. Иди, пока не увидишь пустой кувшин рядом с заброшенной ветряной мельницей, стоящей на крутом берегу у моря. В том кувшине найдешь, что ищешь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (47,'За то, что ты нашел для меня бутылочку старого доброго виски, я скажу, где находится сокровище! Иди вдоль берега, двигаясь на запад от бутылки. Дойдешь до воды – плыви дальше на запад. Через некоторое время ты приплывешь на остров, где и найдешь мой сундук с сокровищами!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','За то, что ты нашел для меня бутылочку старого доброго виски, я скажу, где находится сокровище! Иди вдоль берега, двигаясь на запад от бутылки. Дойдешь до воды – плыви дальше на запад. Через некоторое время ты приплывешь на остров, где и найдешь мой сундук с сокровищами!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (48,'Чернокоготь--\r\n\r\nМоре ждет нас. Нам нужны ресурсы с севера. Несите все: рельсы, ведра. Нам нужен металл. Ожидается прибытие груза из ПБ, но поставка задерживается. Потрудитесь как следует, Чернокоготь! В этот раз посылайте припасы прямо в "амбар". Времени в обрез.\r\n\r\n--ван Клиф') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Чернокоготь--\r\n\r\nМоре ждет нас. Нам нужны ресурсы с севера. Несите все: рельсы, ведра. Нам нужен металл. Ожидается прибытие груза из ПБ, но поставка задерживается. Потрудитесь как следует, Чернокоготь! В этот раз посылайте припасы прямо в "амбар". Времени в обрез.\r\n\r\n--ван Клиф',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (49,'Лорд Сильноплечий --\r\n\r\nГородской совет Озер смиренно просит у вас военной помощи. В то время как я пишу эти строки, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лорд Сильноплечий --\r\n\r\nГородской совет Озер смиренно просит у вас военной помощи. В то время как я пишу эти строки, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (50,'Ваша честь--\r\n\r\nВсе жители Западного Края скорбят вместе с вами, но здесь, в Западном Крае, идет своя война. Крестьяне покидают район из-за воров и механических големов. Штормград отозвал войска, лишив нас всякой защиты. Я организовал местное ополчение на случай, если Штормград не предпримет попыток нас спасти. Направить людей в Красногорье – все равно что подписать приговор Западному Краю.\r\n\r\nСожалею,\r\nГриан Сильноплечий') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ваша честь--\r\n\r\nВсе жители Западного Края скорбят вместе с вами, но здесь, в Западном Крае, идет своя война. Крестьяне покидают район из-за воров и механических големов. Штормград отозвал войска, лишив нас всякой защиты. Я организовал местное ополчение на случай, если Штормград не предпримет попыток нас спасти. Направить людей в Красногорье – все равно что подписать приговор Западному Краю.\r\n\r\nСожалею,\r\nГриан Сильноплечий',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (51,'Лорд Элло Чернодрев--\r\n\r\nГород Приозерье смиренно просят Ночной дозор о помощи. Нас осаждают, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу Вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лорд Элло Чернодрев--\r\n\r\nГород Приозерье смиренно просят Ночной дозор о помощи. Нас осаждают, нас держат в осаде орки Черной Горы и гноллы из стаи Темношкуров, прислужнивающие Морганту. Я бы никогда не попросил о помощи, но мы в тяжелом положении. Мы ожидаем подкрепления из Штормграда, но пока оно прибудет, я прошу Вас оказать нам поддержку. Падет королевство – и все люди будут обречены.\r\n\r\nМировой судья Соломон',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (52,'Ваша честь--\r\n\r\nС сожалением сообщаю, что в настоящее время Ночной Дозор не может покинуть свой пост в Темнолесье. Возможно, вы еще не знаете, но Штормград больше не оказывает военной поддержки нашему региону. Ночной Дозор был создан и подготовлен для защиты Темнолесья в отсутствие поддержки Штормграда. Без защиты Дозора город будет уничтожен. Желаю удачи.\r\n\r\n--Лорд Элло Чернодрев') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ваша честь--\r\n\r\nС сожалением сообщаю, что в настоящее время Ночной Дозор не может покинуть свой пост в Темнолесье. Возможно, вы еще не знаете, но Штормград больше не оказывает военной поддержки нашему региону. Ночной Дозор был создан и подготовлен для защиты Темнолесья в отсутствие поддержки Штормграда. Без защиты Дозора город будет уничтожен. Желаю удачи.\r\n\r\n--Лорд Элло Чернодрев',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (53,'Буквы вспыхивают на записке и исчезают. Уловить их смысл невозможно...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Буквы вспыхивают на записке и исчезают. Уловить их смысл невозможно...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (58,'Луна над долиной взошла,\r\nОсвещая ночные джунгли,\r\nГде воины сошлись на зов\r\nЗащищать свой народ и святыни. \r\n\r\nЛуна над долиной взошла,\r\nРаздаются крики битвы,\r\nИ кровь ручьями струится,\r\nПогибают враги и побратимы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Луна над долиной взошла,\r\nОсвещая ночные джунгли,\r\nГде воины сошлись на зов\r\nЗащищать свой народ и святыни. \r\n\r\nЛуна над долиной взошла,\r\nРаздаются крики битвы,\r\nИ кровь ручьями струится,\r\nПогибают враги и побратимы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (59,'Когда наши побратимы уходят\r\nВ мир иной, потусторонний,\r\nДуша застывает\r\nВ глубине подземелий долины.\r\n\r\nКогда наши побратимы уходят\r\nВ Храм Горы,\r\nМы на защиту встаем их духу,\r\nСокрытому в святом синем кристалле.\r\n\r\nКогда наши побратимы уходят,\r\nВосходит Луна над долиной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда наши побратимы уходят\r\nВ мир иной, потусторонний,\r\nДуша застывает\r\nВ глубине подземелий долины.\r\n\r\nКогда наши побратимы уходят\r\nВ Храм Горы,\r\nМы на защиту встаем их духу,\r\nСокрытому в святом синем кристалле.\r\n\r\nКогда наши побратимы уходят,\r\nВосходит Луна над долиной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (62,'Заклятый солнцем и луной,\r\nОставь сей камень роковой,\r\nНетленны рока письмена:\r\nВ гробнице Смерть заточена,\r\nХранит недрогнувшей рукой\r\nОна властителя покой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Заклятый солнцем и луной,\r\nОставь сей камень роковой,\r\nНетленны рока письмена:\r\nВ гробнице Смерть заточена,\r\nХранит недрогнувшей рукой\r\nОна властителя покой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (63,'Мастер Карвин!\r\n\r\n $gПринесший:Принесшая; это сообщение $gосенен:осенена; благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Карвин на их пути к Свету.\r\n\r\nВ моем послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света.\r\n\r\nС уважением,\r\nКалор') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мастер Карвин!\r\n\r\n $gПринесший:Принесшая; это сообщение $gосенен:осенена; благословением Света, может сражаться с мертвецами и демонами, наводнившими пределы Сумеречного леса, и желает присоединиться к семье Карвин на их пути к Свету.\r\n\r\nВ моем послании я прошу вас предоставить этому воину Света задание – возможно, это будет поиск горожан, замеченных в помощи врагам Света.\r\n\r\nС уважением,\r\nКалор',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (73,'Ужас этих последних недель становится невыносимым; и все же, написав увиденное мною, я чувствую себя немного лучше. И я буду продолжать свое занятие, так как это единственное мое успокоение в эти страшные дни.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ужас этих последних недель становится невыносимым; и все же, написав увиденное мною, я чувствую себя немного лучше. И я буду продолжать свое занятие, так как это единственное мое успокоение в эти страшные дни.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (78,'Этот знак брони можно обменять на изделие из кожи или ткани у Тимберлейнов на Лесопилке Восточной долины.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот знак брони можно обменять на изделие из кожи или ткани у Тимберлейнов на Лесопилке Восточной долины.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (80,'Грелин, у меня мало времени и много забот; надеюсь, ваш интерес к троллям не сильно отвлечет меня от моих дел. Тем не менее я разрешаю вам ссылаться на меня при необходимости, если вы, разумеется, не станете выходить за рамки целесообразности.\r\n\r\nМагни Бронзобород') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Грелин, у меня мало времени и много забот; надеюсь, ваш интерес к троллям не сильно отвлечет меня от моих дел. Тем не менее я разрешаю вам ссылаться на меня при необходимости, если вы, разумеется, не станете выходить за рамки целесообразности.\r\n\r\nМагни Бронзобород',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (84,'но вооружение у них никудышное и нет дисциплины. Небольшое проявление силы – вот и все, что нужно для устранения "угрозы".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','но вооружение у них никудышное и нет дисциплины. Небольшое проявление силы – вот и все, что нужно для устранения "угрозы".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (85,'Мой дневник\r\n\r\nУжасы последних недель почти лишают меня разума; единственное, что меня спасает, – записи в дневнике. Я как будто исповедуюсь в своих грехах перед безмолвным собеседником или как будто освобождаю свою голову от мрачных мыслей, перенося их на бумагу. \r\n\r\nЭто второй мой дневник, первый остался в месте, куда я не могу вернуться. Поэтому я начал все с нуля. Но в этот раз я буду писать только правду.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мой дневник\r\n\r\nУжасы последних недель почти лишают меня разума; единственное, что меня спасает, – записи в дневнике. Я как будто исповедуюсь в своих грехах перед безмолвным собеседником или как будто освобождаю свою голову от мрачных мыслей, перенося их на бумагу. \r\n\r\nЭто второй мой дневник, первый остался в месте, куда я не могу вернуться. Поэтому я начал все с нуля. Но в этот раз я буду писать только правду.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (86,'Отчет о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины.\r\n\r\nПодготовлен Грелином Белобородом, особым посланником Сената\r\n\r\nЯ потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Отчет о положении дел с троллями из племени Мерзлогривов в регионе Холодной долины.\r\n\r\nПодготовлен Грелином Белобородом, особым посланником Сената\r\n\r\nЯ потратил немало времени, наблюдая за деятельностью племени Мерзлогривов в Холодной долине, и полагаю, что они не представляют особой угрозы дворфским поселениям в этом районе. Более того, эту угрозу можно уничтожить даже без особой поддержки со стороны армии. Учитывая помощь горных пехотинцев, уже находящихся в',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (87,'Холодной долине и наемников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время. \r\n\r\nВся кампания официально одобрена королем Бронзобородом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Холодной долине и наемников (нанятых на деньги, выделенные мне старейшиной Сената), я уверен, что проблема будет решена в ближайшее время. \r\n\r\nВся кампания официально одобрена королем Бронзобородом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (92,'Дорогой Таррел! -\r\n\r\nПрости за поспешность, с которой написано это послание, однако сейчас время для нас роскошь.\r\n\r\nРаскопщики достигли неплохих результатов в поиске артефактов титанов. Но мы обнаружили также другие древние предметы – в частности, огромные кости.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой Таррел! -\r\n\r\nПрости за поспешность, с которой написано это послание, однако сейчас время для нас роскошь.\r\n\r\nРаскопщики достигли неплохих результатов в поиске артефактов титанов. Но мы обнаружили также другие древние предметы – в частности, огромные кости.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (93,'Спустя некоторое время после этой находки мы подверглись нападению ящеров. Батальон Длинной Косы сражался мужественно. Но силы были не равны. Почти все погибли. Спаслись только трое. Рабочий Ормер Сталеплет был самым отважным бойцом, он спас меня и геолога Велгара.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Спустя некоторое время после этой находки мы подверглись нападению ящеров. Батальон Длинной Косы сражался мужественно. Но силы были не равны. Почти все погибли. Спаслись только трое. Рабочий Ормер Сталеплет был самым отважным бойцом, он спас меня и геолога Велгара.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (94,'Мы спрятались в укромной пещере; похоже, это достаточно безопасное место. Но мы все равно находимся в ловушке до тех пор, пока не прибудет подкрепление. Вельгар пытается продолжать работу, но, похоже, он все еще слишком напуган. Мы находимся в тяжелом положении, Таррел. Пожалуйста, поторопи Длинную Косу со сбором дополнительных сил.\r\n\r\nЯ все также сильно тебя люблю, даже в эти ужасные времена.\r\n\r\n--Меррин') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы спрятались в укромной пещере; похоже, это достаточно безопасное место. Но мы все равно находимся в ловушке до тех пор, пока не прибудет подкрепление. Вельгар пытается продолжать работу, но, похоже, он все еще слишком напуган. Мы находимся в тяжелом положении, Таррел. Пожалуйста, поторопи Длинную Косу со сбором дополнительных сил.\r\n\r\nЯ все также сильно тебя люблю, даже в эти ужасные времена.\r\n\r\n--Меррин',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (100,'Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (102,'После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но  вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но  вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (104,'Первое убийство взбодрило нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Первое убийство взбодрило нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (105,'На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (108,'В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (110,'Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (112,'Ружье резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздернувшееся к кронам деревьев ружье отчетливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ружье резко подалось назад в его руках. Дуло ушло в сторону и попало под ствол ружья Ажек. И именно в этот момент Ажек спустила курок. Неуклюже вздернувшееся к кронам деревьев ружье отчетливо и громко выстрелило. Стая птиц, крича, вспорхнула в небо, разлетаясь во все стороны. Струйка дыма вилась из дерева. Мы в оцепенении смотрели, как гигантская ветка рухнула прямо на убегающую пантеру и сломала ей хребет.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (114,'С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С первыми лучами солнца мы отправились на охоту на юг, за руины Ткаши. Барнил беспокоился, что мы можем наткнуться на троллей племени Кровавого Скальпа. Мои слова о том, что это племя сейчас занято войной со своими заклятыми врагами из племени Дробителей Черепов, конечно же, ничуть не успокоили его. Меня же возможность засады беспокоила гораздо меньше: в моих руках была заряженная винтовка, на поясе – полная сумка пороха, а рядом – трое отличных охотников.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (115,'Я помню битву с армией Пылающего Легиона: враги надвигалась со всех направлений, а прямо передо мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога.\r\n\r\nК величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул\'Кунды. Взобравшись на высокий утес над морем, мы увидели нашего первого ящера.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я помню битву с армией Пылающего Легиона: враги надвигалась со всех направлений, а прямо передо мной возвышался огромный инфернал. Толпа злобных троллей по сравнению с этим кажется безобидной, как заяц в горах Дун Морога.\r\n\r\nК величайшей радости Барнила, мы миновали руины Ткаши без всяких приключений. Мы продолжали двигаться на запад к Великому морю, обходя руины Зул\'Кунды. Взобравшись на высокий утес над морем, мы увидели нашего первого ящера.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (118,'Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов.\r\n\r\nОхотники превратились в добычу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наших суматошных выстрелов оказалось достаточно, чтобы дать Барнилу время убежать. Барнил скатился с холма и присоединился к нашей группе. Мы побежали в джунгли, преследуемые стаей свирепых ящеров-кнутохвостов.\r\n\r\nОхотники превратились в добычу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (119,'Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (120,'Я медленно шагнул вперед, держа ружье наготове. Я привел этих отважных охотников к гибели. И готов был погибнуть сам, защищая их. Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови. Их было намного больше нас. Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я медленно шагнул вперед, держа ружье наготове. Я привел этих отважных охотников к гибели. И готов был погибнуть сам, защищая их. Ящеры-кнутохвосты известны своей свирепостью и неумолимой жаждой крови. Их было намного больше нас. Но я бы себе не простил, если бы позволил расправиться с собой и моими товарищами, не прикончив сначала несколько этих тварей!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (121,'Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (157,'Мы проснулись чуть свет. Барнил занялся приготовлением завтрака. Мне показалось, что мысли Ажек в этот момент были где-то далеко. Впереди нас ждал долгий день и немало опасностей. Нужна была полная сосредоточенность, иначе последствия могли быть печальными. Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьем столовых принадлежностей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы проснулись чуть свет. Барнил занялся приготовлением завтрака. Мне показалось, что мысли Ажек в этот момент были где-то далеко. Впереди нас ждал долгий день и немало опасностей. Нужна была полная сосредоточенность, иначе последствия могли быть печальными. Но Ажек была не в состоянии отвести взгляд от Барнила, занятого мытьем столовых принадлежностей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (158,'Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда я уже собирался спросить, почему Ажек не участвует в обсуждении плана сегодняшней охоты, она выхватила стрелу из колчана, натянула тетиву и выстрелила в бедного Барнила. Однако стрела пролетела мимо. Разинув рот, Барнил наблюдал за тем, как возле него на поверхность реки всплыл огромный кроколиск, а между глаз у него торчала стрела Ажек.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (159,'Мы отправились на запад через дикие непроходимые джунгли. В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность. К нашему сожалению, утром все было тихо. Даже ветер не шумел в кронах деревьев. К полудню мы начали волноваться. Шаги Барнила уже не были столь осторожными и тихими, как раньше. Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы отправились на запад через дикие непроходимые джунгли. В поисках добычи мы медленно, но верно прокладывали себе путь сквозь густую растительность. К нашему сожалению, утром все было тихо. Даже ветер не шумел в кронах деревьев. К полудню мы начали волноваться. Шаги Барнила уже не были столь осторожными и тихими, как раньше. Теперь он неуклюже переваливался с ноги на ногу, с треском ломая упавшие на землю сухие ветки.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (160,'После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После очередного неверного шага Барнила Эрлгедин положил свою тяжелую руку ему на плечо. Мы с Ажек переглянулись, уверенные, что он решил-таки напомнить Барнилу о необходимости соблюдать осторожность. Но вместо этого Эрлгедин кивнул головой в сторону лежащего неподалеку дерева. Оттуда на нас пристально смотрели два черных глаза, а под ними была пасть, полная острых зубов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (161,'Этим чудищем был самец тигра Тернистой долины. Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя. Стрела ушла немного в сторону и вонзилась в левый бок тигра. Зверь попытался убежать, но его рана была слишком глубокой. Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этим чудищем был самец тигра Тернистой долины. Прежде чем мне удалось взвести винтовку, Эрлгедин поднял свой арбалет и выстрелил в зверя. Стрела ушла немного в сторону и вонзилась в левый бок тигра. Зверь попытался убежать, но его рана была слишком глубокой. Он сумел сделать лишь несколько шагов, а затем его настиг метательный топор Барнила.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (162,'Первый успех взбодрил нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Первый успех взбодрил нашу команду. Барнил налил всем меда, чтобы отметить его. Но нашему празднованию не суждено было продолжаться долго. Когда мы подготавливали тушу к транспортировке в лагерь, внезапно раздался ужасный рев. Я в жизни не слышал такого леденящего кровь звука.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (163,'На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На скалистом склоне, возвышавшемся над нами, в лучах заходящего солнца вырисовывался силуэт самой большой кошки, которую я когда-либо видел. Мне удалось сделать неловкий выстрел из ружья, но кошка не двинулась с места. Она издала еще один ужасный рык, громче прошлого, и исчезла.\r\n\r\nМы собрали вещи и мрачно двинулись в лагерь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (164,'Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту. Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех еще больше возрос в цене.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я обещал своим товарищам, что на следующий день мы отправимся охотиться на пантер, так как их мех очень высоко ценится по всему Азероту. Учитывая, что большинство охотников и торговцев мехом сейчас храбро отдавали свои жизни, сражаясь за Альянс, этот мех еще больше возрос в цене.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (165,'Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок. Я велел им оставить свое примитивное оружие в лагере. Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек и сэр Эрлгедин страстно желали научиться стрелять из дворфийских винтовок. Я велел им оставить свое примитивное оружие в лагере. Мы с Барнилом снарядили их лучшими образцами стальгорнских ружей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (166,'В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В тот день мы пошли на юг, двигаясь по свежим следам пантеры. Вскоре мы пришли к ущелью, через которое был перекинут длинный веревочный мостик. При виде этого чуда инженерной мысли мне сразу вспомнилось, как описывал этот район Бранн. Тролли, коренные жители этих мест, всегда считались примитивной расой, но мастерство, с которым они сконструировали этот мост через непреодолимую пропасть, было неоспоримо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (167,'Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад. Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех. Треск веток, донесшийся из рощи неподалеку, немедленно привлек наше внимание. Там кто-то был. Одного взгляда на Барнила хватило, чтобы он понял меня. Он медленно опустил винтовку. Эта добыча – не для нас, а для наших спутников-людей. Сколько пантер уже погибло от наших пуль! Нет, эта добыча – не для нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек не понадобилось много времени, чтобы выследить пантеру; она ушла на юго-запад. Мы шли быстрым шагом, с оружием наготове, и уже предвкушали успех. Треск веток, донесшийся из рощи неподалеку, немедленно привлек наше внимание. Там кто-то был. Одного взгляда на Барнила хватило, чтобы он понял меня. Он медленно опустил винтовку. Эта добыча – не для нас, а для наших спутников-людей. Сколько пантер уже погибло от наших пуль! Нет, эта добыча – не для нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (168,'Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек и сэр Эрлгедин стояли наготове, направив ружья в сторону колючего кустарника у подножия раскачивающихся деревьев. Полуденное солнце нещадно палило. Капля пота медленно скатилась по виску Эрлгедина, когда он взводил курок. В момент щелчка из кустов на поляну выпрыгнула огромная черная пантера – невероятно грациозное животное.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (177,'Я повел группу по направлению к морю, надеясь, что линия берега послужит нам защитой от ящеров. В спешке мы забрались слишком далеко к северу, на особенно высокий холм. Это было ошибкой. Я был виноват. Мы остановились прямо перед обрывом, заканчивающимся отвесной скалой, а ящеры были всего в нескольких шагах позади нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я повел группу по направлению к морю, надеясь, что линия берега послужит нам защитой от ящеров. В спешке мы забрались слишком далеко к северу, на особенно высокий холм. Это было ошибкой. Я был виноват. Мы остановились прямо перед обрывом, заканчивающимся отвесной скалой, а ящеры были всего в нескольких шагах позади нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (178,'Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я вел отряд по направлению к морю в надежде, что вода остановит ящеров. Но в спешке мы зашли слишком далеко на север, на возвышенность. Исправлять ошибку было уже поздно. И вина была в этом моя. Мы остановились на краю отвесной скалы, а ящеры были уже в нескольких шагах от нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (179,'Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ажек и сэр Эрлгедин вскинули свое оружие, прикрывая меня с боков, спиной к морю. Барнил обреченно вздохнул и обнажил свой топор. Кнутохвосты были практически рядом с нами. Их уверенные шаги замедлились. Они крадучись подбирались к своим жертвам, зная, что загнали нас в ловушку.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (180,'И тогда случилось чудо. Прямо рядом с нами раздался резкий, ужасающий рев огромного белого тигра. Несмотря на количество, ящеры развернулись и бросились врассыпную. Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров. Нам не требовалось команды. Все четыре члена нашего отряда знали, что пришло время бежать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И тогда случилось чудо. Прямо рядом с нами раздался резкий, ужасающий рев огромного белого тигра. Несмотря на количество, ящеры развернулись и бросились врассыпную. Мы увидели лишь белый сполох, когда тигр минул нас и помчался за одним из ящеров. Нам не требовалось команды. Все четыре члена нашего отряда знали, что пришло время бежать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (181,'Мы без остановки мчались назад, к нашему лагерю. Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы. Этому риску подвергается любой участник большой охоты. Мы – игрушки в руках судьбы. Когда-нибудь каждый из нас встретится с хищным оскалом смерти. И ваш покорный слуга рад, что эта встреча не произошла на зеленых холмах Тернистой долины.\r\n\r\n--Конец--') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы без остановки мчались назад, к нашему лагерю. Позже той ночью мы тихо сидели у костра, зная, что наши жизни были спасены по странной прихоти судьбы. Этому риску подвергается любой участник большой охоты. Мы – игрушки в руках судьбы. Когда-нибудь каждый из нас встретится с хищным оскалом смерти. И ваш покорный слуга рад, что эта встреча не произошла на зеленых холмах Тернистой долины.\r\n\r\n--Конец--',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (182,'Достопочтенные коллеги и искатели правды.\r\n\r\nРаскопки продолжаются, но они были приостановлены из-за троггов, о которых я сообщал в моем последнем докладе. Я уверен, их проблему можно решить даже несмотря на то, что некоторые трогги гораздо более агрессивны, чем обычно.\r\n\r\nМы нашли еще больше артефактов, хотя во всех случаях, кроме одного (о котором я напишу ниже), эти находки были такие же, как и раньше, – интересные, если не сказать более.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Достопочтенные коллеги и искатели правды.\r\n\r\nРаскопки продолжаются, но они были приостановлены из-за троггов, о которых я сообщал в моем последнем докладе. Я уверен, их проблему можно решить даже несмотря на то, что некоторые трогги гораздо более агрессивны, чем обычно.\r\n\r\nМы нашли еще больше артефактов, хотя во всех случаях, кроме одного (о котором я напишу ниже), эти находки были такие же, как и раньше, – интересные, если не сказать более.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (183,'За одним лишь исключением. Странно высеченные идолы, что мы обнаружили недавно (краткое их описание прилагалось к моему последнему докладу), похоже, возымели побочный эффект на троггов на месте раскопок. Их притягивают эти высеченные фигуры, и некоторые трогги впадают из-за них в ярость!\r\n\r\nНеобходимо изучить этих идолов внимательнее, чтобы сделать по поводу них какие либо выводы, но я все еще надеюсь, что они прольют свет на связь между троггами и титанами.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','За одним лишь исключением. Странно высеченные идолы, что мы обнаружили недавно (краткое их описание прилагалось к моему последнему докладу), похоже, возымели побочный эффект на троггов на месте раскопок. Их притягивают эти высеченные фигуры, и некоторые трогги впадают из-за них в ярость!\r\n\r\nНеобходимо изучить этих идолов внимательнее, чтобы сделать по поводу них какие либо выводы, но я все еще надеюсь, что они прольют свет на связь между троггами и титанами.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (184,'И в заключение я должен вновь напомнить о моей просьбе доставить взрывчатого порошка. Мои запасы подходят к концу, что серьезно препятствует успеху экспедиции. Мне обещали, что взрывчатый порошок вскоре будет доставлен, но я до сих пор его не получил.\r\n\r\nКакова причина, позвольте спросить, этой задержки?\r\n\r\nС уважением,\r\nгеолог Дартеус Железняк') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И в заключение я должен вновь напомнить о моей просьбе доставить взрывчатого порошка. Мои запасы подходят к концу, что серьезно препятствует успеху экспедиции. Мне обещали, что взрывчатый порошок вскоре будет доставлен, но я до сих пор его не получил.\r\n\r\nКакова причина, позвольте спросить, этой задержки?\r\n\r\nС уважением,\r\nгеолог Дартеус Железняк',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (185,'Все началось с находки этой проклятой косы в Погибели Роланда. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Все началось с находки этой проклятой косы в Погибели Роланда. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (186,'Все началось с находки этой проклятой косы в шахте, которую называют Погибелью Роланда. Да, тогда все и началось. Прежде чем это случилось, Братство Справедливости радовалось нашим успехам в Сумеречном лесу. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Все началось с находки этой проклятой косы в шахте, которую называют Погибелью Роланда. Да, тогда все и началось. Прежде чем это случилось, Братство Справедливости радовалось нашим успехам в Сумеречном лесу. До того, как я нашел косу, местные страхи казались мне такими же смешными, как страхи жителей Долины Североземья.\r\n\r\nНо с тех пор как я увидел рукоять косы, выглядывающую из-под груды щебня в шахте, и, будь я проклят, вытащил ее, Погибель Роланда превратилась в место ужасной смерти!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (187,'Если бы я знал, что произойдет, я бы отрезал свою собственную руку, лишь бы не вытаскивать этот кусок дерева, покрытый рунами. Как сильно я жалею об этом! Я всегда думал, что сожаления – привилегия старости. Теперь я знаю, что не старость, а отчаяние надевает на нас мантию из сожалений, не способную и не желающую спадать с плеч, сгорбленных страданием.\r\n\r\nНо достаточно стенать, как какой-нибудь недоделанный поэт. Я должен продолжать свои хроники...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Если бы я знал, что произойдет, я бы отрезал свою собственную руку, лишь бы не вытаскивать этот кусок дерева, покрытый рунами. Как сильно я жалею об этом! Я всегда думал, что сожаления – привилегия старости. Теперь я знаю, что не старость, а отчаяние надевает на нас мантию из сожалений, не способную и не желающую спадать с плеч, сгорбленных страданием.\r\n\r\nНо достаточно стенать, как какой-нибудь недоделанный поэт. Я должен продолжать свои хроники...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (188,'После того как я вытащил косу, волна изменений прокатилась по шахте. Свет от наших мерцающих факелов заметался, и казалось, что мы больше не контролируем силу нашего голоса. То шепот звучал, как рев, мечущийся по туннелям, заставляя зажимать уши руками, то наши крики на расстоянии нескольких шагов переставали быть слышны и становились подобны легкому дуновению ветра.\r\n\r\nЭто нервировало, да, но недолго мы пытались понять странную природу этих явлений. Это стало лишь предвестником того, что в действительности изгнало нас из шахты. Воргены.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После того как я вытащил косу, волна изменений прокатилась по шахте. Свет от наших мерцающих факелов заметался, и казалось, что мы больше не контролируем силу нашего голоса. То шепот звучал, как рев, мечущийся по туннелям, заставляя зажимать уши руками, то наши крики на расстоянии нескольких шагов переставали быть слышны и становились подобны легкому дуновению ветра.\r\n\r\nЭто нервировало, да, но недолго мы пытались понять странную природу этих явлений. Это стало лишь предвестником того, что в действительности изгнало нас из шахты. Воргены.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (189,'Они нападали на нас отовсюду, выползая из укромных щелей под ногами и падая на нас откуда-то с потолка. Половина моих товарищей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.\r\n\r\nВсе, что я знаю, – это то, что я – единственный, кто смог спастись из этого места.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Они нападали на нас отовсюду, выползая из укромных щелей под ногами и падая на нас откуда-то с потолка. Половина моих товарищей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.\r\n\r\nВсе, что я знаю, – это то, что я – единственный, кто смог спастись из этого места.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (190,'Я могу лишь гадать, как я смог выжить в ту ночь. Я всегда был осторожен, всегда быстро уворачивался от ударов и не раздумывая спрыгивал с обрывов. Мое прозвище, Трясунчик, досталось мне из-за этой моей черты. Так что, возможно, лишь эта способность всегда быть настороже спасла меня...\r\n\r\nИли, возможно, коса, что я вытянул из-под груды щебня. Это не могла быть сама коса, ее я потерял во время моего безумного бегства. Но если это я привел воргенов в Сумеречный лес, то, возможно, воргены отплатили мне неслыханной любезностью. Да будут они прокляты.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я могу лишь гадать, как я смог выжить в ту ночь. Я всегда был осторожен, всегда быстро уворачивался от ударов и не раздумывая спрыгивал с обрывов. Мое прозвище, Трясунчик, досталось мне из-за этой моей черты. Так что, возможно, лишь эта способность всегда быть настороже спасла меня...\r\n\r\nИли, возможно, коса, что я вытянул из-под груды щебня. Это не могла быть сама коса, ее я потерял во время моего безумного бегства. Но если это я привел воргенов в Сумеречный лес, то, возможно, воргены отплатили мне неслыханной любезностью. Да будут они прокляты.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (191,'Или, возможно, я был обречен стать свидетелем тех перемен, что навлек я на Сумеречный лес. Возможно, мой жребий – наблюдать, как воргены врываются на эту землю, окрашивая ее в еще более темный цвет своей злобой.\r\n\r\nЕсли это и правда мой жребий, то он выпал мне дважды. Поскольку воргены – не единственная сила, что пыталась ворваться в Сумеречный лес: монстры со стороны Мертвого Ветра также пытались вторгнуться в него.\r\n\r\nЭто будет в следующей главе моей истории, и я молюсь, чтобы она была последней...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Или, возможно, я был обречен стать свидетелем тех перемен, что навлек я на Сумеречный лес. Возможно, мой жребий – наблюдать, как воргены врываются на эту землю, окрашивая ее в еще более темный цвет своей злобой.\r\n\r\nЕсли это и правда мой жребий, то он выпал мне дважды. Поскольку воргены – не единственная сила, что пыталась ворваться в Сумеречный лес: монстры со стороны Мертвого Ветра также пытались вторгнуться в него.\r\n\r\nЭто будет в следующей главе моей истории, и я молюсь, чтобы она была последней...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (192,'После того как я выжил при побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\nТак что я оставался в укрытии. И это спасло мне жизнь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После того как я выжил при побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\nТак что я оставался в укрытии. И это спасло мне жизнь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (193,'Спустя несколько дней после того, как я начал прятаться в сарае, Свен отправился со своей фермы в Темнолесье. Он поцеловал жену и улыбнулся детям, и обещал вскоре вернуться с игрушками и сладостями. Несчастный человек. То был последний раз, когда он видел свою семью живой.\r\n\r\nПо крайней мере, они расстались счастливыми. И по крайней мере, его жена умерла первой, и ей не пришлось смотреть, как убивали ее детей. Но этот малый жест благоволения судьбы мне ничем не помог. Я видел все, что случилось, и это преследует меня в моих кошмарах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Спустя несколько дней после того, как я начал прятаться в сарае, Свен отправился со своей фермы в Темнолесье. Он поцеловал жену и улыбнулся детям, и обещал вскоре вернуться с игрушками и сладостями. Несчастный человек. То был последний раз, когда он видел свою семью живой.\r\n\r\nПо крайней мере, они расстались счастливыми. И по крайней мере, его жена умерла первой, и ей не пришлось смотреть, как убивали ее детей. Но этот малый жест благоволения судьбы мне ничем не помог. Я видел все, что случилось, и это преследует меня в моих кошмарах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (194,'Мои руки дрожат, когда я вспоминаю о подробностях той ночи, когда Свен ушел и его семья была обречена встретиться с черными всадниками один на один. Вновь сожаления гложут меня, ибо я был там и мог восстать против монстров из Мертвого Ветра. Но это никчемные сожаления. Подобные сомнения терзают любого, выжившего после трагедии. Я знаю, что если бы я покинул мое убежище, я тоже был бы убит, мое тело было бы разорвано и раскромсано, а его части разбросаны так далеко, что никто не смог бы меня опознать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мои руки дрожат, когда я вспоминаю о подробностях той ночи, когда Свен ушел и его семья была обречена встретиться с черными всадниками один на один. Вновь сожаления гложут меня, ибо я был там и мог восстать против монстров из Мертвого Ветра. Но это никчемные сожаления. Подобные сомнения терзают любого, выжившего после трагедии. Я знаю, что если бы я покинул мое убежище, я тоже был бы убит, мое тело было бы разорвано и раскромсано, а его части разбросаны так далеко, что никто не смог бы меня опознать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (195,'Но несмотря на то что я был бессилен и не мог остановить это ужасное убийство, одно истинное сожаление все же остается: ведь это я привел черных всадников к ферме Свена. Моя находка не только высвободила воргенов по всему Сумеречному лесу – она привлекла всадников из Мертвого Ветра.\r\n\r\nЯ знаю это, потому что прежде чем они начали убивать, они задали жене Свена один вопрос в тот момент, когда она прижимала к себе своих детей, пытаясь успокоить их и ободрить, зная, что вскоре их ожидает смерть.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но несмотря на то что я был бессилен и не мог остановить это ужасное убийство, одно истинное сожаление все же остается: ведь это я привел черных всадников к ферме Свена. Моя находка не только высвободила воргенов по всему Сумеречному лесу – она привлекла всадников из Мертвого Ветра.\r\n\r\nЯ знаю это, потому что прежде чем они начали убивать, они задали жене Свена один вопрос в тот момент, когда она прижимала к себе своих детей, пытаясь успокоить их и ободрить, зная, что вскоре их ожидает смерть.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (196,'"Коса Элуны," – проскрежетал один из всадников голосом одновременно грубым и пронзительным, как звук точильного камня по лезвию секиры. И последнее слово – Элуны – он прокаркал, как будто заглушая звук.\r\n\r\nУжас сковал меня, когда я услышал этот голос, и от страшного его звука, и потому что... я знал, о какой косе говорил всадник. Должно быть, это была та самая проклятая вещь, что я вытащил из-под камней в Погибели Роланда несколькими днями раньше. Вот что искали черные всадники!\r\n\r\nИ вот что убило семью Свена.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Коса Элуны," – проскрежетал один из всадников голосом одновременно грубым и пронзительным, как звук точильного камня по лезвию секиры. И последнее слово – Элуны – он прокаркал, как будто заглушая звук.\r\n\r\nУжас сковал меня, когда я услышал этот голос, и от страшного его звука, и потому что... я знал, о какой косе говорил всадник. Должно быть, это была та самая проклятая вещь, что я вытащил из-под камней в Погибели Роланда несколькими днями раньше. Вот что искали черные всадники!\r\n\r\nИ вот что убило семью Свена.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (197,'Я никогда не знал, как зовут жену Свена, поскольку ее всегда звали "дорогая", "любовь моя" или "мамочка". Но я хотел бы знать. Я – единственный, кто знает о ее подвиге в тот день, и несмотря на то, что она лишь простая жена фермера, никогда не видел я женщину или мужчину, действующих столь храбро.\r\n\r\nКонечно же, она не знала ничего о косе, но она поняла, что всадники ищут ее, и мгновенный план сформировался в ее голове.\r\n\r\nОн был прост и ясен. Если бы он только сработал.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я никогда не знал, как зовут жену Свена, поскольку ее всегда звали "дорогая", "любовь моя" или "мамочка". Но я хотел бы знать. Я – единственный, кто знает о ее подвиге в тот день, и несмотря на то, что она лишь простая жена фермера, никогда не видел я женщину или мужчину, действующих столь храбро.\r\n\r\nКонечно же, она не знала ничего о косе, но она поняла, что всадники ищут ее, и мгновенный план сформировался в ее голове.\r\n\r\nОн был прост и ясен. Если бы он только сработал.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (198,'"Коса?" – спросила она спокойным голосом."Конечно, знаю. А кто о ней здесь не знает?" Она посмотрела на всадников твердым взглядом, и я бы поклялся, что она говорит правду, если бы не знал, что это не так. Она не могла знать ничего о косе.\r\n\r\nЕе уловка сработала. Тот же всадник, что задал вопрос, нагнулся к ней и проскрежетал: "Где?"\r\n\r\n"Я отведу вас. Всех вас," – сказала она, и я увидел проблеск надежды в ее глазах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Коса?" – спросила она спокойным голосом."Конечно, знаю. А кто о ней здесь не знает?" Она посмотрела на всадников твердым взглядом, и я бы поклялся, что она говорит правду, если бы не знал, что это не так. Она не могла знать ничего о косе.\r\n\r\nЕе уловка сработала. Тот же всадник, что задал вопрос, нагнулся к ней и проскрежетал: "Где?"\r\n\r\n"Я отведу вас. Всех вас," – сказала она, и я увидел проблеск надежды в ее глазах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (199,'"Но это далеко отсюда, а у меня на руках дети. Мы должны оставить их здесь."\'\r\n\r\nЕе уловка была проста, но лишь простая уловка могла увенчаться успехом. Если бы она сработала, она бы увела всадников далеко от фермы. Она была бы убита, но ее дети были бы спасены. Это было бы так, если бы всадники поверили ее благородной лжи.\r\n\r\nНесмотря на то что я никогда не был последователем Света, я яростно молился за жену Свена, когда она стояла перед ужасными всадниками.\r\n\r\n"Пожалуйста, – молился я. – Пусть они поверят".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Но это далеко отсюда, а у меня на руках дети. Мы должны оставить их здесь."\'\r\n\r\nЕе уловка была проста, но лишь простая уловка могла увенчаться успехом. Если бы она сработала, она бы увела всадников далеко от фермы. Она была бы убита, но ее дети были бы спасены. Это было бы так, если бы всадники поверили ее благородной лжи.\r\n\r\nНесмотря на то что я никогда не был последователем Света, я яростно молился за жену Свена, когда она стояла перед ужасными всадниками.\r\n\r\n"Пожалуйста, – молился я. – Пусть они поверят".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (200,'Они стояли, замерев, а она спокойно смотрела им в глаза. И тогда один из всадников посмотрел вверх, как будто услышал далекий зов. Он вытащил из-под одежды небольшой камень и заглянул в него. Затем он жестом указал на него жене Свена. Свет полился из всадника в сторону женщины, формируясь в страшную белую руку. Она решительно смотрела на этот свет, но я видел неуверенность за ее маской спокойствия. Когда рука достигла ее, она обхватила пальцами голову женщины.\r\n\r\nИ сжала ее.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Они стояли, замерев, а она спокойно смотрела им в глаза. И тогда один из всадников посмотрел вверх, как будто услышал далекий зов. Он вытащил из-под одежды небольшой камень и заглянул в него. Затем он жестом указал на него жене Свена. Свет полился из всадника в сторону женщины, формируясь в страшную белую руку. Она решительно смотрела на этот свет, но я видел неуверенность за ее маской спокойствия. Когда рука достигла ее, она обхватила пальцами голову женщины.\r\n\r\nИ сжала ее.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (201,'Тело жены Свена стояло прямо, как доска, а ее глаза распахнулись. И хотя ее губы широко открылись в крике, не раздалось ни звука. После нескольких секунд этой пытки рука отпустила ее, и она упала на колени. Всадник, державший драгоценность, сел прямо в своем седле и громкий голос раздался из камня.\r\n\r\n"Эта женщина лжет," – раздался голос, пугающий меня теперь в кошмарах. "Она никогда не видела косу"."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тело жены Свена стояло прямо, как доска, а ее глаза распахнулись. И хотя ее губы широко открылись в крике, не раздалось ни звука. После нескольких секунд этой пытки рука отпустила ее, и она упала на колени. Всадник, державший драгоценность, сел прямо в своем седле и громкий голос раздался из камня.\r\n\r\n"Эта женщина лжет," – раздался голос, пугающий меня теперь в кошмарах. "Она никогда не видела косу"."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (202,'После этого всадник поник, как будто чей-то дух покинул его. И тогда прежним визгливым голосом старика он произнес последние слова:\r\n\r\n"Повелитель сказал свое слово. Убить их".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После этого всадник поник, как будто чей-то дух покинул его. И тогда прежним визгливым голосом старика он произнес последние слова:\r\n\r\n"Повелитель сказал свое слово. Убить их".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (203,'Я не могу описать того, что случилось дальше. Я ясно помню все, но даже моя истерзанная душа не может изложить на бумагу последовавшие за тем несколько ужасающих минут.\r\n\r\nЯ могу лишь написать, что семья Свена была убита. И вскоре вернулся Свен, чтобы увидеть эту страшную картину смерти. Такое горе исказило его черты, что я боялся выйти к нему. И я так боялся, что он может обнаружить меня сам, что покинул свое убежище в сарае. Я не знаю, где теперь Свен, но я молюсь, что когда-нибудь он обретет покой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я не могу описать того, что случилось дальше. Я ясно помню все, но даже моя истерзанная душа не может изложить на бумагу последовавшие за тем несколько ужасающих минут.\r\n\r\nЯ могу лишь написать, что семья Свена была убита. И вскоре вернулся Свен, чтобы увидеть эту страшную картину смерти. Такое горе исказило его черты, что я боялся выйти к нему. И я так боялся, что он может обнаружить меня сам, что покинул свое убежище в сарае. Я не знаю, где теперь Свен, но я молюсь, что когда-нибудь он обретет покой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (205,'После того как я вытащил косу, они напали на нас отовсюду, выползая из укромных щелей под нашими ногами и падая на нас откуда-то с потолка. Половина наших людей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После того как я вытащил косу, они напали на нас отовсюду, выползая из укромных щелей под нашими ногами и падая на нас откуда-то с потолка. Половина наших людей погибла в эти первые минуты паники. Оставшиеся, включая меня, пытались бежать. Во время моего бегства я видел, как многих моих братьев разорвали зубами и когтями, слышал обрывающиеся крики и затихающее бульканье.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (206,'Не понимаю, как мне удалось выжить в ту ночь. Я всегда был осторожным, не ввязывался в драки и не попадался в ловушки. Я даже получил за это свое прозвище. Наверное, эта природная осторожность спасла меня от смерти...\r\n\r\nИли Коса, которую я вытащил из хлама. Хотя вряд ли сама Коса, ее я потерял во время своего отчаянного бегства. Но если воргены появились в Сумеречном лесу из-за меня, тогда, похоже, они оказали мне ответную любезность. Чтоб им провалиться!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не понимаю, как мне удалось выжить в ту ночь. Я всегда был осторожным, не ввязывался в драки и не попадался в ловушки. Я даже получил за это свое прозвище. Наверное, эта природная осторожность спасла меня от смерти...\r\n\r\nИли Коса, которую я вытащил из хлама. Хотя вряд ли сама Коса, ее я потерял во время своего отчаянного бегства. Но если воргены появились в Сумеречном лесу из-за меня, тогда, похоже, они оказали мне ответную любезность. Чтоб им провалиться!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (207,'После того как я выжил в побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места, я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\n Так что я оставался в укрытии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После того как я выжил в побеге из Погибели Роланда, я прятался в сарае, принадлежавшем человеку по имени Свен. Я провел в нем несколько дней, и такой ужас сковал меня, что я никогда не показывался Свену или его семье на глаза. Но оттуда, с моего места, я мог видеть, что эти фермеры – славные ребята. Если бы я вышел из своего укрытия, я думаю, они бы приняли меня, но мне всегда было тяжело кому-то доверять. И стало еще тяжелее после случившегося ужаса в шахте.\r\n\r\n Так что я оставался в укрытии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (208,'<Оставшаяся часть книги пуста.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Оставшаяся часть книги пуста.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (213,'Похлебка Западного Края\r\n\r\n3 куска жилистого мяса стервятника \r\n3 рыла кровоклыка\r\n3 глаза мурлока \r\n3 окры\r\n\r\nСмешать и довести до кипения. Тушить на медленном огне по крайней мере часа два и подавать на стол.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Похлебка Западного Края\r\n\r\n3 куска жилистого мяса стервятника \r\n3 рыла кровоклыка\r\n3 глаза мурлока \r\n3 окры\r\n\r\nСмешать и довести до кипения. Тушить на медленном огне по крайней мере часа два и подавать на стол.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (214,'Дорогая Иветта, я доверяю это письмо нашему самому быстрому бегуну. Я молюсь, чтобы он смог пробраться сквозь кольцо окруживших нас сил. И молюсь, что ты прочитаешь мои слова, поскольку это последнее, что ты услышишь от меня.\r\n\r\nЕдинственное, что меня успокаивает в эти мрачные дни, – это чувство облегчения от того, что я знаю: ты не разделишь мою участь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогая Иветта, я доверяю это письмо нашему самому быстрому бегуну. Я молюсь, чтобы он смог пробраться сквозь кольцо окруживших нас сил. И молюсь, что ты прочитаешь мои слова, поскольку это последнее, что ты услышишь от меня.\r\n\r\nЕдинственное, что меня успокаивает в эти мрачные дни, – это чувство облегчения от того, что я знаю: ты не разделишь мою участь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (219,'От Бароса Алекстона,\r\nгородского архитектора\r\nШтормград\r\n\r\nВаше Величество,\r\n\r\nЕсть множество причин, по которым, мне кажется, должен быть составлен и предоставлен рапорт о недавних аферах "Братства Справедливости" и их активности в королевстве.\r\n\r\nДля начала немного истории. Как вы можете знать – а может быть, и нет – мое служение городу Штормград началось в качестве члена гильдии Каменщиков. Спустя годы работы мы закончили восстановление') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','От Бароса Алекстона,\r\nгородского архитектора\r\nШтормград\r\n\r\nВаше Величество,\r\n\r\nЕсть множество причин, по которым, мне кажется, должен быть составлен и предоставлен рапорт о недавних аферах "Братства Справедливости" и их активности в королевстве.\r\n\r\nДля начала немного истории. Как вы можете знать – а может быть, и нет – мое служение городу Штормград началось в качестве члена гильдии Каменщиков. Спустя годы работы мы закончили восстановление',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (220,'Штормграда. К тому времени счета все еще не были оплачены, а о вознаграждениях и заработных платах гильдии Каменщиков старательно умалчивалось.\r\n\r\nВ то время Эдвин ван Клиф был избранным главой гильдии Каменщиков, и он в открытую требовал возмещения за нашу работу. В ответ Благородный дом Штормграда приказал распустить гильдию Каменщиков, что, естественно, разозлило ван Клифа. Возглавив бунт, ван Клиф вывел Каменщиков из города.\r\n\r\nПрежде чем я продолжу, я бы хотел рассказать о других событиях, случившихся') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Штормграда. К тому времени счета все еще не были оплачены, а о вознаграждениях и заработных платах гильдии Каменщиков старательно умалчивалось.\r\n\r\nВ то время Эдвин ван Клиф был избранным главой гильдии Каменщиков, и он в открытую требовал возмещения за нашу работу. В ответ Благородный дом Штормграда приказал распустить гильдию Каменщиков, что, естественно, разозлило ван Клифа. Возглавив бунт, ван Клиф вывел Каменщиков из города.\r\n\r\nПрежде чем я продолжу, я бы хотел рассказать о других событиях, случившихся',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (221,'в то же время, к которым я хотел бы привлечь ваше внимание.\r\n\r\nВо-первых, в то время мне предложили пост городского архитектора с условием, что я не стану присоединяться к ван Клифу. Исходя из явственных идеологических разногласий, я принял решение остаться в Штормграде.\r\n\r\nВо время восстания лейтенанта и самого доверенного помощника ван Клифа, Базиля Тредда, поймали и заключили в тюрьму. В ожидании суда и следствия Тредд был практически забыт в тюрьме Штормграда.\r\n\r\nВозвращаясь к ван Клифу: после того как он вывел оставшихся') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','в то же время, к которым я хотел бы привлечь ваше внимание.\r\n\r\nВо-первых, в то время мне предложили пост городского архитектора с условием, что я не стану присоединяться к ван Клифу. Исходя из явственных идеологических разногласий, я принял решение остаться в Штормграде.\r\n\r\nВо время восстания лейтенанта и самого доверенного помощника ван Клифа, Базиля Тредда, поймали и заключили в тюрьму. В ожидании суда и следствия Тредд был практически забыт в тюрьме Штормграда.\r\n\r\nВозвращаясь к ван Клифу: после того как он вывел оставшихся',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (222,'Каменщиков из Штормграда, он воспользовался относительно незащищенным статусом Западного Края и использовал свое превосходство в силе, чтобы выгнать оттуда множество фермеров и захватить несколько золотых рудников.\r\n\r\nВоспользовавшись ресурсами, оказавшимися в его распоряжении, ван Клиф составил план возмездия правительству Штормграда.\r\n\r\nЭта информация стала известна лишь недавно благодаря помощи носителя этого документа, который сыграл важную роль в пролитии света на этот громадный заговор.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Каменщиков из Штормграда, он воспользовался относительно незащищенным статусом Западного Края и использовал свое превосходство в силе, чтобы выгнать оттуда множество фермеров и захватить несколько золотых рудников.\r\n\r\nВоспользовавшись ресурсами, оказавшимися в его распоряжении, ван Клиф составил план возмездия правительству Штормграда.\r\n\r\nЭта информация стала известна лишь недавно благодаря помощи носителя этого документа, который сыграл важную роль в пролитии света на этот громадный заговор.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (230,'День второй\r\n\r\nМой поиск продолжается, но до сих пор нет следов руды. Интересно, не пошутил ли Каменный Убор по поводу этой руды. Если так, то он получит хорошую затрещину от меня, когда я вернусь в Поселок Сталежара!\r\n\r\nКогда я размещал свой лагерь, то услышал эхо рычания в каньонах.\r\n\r\nЭто был не волк. Это, должно быть, медведь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День второй\r\n\r\nМой поиск продолжается, но до сих пор нет следов руды. Интересно, не пошутил ли Каменный Убор по поводу этой руды. Если так, то он получит хорошую затрещину от меня, когда я вернусь в Поселок Сталежара!\r\n\r\nКогда я размещал свой лагерь, то услышал эхо рычания в каньонах.\r\n\r\nЭто был не волк. Это, должно быть, медведь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (231,'Третий день\r\n\r\nРычание не прекращалось всю ночь и преследует меня даже днем. Я не могу сосредоточиться на добыче руды. Думаю, это медведь!\r\n\r\nПусть только подойдет поближе, мне уже не терпится всадить кирку в его череп!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Третий день\r\n\r\nРычание не прекращалось всю ночь и преследует меня даже днем. Я не могу сосредоточиться на добыче руды. Думаю, это медведь!\r\n\r\nПусть только подойдет поближе, мне уже не терпится всадить кирку в его череп!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (233,'День пятый.\r\n\r\nЭтот проклятый медведь добрался до меня! Он бросился на меня в полдень и напал со спины.\r\n\r\nЯ бы унюхал его задолго до этого, если бы он напал на меня не с подветренной стороны – запах от него шел ужасный! Одна только вонь от его грязной шкуры и гнилое дыхание заставили бы меня сбежать оттуда!\r\n\r\nЯ сражался с ним, но он хорошо подрал мою ногу. Теперь я не могу двигаться, эля нет, и я так и не нашел эту руду. Проклятье!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День пятый.\r\n\r\nЭтот проклятый медведь добрался до меня! Он бросился на меня в полдень и напал со спины.\r\n\r\nЯ бы унюхал его задолго до этого, если бы он напал на меня не с подветренной стороны – запах от него шел ужасный! Одна только вонь от его грязной шкуры и гнилое дыхание заставили бы меня сбежать оттуда!\r\n\r\nЯ сражался с ним, но он хорошо подрал мою ногу. Теперь я не могу двигаться, эля нет, и я так и не нашел эту руду. Проклятье!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (236,'Исследуя окаменелости, я пришел к выводу, что в древние времена великая чума свирепствовала у озера Лордамер. Что послужило ее причиной? Мы никогда не узнаем. Но уровень загрязнения весьма высок, исходя из насыщенной концентрации останков, представленных в залежах озерного пласта.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Исследуя окаменелости, я пришел к выводу, что в древние времена великая чума свирепствовала у озера Лордамер. Что послужило ее причиной? Мы никогда не узнаем. Но уровень загрязнения весьма высок, исходя из насыщенной концентрации останков, представленных в залежах озерного пласта.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (237,'В попытке понять прошлое я начал изучать создания настоящего, надеясь обнаружить недостающие ключи к загадке. Озерные тихоходы и озерные ползуны – древние создания, населяющие остров в центре озера Лордамер. Мох, растущий на них, содержит следы частиц тех самых окаменелостей. Необходимо провести больше исследований, прежде чем я смог бы сделать выводы о том, что означает эта связь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В попытке понять прошлое я начал изучать создания настоящего, надеясь обнаружить недостающие ключи к загадке. Озерные тихоходы и озерные ползуны – древние создания, населяющие остров в центре озера Лордамер. Мох, растущий на них, содержит следы частиц тех самых окаменелостей. Необходимо провести больше исследований, прежде чем я смог бы сделать выводы о том, что означает эта связь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (238,'Собирая образцы мха, я случайно стал свидетелем сцены кровавой битвы. Клан мурлоков Коварного Плавника подвергся нападению мародерствующих банд гноллов. Трупы и гноллов, и мурлоков были разбросаны по всему полю боя. Когда я проходил мимо растерзанного тела мурлока, я заметил странно затвердевшую опухоль, выступающую из раны. Когда я начал изучать ее, стало ясно, что похожие свойства я обнаружил у мха, который собирал. К сожалению, больше я не смог больше найти ни одной опухоли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Собирая образцы мха, я случайно стал свидетелем сцены кровавой битвы. Клан мурлоков Коварного Плавника подвергся нападению мародерствующих банд гноллов. Трупы и гноллов, и мурлоков были разбросаны по всему полю боя. Когда я проходил мимо растерзанного тела мурлока, я заметил странно затвердевшую опухоль, выступающую из раны. Когда я начал изучать ее, стало ясно, что похожие свойства я обнаружил у мха, который собирал. К сожалению, больше я не смог больше найти ни одной опухоли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (246,'Я провел следующие недели, перебегая с места на место, нигде не задерживаясь, из страха перед всадниками. Сейчас я остановился в заброшенном городе Вороньем холме – прячусь, как обычно. Я не могу встретиться с той силой, что они использовали на жене Свена, и я знаю, что она рыщет по Сумеречному лесу, все еще ищет косу. Я потерял ее, и за это я благодарю Свет, ибо если бы я оставил ее у себя, я знаю, меня бы обнаружили. Даже теперь в глубине моего сердца я уверен, что меня найдут.\r\n\r\nЯ так устал...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я провел следующие недели, перебегая с места на место, нигде не задерживаясь, из страха перед всадниками. Сейчас я остановился в заброшенном городе Вороньем холме – прячусь, как обычно. Я не могу встретиться с той силой, что они использовали на жене Свена, и я знаю, что она рыщет по Сумеречному лесу, все еще ищет косу. Я потерял ее, и за это я благодарю Свет, ибо если бы я оставил ее у себя, я знаю, меня бы обнаружили. Даже теперь в глубине моего сердца я уверен, что меня найдут.\r\n\r\nЯ так устал...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (248,'Приветствую вас, Господин,\r\n\r\nПриношу свои извинения за то, как мое послание попало к вам. Темные маги в Альтераке сосредоточили все свои силы на выполнении поставленной задачи, и я был вынужден передать вам сообщение с этим гонцом – новобранцем из рядов наших новых "союзников". Однако я зашифровал послание самым тайным из наших шифром. Эта деревенщина не поймет ни слова.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую вас, Господин,\r\n\r\nПриношу свои извинения за то, как мое послание попало к вам. Темные маги в Альтераке сосредоточили все свои силы на выполнении поставленной задачи, и я был вынужден передать вам сообщение с этим гонцом – новобранцем из рядов наших новых "союзников". Однако я зашифровал послание самым тайным из наших шифром. Эта деревенщина не поймет ни слова.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (249,'Валлик,\r\nохраняй раба до нашего возвращения. Теперь здесь небезопасно, мы не можем больше хранить ЕГО тут. Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить.\r\n\r\nОни – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства. Лучше спрятать любые знаки, что могли бы заставить собраться их вместе. Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Валлик,\r\nохраняй раба до нашего возвращения. Теперь здесь небезопасно, мы не можем больше хранить ЕГО тут. Мы отправимся на север, обходя стороной любые места, где нас могли бы заметить.\r\n\r\nОни – животные, но животные безжалостные – мы достаточно от них натерпелись, у нас есть причины для беспокойства. Лучше спрятать любые знаки, что могли бы заставить собраться их вместе. Меньше всего мы бы хотели дать им повод воссоединиться и напасть на нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (250,'Группа из Братства Справедливости встретится с Собирателем, после чего он переправит собранное золото.\r\n\r\nУбедитесь, что этот процесс произойдет без ошибок и в условиях строжайшей секретности. Собиратель ответственен за переправку золота, но в конечном счете каждый член Братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Группа из Братства Справедливости встретится с Собирателем, после чего он переправит собранное золото.\r\n\r\nУбедитесь, что этот процесс произойдет без ошибок и в условиях строжайшей секретности. Собиратель ответственен за переправку золота, но в конечном счете каждый член Братства Справедливости должен убедиться, что его роль будет выполнена со всем тщанием и осторожностью.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (251,'Помните, мои братья, когда-то мы были гордыми ремесленниками. Мы будем исполнять наши сегодняшние обязанности с тем же тщанием, что когда-то использовали в нашем ремесле.\r\n\r\n-ЭВК') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Помните, мои братья, когда-то мы были гордыми ремесленниками. Мы будем исполнять наши сегодняшние обязанности с тем же тщанием, что когда-то использовали в нашем ремесле.\r\n\r\n-ЭВК',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (252,'Боюсь, мой отец сделал огромную ошибку, решившись остаться и защищать наш дом. Силы Плети свирепствуют в Тирисфальских лесах, и несмотря на то что мы достаточно укреплены и у нас хватает запасов, после предательства моего брата Девлина у нас не хватает сил и рук, чтобы противостоять их постоянным атакам.\r\n\r\nКогда ты получишь мое письмо, Иветта, то будешь знать, что Девлин – предатель.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Боюсь, мой отец сделал огромную ошибку, решившись остаться и защищать наш дом. Силы Плети свирепствуют в Тирисфальских лесах, и несмотря на то что мы достаточно укреплены и у нас хватает запасов, после предательства моего брата Девлина у нас не хватает сил и рук, чтобы противостоять их постоянным атакам.\r\n\r\nКогда ты получишь мое письмо, Иветта, то будешь знать, что Девлин – предатель.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (253,'Девлином завладело отчаяние, и он искал, как избежать ожидающей нас печальной участи, и вот почему он заключил договор с Плетью. Я не знаю, сколько ему пообещали за предательство, но я уверен, все это было ложью.\r\n\r\nЕсли ты встретишь моего брата, беги от него. Он – монстр. Несколько ночей назад он убил двоих наших часовых и провел небольшую группу Плети через эту брешь к тому месту, где спало большинство из нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Девлином завладело отчаяние, и он искал, как избежать ожидающей нас печальной участи, и вот почему он заключил договор с Плетью. Я не знаю, сколько ему пообещали за предательство, но я уверен, все это было ложью.\r\n\r\nЕсли ты встретишь моего брата, беги от него. Он – монстр. Несколько ночей назад он убил двоих наших часовых и провел небольшую группу Плети через эту брешь к тому месту, где спало большинство из нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (254,'Нападение было ужасным. Они убили треть из нас к тому моменту, когда мы смогли их уничтожить. И теперь у нас едва хватает людей для защиты наших границ. Это лишь вопрос времени, когда наши утомленные стражники падут и Плеть атакует нас.\r\n\r\nИ хотя я видел лицо Девлина среди доведенных до отчаяния мужчин и мрачнолицых воинов Плети в ту проклятую ночь, он ускользнул от меня прежде, чем я смог до него добраться. Возможно, он мертв – а возможно, выжил, и стал агентом Плети.\r\n\r\nКак бы то ни было, он – монстр.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нападение было ужасным. Они убили треть из нас к тому моменту, когда мы смогли их уничтожить. И теперь у нас едва хватает людей для защиты наших границ. Это лишь вопрос времени, когда наши утомленные стражники падут и Плеть атакует нас.\r\n\r\nИ хотя я видел лицо Девлина среди доведенных до отчаяния мужчин и мрачнолицых воинов Плети в ту проклятую ночь, он ускользнул от меня прежде, чем я смог до него добраться. Возможно, он мертв – а возможно, выжил, и стал агентом Плети.\r\n\r\nКак бы то ни было, он – монстр.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (255,'Девлин предупреждал нас, что если мы попробуем противостоять Плети, все мы будем обречены. Он говорил нам об этом, когда они только ступили в Тирисфальские леса, задолго до того как они достигли нашего дома. Возможно, он умолял нас покинуть его, а может быть, злорадствовал.\r\n\r\nВсегда было сложно понять истинные мотивы Девлина. Еще будучи ребенком, он был для нас всех загадкой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Девлин предупреждал нас, что если мы попробуем противостоять Плети, все мы будем обречены. Он говорил нам об этом, когда они только ступили в Тирисфальские леса, задолго до того как они достигли нашего дома. Возможно, он умолял нас покинуть его, а может быть, злорадствовал.\r\n\r\nВсегда было сложно понять истинные мотивы Девлина. Еще будучи ребенком, он был для нас всех загадкой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (256,'Но он был прав. Мы обречены. Линия семьи Агамондов прервется. Несмотря на то что я все еще жив, скоро я погибну.\r\n\r\nЯ не боюсь, и не сожалею о том, что остался со своей семьей. Но мои последние мысли – о тебе.\r\n\r\nПродолжай жить, моя возлюбленная Иветта, и я обрету покой.\r\nТармен') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но он был прав. Мы обречены. Линия семьи Агамондов прервется. Несмотря на то что я все еще жив, скоро я погибну.\r\n\r\nЯ не боюсь, и не сожалею о том, что остался со своей семьей. Но мои последние мысли – о тебе.\r\n\r\nПродолжай жить, моя возлюбленная Иветта, и я обрету покой.\r\nТармен',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (257,'Наши планы продвигаются споро; как я уже упоминал, мы заключили союз с группой людей, называющих себя Синдикатом. Их лидеры когда-то принадлежали к Альтеракской знати, и они жаждут вновь править там.\r\n\r\nИтак, они заключили с нами сделку. Сделку, о которой они пожалеют.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наши планы продвигаются споро; как я уже упоминал, мы заключили союз с группой людей, называющих себя Синдикатом. Их лидеры когда-то принадлежали к Альтеракской знати, и они жаждут вновь править там.\r\n\r\nИтак, они заключили с нами сделку. Сделку, о которой они пожалеют.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (258,'Сегодня Синдикат контролирует лишь малые силы, но они хорошо знают эту область и собрали достаточное количество воинов для выполнения задач. С должным руководством, я уверен, Синдикат захватит Альтерак довольно скоро.\r\n\r\nМы убедили Синдикат направиться в город Стромгард неподалеку в нагорье Арати. Этот город – поле боя между нашими силами, ограми и людьми Стромгарда, но мы думаем, что продумав тщательную тактику, мы завладеем этим когда-то великим городом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сегодня Синдикат контролирует лишь малые силы, но они хорошо знают эту область и собрали достаточное количество воинов для выполнения задач. С должным руководством, я уверен, Синдикат захватит Альтерак довольно скоро.\r\n\r\nМы убедили Синдикат направиться в город Стромгард неподалеку в нагорье Арати. Этот город – поле боя между нашими силами, ограми и людьми Стромгарда, но мы думаем, что продумав тщательную тактику, мы завладеем этим когда-то великим городом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (259,'Воплотив наш замысел в жизнь, мы сможем перейти к следующему этапу плана. Необходимо сплотиться вместе и закрепиться в этом регионе, после этого мы сможем начать приготовления к Третьему Походу.\r\n\r\nСкоро владыки Легиона вознаградят нас за наши труды и снова низвергнут огонь с небес!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Воплотив наш замысел в жизнь, мы сможем перейти к следующему этапу плана. Необходимо сплотиться вместе и закрепиться в этом регионе, после этого мы сможем начать приготовления к Третьему Походу.\r\n\r\nСкоро владыки Легиона вознаградят нас за наши труды и снова низвергнут огонь с небес!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (265,'Шахтер Оруэлл\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nШахтер Фитцджеральд\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nГражданин Недранд\r\nВсе задолженности выплачены.\r\n\r\nГражданин Мэй\r\nВсе задолженности выплачены.\r\n\r\nСтаршина Бондс\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Шахтер Оруэлл\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nШахтер Фитцджеральд\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.\r\n\r\nГражданин Недранд\r\nВсе задолженности выплачены.\r\n\r\nГражданин Мэй\r\nВсе задолженности выплачены.\r\n\r\nСтаршина Бондс\r\nКрупный долг. Выплата долга состоится после поставки руды из Лазурного рудника.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (285,'История Гри\'лека Странника\r\n\r\n[...Начало надписи, выбитой на камне, стерлось, но окончание все еще можно было прочитать...]\r\n\r\nГри\'лек топал по джунглям. Его глаза горели, и его грудь клокотала, ибо великий гнев переполнял его. \r\n\r\nВ ярости он рычал на небо и воздевал руку. Он воздевал левую руку, ставшую сильной и крепкой от охоты без своего близнеца. \r\n\r\nИбо правая рука Гри\'лека была утрачена безвозвратно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','История Гри\'лека Странника\r\n\r\n[...Начало надписи, выбитой на камне, стерлось, но окончание все еще можно было прочитать...]\r\n\r\nГри\'лек топал по джунглям. Его глаза горели, и его грудь клокотала, ибо великий гнев переполнял его. \r\n\r\nВ ярости он рычал на небо и воздевал руку. Он воздевал левую руку, ставшую сильной и крепкой от охоты без своего близнеца. \r\n\r\nИбо правая рука Гри\'лека была утрачена безвозвратно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (286,'"Легенды троллей", том III\r\n"Камень Приливов"\r\n\r\nПринадлежит перу\r\nверховного мага Ансарема Руноплета\r\nДаларан\r\n\r\nВСТУПЛЕНИЕ\r\n\r\nДревняя империя Гурубаши была источником многих завораживающих и интригующих легенд, которые, без сомнения, основаны на пристальных наблюдениях за живой природой, поскольку исследования верований и традиций этих троллей указывают на благоговение перед своей естественной средой обитания.\r\n\r\nВ то время как я исследовал многие') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Легенды троллей", том III\r\n"Камень Приливов"\r\n\r\nПринадлежит перу\r\nверховного мага Ансарема Руноплета\r\nДаларан\r\n\r\nВСТУПЛЕНИЕ\r\n\r\nДревняя империя Гурубаши была источником многих завораживающих и интригующих легенд, которые, без сомнения, основаны на пристальных наблюдениях за живой природой, поскольку исследования верований и традиций этих троллей указывают на благоговение перед своей естественной средой обитания.\r\n\r\nВ то время как я исследовал многие',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (292,'Здесь покоится Утер Светоносный –\r\nпервый паладин и основатель ордена Серебряной Длани\r\n\r\nУтер жил и умер, защищая королевство Лордерон. Его предал любимый ученик, но мы верим, что дух Утера все еще жив. Он по-прежнему наблюдает за нами теперь, когда вокруг нашей разоренной земли сгущаются тени. Его свет – свет всего человечества, и пока мы чтим пример Утера, этот свет никогда не угаснет. \r\n- Аноним') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Здесь покоится Утер Светоносный –\r\nпервый паладин и основатель ордена Серебряной Длани\r\n\r\nУтер жил и умер, защищая королевство Лордерон. Его предал любимый ученик, но мы верим, что дух Утера все еще жив. Он по-прежнему наблюдает за нами теперь, когда вокруг нашей разоренной земли сгущаются тени. Его свет – свет всего человечества, и пока мы чтим пример Утера, этот свет никогда не угаснет. \r\n- Аноним',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (293,'аспекты их поклонения змеям в предыдущих томах этой работы, здесь я хотел бы рассмотреть примеры особого отношения троллей к морю.\r\n\r\n\r\nВЕЛИКОЕ МОРЕ\r\n\r\nИмперия Гурубаши с трех сторон была окружена морем, так что неудивительно, что морские воды играли значительную роль в жизни их общества. Обширные пространства своей поросшей джунглями империи тролли могли контролировать беспрепятственно, а вот море не желало им подчиняться. Широкое, бескрайнее, оно, несомненно,') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','аспекты их поклонения змеям в предыдущих томах этой работы, здесь я хотел бы рассмотреть примеры особого отношения троллей к морю.\r\n\r\n\r\nВЕЛИКОЕ МОРЕ\r\n\r\nИмперия Гурубаши с трех сторон была окружена морем, так что неудивительно, что морские воды играли значительную роль в жизни их общества. Обширные пространства своей поросшей джунглями империи тролли могли контролировать беспрепятственно, а вот море не желало им подчиняться. Широкое, бескрайнее, оно, несомненно,',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (294,'обескураживало могущественных троллей.\r\n\r\nЗдесь следует отметить, что последние открытия, по всей видимости, показывают, что тролли мало интересовались исследованием земель, находящихся за Великим морем. Хотя различные племена троллей обитали на всей территории Азерота, Каз Модана и Лордерона, в новооткрытых землях Калимдора и на островах Южных морей следов их цивилизации обнаружено практически не было. Говорит ли это о нежелании') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','обескураживало могущественных троллей.\r\n\r\nЗдесь следует отметить, что последние открытия, по всей видимости, показывают, что тролли мало интересовались исследованием земель, находящихся за Великим морем. Хотя различные племена троллей обитали на всей территории Азерота, Каз Модана и Лордерона, в новооткрытых землях Калимдора и на островах Южных морей следов их цивилизации обнаружено практически не было. Говорит ли это о нежелании',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (295,'троллей удаляться от своих исконных владений, или же об их неумении разработать технологии, необходимые для такого путешествия? Ответ на этот вопрос потребует дальнейших исследований, выходящих за рамки моей работы.\r\n\r\nОднако же вряд ли тролли могли игнорировать столь крупный объект. И новые находки в обширных тролльских развалинах в Тернистой долине демонстрируют ранее не известный аспект их взаимоотношений с морем.\r\n\r\n\r\nКАМЕНЬ ПРИЛИВОВ\r\n\r\nНедавние открытия, произведенные при обследовании') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','троллей удаляться от своих исконных владений, или же об их неумении разработать технологии, необходимые для такого путешествия? Ответ на этот вопрос потребует дальнейших исследований, выходящих за рамки моей работы.\r\n\r\nОднако же вряд ли тролли могли игнорировать столь крупный объект. И новые находки в обширных тролльских развалинах в Тернистой долине демонстрируют ранее не известный аспект их взаимоотношений с морем.\r\n\r\n\r\nКАМЕНЬ ПРИЛИВОВ\r\n\r\nНедавние открытия, произведенные при обследовании',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (296,'тролльских развалин в Тернистой долине, позволили обнаружить упоминания о предмете, известном как Камень Приливов. Объединяя различные фрагменты тролльских преданий, мы получим достаточно сложную картину представлений о Камне и его значении для древней империи Гурубаши.\r\n\r\nСкладывается впечатление, что Камень Приливов позволял своему владельцу повелевать водой в любых ее видах: реками, дождями, приливами. На основании легенд, связанных с использованием Камня Приливов, я пришел к выводу, что он,') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','тролльских развалин в Тернистой долине, позволили обнаружить упоминания о предмете, известном как Камень Приливов. Объединяя различные фрагменты тролльских преданий, мы получим достаточно сложную картину представлений о Камне и его значении для древней империи Гурубаши.\r\n\r\nСкладывается впечатление, что Камень Приливов позволял своему владельцу повелевать водой в любых ее видах: реками, дождями, приливами. На основании легенд, связанных с использованием Камня Приливов, я пришел к выводу, что он,',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (297,'по сути представляет собой материальное воплощение силы Повелителя вод, могущественного морского элементаля. Как и почему подобный предмет вышел из-под власти Повелителя вод и попал в руки троллей – другой вопрос, ответ на который мне неизвестен.\r\n\r\n\r\nВЛАДЫКА ПРИЛИВОВ\r\n\r\nПодобно самим приливам, Камень Приливов был непостоянен: он появлялся в мире троллей и исчезал снова, никогда не оставаясь в их руках дольше жизни одного поколения.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','по сути представляет собой материальное воплощение силы Повелителя вод, могущественного морского элементаля. Как и почему подобный предмет вышел из-под власти Повелителя вод и попал в руки троллей – другой вопрос, ответ на который мне неизвестен.\r\n\r\n\r\nВЛАДЫКА ПРИЛИВОВ\r\n\r\nПодобно самим приливам, Камень Приливов был непостоянен: он появлялся в мире троллей и исчезал снова, никогда не оставаясь в их руках дольше жизни одного поколения.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (298,'В преданиях троллей говорится, что в первый раз Камень Приливов попал в империю Гурубаши, будучи найденным воином-троллем, бродившим по побережью Тернистой долины. Воину попался на глаза таинственный синий камень, внутри которого сплетались и струились молочно-белые прожилки. Заинтригованный воин взял камень с собой и продолжил свой путь.\r\n\r\nСо временем воин обнаружил, что камень дает ему власть над водами. Он мог вызывать') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В преданиях троллей говорится, что в первый раз Камень Приливов попал в империю Гурубаши, будучи найденным воином-троллем, бродившим по побережью Тернистой долины. Воину попался на глаза таинственный синий камень, внутри которого сплетались и струились молочно-белые прожилки. Заинтригованный воин взял камень с собой и продолжил свой путь.\r\n\r\nСо временем воин обнаружил, что камень дает ему власть над водами. Он мог вызывать',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (299,'элементалей воды, существ, целиком состоящих из воды, что прежде удавалось только могущественным магам Кирин-Тора.\r\n\r\nВоин отправился в Зул\'Гуруб, в сердце империи, чтобы продемонстрировать свои новые способности императору. Он с легкостью добился аудиенции при дворе после того, как продемонстрировал свое могущество в центре столицы империи. Его способности поразили императора Гурубаши, который немедленно предоставил ему почетное место при дворе, назвав воина Владыкой Приливов. Прежнее его имя') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','элементалей воды, существ, целиком состоящих из воды, что прежде удавалось только могущественным магам Кирин-Тора.\r\n\r\nВоин отправился в Зул\'Гуруб, в сердце империи, чтобы продемонстрировать свои новые способности императору. Он с легкостью добился аудиенции при дворе после того, как продемонстрировал свое могущество в центре столицы империи. Его способности поразили императора Гурубаши, который немедленно предоставил ему почетное место при дворе, назвав воина Владыкой Приливов. Прежнее его имя',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (300,'было забыто.\r\n\r\nГодами Владыка Приливов служил империи Гурубаши, заставляя служивших ему элементалей воды сражаться в бою и управляя течением воды в Тернистой долине во благо империи. Но с годами Владыка Приливов стал более склонен к уединению. Он все чаще и чаще надолго удалялся от двора.\r\n\r\nВладыка Приливов скрывал от любопытных глаз придворных свою страшную тайну. Способности, которые дал ему Камень Приливов, сопровождало проклятие. С ходом лет') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','было забыто.\r\n\r\nГодами Владыка Приливов служил империи Гурубаши, заставляя служивших ему элементалей воды сражаться в бою и управляя течением воды в Тернистой долине во благо империи. Но с годами Владыка Приливов стал более склонен к уединению. Он все чаще и чаще надолго удалялся от двора.\r\n\r\nВладыка Приливов скрывал от любопытных глаз придворных свою страшную тайну. Способности, которые дал ему Камень Приливов, сопровождало проклятие. С ходом лет',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (301,'Владыка Приливов таял. С каждым приливом и отливом он терял часть себя, утрачивал свою телесную форму – исчезая и снова появляясь, – пока, наконец, в свой смертный час он не отправился на берег, на котором нашел Камень, и не вошел в море, исчезнув в последний раз.\r\n\r\nНесколько поколений спустя Камень Приливов снова вынесло прибоем на берега Тернистой долины, и тролль, принесший его в Зул-Гуруб, был избран новым') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Владыка Приливов таял. С каждым приливом и отливом он терял часть себя, утрачивал свою телесную форму – исчезая и снова появляясь, – пока, наконец, в свой смертный час он не отправился на берег, на котором нашел Камень, и не вошел в море, исчезнув в последний раз.\r\n\r\nНесколько поколений спустя Камень Приливов снова вынесло прибоем на берега Тернистой долины, и тролль, принесший его в Зул-Гуруб, был избран новым',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (302,'Владыкой Приливов. Так продолжалось много веков: Камень выносило на берег, а потом Владыка Приливов уходил в море.\r\n\r\n\r\nКамень Приливов периодически упоминается в современных источниках, но почему столь могущественный предмет появляется с такой регулярностью и кто тому причиной, остается загадкой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Владыкой Приливов. Так продолжалось много веков: Камень выносило на берег, а потом Владыка Приливов уходил в море.\r\n\r\n\r\nКамень Приливов периодически упоминается в современных источниках, но почему столь могущественный предмет появляется с такой регулярностью и кто тому причиной, остается загадкой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (303,'Приказ пиратам Кровавого Паруса\r\n\r\nЧитайте и запоминайте, ребятки, другого такого удачного шанса напасть на Пиратскую бухту у нас не будет!\r\n\r\nСтарину Данкена я послал с разведкой на север и сказал ему ждать сигнала.\r\n\r\n"Госпожа Удача" бросит якорь у южного мыса, чтобы взять припасы. Наш коротышка, капитан Штиллец, со своей командой приготовится забрать все награбленное на борт. Ну а с остальным управится наш болван Брут.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приказ пиратам Кровавого Паруса\r\n\r\nЧитайте и запоминайте, ребятки, другого такого удачного шанса напасть на Пиратскую бухту у нас не будет!\r\n\r\nСтарину Данкена я послал с разведкой на север и сказал ему ждать сигнала.\r\n\r\n"Госпожа Удача" бросит якорь у южного мыса, чтобы взять припасы. Наш коротышка, капитан Штиллец, со своей командой приготовится забрать все награбленное на борт. Ну а с остальным управится наш болван Брут.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (306,'Я хочу, чтобы капитан Кильватель привел "Бурун" к берегу с юго-востока. Мы отправим его команду по суше, когда будет дан сигнал. \r\n\r\nЭтот здоровый увалень, Соленое Копыто, может повести ребят в атаку. На Ревилгазе и Морском Роге я ставлю черную метку. Шлите их прямиком на дно моря.\r\n\r\nА вы, парни, отвечаете за то, чтобы спасти все, что может пригодиться для нашей затеи с ван Клифом в Мертвых копях.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я хочу, чтобы капитан Кильватель привел "Бурун" к берегу с юго-востока. Мы отправим его команду по суше, когда будет дан сигнал. \r\n\r\nЭтот здоровый увалень, Соленое Копыто, может повести ребят в атаку. На Ревилгазе и Морском Роге я ставлю черную метку. Шлите их прямиком на дно моря.\r\n\r\nА вы, парни, отвечаете за то, чтобы спасти все, что может пригодиться для нашей затеи с ван Клифом в Мертвых копях.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (307,'Я отдам приказ Многоглазу открыть огонь. Артиллерийский обстрел помешает кораблям Черноводья выходить из гавани и входить в нее.\r\n\r\nПосле того как "Багровый Парус" разрядит свои пушки, я поставлю его рядом с "Буруном" для поддержки и обеспечения резервов, если это понадобится.\r\n\r\nКогда Соленое Копыто и его парни вычистят город и все наши будут на борту, мы поднимем паруса и еще разок обстреляем Пиратскую Бухту со стороны Гибельного берега, для очистки совести.\r\n\r\n--Флотоводец Фираллон') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я отдам приказ Многоглазу открыть огонь. Артиллерийский обстрел помешает кораблям Черноводья выходить из гавани и входить в нее.\r\n\r\nПосле того как "Багровый Парус" разрядит свои пушки, я поставлю его рядом с "Буруном" для поддержки и обеспечения резервов, если это понадобится.\r\n\r\nКогда Соленое Копыто и его парни вычистят город и все наши будут на борту, мы поднимем паруса и еще разок обстреляем Пиратскую Бухту со стороны Гибельного берега, для очистки совести.\r\n\r\n--Флотоводец Фираллон',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (311,'День 1:\r\n6–11 утра – верхний лагерь\r\n11–11:30 утра – перерыв, обед\r\n11:30 утра–4:00 дня – проход через каньон\r\n4:00 дня–7:30 вечера – верхний лагерь\r\n\r\nДень 2:\r\nТо же расписание, что в день 1\r\n\r\nДень 3:\r\nТо же расписание\r\n\r\nДень 4:\r\nТо же расписание, с одним исключением. Перед самым закатом Торсен приказал мне прикрыть его, пока он пробирался по проходу через каньон. Ну, думаю, отправился встречаться с нашими агентами.\r\n\r\nНо он вернулся через час. Это меня удивило. Я-то думаю: сейчас встретится с нашими агентами, снова присоединится к Курцену... Но что-то пошло не так.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 1:\r\n6–11 утра – верхний лагерь\r\n11–11:30 утра – перерыв, обед\r\n11:30 утра–4:00 дня – проход через каньон\r\n4:00 дня–7:30 вечера – верхний лагерь\r\n\r\nДень 2:\r\nТо же расписание, что в день 1\r\n\r\nДень 3:\r\nТо же расписание\r\n\r\nДень 4:\r\nТо же расписание, с одним исключением. Перед самым закатом Торсен приказал мне прикрыть его, пока он пробирался по проходу через каньон. Ну, думаю, отправился встречаться с нашими агентами.\r\n\r\nНо он вернулся через час. Это меня удивило. Я-то думаю: сейчас встретится с нашими агентами, снова присоединится к Курцену... Но что-то пошло не так.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (312,'День 5:\r\nТорсен был сегодня очень взволнован. Кого бы или что бы он ни встретил на своей вчерашней прогулке, это его, должно быть, испугало.\r\n\r\nМне думалось, что с ним говорили наши агенты, но на мой вопрос, куда он ходил, Торсен ничего не ответил. Он считает, что я его друг, и думает, будто мне безопаснее не знать его тайны.\r\n\r\nОн служит не тем, кому следовало бы, но его преданность крепка. Когда он вернется к нам, он станет ценным приобретением для Курцена.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 5:\r\nТорсен был сегодня очень взволнован. Кого бы или что бы он ни встретил на своей вчерашней прогулке, это его, должно быть, испугало.\r\n\r\nМне думалось, что с ним говорили наши агенты, но на мой вопрос, куда он ходил, Торсен ничего не ответил. Он считает, что я его друг, и думает, будто мне безопаснее не знать его тайны.\r\n\r\nОн служит не тем, кому следовало бы, но его преданность крепка. Когда он вернется к нам, он станет ценным приобретением для Курцена.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (313,'День 6:\r\nРано утром Торсен долго говорил с сержантом Йохвой. Мне пришлось притворяться, что сплю, так что подойти поближе мне не удалось. Но я думаю, что они говорили о том, куда ходил Торсен.\r\n\r\nЯ за ним пристально слежу – кстати, Йохва тоже. Позднее Торсена вызвал Дорен. У этих троих какая-то общая тайна. Дорен и Йохва, должно быть, знают, что Торсен встречается с вашими агентами.\r\n\r\nОн шпионит в пользу мятежников.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 6:\r\nРано утром Торсен долго говорил с сержантом Йохвой. Мне пришлось притворяться, что сплю, так что подойти поближе мне не удалось. Но я думаю, что они говорили о том, куда ходил Торсен.\r\n\r\nЯ за ним пристально слежу – кстати, Йохва тоже. Позднее Торсена вызвал Дорен. У этих троих какая-то общая тайна. Дорен и Йохва, должно быть, знают, что Торсен встречается с вашими агентами.\r\n\r\nОн шпионит в пользу мятежников.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (314,'Не следует давать новых сведений Торсену. Его нужно убить. Он больше не принесет пользы нашему полковнику.\r\n\r\nЯ прикончу Торсена, если будет возможность, но если вы получите это письмо, знайте, что пока у меня такой возможности не было.\r\n\r\nВ этом случае я рекомендую, чтобы следующая встреча Торсена с нашими агентами закончилась его смертью.\r\n\r\nСлава Курцену!\r\n-M') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не следует давать новых сведений Торсену. Его нужно убить. Он больше не принесет пользы нашему полковнику.\r\n\r\nЯ прикончу Торсена, если будет возможность, но если вы получите это письмо, знайте, что пока у меня такой возможности не было.\r\n\r\nВ этом случае я рекомендую, чтобы следующая встреча Торсена с нашими агентами закончилась его смертью.\r\n\r\nСлава Курцену!\r\n-M',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (315,'Совет поступил мудро, назначив вас главой Недремлющего Аргуса, исполнителем их предначертаний в землях людей и дворфов. И для меня большая честь служить проводником вашей воли в Альтераке.\r\n\r\nВо имя Саргераса!\r\n\r\nНагаз,\r\nЖрец Аргуса') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Совет поступил мудро, назначив вас главой Недремлющего Аргуса, исполнителем их предначертаний в землях людей и дворфов. И для меня большая честь служить проводником вашей воли в Альтераке.\r\n\r\nВо имя Саргераса!\r\n\r\nНагаз,\r\nЖрец Аргуса',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (317,'Дун Модр, Болотина\r\n\r\nДорогая моя Сара!\r\n\r\nСудя по всему, через несколько дней мы сменим позиции, чтобы охранять Мост Тандола. Возможно, я больше не смогу писать тебе. Мне хочется написать несколько строк, которые могут попасться тебе на глаза, когда меня не станет.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дун Модр, Болотина\r\n\r\nДорогая моя Сара!\r\n\r\nСудя по всему, через несколько дней мы сменим позиции, чтобы охранять Мост Тандола. Возможно, я больше не смогу писать тебе. Мне хочется написать несколько строк, которые могут попасться тебе на глаза, когда меня не станет.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (318,'Наш поход может продлиться всего несколько дней и оказаться приятной прогулкой, а может завершиться кровопролитным сражением, в котором я погибну. Если уж мне суждено пасть, сражаясь за Альянс, то я готов.\r\n\r\nМеня не терзают никакие сомнения или колебания, моя храбрость несокрушима.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наш поход может продлиться всего несколько дней и оказаться приятной прогулкой, а может завершиться кровопролитным сражением, в котором я погибну. Если уж мне суждено пасть, сражаясь за Альянс, то я готов.\r\n\r\nМеня не терзают никакие сомнения или колебания, моя храбрость несокрушима.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (319,'Я знаю, насколько судьба королевства Стальгорн зависит от победы или поражения Альянса и насколько велик наш долг перед теми, кто раньше нас прошел через кровь и страдания Великих войн. И я готов полностью отказаться от всех радостей жизни, чтобы помочь поддержать Альянс и вернуть этот долг.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я знаю, насколько судьба королевства Стальгорн зависит от победы или поражения Альянса и насколько велик наш долг перед теми, кто раньше нас прошел через кровь и страдания Великих войн. И я готов полностью отказаться от всех радостей жизни, чтобы помочь поддержать Альянс и вернуть этот долг.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (320,'Сара, моя любовь к тебе бессмертна, она словно связывает меня мощными путами, которые не разорвало бы ничто, кроме Всемогущества. А любовь к королевству подхватывает меня, словно ураган, и необоримо влечет меня вместе со всеми этими цепями на поле боя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сара, моя любовь к тебе бессмертна, она словно связывает меня мощными путами, которые не разорвало бы ничто, кроме Всемогущества. А любовь к королевству подхватывает меня, словно ураган, и необоримо влечет меня вместе со всеми этими цепями на поле боя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (321,'Мне вспоминаются блаженные минуты, проведенные с тобой, и я испытываю огромную благодарность Свету и тебе за то, что наслаждался ими так долго. Но как же тяжело мне отказаться от них и спалить дотла надежды на будущие годы, в которых мы все еще могли бы жить вместе, любить друг друга и смотреть, как наши сыновья растут честными дворфами!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мне вспоминаются блаженные минуты, проведенные с тобой, и я испытываю огромную благодарность Свету и тебе за то, что наслаждался ими так долго. Но как же тяжело мне отказаться от них и спалить дотла надежды на будущие годы, в которых мы все еще могли бы жить вместе, любить друг друга и смотреть, как наши сыновья растут честными дворфами!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (322,'Я знаю, что у меня немного оснований претендовать на благосклонность высших сил, но что-то мне подсказывает – может быть, до меня доносятся молитвы моего маленького Эдгара, – что я вернусь невредимым к тем, кого люблю. Если же я не вернусь, никогда не забывай, моя дорогая Сара, как сильно я любил тебя, и знай, что, умирая на поле боя, с последним вздохом я прошептал твое имя.\r\n\r\nПрости мне мои многочисленные недостатки и всю боль, которую мне случалось тебе причинить. Как бездумен, как глуп я зачастую бывал!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я знаю, что у меня немного оснований претендовать на благосклонность высших сил, но что-то мне подсказывает – может быть, до меня доносятся молитвы моего маленького Эдгара, – что я вернусь невредимым к тем, кого люблю. Если же я не вернусь, никогда не забывай, моя дорогая Сара, как сильно я любил тебя, и знай, что, умирая на поле боя, с последним вздохом я прошептал твое имя.\r\n\r\nПрости мне мои многочисленные недостатки и всю боль, которую мне случалось тебе причинить. Как бездумен, как глуп я зачастую бывал!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (323,'С какой радостью я бы смыл своими собственными слезами малейшее пятнышко на твоем счастье и боролся бы со всеми невзгодами этого мира, чтобы защитить тебя и наших дорогих деток!\r\n\r\nНо я не могу.\r\n\r\nМне придется наблюдать за тобой из Круговерти Пустоты и витать возле тебя, пока ты в одиночку противостоишь всем бурями со своей драгоценной маленькой ношей, выдерживаешь шторм со своим маленьким ценным грузом. Мне придется терпеливо ждать, пока мы встретимся, чтобы больше не расставаться никогда.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С какой радостью я бы смыл своими собственными слезами малейшее пятнышко на твоем счастье и боролся бы со всеми невзгодами этого мира, чтобы защитить тебя и наших дорогих деток!\r\n\r\nНо я не могу.\r\n\r\nМне придется наблюдать за тобой из Круговерти Пустоты и витать возле тебя, пока ты в одиночку противостоишь всем бурями со своей драгоценной маленькой ношей, выдерживаешь шторм со своим маленьким ценным грузом. Мне придется терпеливо ждать, пока мы встретимся, чтобы больше не расставаться никогда.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (325,'Кракен ревел, и его голос гремел, как океанская буря:$B$B"Я явился."$B$BМин\'лот, стоя твердо, призвал свою магию. Волны, посланные в Илалию, разошлись и омыли обе стороны, затопив джунгли за ними. Затем Мин\'лот приказал своим слугам произносить заклинания подчинения, и раздался грохот, и десятки голосов троллей поднялись.$B$BИ один голос возвысился над остальными.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кракен ревел, и его голос гремел, как океанская буря:$B$B"Я явился."$B$BМин\'лот, стоя твердо, призвал свою магию. Волны, посланные в Илалию, разошлись и омыли обе стороны, затопив джунгли за ними. Затем Мин\'лот приказал своим слугам произносить заклинания подчинения, и раздался грохот, и десятки голосов троллей поднялись.$B$BИ один голос возвысился над остальными.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (326,'Мин\'лот взревел, и его магия собрала силу заклинаний его слуг, и он направил её на приближающегося Краккена.$B$BМоре разошлось, и заклинание Мин\'лот устремилось к слугам Нептулона. Молния разорвала небо, и их поразило заклинание, и ударила тысяча молний, заставляя кипеть воду и оставляя горящие кратеры на земле.$B$BМин\'лот торжествующе закричал, зная, что его заклинание падет на огромных зверей. ') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мин\'лот взревел, и его магия собрала силу заклинаний его слуг, и он направил её на приближающегося Краккена.$B$BМоре разошлось, и заклинание Мин\'лот устремилось к слугам Нептулона. Молния разорвала небо, и их поразило заклинание, и ударила тысяча молний, заставляя кипеть воду и оставляя горящие кратеры на земле.$B$BМин\'лот торжествующе закричал, зная, что его заклинание падет на огромных зверей. ',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (327,'Но Кракены старые, очень старые. Они помнили времена, когда земля впервые родилась из моря.$B$BОни помнили, когда правили Древние и когда пришли Странники и низложили их. Они помнили, когда магия была новой.$B$BОни старые и хранят много секретов. И хотя заклинание Мин\'лот было сильным, он был троллем, смертным.$B$BИ поэтому он потерпел неудачу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но Кракены старые, очень старые. Они помнили времена, когда земля впервые родилась из моря.$B$BОни помнили, когда правили Древние и когда пришли Странники и низложили их. Они помнили, когда магия была новой.$B$BОни старые и хранят много секретов. И хотя заклинание Мин\'лот было сильным, он был троллем, смертным.$B$BИ поэтому он потерпел неудачу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (328,'Если не удастся подчинить Краккена, то это его взбесит. Никогда еще ни один смертный не причинял им боли, а заклинание тролля было болезненным.$B$BИ поэтому он сбросил оковы заклинания Минлота, но затем взревел и застыл в ярости.$B$BПослышался грохот, когда огромные волны поднялись из глубины и устремились к земле. Достигнув Илалая, они бросили тень на город.$B$BНо прежде чем его уничтожить, Кракен на мгновение остановился. ') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Если не удастся подчинить Краккена, то это его взбесит. Никогда еще ни один смертный не причинял им боли, а заклинание тролля было болезненным.$B$BИ поэтому он сбросил оковы заклинания Минлота, но затем взревел и застыл в ярости.$B$BПослышался грохот, когда огромные волны поднялись из глубины и устремились к земле. Достигнув Илалая, они бросили тень на город.$B$BНо прежде чем его уничтожить, Кракен на мгновение остановился. ',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (329,'Тролли-знахари задрожали и закричали своему хозяину. Мин\'лот смотрел на горы из морской воды, обреченный и дерзкий. Он повернулся к своим адептам и прошептал, и тролли выгравировали его последние слова на камне. Затем Мин\'лот встретился с приближающимся Кракеном.$B$BОн поморщился и швырнул свой посох - его последний смелый поступок.$B$BЗатем Кракен направил свою ярость на Мин\'лота, и океан обрушился на Илалая.$B$BИ не стало его.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тролли-знахари задрожали и закричали своему хозяину. Мин\'лот смотрел на горы из морской воды, обреченный и дерзкий. Он повернулся к своим адептам и прошептал, и тролли выгравировали его последние слова на камне. Затем Мин\'лот встретился с приближающимся Кракеном.$B$BОн поморщился и швырнул свой посох - его последний смелый поступок.$B$BЗатем Кракен направил свою ярость на Мин\'лота, и океан обрушился на Илалая.$B$BИ не стало его.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (330,'А затем вода упала на джунгли, смывая всех на своём пути. Тролли и звери кричали, когда вода настигала и топила их.$B$BМногие Гурубаши недоумевали, почему океан решил поглотил их, но потом они умерли, так и не поняв этого.$B$BИ, наконец, когда вода достигла гор, она остановилась. Умиротворенная, она отступила за берега и оставила после себя след смерти.$B$BОна отступила, но окружила Илалайа, остановилась, и навсегда поглатила его. ') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','А затем вода упала на джунгли, смывая всех на своём пути. Тролли и звери кричали, когда вода настигала и топила их.$B$BМногие Гурубаши недоумевали, почему океан решил поглотил их, но потом они умерли, так и не поняв этого.$B$BИ, наконец, когда вода достигла гор, она остановилась. Умиротворенная, она отступила за берега и оставила после себя след смерти.$B$BОна отступила, но окружила Илалайа, остановилась, и навсегда поглатила его. ',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (331,'И вождь Вар\'газул, находящийся в безопасности за горами в Зул\'Гурубe, вышел в джунгли и обнаружил, что вода опустошила земли его народа.$B$BИ он отчаялся, потому что его мечты о завоевании не суждено было сбыться.$B$BИ змей Мин\'лот так и не был найден. ') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И вождь Вар\'газул, находящийся в безопасности за горами в Зул\'Гурубe, вышел в джунгли и обнаружил, что вода опустошила земли его народа.$B$BИ он отчаялся, потому что его мечты о завоевании не суждено было сбыться.$B$BИ змей Мин\'лот так и не был найден. ',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (333,'Моему досточтимому королю:\r\n\r\n\'Не пристало скромной жене солдата подвергать сомнению действия великих военачальников, таких как вы. Битвы, бушующие в наших землях, ведутся, чтобы сохранить прекрасную жизнь, которую мы знаем и любим, – от прохладных вод озера Лок Модан до острых заснеженных пиков Дун Морога.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Моему досточтимому королю:\r\n\r\n\'Не пристало скромной жене солдата подвергать сомнению действия великих военачальников, таких как вы. Битвы, бушующие в наших землях, ведутся, чтобы сохранить прекрасную жизнь, которую мы знаем и любим, – от прохладных вод озера Лок Модан до острых заснеженных пиков Дун Морога.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (334,'Но какой ценой должны вестись войны за сохранение жизни? После которой смерти павшего в бою солдата мы поймем, что жизнь, которую мы стремимся спасти, ускользает от нас на поле боя?\r\n\r\nПод сколько мечей и топоров должны мы бросить наше будущее? Под сколькими метрами пропитанной кровью земли должны мы похоронить наше прошлое?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но какой ценой должны вестись войны за сохранение жизни? После которой смерти павшего в бою солдата мы поймем, что жизнь, которую мы стремимся спасти, ускользает от нас на поле боя?\r\n\r\nПод сколько мечей и топоров должны мы бросить наше будущее? Под сколькими метрами пропитанной кровью земли должны мы похоронить наше прошлое?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (336,'Добрый день, Шнайдер!\r\n\r\nНадеюсь, дела в районе каналов идут хорошо. У нас тут, в торговом квартале, большой наплыв покупателей.\r\n\r\nНам нужно побольше вязаной одежды, наши запасы на исходе. Пожалуйста, пришлите мне стандартную партию при первой же возможности.\r\n\r\nУдачи. Надеюсь, занятия вашего сына Тармена тоже продвигаются неплохо. \r\n\r\n--Харлан Багли') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Добрый день, Шнайдер!\r\n\r\nНадеюсь, дела в районе каналов идут хорошо. У нас тут, в торговом квартале, большой наплыв покупателей.\r\n\r\nНам нужно побольше вязаной одежды, наши запасы на исходе. Пожалуйста, пришлите мне стандартную партию при первой же возможности.\r\n\r\nУдачи. Надеюсь, занятия вашего сына Тармена тоже продвигаются неплохо. \r\n\r\n--Харлан Багли',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (337,'Официальный приказ флоту Кул-Тираса\r\n\r\nЯ, адмирал Праудмур, буду лично командовать первой высадкой на берега Калимдора.\r\n\r\nЛейтенант Бенедикт назначается моим заместителем на время моего отсутствия. Все вопросы обороны Кул-Тираса будут решаться им. Если от меня не поступит вестей из крепости Тирагард в течение 12 месяцев, лейтенант Бенедикт возглавит вторую экспедицию, которая должна будет захватить крепость.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Официальный приказ флоту Кул-Тираса\r\n\r\nЯ, адмирал Праудмур, буду лично командовать первой высадкой на берега Калимдора.\r\n\r\nЛейтенант Бенедикт назначается моим заместителем на время моего отсутствия. Все вопросы обороны Кул-Тираса будут решаться им. Если от меня не поступит вестей из крепости Тирагард в течение 12 месяцев, лейтенант Бенедикт возглавит вторую экспедицию, которая должна будет захватить крепость.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (338,'Тем временем я посылаю лейтенанта Элверолда в экспедицию вокруг континента Калимдор. После того как его силы завершат экспедицию, им следует воссоединиться с нашими силами в крепости Тирагард.\r\n\r\nПо расчетам, экспедиция лейтенанта Элверолда должна занять довольно много времени. Новый материк выглядит обширным и опасным. Но если со мной или Бенедиктом стрясется какая-либо беда, войска Элверолда сумеют снова захватить крепость. \r\n\r\nМы будем посылать одну экспедицию за другой, пока Тирагард не станет нашим!\r\n\r\n--Адмирал Праудмур') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тем временем я посылаю лейтенанта Элверолда в экспедицию вокруг континента Калимдор. После того как его силы завершат экспедицию, им следует воссоединиться с нашими силами в крепости Тирагард.\r\n\r\nПо расчетам, экспедиция лейтенанта Элверолда должна занять довольно много времени. Новый материк выглядит обширным и опасным. Но если со мной или Бенедиктом стрясется какая-либо беда, войска Элверолда сумеют снова захватить крепость. \r\n\r\nМы будем посылать одну экспедицию за другой, пока Тирагард не станет нашим!\r\n\r\n--Адмирал Праудмур',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (341,'<HTML>\r\n<BODY>\r\n<H1>Призыв на службу в Орду</H1>\r\n<BR></BR>\r\n<P>Этот человек показал невероятные достижения силы и навыка во имя. Его следует немедленно назначить на работу на Перекресток.</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Почтительно ваш:</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Мне кажется, неплохо.<BR></BR>\r\n- Такрин Торитель Путей</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1>Призыв на службу в Орду</H1>\r\n<BR></BR>\r\n<P>Этот человек показал невероятные достижения силы и навыка во имя. Его следует немедленно назначить на работу на Перекресток.</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Почтительно ваш:</P>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<BR></BR>\r\n<P>Мне кажется, неплохо.<BR></BR>\r\n- Такрин Торитель Путей</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (342,'Раскопки Бейл Модана\r\n\r\nПервая исследовательская команда, отправленная Лигой Исследователей, не ошиблась в своих выводах. Здешняя земля содержит артефакты неограниченной ценности для нашего народа. Без сомнения, под песком и скалами Бейл Модана мы найдем много новых знаний.\r\n\r\nГеология этого региона, однако, заставляет нас прибегать к крайним мерам. Многие из залежей песка затвердели под воздействием суровой погоды и переменчивого климата.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Раскопки Бейл Модана\r\n\r\nПервая исследовательская команда, отправленная Лигой Исследователей, не ошиблась в своих выводах. Здешняя земля содержит артефакты неограниченной ценности для нашего народа. Без сомнения, под песком и скалами Бейл Модана мы найдем много новых знаний.\r\n\r\nГеология этого региона, однако, заставляет нас прибегать к крайним мерам. Многие из залежей песка затвердели под воздействием суровой погоды и переменчивого климата.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (343,'Решение, впрочем, весьма просто. Используя мякоть дерева в качестве адсорбента, мы можем соединить следы нитроглицерина с нитратом натрия, чтобы получить сильный взрывной заряд, способный пробиться даже через самые плотные массы.\r\n\r\nРабота будет шумной и разрушительной, но наши поиски гораздо важнее комфорта местных жителей. На самом деле нам уже пришлось выгнать из этой области стаю рогатых, которые мешали нам.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Решение, впрочем, весьма просто. Используя мякоть дерева в качестве адсорбента, мы можем соединить следы нитроглицерина с нитратом натрия, чтобы получить сильный взрывной заряд, способный пробиться даже через самые плотные массы.\r\n\r\nРабота будет шумной и разрушительной, но наши поиски гораздо важнее комфорта местных жителей. На самом деле нам уже пришлось выгнать из этой области стаю рогатых, которые мешали нам.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (344,'То обстоятельство, что мы здесь имеем дело с различными мошенниками, заставляет меня считать, что нам понадобится поддержка армии короля. Помимо того что раскопки потребуют военной поддержки, на мой неопытный взгляд, Бейл Модана может представлять стратегическую ценность для Альянса, учитывая нестабильность мировой политики в ее текущем состоянии.\r\n\r\nУвы, я отвлекаюсь. Под скалой нужно проделать много работы. Я провел слишком много времени за письмом и недостаточно – за раскопками...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','То обстоятельство, что мы здесь имеем дело с различными мошенниками, заставляет меня считать, что нам понадобится поддержка армии короля. Помимо того что раскопки потребуют военной поддержки, на мой неопытный взгляд, Бейл Модана может представлять стратегическую ценность для Альянса, учитывая нестабильность мировой политики в ее текущем состоянии.\r\n\r\nУвы, я отвлекаюсь. Под скалой нужно проделать много работы. Я провел слишком много времени за письмом и недостаточно – за раскопками...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (354,'Мельницы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мельницы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (367,'они обрели бы вечную жизнь и им было бы незачем бояться грядущего Раскола...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','они обрели бы вечную жизнь и им было бы незачем бояться грядущего Раскола...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (371,'Л. Ф. приказал увеличить давление на дураков из Альянса. Ниже – список материалов, необходимых для важной миссии против Южнобережья:\r\n\r\nнедельные походные рационы для 20 человек\r\n20 черных ночных костюмов\r\n20 новых пар туфель\r\n25 новых мечей\r\n30 метательных ножей\r\n20 черных масок\r\n10 склянок зажигательного масла\r\n50 доз парализующего яда\r\n5 украденных униформ стражников Южнобережья, если есть\r\n100 серебряных монет\r\n\r\n--Барон В..\r\nквартирмейстер.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Л. Ф. приказал увеличить давление на дураков из Альянса. Ниже – список материалов, необходимых для важной миссии против Южнобережья:\r\n\r\nнедельные походные рационы для 20 человек\r\n20 черных ночных костюмов\r\n20 новых пар туфель\r\n25 новых мечей\r\n30 метательных ножей\r\n20 черных масок\r\n10 склянок зажигательного масла\r\n50 доз парализующего яда\r\n5 украденных униформ стражников Южнобережья, если есть\r\n100 серебряных монет\r\n\r\n--Барон В..\r\nквартирмейстер.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (376,'Звезда Ксиль\'и\r\n\r\nОгр в долине Альтерака, Грел\'борг Скряга был последним известным владельцем этого камня, по слухам дававшего своему владельцу умение сообщаться с другими мирами. По нашим сведениям, Грел\'борг бродит по руинам Альтерака в одноименных горах в поисках других реликвий.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Звезда Ксиль\'и\r\n\r\nОгр в долине Альтерака, Грел\'борг Скряга был последним известным владельцем этого камня, по слухам дававшего своему владельцу умение сообщаться с другими мирами. По нашим сведениям, Грел\'борг бродит по руинам Альтерака в одноименных горах в поисках других реликвий.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (377,'Рука Дагуна\r\n\r\nДагун – существо из глубины, которому поклоняются мурлоки в Пылевых топях. Они заманивают его на поверхность при помощи особенных морских водорослей, зачарованных их шаманами. Найди мурлоков, собери их зачарованные водоросли, затем помести его на Алтарь Мурлоков. Дагун придет, когда будешь ждать его.\r\n\r\nМне нужна эта рука.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Рука Дагуна\r\n\r\nДагун – существо из глубины, которому поклоняются мурлоки в Пылевых топях. Они заманивают его на поверхность при помощи особенных морских водорослей, зачарованных их шаманами. Найди мурлоков, собери их зачарованные водоросли, затем помести его на Алтарь Мурлоков. Дагун придет, когда будешь ждать его.\r\n\r\nМне нужна эта рука.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (378,'Сердце Наследия\r\n\r\nСтарые тексты говорят, что тот, кто обладает сердцем Наследия, не боится могилы. Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий. Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул\'Мамве.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сердце Наследия\r\n\r\nСтарые тексты говорят, что тот, кто обладает сердцем Наследия, не боится могилы. Возможно, это правда, ведь владелец сердца, Тролль Могх, известен как Могх Неумирающий. Знахарь клана Дробителей Черепов, Могх, обитает в Тернистой долине на Руинах Зул\'Мамве.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (379,'Принеси мне эти вещи, Звезду, Руку и Сердце, и я дам тебе копию Книги Йагина.\r\n\r\n-Хранитель') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Принеси мне эти вещи, Звезду, Руку и Сердце, и я дам тебе копию Книги Йагина.\r\n\r\n-Хранитель',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (387,'И так он бродил, и так он искал. И его рука оставалась потерянной для него. И так он изрыгал проклятия и рычал при ходьбе. \r\n\r\nНо Гри\'лек давно перестал слушать духов, и они были сердиты на него и не слышали его проклятий.\r\n\r\nГри\'лек был обречен. Обречен бродить без руки.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И так он бродил, и так он искал. И его рука оставалась потерянной для него. И так он изрыгал проклятия и рычал при ходьбе. \r\n\r\nНо Гри\'лек давно перестал слушать духов, и они были сердиты на него и не слышали его проклятий.\r\n\r\nГри\'лек был обречен. Обречен бродить без руки.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (395,'Святилище Мел-Тандрис\r\n\r\n"Пусть свет Элуны вечно озаряет эту долину и освещает пути леса, как было с незапамятных времен".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Святилище Мел-Тандрис\r\n\r\n"Пусть свет Элуны вечно озаряет эту долину и освещает пути леса, как было с незапамятных времен".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (417,'Хорошо, у тебя должны быть заряды и детонаторы NG-5. Я их пометил для тебя... Синий – для лесопилки. Красный – для Рудника Ветрорезов.\r\n\r\nЯ кое-что разведал и выяснил, что на Утесе Ветрорезов достаточно взрывчатки, чтобы тебе не было сложно зайти туда, установить детонаторы и выйти оттуда, перед тем как взрывать.\r\n\\Помни, это отвлекающий маневр. Отойди далеко от вагонов перед тем, как гоблины доберутся туда, чтобы проверить, что случилось, затем проскользни за ними.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хорошо, у тебя должны быть заряды и детонаторы NG-5. Я их пометил для тебя... Синий – для лесопилки. Красный – для Рудника Ветрорезов.\r\n\r\nЯ кое-что разведал и выяснил, что на Утесе Ветрорезов достаточно взрывчатки, чтобы тебе не было сложно зайти туда, установить детонаторы и выйти оттуда, перед тем как взрывать.\r\n\\Помни, это отвлекающий маневр. Отойди далеко от вагонов перед тем, как гоблины доберутся туда, чтобы проверить, что случилось, затем проскользни за ними.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (418,'Кстати, будь осторожен с ними. Один нитромирглицероний сам по себе может разнести тебя в пыль. Я поместил часть жидкости в медные пробирки, которые должны защитить от сотрясений и обеспечить безопасность.\r\n\r\nСвиток, который ты получил от Коллина, я использовал в коробках с детонаторами. Теперь они пошлют бесшумное сообщение зарядам NG-5 когда ты их включишь. Я использовал простой сталтваргонский механизм, чтобы обеспечить оптимальную проводимость проводов и скорость потока нитромирглицерония между разностными жидкостями лучше среднего.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кстати, будь осторожен с ними. Один нитромирглицероний сам по себе может разнести тебя в пыль. Я поместил часть жидкости в медные пробирки, которые должны защитить от сотрясений и обеспечить безопасность.\r\n\r\nСвиток, который ты получил от Коллина, я использовал в коробках с детонаторами. Теперь они пошлют бесшумное сообщение зарядам NG-5 когда ты их включишь. Я использовал простой сталтваргонский механизм, чтобы обеспечить оптимальную проводимость проводов и скорость потока нитромирглицерония между разностными жидкостями лучше среднего.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (419,'Прежде чем я вернусь к подробностям своего плана, давай я объясню тебе, куда поместить взрывчатку.\r\n\r\nПлан альфа – лесопилка:\r\nПеред лесопилкой есть вагончик (это к северо-востоку от места, где они вырубают лес и собирают древесину). Я подозреваю, что инженерные планы находятся внутри лесопилки.\r\n\r\nЧтобы установить заряд, направляйся за вагончик. Установив его, поспеши удалиться на приличное расстояние.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прежде чем я вернусь к подробностям своего плана, давай я объясню тебе, куда поместить взрывчатку.\r\n\r\nПлан альфа – лесопилка:\r\nПеред лесопилкой есть вагончик (это к северо-востоку от места, где они вырубают лес и собирают древесину). Я подозреваю, что инженерные планы находятся внутри лесопилки.\r\n\r\nЧтобы установить заряд, направляйся за вагончик. Установив его, поспеши удалиться на приличное расстояние.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (420,'Когда ты будешь готов, нажми на взрыватель.\r\n\r\nЯ обеспечил сильный сигнал, соединив медные и серебряные провода с рядом мелтузианских антенн внутри коробки. Это должно обеспечить тебе хороший радиус действия. Но будь осторожен с гоблинами, шляющимися поблизости. Они не оценят мое творение, если поймают тебя на своей территории.\r\n\r\nДа, на случай, если это не очевидно, не находись рядом с вагончиком в момент взрыва... будет больно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда ты будешь готов, нажми на взрыватель.\r\n\r\nЯ обеспечил сильный сигнал, соединив медные и серебряные провода с рядом мелтузианских антенн внутри коробки. Это должно обеспечить тебе хороший радиус действия. Но будь осторожен с гоблинами, шляющимися поблизости. Они не оценят мое творение, если поймают тебя на своей территории.\r\n\r\nДа, на случай, если это не очевидно, не находись рядом с вагончиком в момент взрыва... будет больно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (421,'План бета – Рудник Ветрорезов:\r\n\r\nЯ видел, как гоблины используют другой вагончик со взрывчаткой к северу от входа на шахту. Я думаю, поместить заряд NG-5 (красный) там – это хорошая идея. Установив заряд за вагончиком, отойди на какое-то расстояние и нажми на кнопку.\r\n\r\nЕсли гоблины не прибегут, чтобы проверить, что случилось, – скорее всего, это потому, что гора обрушилась им на головы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','План бета – Рудник Ветрорезов:\r\n\r\nЯ видел, как гоблины используют другой вагончик со взрывчаткой к северу от входа на шахту. Я думаю, поместить заряд NG-5 (красный) там – это хорошая идея. Установив заряд за вагончиком, отойди на какое-то расстояние и нажми на кнопку.\r\n\r\nЕсли гоблины не прибегут, чтобы проверить, что случилось, – скорее всего, это потому, что гора обрушилась им на головы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (422,'Документы Торговой Компании снаружи шахты... Я думаю, лежат на каких-нибудь ящиках на нижнем уровне.\r\n\r\nУдачи, и помни...\r\n\r\nСиний заряд – лесопилка\r\nКрасный заряд – шахта\r\n\r\nА, и уничтожь это письмо, после того как выполнишь свое задание. Хм, может быть мне стоит поискать способ заставить эти штуки самоуничтожаться, после того как их прочитают. Это неплохая идея...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Документы Торговой Компании снаружи шахты... Я думаю, лежат на каких-нибудь ящиках на нижнем уровне.\r\n\r\nУдачи, и помни...\r\n\r\nСиний заряд – лесопилка\r\nКрасный заряд – шахта\r\n\r\nА, и уничтожь это письмо, после того как выполнишь свое задание. Хм, может быть мне стоит поискать способ заставить эти штуки самоуничтожаться, после того как их прочитают. Это неплохая идея...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (424,'--День первый--\r\n\r\nНаконец-то я из Стальгорна добрался до Калимдора!\r\n\r\nГеолог Хазгорм из Бейл Модана отлично продвигается. Он сегодня раскопал окаменелость, которую местные ученые считают фрагментом кости древнего бога. Хазгорм уверен, что окаменелость – часть великой загадки. Пока он приглядывает за раскопками, но поручил мне найти еще окаменелостей, чтобы собрать эту историю воедино. \r\n\r\nМое задание: отправиться на юг в поисках дополнительных ключей к тайне.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День первый--\r\n\r\nНаконец-то я из Стальгорна добрался до Калимдора!\r\n\r\nГеолог Хазгорм из Бейл Модана отлично продвигается. Он сегодня раскопал окаменелость, которую местные ученые считают фрагментом кости древнего бога. Хазгорм уверен, что окаменелость – часть великой загадки. Пока он приглядывает за раскопками, но поручил мне найти еще окаменелостей, чтобы собрать эту историю воедино. \r\n\r\nМое задание: отправиться на юг в поисках дополнительных ключей к тайне.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (425,'--День второй--\r\n\r\nСтепи бескрайни. Мой поход был долог и утомителен, но пока что не дал никаких результатов, могущих заинтересовать Лигу Исследователей. \r\n\r\nЕдинственный примечательный инцидент произошел возле Золотого Пути. Вдали я заметил каких-то странных существ. Наполовину свиньи, наполовину люди – так мне показалось. Я быстро спрятался и дал мерзким животным пройти. Ну и вонь они оставили за собой!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День второй--\r\n\r\nСтепи бескрайни. Мой поход был долог и утомителен, но пока что не дал никаких результатов, могущих заинтересовать Лигу Исследователей. \r\n\r\nЕдинственный примечательный инцидент произошел возле Золотого Пути. Вдали я заметил каких-то странных существ. Наполовину свиньи, наполовину люди – так мне показалось. Я быстро спрятался и дал мерзким животным пройти. Ну и вонь они оставили за собой!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (426,'--День третий--\r\n\r\nО, какое великолепное открытие!\r\n\r\nСегодня я нашел потрясающую вещь: массивные останки существа, похожего на кабана. Его череп возвышался надо мной на много ростов. Каждый зуб зверя мог заставить казаться карликом даже... ну, дворфа. Учитывая размер находки, я склонен полагать, что это останки одного из Древних Богов, о которых повествуют предания.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День третий--\r\n\r\nО, какое великолепное открытие!\r\n\r\nСегодня я нашел потрясающую вещь: массивные останки существа, похожего на кабана. Его череп возвышался надо мной на много ростов. Каждый зуб зверя мог заставить казаться карликом даже... ну, дворфа. Учитывая размер находки, я склонен полагать, что это останки одного из Древних Богов, о которых повествуют предания.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (427,'Некоторое время назад в штабе Лиги Исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус. Старикан упоминал такое божество, почитаемое странными эльфами Дарнаса за его, по слухам, бескорыстную натуру...\r\n\r\nБа! Один момент. Я слышу хрюканье за моей палаткой. Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Некоторое время назад в штабе Лиги Исследователей в Стальгорне нам читал лекцию главный археолог Седой Ус. Старикан упоминал такое божество, почитаемое странными эльфами Дарнаса за его, по слухам, бескорыстную натуру...\r\n\r\nБа! Один момент. Я слышу хрюканье за моей палаткой. Наверняка это просто щетинистые вепри пытаются добраться до моего запаса яблок...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (428,'--День 4--\r\n\r\nЯ в плену!\r\n\r\nНужно... писать... быстро. \r\n\r\nНа меня напали свинолюди из племени Иглошкурых. Я думал, что они ведут меня к кабаньим останкам павшего бога. Вместо этого они обогнули окаменелость и направились прямо к западу от гигантского черепа, пересекая Золотой Путь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 4--\r\n\r\nЯ в плену!\r\n\r\nНужно... писать... быстро. \r\n\r\nНа меня напали свинолюди из племени Иглошкурых. Я думал, что они ведут меня к кабаньим останкам павшего бога. Вместо этого они обогнули окаменелость и направились прямо к западу от гигантского черепа, пересекая Золотой Путь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (429,'Меня грубо затащили в какие-то жутко колючие заросли под названием Лабиринты Иглошкурых. Меня бросили в убогую хижину и держали в плену вместе с умирающим ночным эльфом. \r\n\r\nУ меня не осталось ничего, кроме этого дневника, пера и карманных часов... \r\n\r\nКто-то идет...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Меня грубо затащили в какие-то жутко колючие заросли под названием Лабиринты Иглошкурых. Меня бросили в убогую хижину и держали в плену вместе с умирающим ночным эльфом. \r\n\r\nУ меня не осталось ничего, кроме этого дневника, пера и карманных часов... \r\n\r\nКто-то идет...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (430,'--День 5--\r\n\r\nМой товарищ по заключению, ночной эльф, страдает от тяжких ран. Свинолюди долго истязали его хлыстом, и, сдается мне, он уже скоро испустит дух – если, конечно, в этом зловещем месте каким-то чудом не окажется отряда спасателей. Он то теряет, то вновь обретает сознание. Когда он приходит в себя, я пытаюсь поделиться с ним своим скудным запасом воды.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 5--\r\n\r\nМой товарищ по заключению, ночной эльф, страдает от тяжких ран. Свинолюди долго истязали его хлыстом, и, сдается мне, он уже скоро испустит дух – если, конечно, в этом зловещем месте каким-то чудом не окажется отряда спасателей. Он то теряет, то вновь обретает сознание. Когда он приходит в себя, я пытаюсь поделиться с ним своим скудным запасом воды.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (431,'Вчера он впервые сумел заговорить. Он, друид по имени Гералат, послан в эти земли, чтобы проверить слухи о павшем боге-вепре.\r\n\r\nСлабеющим голосом он поведал мне, что считал, будто бы огромный кабаний череп лежит на том самом месте, где великий бог-вепрь Агамагган пал в битве с Пылающим Легионом примерно 10 000 лет тому назад, во время Войны Древних. Земля превратилась в равнину там, где рухнула его массивная туша, а кровь бога-вепря впиталась в почву – и там, куда пала кровь, растут острые шипы...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вчера он впервые сумел заговорить. Он, друид по имени Гералат, послан в эти земли, чтобы проверить слухи о павшем боге-вепре.\r\n\r\nСлабеющим голосом он поведал мне, что считал, будто бы огромный кабаний череп лежит на том самом месте, где великий бог-вепрь Агамагган пал в битве с Пылающим Легионом примерно 10 000 лет тому назад, во время Войны Древних. Земля превратилась в равнину там, где рухнула его массивная туша, а кровь бога-вепря впиталась в почву – и там, куда пала кровь, растут острые шипы...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (432,'Гералат и его помощники хотят найти здесь источник зла. Он сказал мне, что Агамагган почитается за подлинного бога. А почему эта земля кишит зловредными тварями и колкими шипами – вот это тайна.\r\n\r\nЯ хотел узнать у Гералата больше, но он впал в очередное забытье...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гералат и его помощники хотят найти здесь источник зла. Он сказал мне, что Агамагган почитается за подлинного бога. А почему эта земля кишит зловредными тварями и колкими шипами – вот это тайна.\r\n\r\nЯ хотел узнать у Гералата больше, но он впал в очередное забытье...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (433,'--День 6--\r\n\r\nГералату становится хуже.\r\n\r\nСегодня он открыл глаза лишь однажды. Говорил он, превозмогая боль, но вполне ясно. Если мне удастся избежать зловещей судьбы в Лабиринтах Иглошкурых, я должен буду передать Хранителю дорог Фалфинделу в Таланаар, что Чарлга Остробок собирает своих приспешников в южных Степях. Его мощь крепнет с каждым днем. Эту ведьму нужно остановить, пока зло не вышло за пределы Лабиринтов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 6--\r\n\r\nГералату становится хуже.\r\n\r\nСегодня он открыл глаза лишь однажды. Говорил он, превозмогая боль, но вполне ясно. Если мне удастся избежать зловещей судьбы в Лабиринтах Иглошкурых, я должен буду передать Хранителю дорог Фалфинделу в Таланаар, что Чарлга Остробок собирает своих приспешников в южных Степях. Его мощь крепнет с каждым днем. Эту ведьму нужно остановить, пока зло не вышло за пределы Лабиринтов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (434,'Бедный Гералат бледен, точно смерть. Его с каждой минутой лихорадит все сильнее. А свинолюди без устали готовятся к какому-то крупному военному походу. Боюсь, что если я не попытаюсь вскоре бежать, мне будет уготована та же судьба, что и моему сотоварищу эльфу.\r\n\r\nЯ планирую тайком пробраться наружу, когда свинолюди в очередной раз уйдут на охоту. Стражники, охраняющие меня, ленивы и то и дело спят на посту.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Бедный Гералат бледен, точно смерть. Его с каждой минутой лихорадит все сильнее. А свинолюди без устали готовятся к какому-то крупному военному походу. Боюсь, что если я не попытаюсь вскоре бежать, мне будет уготована та же судьба, что и моему сотоварищу эльфу.\r\n\r\nЯ планирую тайком пробраться наружу, когда свинолюди в очередной раз уйдут на охоту. Стражники, охраняющие меня, ленивы и то и дело спят на посту.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (435,'Покинув Лабиринты, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас. Там я найду друида, известного как Хранитель дорог Фалфиндел.\r\n\r\nПытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее. Теперь в моих руках – безопасность всего Альянса...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Покинув Лабиринты, я направлюсь в Тысячу Игл, а затем на запад в сторону Таланаара, к границе с таинственным лесом Фералас. Там я найду друида, известного как Хранитель дорог Фалфиндел.\r\n\r\nПытаясь узнать прошлое моего народа, я, кажется, наткнулся на что-то большее. Теперь в моих руках – безопасность всего Альянса...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (436,'НОМЕР ЗАКАЗА: 45TK-3\r\nПОКУПАТЕЛЬ: Крейвел Угольная Борода\r\n\r\nНАКЛАДНАЯ:\r\n\r\nГидромеханизмы (3)\r\nУсилительные болты (50)\r\n30-дюймовая медная труба калибра 20 (12)\r\nТабак марки Темная Ярость (1)\r\nВысококачественная призма (3)') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','НОМЕР ЗАКАЗА: 45TK-3\r\nПОКУПАТЕЛЬ: Крейвел Угольная Борода\r\n\r\nНАКЛАДНАЯ:\r\n\r\nГидромеханизмы (3)\r\nУсилительные болты (50)\r\n30-дюймовая медная труба калибра 20 (12)\r\nТабак марки Темная Ярость (1)\r\nВысококачественная призма (3)',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (440,'Г-н Шипучка!\r\n\r\nНапиток, который вы дали моему помощнику, возымел большой успех. Мало того что он крепок и сильно затуманивает разум, он, похоже, еще и вызывает привыкание. Уверен: те, кто его отведали, будут просить добавки.\r\n\r\nМы в долгу перед вами, Кранк.\r\n\r\nТакже приглашаю вас посетить Мерцающую равнину либо послать свое доверенное лицо, дабы воспользоваться нашими новыми возможностями в азартных играх.\r\n\r\n--Крейвел') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Г-н Шипучка!\r\n\r\nНапиток, который вы дали моему помощнику, возымел большой успех. Мало того что он крепок и сильно затуманивает разум, он, похоже, еще и вызывает привыкание. Уверен: те, кто его отведали, будут просить добавки.\r\n\r\nМы в долгу перед вами, Кранк.\r\n\r\nТакже приглашаю вас посетить Мерцающую равнину либо послать свое доверенное лицо, дабы воспользоваться нашими новыми возможностями в азартных играх.\r\n\r\n--Крейвел',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (447,'Я долго исследовал Аспекты и их создателей-титанов – так долго, насколько хватит человеческой жизни. Когда титаны покинули этот мир, Аспектов насчитывалось пять; это были могучие драконы, в задачи которых входила защита мира Азерота. О них сложено множество разных историй, и даже сейчас, когда я собрал множество сведений, я знаю, что нам еще очень многое предстоит узнать об этих величественных существах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я долго исследовал Аспекты и их создателей-титанов – так долго, насколько хватит человеческой жизни. Когда титаны покинули этот мир, Аспектов насчитывалось пять; это были могучие драконы, в задачи которых входила защита мира Азерота. О них сложено множество разных историй, и даже сейчас, когда я собрал множество сведений, я знаю, что нам еще очень многое предстоит узнать об этих величественных существах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (450,'Самому мне, наверное, никогда не удалось бы достичь нынешних вершин знания. Я очень благодарен ночным эльфам: без них я мало что сумел бы узнать. Из своего опыта могу заключить, что Аспекты значат для них много больше, чем я предполагал. Однако ночные эльфы бережно оберегают свои тайны, и даже я не могу быть до конца уверен в своей правоте.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Самому мне, наверное, никогда не удалось бы достичь нынешних вершин знания. Я очень благодарен ночным эльфам: без них я мало что сумел бы узнать. Из своего опыта могу заключить, что Аспекты значат для них много больше, чем я предполагал. Однако ночные эльфы бережно оберегают свои тайны, и даже я не могу быть до конца уверен в своей правоте.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (451,'То, что я узнал об Аспектах, я привожу здесь для того, чтобы на это могли ссылаться другие. Я знаю, что от моих изысканий будет польза и что эти драконы со временем еще во многом повлияют на наш мир.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','То, что я узнал об Аспектах, я привожу здесь для того, чтобы на это могли ссылаться другие. Я знаю, что от моих изысканий будет польза и что эти драконы со временем еще во многом повлияют на наш мир.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (452,'Алекстраза:\r\nАлекстраза, древняя и могущественная царица драконов, была названа титанами Связующей Жизнь. Ее первую создали титаны для защиты мира после их ухода. Говорят, что она видела зарождение всех народов в мире Азерота. Предводительствуемые ею красные драконы, известные своим гордым нравом, некогда правили всем остальным драконьим племенем.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Алекстраза:\r\nАлекстраза, древняя и могущественная царица драконов, была названа титанами Связующей Жизнь. Ее первую создали титаны для защиты мира после их ухода. Говорят, что она видела зарождение всех народов в мире Азерота. Предводительствуемые ею красные драконы, известные своим гордым нравом, некогда правили всем остальным драконьим племенем.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (453,'Среди ночных эльфов ходят слухи, будто Алекстраза и полубог Кенарий были близкими друзьями и будто именно Кенарий призвал ее во время первого вторжения Пылающего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Среди ночных эльфов ходят слухи, будто Алекстраза и полубог Кенарий были близкими друзьями и будто именно Кенарий призвал ее во время первого вторжения Пылающего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (454,'Изера:\r\nИзера Спящая представляет подсознание смертных. Она олицетворяет Изумрудный Сон... Она благоволит к искусствам и амбициям смертных народов, но в то же время считает, как и все ее драконы, что настоящий мир – это лишь иллюзия. Изера – одно из самых могучих и грациозных созданий, которое только может узреть смертный.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Изера:\r\nИзера Спящая представляет подсознание смертных. Она олицетворяет Изумрудный Сон... Она благоволит к искусствам и амбициям смертных народов, но в то же время считает, как и все ее драконы, что настоящий мир – это лишь иллюзия. Изера – одно из самых могучих и грациозных созданий, которое только может узреть смертный.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (455,'Малигос:\r\nМалигос известен как Управитель или хранитенль магии. Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию. Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Малигос:\r\nМалигос известен как Управитель или хранитенль магии. Его естественное обличье не типично для драконов, и говорят, что он может изменять свой внешний вид по желанию. Его редко видят после ухода далеко на север, а если и видят, то чаще всего в образе насекомоподобного создания, но, принимая форму драконов, он и его сородичи отливают различными оттенками синего цвета.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (456,'Ноздорму:\r\nНоздорму известен как Хозяин Времени и Вневременный. Он и его драконы – бронзового цвета, показывают большую сметливость во всем. Внимание Ноздорму всегда привлекают артефакты прошлого, ведь о нынешних делах смертных народов, как и о замыслах его сотоварищей-Аспектов, он особо не заботится. Но его безразличие к задумкам других не означает, что он не уделяет внимания событиям, происходящим в мире.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ноздорму:\r\nНоздорму известен как Хозяин Времени и Вневременный. Он и его драконы – бронзового цвета, показывают большую сметливость во всем. Внимание Ноздорму всегда привлекают артефакты прошлого, ведь о нынешних делах смертных народов, как и о замыслах его сотоварищей-Аспектов, он особо не заботится. Но его безразличие к задумкам других не означает, что он не уделяет внимания событиям, происходящим в мире.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (457,'Бронзовые драконы, что считаются защитниками, склонны обитать в обжитых местах. Вневременный и все его племя по натуре своей очень терпеливы и всегда обдумают все заранее, прежде чем действовать. Ноздорму неизменно будет защищать нормальное течение времени, а также и смертные народы, если им будут угрожать могущественные враги.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Бронзовые драконы, что считаются защитниками, склонны обитать в обжитых местах. Вневременный и все его племя по натуре своей очень терпеливы и всегда обдумают все заранее, прежде чем действовать. Ноздорму неизменно будет защищать нормальное течение времени, а также и смертные народы, если им будут угрожать могущественные враги.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (458,'Нелтарион:\r\nНелтарион, названный при рождении Землестражем, был предан Азероту сильнее, чем кто-либо из другой из Аспектов. Его черные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов. До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость. Интересно знать, причастны ли этой порче, которой подвергся великий черный дракон, Древние Боги.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нелтарион:\r\nНелтарион, названный при рождении Землестражем, был предан Азероту сильнее, чем кто-либо из другой из Аспектов. Его черные драконы создали горы и прочие возвышенности, включая и границы между землями смертных народов. До сих пор неизвестно, что толкнуло его в пучину зла: внешнее ли влияние, внутренняя ли слабость. Интересно знать, причастны ли этой порче, которой подвергся великий черный дракон, Древние Боги.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (459,'Черный дракон прошел через полное преображение, после чего Нелтариона уже не существовало. Он стал Смертокрылом – злобным и яростным созданием. Он больше не был Землестражем в глазах Высших эльфов, теперь, вместо имени, данному ему титанами, его стали называть Аспектом Смерти и Заккасом. Смертокрыл – воплощение зла и хаоса, вечно алчущее разрушения. Возможно, он – первое зло Азерота, что появилось после изгнания Древних Богов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Черный дракон прошел через полное преображение, после чего Нелтариона уже не существовало. Он стал Смертокрылом – злобным и яростным созданием. Он больше не был Землестражем в глазах Высших эльфов, теперь, вместо имени, данному ему титанами, его стали называть Аспектом Смерти и Заккасом. Смертокрыл – воплощение зла и хаоса, вечно алчущее разрушения. Возможно, он – первое зло Азерота, что появилось после изгнания Древних Богов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (507,'--День 13\r\nДвижение войск у Терамора усилилось. Крупные отряды людей оставили город и спешно идут на запад.\r\n\r\n--День 14\r\nИз города уходят все новые отряды. Я проследил за одной маленькой группой и видел, как все в ней сняли униформу, удалившись от Терамора на расстояние полета стрелы. Может быть, они дезертиры?\r\n\r\n--День 15\r\nСегодня я слышал, как солдаты в Тераморе говорили о часовых, оставляющих посты. Должно быть, мои подозрения о дезертирах верны') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 13\r\nДвижение войск у Терамора усилилось. Крупные отряды людей оставили город и спешно идут на запад.\r\n\r\n--День 14\r\nИз города уходят все новые отряды. Я проследил за одной маленькой группой и видел, как все в ней сняли униформу, удалившись от Терамора на расстояние полета стрелы. Может быть, они дезертиры?\r\n\r\n--День 15\r\nСегодня я слышал, как солдаты в Тераморе говорили о часовых, оставляющих посты. Должно быть, мои подозрения о дезертирах верны',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (528,'Йорген, мои худшие ожидания оправдались, сбылось то, чего я и представить не мог. Я никогда не думал, что они подберутся так близко, но это случилось. \r\n\r\nПожалуйста, помоги подателю сего письма и отправь его к НЕМУ. Откровенно говоря, я думаю, что он поможет нам из-за серьезности этого дела. Если бы нам грозило что-то другое, он, возможно, так и не обратил бы внимания на нас и на проблемы нашего славного города.\r\n\r\nСпасибо тебе, старый рыбак. Я, как обычно, у тебя в долгу.\r\n\r\nТвой друг \r\n Делавей') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Йорген, мои худшие ожидания оправдались, сбылось то, чего я и представить не мог. Я никогда не думал, что они подберутся так близко, но это случилось. \r\n\r\nПожалуйста, помоги подателю сего письма и отправь его к НЕМУ. Откровенно говоря, я думаю, что он поможет нам из-за серьезности этого дела. Если бы нам грозило что-то другое, он, возможно, так и не обратил бы внимания на нас и на проблемы нашего славного города.\r\n\r\nСпасибо тебе, старый рыбак. Я, как обычно, у тебя в долгу.\r\n\r\nТвой друг \r\n Делавей',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (547,'Капитан, удачи тебе в путешествиях. К несчастью, в первой нашей попытке похищения удача нам не благоволила.\r\n\r\nКогда наша команда вышла на объект в тоннеле между Штормградом и Стальгорном, она обнаружила там лишь приманку. Очевидно, он куда умнее, чем мы о нем думаем.\r\n\r\nНо теперь уже задействован наш второй план. Агенты Братства Справедливости готовятся захватить объект, как только он приблизится к Терамору. Скоро в Штормграде узнают, как мы умеем кусаться...\r\n\r\n-М') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Капитан, удачи тебе в путешествиях. К несчастью, в первой нашей попытке похищения удача нам не благоволила.\r\n\r\nКогда наша команда вышла на объект в тоннеле между Штормградом и Стальгорном, она обнаружила там лишь приманку. Очевидно, он куда умнее, чем мы о нем думаем.\r\n\r\nНо теперь уже задействован наш второй план. Агенты Братства Справедливости готовятся захватить объект, как только он приблизится к Терамору. Скоро в Штормграде узнают, как мы умеем кусаться...\r\n\r\n-М',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (548,'--День 16\r\nУлег и Таргил вернулись с задания в доках Терамора. В порту они видели новый корабль – "Бешеный Воробей". Корабль прибыл из Гавани Менетилов.\r\n\r\nЗавтра Улег и Таргил вернутся в доки и прокрадутся на корабль. Они надеются найти там политические документы, раскрывающие отношения Терамора и Альянса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 16\r\nУлег и Таргил вернулись с задания в доках Терамора. В порту они видели новый корабль – "Бешеный Воробей". Корабль прибыл из Гавани Менетилов.\r\n\r\nЗавтра Улег и Таргил вернутся в доки и прокрадутся на корабль. Они надеются найти там политические документы, раскрывающие отношения Терамора и Альянса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (578,'Благой Пантеон, желающий оградить свои упорядоченные миры от всякого зла, зорко наблюдал за действиями темных сил Круговерти Пустоты. Там, в неосязаемом мире неупорядоченных магических энергий, соединяющем мириады миров во Вселенной, обитали неисчислимые множества зловредных демонических существ, жаждавших лишь умерщвления и пожирания всего сущего в мирах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Благой Пантеон, желающий оградить свои упорядоченные миры от всякого зла, зорко наблюдал за действиями темных сил Круговерти Пустоты. Там, в неосязаемом мире неупорядоченных магических энергий, соединяющем мириады миров во Вселенной, обитали неисчислимые множества зловредных демонических существ, жаждавших лишь умерщвления и пожирания всего сущего в мирах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (579,'--День 17\r\nУлег вернулся с задания. Он потерпел неудачу, а Таргил попал в плен. Я послал Улега доставить это сообщение Назиру.\r\n\r\nЯ останусь здесь. Я видел, что от побережья Терамора все чаще отходят корабли. Продолжу вести наблюдение и буду лично сообщать о всяком заслуживающем упоминания событии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','--День 17\r\nУлег вернулся с задания. Он потерпел неудачу, а Таргил попал в плен. Я послал Улега доставить это сообщение Назиру.\r\n\r\nЯ останусь здесь. Я видел, что от побережья Терамора все чаще отходят корабли. Продолжу вести наблюдение и буду лично сообщать о всяком заслуживающем упоминания событии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (582,'Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши союзники. Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши союзники. Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (606,'Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши "союзники". Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нападение произойдет за несколько миль до места прибытия. Именно там будут ожидать наши "союзники". Я не вполне понимаю, почему нам пришлось объединиться с этими созданиями, и меня не покидает ощущение, что союз этот – вынужденный. Но это, в общем-то, не важно. Захватив объект, мы сделаем большой шаг к тому, чтобы отобрать Штормград у тех, кто его у нас отнял!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (607,'Мастер Длиннобородый, как тебе известно, мы в клане Грозовой Вершины разбираемся в отличной работе, так что качество твоих щитов для нас не новость.\r\n\r\nИменно поэтому я хотел бы заказать у тебя щит. Описание его я привожу на следующей странице:') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мастер Длиннобородый, как тебе известно, мы в клане Грозовой Вершины разбираемся в отличной работе, так что качество твоих щитов для нас не новость.\r\n\r\nИменно поэтому я хотел бы заказать у тебя щит. Описание его я привожу на следующей странице:',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (627,'Опустошительная Вторая война против орочьей орды оставила Альянс Лордерона в потрясении и беспорядке. Кровожадные орки, которых возглавлял могущественный вождь, Оргрим Молот Рока, не только силой проложили себе путь через дворфийские земли Каз Модана, но и стерли с лица земли множество центральных провинций Лордерона. Жестокие орки разграбили даже\r\nотдаленное эльфийское королевство Кель\'Талас, прежде чем их разрушительный поход был остановлен.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Опустошительная Вторая война против орочьей орды оставила Альянс Лордерона в потрясении и беспорядке. Кровожадные орки, которых возглавлял могущественный вождь, Оргрим Молот Рока, не только силой проложили себе путь через дворфийские земли Каз Модана, но и стерли с лица земли множество центральных провинций Лордерона. Жестокие орки разграбили даже\r\nотдаленное эльфийское королевство Кель\'Талас, прежде чем их разрушительный поход был остановлен.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (629,'В последней отчаянной попытке Молот Рока и его командиры храбро ринулись в атаку с Пика и схлестнулись с паладинами Лотара прямо посреди Пылающих степей. Молот Рока и Лотар сошлись в яростном бою, который изрядно измотал обоих могучих бойцов. И хотя Оргрим в итоге смог одолеть Лотара, смерть прославленного героя не возымела того эффекта, на который надеялся орочий вождь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В последней отчаянной попытке Молот Рока и его командиры храбро ринулись в атаку с Пика и схлестнулись с паладинами Лотара прямо посреди Пылающих степей. Молот Рока и Лотар сошлись в яростном бою, который изрядно измотал обоих могучих бойцов. И хотя Оргрим в итоге смог одолеть Лотара, смерть прославленного героя не возымела того эффекта, на который надеялся орочий вождь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (630,'Туралион, наиболее приближенный к Лотару командир, поднял его окровавленный щит и призвал своих пораженных горем собратьев нанести со всей яростью ответный удар. Под истрепанными знаменами Лордерона и Азерота воинство Туралиона разбило почти всю армию Молота Рока в славной, но жестокой сече.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Туралион, наиболее приближенный к Лотару командир, поднял его окровавленный щит и призвал своих пораженных горем собратьев нанести со всей яростью ответный удар. Под истрепанными знаменами Лордерона и Азерота воинство Туралиона разбило почти всю армию Молота Рока в славной, но жестокой сече.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (632,'Орки, уступавшие противнику числом и обезумевшие от собственной жажды крови, пали пред гневом Альянса. Молот Рока был взят в плен и препровожден обратно в Лордерон, как и его разбитые кланы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орки, уступавшие противнику числом и обезумевшие от собственной жажды крови, пали пред гневом Альянса. Молот Рока был взят в плен и препровожден обратно в Лордерон, как и его разбитые кланы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (633,'Всего через несколько месяцев после завершения строительства Крепости Стражей Пустоты вся энергия Темного портала слилась воедино и открылся новый проход на Дренор. Оставшиеся кланы орков под предводительством старого шамана Нер\'зула вновь напали на Азерот. Собираясь украсть ряд магических артефактов, которые должны были увеличить могущество Нер\'зула, орки планировали открыть несколько новых порталов на Дреноре, которые позволили бы им навсегда покинуть свой обреченный мир.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Всего через несколько месяцев после завершения строительства Крепости Стражей Пустоты вся энергия Темного портала слилась воедино и открылся новый проход на Дренор. Оставшиеся кланы орков под предводительством старого шамана Нер\'зула вновь напали на Азерот. Собираясь украсть ряд магических артефактов, которые должны были увеличить могущество Нер\'зула, орки планировали открыть несколько новых порталов на Дреноре, которые позволили бы им навсегда покинуть свой обреченный мир.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (635,'Чудовищные магические штормы, вызванные скапливающейся энергией портала, начали разрывать опустошенный мир на части. Нер\'зул, за которым пошли лишь самые преданные его слуги, смог убежать через один такой портал, пока Кадгар отчаянно сражался, чтобы вернуть своих товарищей в Азерот. Поняв, что они окажутся в ловушке в этом гибнущем мире, Кадгар и его спутники приняли самоотверженное решение уничтожить Темный портал, чтобы Азерот не пострадал от кошмарного разрушения Дренора.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Чудовищные магические штормы, вызванные скапливающейся энергией портала, начали разрывать опустошенный мир на части. Нер\'зул, за которым пошли лишь самые преданные его слуги, смог убежать через один такой портал, пока Кадгар отчаянно сражался, чтобы вернуть своих товарищей в Азерот. Поняв, что они окажутся в ловушке в этом гибнущем мире, Кадгар и его спутники приняли самоотверженное решение уничтожить Темный портал, чтобы Азерот не пострадал от кошмарного разрушения Дренора.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (636,'Конечно, героям удалось разрушить портал и спасти Азерот, но сумели ли они выжить среди предсмертных мук Дренора – остается загадкой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Конечно, героям удалось разрушить портал и спасти Азерот, но сумели ли они выжить среди предсмертных мук Дренора – остается загадкой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (646,'Хотя Азшара вместе с ее высокорожденными понимали, что при безответственном обхождении такая магия может быть опасна, они начали практиковать ее с неуемной страстью. Кенарий и многие из ночных эльфов-мудрецов предупреждали, что безрассудство при обращении со столь неуловимой магической силой неизбежно грозит бедой. Но Азшара и ее последователи упрямо продолжали усиливать свое растущее могущество.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя Азшара вместе с ее высокорожденными понимали, что при безответственном обхождении такая магия может быть опасна, они начали практиковать ее с неуемной страстью. Кенарий и многие из ночных эльфов-мудрецов предупреждали, что безрассудство при обращении со столь неуловимой магической силой неизбежно грозит бедой. Но Азшара и ее последователи упрямо продолжали усиливать свое растущее могущество.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (647,'По мере того как могущество Высокорожденных и самой Азшары росло, в их характере наметились явственные изменения. И без того высокомерные и холодные, представители высшего класса становились все более чванливыми и жестокими по отношению к соплеменникам. Некогда завораживающую красоту Азшары окутал темный покров. Она начала отдаляться от любящих подданных и не хотела общаться ни с кем, кроме своих доверенных жрецов из числа Высокорожденных.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','По мере того как могущество Высокорожденных и самой Азшары росло, в их характере наметились явственные изменения. И без того высокомерные и холодные, представители высшего класса становились все более чванливыми и жестокими по отношению к соплеменникам. Некогда завораживающую красоту Азшары окутал темный покров. Она начала отдаляться от любящих подданных и не хотела общаться ни с кем, кроме своих доверенных жрецов из числа Высокорожденных.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (649,'-Идеально круглый, от центра до края – локоть длины.\r\n\r\n-По краю – заклепки. Серебряные.\r\n\r\n-В центре – большой шип, диаметр основания – три пальца. Серебряный.\r\n\r\n-Сам щит из дуба, укрепленный железом.\r\n\r\n-На наружном ободе выгравировать мое имя – Грингер Грозовая Вершина.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','-Идеально круглый, от центра до края – локоть длины.\r\n\r\n-По краю – заклепки. Серебряные.\r\n\r\n-В центре – большой шип, диаметр основания – три пальца. Серебряный.\r\n\r\n-Сам щит из дуба, укрепленный железом.\r\n\r\n-На наружном ободе выгравировать мое имя – Грингер Грозовая Вершина.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (650,'Оплата будет произведена обычным способом. И расплатись с подателем сего письма за доставку. Эти деньги можешь прибавить к цене щита.\r\n\r\nПремного тебе благодарен,\r\n--Грингер Грозовая Вершина.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Оплата будет произведена обычным способом. И расплатись с подателем сего письма за доставку. Эти деньги можешь прибавить к цене щита.\r\n\r\nПремного тебе благодарен,\r\n--Грингер Грозовая Вершина.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (669,'Козни нежити на земле Азерота начались не с падения принца Артаса, они начались задолго до того, как и события, вызвавшие падение Лордерона. Началом всему послужило пришествие орочьих кланов и Пылающего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Козни нежити на земле Азерота начались не с падения принца Артаса, они начались задолго до того, как и события, вызвавшие падение Лордерона. Началом всему послужило пришествие орочьих кланов и Пылающего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (670,'Орки Дренора (мира, из которого они изначально пришли) были благородными и стремились к знаниям. Они были могучими воинами, сильными телом и душой. Именно поэтому их упорно разыскивал Пылающий Легион. Кил\'джеден, демон великой мощи из рядов Легиона, возжаждал поработить орочьи кланы и напустить их полчища на те миры, которые еще только предстояло покорить Пылающему Легиону.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орки Дренора (мира, из которого они изначально пришли) были благородными и стремились к знаниям. Они были могучими воинами, сильными телом и душой. Именно поэтому их упорно разыскивал Пылающий Легион. Кил\'джеден, демон великой мощи из рядов Легиона, возжаждал поработить орочьи кланы и напустить их полчища на те миры, которые еще только предстояло покорить Пылающему Легиону.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (671,'Кил\'джеден пришел к предводителю кланов, могучему шаману по имени Нер\'зул. Он пообещал ему необычайную мощь и мудрость, если тот заключит с демоном пакт, который отдаст кланы во власть Пылающего Легиона. Этот пакт предопределил не только судьбу орков, но и судьбу всего их мира.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден пришел к предводителю кланов, могучему шаману по имени Нер\'зул. Он пообещал ему необычайную мощь и мудрость, если тот заключит с демоном пакт, который отдаст кланы во власть Пылающего Легиона. Этот пакт предопределил не только судьбу орков, но и судьбу всего их мира.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (672,'Со временем Нер\'зул осознал, что судьба кланов – в руках Пылающего Легиона, и тогда шаман бросил вызов Кил\'джедену. Демон, разъяренный поступком Нер\'зула, обратился к ученику шамана, Гул\'дану, склонить которого ко злу оказалось куда проще, чем Нер\'зула.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Со временем Нер\'зул осознал, что судьба кланов – в руках Пылающего Легиона, и тогда шаман бросил вызов Кил\'джедену. Демон, разъяренный поступком Нер\'зула, обратился к ученику шамана, Гул\'дану, склонить которого ко злу оказалось куда проще, чем Нер\'зула.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (673,'Именно Гул\'дан повинен в том, что шаманские знания в кланах пошли на убыль. Он обещал всем могущество и власть над врагами, и его охотно слушали. С помощью Кил\'джедена Гул\'дан начал манипулировать кланами. Орки, некогда благородные, превратились в злобных и неразумных дикарей. Когда же в их жилы попала кровь демонов, орки стали еще более безжалостными и одержимыми.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Именно Гул\'дан повинен в том, что шаманские знания в кланах пошли на убыль. Он обещал всем могущество и власть над врагами, и его охотно слушали. С помощью Кил\'джедена Гул\'дан начал манипулировать кланами. Орки, некогда благородные, превратились в злобных и неразумных дикарей. Когда же в их жилы попала кровь демонов, орки стали еще более безжалостными и одержимыми.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (674,'Хотя Кил\'джедену удалось склонить к себе Гул\'дана после неудачи с Нер\'зулом, он по-прежнему ненавидел шамана и поклялся заставить его принять тот самый пакт. Кил\'джеден захватил Нер\'зула и начал истязать шамана невыносимой медленной пыткой. Нер\'зул молил о смерти, а Кил\'джеден все напоминал ему о пакте. Затем Кил\'джеден убил орка, но умертвил при этом лишь его тело. Душу орочьего шамана Кил\'джеден удерживал, пока она не нашла свой путь в Круговерть Пустоты.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя Кил\'джедену удалось склонить к себе Гул\'дана после неудачи с Нер\'зулом, он по-прежнему ненавидел шамана и поклялся заставить его принять тот самый пакт. Кил\'джеден захватил Нер\'зула и начал истязать шамана невыносимой медленной пыткой. Нер\'зул молил о смерти, а Кил\'джеден все напоминал ему о пакте. Затем Кил\'джеден убил орка, но умертвил при этом лишь его тело. Душу орочьего шамана Кил\'джеден удерживал, пока она не нашла свой путь в Круговерть Пустоты.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (675,'Кил\'джеден поместил душу Нер\'зула в ледяную глыбу, принесенную из Круговерти Пустоты, и наделил ее еще большим могуществом. Потеря телесной оболочки и обладание невероятной силой привели к перевоплощению Нер\'зула.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден поместил душу Нер\'зула в ледяную глыбу, принесенную из Круговерти Пустоты, и наделил ее еще большим могуществом. Потеря телесной оболочки и обладание невероятной силой привели к перевоплощению Нер\'зула.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (676,'Кил\'джеден бросил в Азерот через иные измерения глыбу льда, и она упала на континенте Нордскол, принеся в наш мир великое зло. Нер\'зул исчез навсегда, вместо него там образовался Ледяной Трон, средоточие ненависти. Некогда уважаемый предводитель шаманов стал невероятно могущественным королем-личом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден бросил в Азерот через иные измерения глыбу льда, и она упала на континенте Нордскол, принеся в наш мир великое зло. Нер\'зул исчез навсегда, вместо него там образовался Ледяной Трон, средоточие ненависти. Некогда уважаемый предводитель шаманов стал невероятно могущественным королем-личом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (677,'Поскольку Кил\'джеден не доверял Королю-личу, он послал своих Повелителей ужаса надзирать за духом и следить, чтобы тот выполнял его приказания. Его слуги-вампиры охотно отправились в Азерот, их влекла мощь и ярость Короля-лича, а также возможность изничтожить население целой планеты.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Поскольку Кил\'джеден не доверял Королю-личу, он послал своих Повелителей ужаса надзирать за духом и следить, чтобы тот выполнял его приказания. Его слуги-вампиры охотно отправились в Азерот, их влекла мощь и ярость Короля-лича, а также возможность изничтожить население целой планеты.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (678,'Прошло больше десяти лет. За это время Король-лич использовал свою огромную мощь, чтобы обрести власть над умами обитателей Нордскола, и повелел им возвести огромную цитадель над его Ледяным Троном. Теперь, когда под его началом был весь Нордскол, Король-лич понял, что настала пора вторгнуться в Лордерон. Находясь в ледяном плену, бывший орочий шаман начал обдумывать новые способы захвата власти. Его призыв достиг всех земель.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прошло больше десяти лет. За это время Король-лич использовал свою огромную мощь, чтобы обрести власть над умами обитателей Нордскола, и повелел им возвести огромную цитадель над его Ледяным Троном. Теперь, когда под его началом был весь Нордскол, Король-лич понял, что настала пора вторгнуться в Лордерон. Находясь в ледяном плену, бывший орочий шаман начал обдумывать новые способы захвата власти. Его призыв достиг всех земель.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (679,'Призывы Короля-лича не остались незамеченными, особенно в небольшой группе могущественных личностей. Среди них был верховный маг Кел\'Тузад, влиятельный участник правящего круга Даларана, Кирин-Тора. Его стремление овладеть всеми видами волшебства нарушало правила Кирин-Тора, возбраняющие практиковаться в черной магии. Кел\'Тузад оставил Кирин-Тор, порвал все связи с обычным миром и поклялся стать прилежным учеником Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Призывы Короля-лича не остались незамеченными, особенно в небольшой группе могущественных личностей. Среди них был верховный маг Кел\'Тузад, влиятельный участник правящего круга Даларана, Кирин-Тора. Его стремление овладеть всеми видами волшебства нарушало правила Кирин-Тора, возбраняющие практиковаться в черной магии. Кел\'Тузад оставил Кирин-Тор, порвал все связи с обычным миром и поклялся стать прилежным учеником Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (680,'Двое заключили между собой пакт. Кел\'Тузад получил бессмертие и великую силу в обмен на верность Королю-личу. Перво-наперво он должен был употребить в Лордероне все свое богатство и влияние, чтобы основать там Культ Проклятых. Этот культ обещал всем своим приверженцам равенство и вечную жизнь, если они присягнут на верность Нер\'зулу, богу Культа Проклятых.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Двое заключили между собой пакт. Кел\'Тузад получил бессмертие и великую силу в обмен на верность Королю-личу. Перво-наперво он должен был употребить в Лордероне все свое богатство и влияние, чтобы основать там Культ Проклятых. Этот культ обещал всем своим приверженцам равенство и вечную жизнь, если они присягнут на верность Нер\'зулу, богу Культа Проклятых.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (681,'Затем Нер\'зул создал артефакты, чтобы распространить чуму среди народов Лордерона. Он отдал их Кел\'Тузаду и повелел волшебнику разнести их по земле. А служителям своего культа приказал защищать артефакты любой ценой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Затем Нер\'зул создал артефакты, чтобы распространить чуму среди народов Лордерона. Он отдал их Кел\'Тузаду и повелел волшебнику разнести их по земле. А служителям своего культа приказал защищать артефакты любой ценой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (682,'Потом чума начала заполонять страну и заражать ее ничего не подозревающих обитателей. Под присмотром Кел\'Тузада войско Короля-лича быстро росло, и вскоре тот подчинил себе обширные земли. Это войско стало известным под именем Плеть, и единственной его целью было истребление всех жителей Азерота.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Потом чума начала заполонять страну и заражать ее ничего не подозревающих обитателей. Под присмотром Кел\'Тузада войско Короля-лича быстро росло, и вскоре тот подчинил себе обширные земли. Это войско стало известным под именем Плеть, и единственной его целью было истребление всех жителей Азерота.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (690,'Слово "ПРЕДАТЕЛЬ" криво нацарапано поверх красиво высеченной эпитафии, гласящей:\r\n\r\n"Здесь покоится Юрив.\r\nОтец, муж, паладин.\r\nПусть же потомки знают, что преданность его Свету была неколебима.\r\nОн никогда не требовал от других того, чего не стал бы делать сам".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Слово "ПРЕДАТЕЛЬ" криво нацарапано поверх красиво высеченной эпитафии, гласящей:\r\n\r\n"Здесь покоится Юрив.\r\nОтец, муж, паладин.\r\nПусть же потомки знают, что преданность его Свету была неколебима.\r\nОн никогда не требовал от других того, чего не стал бы делать сам".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (696,'Дневник – день 4\r\n\r\nЯ сижу на этом острове наедине со своими мыслями уже 4 дня. Бананы очень вкусные, вот только лазать за ними приходится высоко. В свободное от добывания еды или укрывания от дождя время я думаю лишь о спасении.\r\n\r\nЯ не питал бы такой радостной надежды, если бы на берег вместе со мной не выбросило ящики с бумагой и бутылки. Теперь мне смешно вспоминать о том, как недоволен я был, что застрял на корабле, полном алхимиков и писцов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дневник – день 4\r\n\r\nЯ сижу на этом острове наедине со своими мыслями уже 4 дня. Бананы очень вкусные, вот только лазать за ними приходится высоко. В свободное от добывания еды или укрывания от дождя время я думаю лишь о спасении.\r\n\r\nЯ не питал бы такой радостной надежды, если бы на берег вместе со мной не выбросило ящики с бумагой и бутылки. Теперь мне смешно вспоминать о том, как недоволен я был, что застрял на корабле, полном алхимиков и писцов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (697,'Дневник – день 512\r\n\r\nБананы начали говорить со мной, и я многое узнал об их культуре. Теперь я перестал бездумно разрушать их дома и поедать их детей. Как же мало мне было известно о великой цивилизации, которую я уничтожал.\r\n\r\nКроме того, у меня, кажется, заканчиваются бутылки и бумага. Когда я впервые оглядел ту огромную кучу бумаги, что выбросило волнами на берег, то подумал, что она не переведется никогда. Увы, скоро мне придется прекратить свои записи.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дневник – день 512\r\n\r\nБананы начали говорить со мной, и я многое узнал об их культуре. Теперь я перестал бездумно разрушать их дома и поедать их детей. Как же мало мне было известно о великой цивилизации, которую я уничтожал.\r\n\r\nКроме того, у меня, кажется, заканчиваются бутылки и бумага. Когда я впервые оглядел ту огромную кучу бумаги, что выбросило волнами на берег, то подумал, что она не переведется никогда. Увы, скоро мне придется прекратить свои записи.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (705,'Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (710,'Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я надеюсь, что ни один даларанский волшебник не станет разыскивать воргенов, даже из лучших побуждений. С этими тварями нельзя заключить союз, у них нельзя ничему научиться и нельзя узнать ничего полезного.\r\n\r\nБудет лучше, если они останутся в своем мире. Ведь если они придут в наш мир и не будут уничтожены – судьба наша незавидна...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (711,'Хелгрум, передай мою похвалу тому, кто приказал основать нашу базу в Каргате среди Бесплодных Земель. Это место идеально подходит для обучения наших войск. Тамошний суровый климат, злобные звери, воинственные аборигены и полное отсутствие помощи извне сделают так, что выйдут оттуда лишь лучшие из воинов и разведчиков.\r\n\r\nХорошая задумка. Превосходно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хелгрум, передай мою похвалу тому, кто приказал основать нашу базу в Каргате среди Бесплодных Земель. Это место идеально подходит для обучения наших войск. Тамошний суровый климат, злобные звери, воинственные аборигены и полное отсутствие помощи извне сделают так, что выйдут оттуда лишь лучшие из воинов и разведчиков.\r\n\r\nХорошая задумка. Превосходно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (712,'Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры.\r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры.\r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (713,'Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (714,'Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (731,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">\r\nЭлиза\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="center">\r\nВозлюбленная жена, пусть земля утолит твой голод.\r\n</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">\r\nЭлиза\r\n</H1>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<P align="center">\r\nВозлюбленная жена, пусть земля утолит твой голод.\r\n</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (752,'Ну что, друг, доставь-ка вот письмо Франгу в Долину Испытаний. Он обычно рядом с Логовом, гоняет там новобранцев, чтобы стали достойными воинами Орды.$B$BЕму нужны ловкие бойцы вроде тебя, чтобы показать оркам, как можно драться без грубой силы. Ты быстрее и ловчее многих там, но не очень-то бахвалься – орки оскорблений не любят. Друзья они хорошие, может, еще и научат тебя чему полезному.$B$B-Тар-сир') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ну что, друг, доставь-ка вот письмо Франгу в Долину Испытаний. Он обычно рядом с Логовом, гоняет там новобранцев, чтобы стали достойными воинами Орды.$B$BЕму нужны ловкие бойцы вроде тебя, чтобы показать оркам, как можно драться без грубой силы. Ты быстрее и ловчее многих там, но не очень-то бахвалься – орки оскорблений не любят. Друзья они хорошие, может, еще и научат тебя чему полезному.$B$B-Тар-сир',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (791,'Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры. \r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я опишу окружающие земли со слов разведчиков Каргата:\r\n\r\n-Бурые каменистые холмы и сухие равнины, малопригодные для жизни.\r\n-Палящее солнце и суровые ветры. \r\n-Озер или ручьев нет. Даже мелких луж нет. Чтобы найти воду, жители вынуждены копать глубокие и грязные колодцы или добывать скудную влагу из редких кактусов и прочих колючек.\r\n\r\nЕсли вкратце – жарко, жить трудно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (792,'Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Бесплодные Земли кишат врагами. Огры рыщут по раскаленным пескам, нападая на неосторожных путников. Дворфы темной Стали, обитающие в казармах к востоку от Каргата, бьются со своими светлокожими сородичами у северного озера Лок Модан. Жестокие и примитивные создания, именуемые троггами, яростно сражаются за каждый клочок тени.\r\n\r\nА в Восточных Бесплодных землях, в Долине Летлор, живут драконы. Мы не знаем, много ли их там и насколько они велики, ведь разведчики, которые подбираются слишком близко к ним, назад уже не возвращаются.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (793,'Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не стоит и говорить, что мы, служащие в Каргате, очень рады своему назначению. Мы все – как неприступная твердыня, ведь иначе нам не выжить.\r\n\r\nА ничего другого мне и не надо.\r\n\r\nНика Алый Шрам\r\nглава разведчиков, Каргат.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (811,'План приведен в действие.\r\n\r\nСделай из этого некогда великого бастиона веры Геройской Стражи наш лагерь, и мы начнем перебрасывать туда подкрепление из Западного Края, как только узнаем от тебя, что лагерь должным образом подготовлен.\r\n\r\nЖители и солдаты Штормграда давно забыли об этом месте, и мы сможем успешно устраивать оттуда набеги.\r\n\r\nБратство Справедливости отобьет Штормград!\r\n\r\nЖду твоего ответа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','План приведен в действие.\r\n\r\nСделай из этого некогда великого бастиона веры Геройской Стражи наш лагерь, и мы начнем перебрасывать туда подкрепление из Западного Края, как только узнаем от тебя, что лагерь должным образом подготовлен.\r\n\r\nЖители и солдаты Штормграда давно забыли об этом месте, и мы сможем успешно устраивать оттуда набеги.\r\n\r\nБратство Справедливости отобьет Штормград!\r\n\r\nЖду твоего ответа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (812,'Этих грязных троггов так просто обвести вокруг пальца! Их ненависть к нашему роду позволяет двигать ими, как пешками. Вообще непонятно, как они пошли хоть на какой-то союз, ведь мы для них самая страшная угроза... по крайней мере, пока\r\n\r\nКогда начнутся нападения, обе стороны ослабнут и не устоят перед нашим натиском. Захватите ферму к югу от озера Ложе Хелма и ждите дальнейших указаний.\r\n\r\nСтальгорн будет наш.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этих грязных троггов так просто обвести вокруг пальца! Их ненависть к нашему роду позволяет двигать ими, как пешками. Вообще непонятно, как они пошли хоть на какой-то союз, ведь мы для них самая страшная угроза... по крайней мере, пока\r\n\r\nКогда начнутся нападения, обе стороны ослабнут и не устоят перед нашим натиском. Захватите ферму к югу от озера Ложе Хелма и ждите дальнейших указаний.\r\n\r\nСтальгорн будет наш.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (852,'Обугленные рога:\r\n\r\nКак и клыки пауков, обугленные рога химер, которые живут в Обугленной долине, что в Когтистых горах в Калимдоре, обладают весьма ценным свойством. \r\n\r\nРасплющенные и должным образом обработанные, они становятся чрезвычайно стойкими к физическому воздействию.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Обугленные рога:\r\n\r\nКак и клыки пауков, обугленные рога химер, которые живут в Обугленной долине, что в Когтистых горах в Калимдоре, обладают весьма ценным свойством. \r\n\r\nРасплющенные и должным образом обработанные, они становятся чрезвычайно стойкими к физическому воздействию.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (853,'Гальванизированный рог:\r\n\r\nРедкостная твердость гальванизированного рога – основа всей детали доспеха, который я намереваюсь создать, так что его тоже надо добыть.\r\n\r\nЕго можно добыть у редких матриархов химер в Обугленной долине.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гальванизированный рог:\r\n\r\nРедкостная твердость гальванизированного рога – основа всей детали доспеха, который я намереваюсь создать, так что его тоже надо добыть.\r\n\r\nЕго можно добыть у редких матриархов химер в Обугленной долине.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (854,'Сосуд флогистона:\r\n\r\nПоследняя стадия создания брони потребует чрезвычайно горячего кузнечного горна. Чтобы обеспечить необходимый уровень жара, мне понадобится сосуд флогистона.\r\n\r\nЕдинствено известный источник данной субстанции – легендарный иглогрив, Ругуг, и он не отдаст ее без боя. Ругуг обитает в глубинах Лабиринтов Иглошкурых, в южной части Степей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сосуд флогистона:\r\n\r\nПоследняя стадия создания брони потребует чрезвычайно горячего кузнечного горна. Чтобы обеспечить необходимый уровень жара, мне понадобится сосуд флогистона.\r\n\r\nЕдинствено известный источник данной субстанции – легендарный иглогрив, Ругуг, и он не отдаст ее без боя. Ругуг обитает в глубинах Лабиринтов Иглошкурых, в южной части Степей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (856,'Корень жизни:\r\n\r\nОн встречается в природе, а также может быть извлечен из тварей Сухой Лозы в Пылевых топях. Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Корень жизни:\r\n\r\nОн встречается в природе, а также может быть извлечен из тварей Сухой Лозы в Пылевых топях. Его сила будет необходима для привлечения жизненной эссенции Циклониана в этот мир.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (857,'Клык тролля из клана Кровавого Скальпа:\r\n\r\nКлыки троллей из клана Кровавого Скальпа из Тернистой долины обладают редким качеством. Все зло этого клана сконцентрировано в клыках, и если их истолочь в порошок, можно выпустить эту гибельную силу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Клык тролля из клана Кровавого Скальпа:\r\n\r\nКлыки троллей из клана Кровавого Скальпа из Тернистой долины обладают редким качеством. Все зло этого клана сконцентрировано в клыках, и если их истолочь в порошок, можно выпустить эту гибельную силу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (858,'Субстанция изгнанников:\r\n\r\nЭта субстанция может быть получена путем слияния трех оберегов элементалей – изгнанников с Нагорий Арати. Собери с духов Громовой, Пылающий обереги и оберег Гребня, а затем помести по восемь штук каждой разновидности амулетов в мой котёл. \r\n\r\nИз смеси этих оберегов получится субстанция изгнанников.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Субстанция изгнанников:\r\n\r\nЭта субстанция может быть получена путем слияния трех оберегов элементалей – изгнанников с Нагорий Арати. Собери с духов Громовой, Пылающий обереги и оберег Гребня, а затем помести по восемь штук каждой разновидности амулетов в мой котёл. \r\n\r\nИз смеси этих оберегов получится субстанция изгнанников.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (891,'Спиральные символы и пиктограммы, которыми испещрены страницы этого пособия, настолько запутанны, что их невозможно разобрать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Спиральные символы и пиктограммы, которыми испещрены страницы этого пособия, настолько запутанны, что их невозможно разобрать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (911,'Добудь нефрит. Он попадается в различных местах. Камень довольно редок, но если ты спросишь о нем у кузнеца или инженера, они, вероятно, смогут продать тебе несколько таких камней.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Добудь нефрит. Он попадается в различных местах. Камень довольно редок, но если ты спросишь о нем у кузнеца или инженера, они, вероятно, смогут продать тебе несколько таких камней.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (931,'$N, ниже находится список предметов, необходимых для создания твоей брони:\r\n\r\nЗакопченные слитки железа кобольдов Утеса Ветрорезов, что обитают в Руднике Ветрорезов в Когтистых горах.\r\n\r\nТолченый азурит, который можно достать у хилсбрадских шахтеров.\r\n\r\nЖелезные слитки можно взять у горняков или добыть в месторождениях железа, если ты горняк.\r\n\r\nСосуд флогистона, который надо добыть у иглогрива по имени Ругуг из Лабиринтов Иглошкурых.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','$N, ниже находится список предметов, необходимых для создания твоей брони:\r\n\r\nЗакопченные слитки железа кобольдов Утеса Ветрорезов, что обитают в Руднике Ветрорезов в Когтистых горах.\r\n\r\nТолченый азурит, который можно достать у хилсбрадских шахтеров.\r\n\r\nЖелезные слитки можно взять у горняков или добыть в месторождениях железа, если ты горняк.\r\n\r\nСосуд флогистона, который надо добыть у иглогрива по имени Ругуг из Лабиринтов Иглошкурых.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (991,'Мне нужен заряженный молнией жезл. Чтобы заполучить такой, собери 10 тотемных палочек у троллей из племени Сухокожих в Нагорьях Арати. Принеси палочки к Внешнему Кругу, кругу из камней на этом самом нагорье. Положи палочки на центральный камень круга и подожди, когда в них ударит молния. Когда это случится, заряженный молнией жезл будет готов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мне нужен заряженный молнией жезл. Чтобы заполучить такой, собери 10 тотемных палочек у троллей из племени Сухокожих в Нагорьях Арати. Принеси палочки к Внешнему Кругу, кругу из камней на этом самом нагорье. Положи палочки на центральный камень круга и подожди, когда в них ударит молния. Когда это случится, заряженный молнией жезл будет готов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (992,'Предъявитель данного свидетельства имеет права на уважение и почтение, которого заслуживает любой первостатейный жулик и вор.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Предъявитель данного свидетельства имеет права на уважение и почтение, которого заслуживает любой первостатейный жулик и вор.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1031,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<P>\r\nВ память о моем дорогом учителе, Горацио М. Монтгомери, докторе медицины, целителе, учителе, друге.\r\n</P>\r\n<BR/>\r\n<H1 align="center">\r\n50 BTFT – 25 ATFT\r\n</H1>\r\n<BR/>\r\n<P>\r\n"Мир полон боли и тягот. Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\'" \r\n</P>\r\n<BR/>\r\n<P>\r\n- Почетный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных\r\n</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<BR/>\r\n<P>\r\nВ память о моем дорогом учителе, Горацио М. Монтгомери, докторе медицины, целителе, учителе, друге.\r\n</P>\r\n<BR/>\r\n<H1 align="center">\r\n50 BTFT – 25 ATFT\r\n</H1>\r\n<BR/>\r\n<P>\r\n"Мир полон боли и тягот. Наша задача как целителей, НЕТ – мужчин или женщин, отдавших себя медицине, очистить его от всех болезней.\'" \r\n</P>\r\n<BR/>\r\n<P>\r\n- Почетный работник медицины, доктор медицины, доктор философии, доктор юридических наук, Великий Фермер, Экстраординарный Танцор, Друг Животных\r\n</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1051,'Стражники этой башни, похоже, ослаблены и не могут противостоять моим атакам. При разведке с задней стороны башни патрулирующая ее стражница заметила меня и напала. Мне удалось легко ее зарезать, своевременно уклонившись и затем ударив ее в спину.\r\n\r\nНа шум пришел ее напарник. Стражник подошел прямо к тем кустам, куда мне пришлось оттащить труп и обыскать его. Мне пришлось подкрадываться к нему медленно и осторожно, чтобы меня не обнаружили.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Стражники этой башни, похоже, ослаблены и не могут противостоять моим атакам. При разведке с задней стороны башни патрулирующая ее стражница заметила меня и напала. Мне удалось легко ее зарезать, своевременно уклонившись и затем ударив ее в спину.\r\n\r\nНа шум пришел ее напарник. Стражник подошел прямо к тем кустам, куда мне пришлось оттащить труп и обыскать его. Мне пришлось подкрадываться к нему медленно и осторожно, чтобы меня не обнаружили.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1052,'Когда представилась возможность, я всадила нож ему в спину! Его легкие не выдержали силы удара, и его тело упало на землю с глухим звуком.\r\n\r\nЭто было такое быстрое и молниеносное нападение, что бедный глупец даже не успел закричать от боли. Странно, но когда я вынула нож из его спины, из раны хлынул зловонный запах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда представилась возможность, я всадила нож ему в спину! Его легкие не выдержали силы удара, и его тело упало на землю с глухим звуком.\r\n\r\nЭто было такое быстрое и молниеносное нападение, что бедный глупец даже не успел закричать от боли. Странно, но когда я вынула нож из его спины, из раны хлынул зловонный запах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1053,'Похоже, то, что прятал в своем сундуке Клейвен, оно оказало неблагоприятный эффект на обитателей башни. Я подозреваю, что и другие стражники столь же слабы, и, возможно, даже сам Клейвен пал жертвой этих нежелательных побочных эффектов.\r\n\r\nАгент Эмбер Кеарнен\r\nШРУ:7 Полевой оперативник, Отд. 8') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Похоже, то, что прятал в своем сундуке Клейвен, оно оказало неблагоприятный эффект на обитателей башни. Я подозреваю, что и другие стражники столь же слабы, и, возможно, даже сам Клейвен пал жертвой этих нежелательных побочных эффектов.\r\n\r\nАгент Эмбер Кеарнен\r\nШРУ:7 Полевой оперативник, Отд. 8',`Text_loc8`);
