INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1151,'Торговая компания *неразборчиво*. Похоже, эти глупцы сорвали всю свою операцию в попытке стабилизировать зелье.\r\n\r\n*несколько страниц вырвано*') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Торговая компания *неразборчиво*. Похоже, эти глупцы сорвали всю свою операцию в попытке стабилизировать зелье.\r\n\r\n*несколько страниц вырвано*',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1152,'Этот побочный эффект невероятно смертоносен. Только представь, что *текст невозможно прочесть* Ха-ха-ха!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот побочный эффект невероятно смертоносен. Только представь, что *текст невозможно прочесть* Ха-ха-ха!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1153,'Я схожу с ума? Сегодня я оторвал голову одному из самых доверенных стражников под предлогом того, что я хочу получше рассмотреть его душу. И когда я смотрел, как воздух покидает его дыхательные пути, я вспомнил, что несколько дней не ел!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я схожу с ума? Сегодня я оторвал голову одному из самых доверенных стражников под предлогом того, что я хочу получше рассмотреть его душу. И когда я смотрел, как воздух покидает его дыхательные пути, я вспомнил, что несколько дней не ел!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1154,'Матиас Шоу послал какого-то рассыльного убить меня. *текст неразборчив*\r\n\r\nТеперь он бродит снаружи. Тупой, безжизненный чурбан.\r\n\r\nХа-ха-ха!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Матиас Шоу послал какого-то рассыльного убить меня. *текст неразборчив*\r\n\r\nТеперь он бродит снаружи. Тупой, безжизненный чурбан.\r\n\r\nХа-ха-ха!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1155,'ван Клиф...*неразборчиво*\r\n\r\nВызывает МЕНЯ? ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ??? Я – Клавьен Мортвейк! И чтобы какое-то насекомое еще мне указывало?!\r\n\r\n*остальные страницы книги утеряны*') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','ван Клиф...*неразборчиво*\r\n\r\nВызывает МЕНЯ? ДА КЕМ ОН СЕБЯ ВОЗОМНИЛ??? Я – Клавьен Мортвейк! И чтобы какое-то насекомое еще мне указывало?!\r\n\r\n*остальные страницы книги утеряны*',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1191,'ЖИЗНЕННО ВАЖНЫЕ ДАННЫЕ! УРОВЕНЬ СЕКРЕТНОСТИ 5122!\r\n\r\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','ЖИЗНЕННО ВАЖНЫЕ ДАННЫЕ! УРОВЕНЬ СЕКРЕТНОСТИ 5122!\r\n\r\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1192,'Не дай этой информации попасть в руки врага!\r\n\r\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не дай этой информации попасть в руки врага!\r\n\r\n01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1193,'Уровень секретности 10^10000. Суперсекретные данные!\r\n\r\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уровень секретности 10^10000. Суперсекретные данные!\r\n\r\n01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1194,'Уровень секретности этой информации СТОЛЬ высок, что понадобится изобретение нового числа, чтобы описать его!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уровень секретности этой информации СТОЛЬ высок, что понадобится изобретение нового числа, чтобы описать его!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1251,'В эти месяцы у меня было достаточно времени для раздумий о моих старых верованиях и фанатизме. Альянс? Орда? Добро? Зло? Значение этих слов, когда-то таких простых, теперь расплывалось перед моим взором, устремленным на бескрайнее море.\r\n\r\nТеперь я знаю, в чем причина. Эти бананы следят за мной. Сидят высоко и недоброжелательно следят за мной своими глазками. И когда последний раз я пытался съесть один из них, он чуть не задушил меня! Я почти слышал его крик, когда я размазал его, наполовину откушенного, по камням.\r\n\r\nЭто – война, и я ее выиграю.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В эти месяцы у меня было достаточно времени для раздумий о моих старых верованиях и фанатизме. Альянс? Орда? Добро? Зло? Значение этих слов, когда-то таких простых, теперь расплывалось перед моим взором, устремленным на бескрайнее море.\r\n\r\nТеперь я знаю, в чем причина. Эти бананы следят за мной. Сидят высоко и недоброжелательно следят за мной своими глазками. И когда последний раз я пытался съесть один из них, он чуть не задушил меня! Я почти слышал его крик, когда я размазал его, наполовину откушенного, по камням.\r\n\r\nЭто – война, и я ее выиграю.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1271,'Инженерные дисцпилины\r\n\r\nНесмотря на то что вопрос о том, какая раса первой в Азероте додумалась до инженерного дела, является спорным, бесспорен тот факт, что лишь две расы преуспели в ней в настоящее время: гномы и гоблины. Их преданность инженерному делу не только вдохновила их на фантастические изобретения в смутный магический Век Изобретений, но и, как результат, породила интенсивную конкуренцию между расами. Нигде она столь очевидно не проявлялась, как на путях развития их науки.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Инженерные дисцпилины\r\n\r\nНесмотря на то что вопрос о том, какая раса первой в Азероте додумалась до инженерного дела, является спорным, бесспорен тот факт, что лишь две расы преуспели в ней в настоящее время: гномы и гоблины. Их преданность инженерному делу не только вдохновила их на фантастические изобретения в смутный магический Век Изобретений, но и, как результат, породила интенсивную конкуренцию между расами. Нигде она столь очевидно не проявлялась, как на путях развития их науки.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1272,'Гномское инженерное дело\r\n\r\nРаса гномов достигла несравненных успехов в разработке предметов, манипулирующих и управляющих окружающим их миром. Несмотря на то что они обычно стремятся к совершенствованию взрывчатых веществ и оружия, их инженерное дело также сосредоточено на предметах, которые, буквально говоря, делают жизнь проще и удобнее. Эта наука о теоретических возможностях переделки реальности в соответствии с технологией гномских ноу-хау. Некоторые возможности, как бы то ни было, никогда не получится полностью реализовать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гномское инженерное дело\r\n\r\nРаса гномов достигла несравненных успехов в разработке предметов, манипулирующих и управляющих окружающим их миром. Несмотря на то что они обычно стремятся к совершенствованию взрывчатых веществ и оружия, их инженерное дело также сосредоточено на предметах, которые, буквально говоря, делают жизнь проще и удобнее. Эта наука о теоретических возможностях переделки реальности в соответствии с технологией гномских ноу-хау. Некоторые возможности, как бы то ни было, никогда не получится полностью реализовать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1273,'Гоблинское инженерное дело\r\n\r\nБудучи расой, нейтрально относящейся практически ко всем конфликтам, гоблины сумели сделать науку доходным делом. Они нашли практическое применение инженерному делу, столь очевидное в их великолепно разработанной взрывчатке, огнестрельном оружии и машинах. Гоблинское инженерное дело не слишком заинтересована в теории, их изобретения обычно не имеют тенденции не работать, скорее уж работают слишком хорошо. Они точно не для слабонервных.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гоблинское инженерное дело\r\n\r\nБудучи расой, нейтрально относящейся практически ко всем конфликтам, гоблины сумели сделать науку доходным делом. Они нашли практическое применение инженерному делу, столь очевидное в их великолепно разработанной взрывчатке, огнестрельном оружии и машинах. Гоблинское инженерное дело не слишком заинтересована в теории, их изобретения обычно не имеют тенденции не работать, скорее уж работают слишком хорошо. Они точно не для слабонервных.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1274,'Изучение инженерного дела\r\n\r\nГномы и гоблины столь яростно защищают свои знания друг от друга, что невозможно получить доступ к обоим направлениям этой науки одновременно. Каждая раса, независимо от ее политических союзов, дает доступ к знаниям лишь тем, кто согласен отказаться от стремления заняться другим направлением науки. Если ученик выбирает гномское инженерное дело, например, то ни одного урока гоблинского инженерного дела он никогда не получит.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Изучение инженерного дела\r\n\r\nГномы и гоблины столь яростно защищают свои знания друг от друга, что невозможно получить доступ к обоим направлениям этой науки одновременно. Каждая раса, независимо от ее политических союзов, дает доступ к знаниям лишь тем, кто согласен отказаться от стремления заняться другим направлением науки. Если ученик выбирает гномское инженерное дело, например, то ни одного урока гоблинского инженерного дела он никогда не получит.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1275,'Необратимость выбора\r\n\r\nПредыдущий раздел осветил весьма важные моменты о двух направлениях инженерного дела, которые надо усвоить, чтобы начать обучение. Решение заняться тем или иным направлением науки означает, что схемы противополжного направления никогда не будут доступны для изучения. Хотя такая окончательность выбора может отпугнуть непрофессионала, опытный инженер понимает, что гномы и гоблины оберегают свои секреты с великим пылом и что знание о чем-то – все же лучше, чем никого знания.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Необратимость выбора\r\n\r\nПредыдущий раздел осветил весьма важные моменты о двух направлениях инженерного дела, которые надо усвоить, чтобы начать обучение. Решение заняться тем или иным направлением науки означает, что схемы противополжного направления никогда не будут доступны для изучения. Хотя такая окончательность выбора может отпугнуть непрофессионала, опытный инженер понимает, что гномы и гоблины оберегают свои секреты с великим пылом и что знание о чем-то – все же лучше, чем никого знания.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1276,'Цитаты\r\n\r\n"Ты хочешь узнать о гоблинском инженерном деле? Спроси об этом одного из их лучших и талантливейших инженеров – мне кажется, его имя Набби Толстопал. Хочешь знать, почему его так зовут? Таково гоблинское инженерное дело."\r\n-- Ринго Трагедикс, гномский инженер.\r\n\r\n"Говори, что хочешь, о нас, гоблинах, но я скажу тебе вот что: У НАС ЕСТЬ ВЗРЫВЧАТКА!"\r\n-- Блямс Динамиттер, гоблинский бомбардир') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Цитаты\r\n\r\n"Ты хочешь узнать о гоблинском инженерном деле? Спроси об этом одного из их лучших и талантливейших инженеров – мне кажется, его имя Набби Толстопал. Хочешь знать, почему его так зовут? Таково гоблинское инженерное дело."\r\n-- Ринго Трагедикс, гномский инженер.\r\n\r\n"Говори, что хочешь, о нас, гоблинах, но я скажу тебе вот что: У НАС ЕСТЬ ВЗРЫВЧАТКА!"\r\n-- Блямс Динамиттер, гоблинский бомбардир',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1277,'Еще цитаты!\r\n\r\n"Знаешь это чувство, когда ты заканчиваешь делать что-то и включаешь это первый раз, чтобы испытать его силу и насладиться своим изобретением, когда оно начинает оживать? А вот гномы не знают".\r\n-- Никс Шепружин, главный гоблинский инженер из Прибамбасска\r\n\r\n"Инженерное дело – это когда берется фантазия и делается еще более фантастичной!"\r\n-- Ровис Мак-Хрясьшатун, гномский изобретатель.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Еще цитаты!\r\n\r\n"Знаешь это чувство, когда ты заканчиваешь делать что-то и включаешь это первый раз, чтобы испытать его силу и насладиться своим изобретением, когда оно начинает оживать? А вот гномы не знают".\r\n-- Никс Шепружин, главный гоблинский инженер из Прибамбасска\r\n\r\n"Инженерное дело – это когда берется фантазия и делается еще более фантастичной!"\r\n-- Ровис Мак-Хрясьшатун, гномский изобретатель.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1291,'Сотворение зверя:\r\n\r\nЧтобы создать ищейку Скверны, необходимо использовать выданную сферу Скверны.\r\n\r\nПримечания:\r\n\r\nСотворенная ищейка Скверны сможет существовать в этом мире лишь тридцать минут.\r\n\r\nСотворенная ищейка Скверны будет помогать лишь в поиске отложений азшарита.\r\n\r\nСотворенная ищейка Скверны НЕ БУДЕТ делать следующее: фокусы, нападать на кого-либо, помогать в чем-либо, танцевать, уничтожать магических существ.\r\n\r\nПожалуйста, переверните страницу...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сотворение зверя:\r\n\r\nЧтобы создать ищейку Скверны, необходимо использовать выданную сферу Скверны.\r\n\r\nПримечания:\r\n\r\nСотворенная ищейка Скверны сможет существовать в этом мире лишь тридцать минут.\r\n\r\nСотворенная ищейка Скверны будет помогать лишь в поиске отложений азшарита.\r\n\r\nСотворенная ищейка Скверны НЕ БУДЕТ делать следующее: фокусы, нападать на кого-либо, помогать в чем-либо, танцевать, уничтожать магических существ.\r\n\r\nПожалуйста, переверните страницу...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1292,'Контроль над зверем:\r\n\r\nИщейка Скверны понимает только звериные эмоции. Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо на нее бешено зарычать! (Нацельтесь на ищейку Скверны и изобразите /бешенство).\r\n\r\nКогда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ. Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять ее.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Контроль над зверем:\r\n\r\nИщейка Скверны понимает только звериные эмоции. Чтобы заставить вашу ищейку Скверны искать залежи азшарита, необходимо на нее бешено зарычать! (Нацельтесь на ищейку Скверны и изобразите /бешенство).\r\n\r\nКогда ищейка Скверны обнаружит залежь, она побежит к ней, не обращая внимания на окружающих существ. Хотя вам не нужно защищать ищейку Скверны, возможно, вы захотите быть рядом с ней, чтобы не потерять ее.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1293,'Отпустить зверя:\r\n\r\nСпустя 30 минут зверь вернется к себе домой в Пустоту.\r\n\r\nПримечание:\r\n\r\nВ этом своем стремлении зверь МОЖЕТ броситься со скалы или упасть с горы. Не горюйте о потере ищейки Скверны, лучше вызовите другую.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Отпустить зверя:\r\n\r\nСпустя 30 минут зверь вернется к себе домой в Пустоту.\r\n\r\nПримечание:\r\n\r\nВ этом своем стремлении зверь МОЖЕТ броситься со скалы или упасть с горы. Не горюйте о потере ищейки Скверны, лучше вызовите другую.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1313,'О чем я думал?\r\n\r\nВозможно, более лучшим был бы вопрос: о чем я думаю, когда пишу письмо, находясь в брюхе великана?\r\n\r\nОба вопроса хороши, и ни на один у меня нет сейчас ответа…\r\n\r\nСледует признать, что моя миссия была не миссией доброй воли. Я пришел сюда в поисках азшарита, уникального кристалла из южной Азшары. О, я был бы так богат!\r\n\r\nБа! А теперь посмотрите на меня...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','О чем я думал?\r\n\r\nВозможно, более лучшим был бы вопрос: о чем я думаю, когда пишу письмо, находясь в брюхе великана?\r\n\r\nОба вопроса хороши, и ни на один у меня нет сейчас ответа…\r\n\r\nСледует признать, что моя миссия была не миссией доброй воли. Я пришел сюда в поисках азшарита, уникального кристалла из южной Азшары. О, я был бы так богат!\r\n\r\nБа! А теперь посмотрите на меня...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1314,'Если какой-нибудь представитель разумной формы жизни найдет это письмо, пусть он спросит себя:"Какого черта они возятся с этими злобными десятиметровыми великанами?"\r\n\r\n-Муук') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Если какой-нибудь представитель разумной формы жизни найдет это письмо, пусть он спросит себя:"Какого черта они возятся с этими злобными десятиметровыми великанами?"\r\n\r\n-Муук',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1433,'Уггель Тяжелорук\r\n\r\nУггель – серьезный и талантливый гравер, и когда он не отягощен темным ключом, из-под его рук выходят образчики великих творений, хранящихся в Зале Ремесла.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уггель Тяжелорук\r\n\r\nУггель – серьезный и талантливый гравер, и когда он не отягощен темным ключом, из-под его рук выходят образчики великих творений, хранящихся в Зале Ремесла.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1435,'Офгут Каменный Кулак\r\n\r\nБессчетно количество павших от молота Темного хранителя Офгута. \r\n\r\nСолдаты Западного гарнизона склоняются пред ним в благоговении, когда он проходит мимо. Кто среди них может заглянуть в глаза Офгуту и увидеть там секреты, что нашептывает ему темный ключ?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Офгут Каменный Кулак\r\n\r\nБессчетно количество павших от молота Темного хранителя Офгута. \r\n\r\nСолдаты Западного гарнизона склоняются пред ним в благоговении, когда он проходит мимо. Кто среди них может заглянуть в глаза Офгуту и увидеть там секреты, что нашептывает ему темный ключ?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1471,'Соломон!\r\n\r\nПредъявителю данного приказа дарован официальный статус действующего представителя Штормграда. Вы можете воспользоваться <его/ее> помощью в поисках доказательства участия черных драконов в делах орков Черной Горы. В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозерье.\r\n\r\nС наилучшими пожеланиями,\r\n\r\n\r\n\r\nВерховный лорд Болвар Фордрагон') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Соломон!\r\n\r\nПредъявителю данного приказа дарован официальный статус действующего представителя Штормграда. Вы можете воспользоваться <его/ее> помощью в поисках доказательства участия черных драконов в делах орков Черной Горы. В случае если подобное доказательство будет обнаружено, данный представитель должен будет вернуться с вышеуказанным доказательством ко мне в Штормград, и тогда я издам приказ об отправке необходимой военной помощи в Приозерье.\r\n\r\nС наилучшими пожеланиями,\r\n\r\n\r\n\r\nВерховный лорд Болвар Фордрагон',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1533,'<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nДИАГРАММА ЗАПАДНОГО ПИЛОНА\r\n</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">\r\nДИАГРАММА ЗАПАДНОГО ПИЛОНА\r\n</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\11482_crystals_west"/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1551,'Привет и поклон вам, искатели приключений!\r\n\r\nМне, Кринкелю Сталлеру, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений. Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия.\r\n\r\nСписок включает в себя следующие страницы...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Привет и поклон вам, искатели приключений!\r\n\r\nМне, Кринкелю Сталлеру, необходима помощь желающих рискнуть своей жизнью ради выполнения некоторых моих трудных поручений. Поскольку у меня множество обязанностей и я загружен взвалившейся на меня работой, я уверяю, что любому, достаточно смелому, чтобы собрать необходимые предметы из данного списка и принести их мне, будет выплачена солидная премия.\r\n\r\nСписок включает в себя следующие страницы...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1552,'Прочная хрустальная нога- \r\n\r\nХрустальные пауки из Выжженной теснины сделаны из невероятного кристаллоподобного материала. Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров.\r\n\r\nМне понадобится некоторое их количество, чтобы провести тестирование. У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прочная хрустальная нога- \r\n\r\nХрустальные пауки из Выжженной теснины сделаны из невероятного кристаллоподобного материала. Из их ног, в том случае если они не повреждены при убийстве их владельцев, получаются замечательные трубки, необходимые в экспериментах моих компаньонов-инженеров.\r\n\r\nМне понадобится некоторое их количество, чтобы провести тестирование. У пауков есть восемь ног, так что достать их будет не проблемой для крепкого воина или опытного мага.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1553,'Задержанная посылка -\r\n\r\nЯ нанял кое-кого с репутацией надежного пилота, чтобы доставить груз из Терамора. Я ошибался. Несмотря на то что пилот выжил и смог рассказать мне эту историю, он бросил и свой дирижабль и весь мой груз, чтобы спасти свою шею.\r\n\r\nВ общем, мне нужно вернуть мой товар. Исходя из того, что рассказал мне Бизиль, он потерпел крушение к западу от берега Пылевых топей. Он начал падать сразу после того, как пересек холмы, окаймляющие море.\r\n\r\nХм-м-м... он никогда не рассказывал мне, что послужило причиной аварии...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Задержанная посылка -\r\n\r\nЯ нанял кое-кого с репутацией надежного пилота, чтобы доставить груз из Терамора. Я ошибался. Несмотря на то что пилот выжил и смог рассказать мне эту историю, он бросил и свой дирижабль и весь мой груз, чтобы спасти свою шею.\r\n\r\nВ общем, мне нужно вернуть мой товар. Исходя из того, что рассказал мне Бизиль, он потерпел крушение к западу от берега Пылевых топей. Он начал падать сразу после того, как пересек холмы, окаймляющие море.\r\n\r\nХм-м-м... он никогда не рассказывал мне, что послужило причиной аварии...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1554,'Сбалансированная шпага Сталлера- \r\n\r\nИ последнее: я хочу вернуть одну из моих лучших кузнечных работ. Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином. В общем, его побил мурлок по имени... как его там, Джаркай? Как-то так.\r\n\r\nОн подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали. Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сбалансированная шпага Сталлера- \r\n\r\nИ последнее: я хочу вернуть одну из моих лучших кузнечных работ. Эта шпага – невероятное оружие, и я подарил его тому, кого я считал весьма благородным и великим воином. В общем, его побил мурлок по имени... как его там, Джаркай? Как-то так.\r\n\r\nОн подвергся атаке этого чудища во время своего путешествия по берегу Болота Печали. Он проиграл сражение и, видимо, обратился в бегство, оставив оружие в лапах мурлока.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1556,'Найдите их для меня и принесите в Прибамбасск вместе с этим гроссбухом, и я награжу вас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Найдите их для меня и принесите в Прибамбасск вместе с этим гроссбухом, и я награжу вас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1611,'Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам. \r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Страницы покрыты древними эльфийскими рунами.\r\n\r\nЭти страницы содержат воспоминания о событиях, произошедших при сборе и приготовлении реактивов, необходимых для создания простого магического камня.\r\n\r\nДа не получат наши враги никогда доступ к этим письменам. \r\n\r\nДа доживу я до тех пор, когда бледный свет луны вновь осветит Кель\'Талас.\r\n\r\nДа умру я во имя Кель\'таса.\r\n\r\nДа буду убивать я во славу Иллидана.\r\n\r\n-Мастер Кариэль Винтхалус',`Text_loc8`);
