INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1652,'<HTML>\r\n<BODY>\r\n<IMG src="Interface\\Pictures\\11733_ungoro_256"/>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<IMG src="Interface\\Pictures\\11733_ungoro_256"/>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1711,'Срочное сообщение для дозорного утесов Долгорога\r\n\r\nОгромные силы кентавров из Лагеря Э\'ток напали на один из наших торговых караванов. Все члены каравана были убиты, а весь товар потерян. Это было наглое и беспрецедентное нападение, и, я боюсь, не последнее.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Срочное сообщение для дозорного утесов Долгорога\r\n\r\nОгромные силы кентавров из Лагеря Э\'ток напали на один из наших торговых караванов. Все члены каравана были убиты, а весь товар потерян. Это было наглое и беспрецедентное нападение, и, я боюсь, не последнее.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1752,'Этот окаменевший коготь был найден у южных берегов Тернистой долины. Экологи полагают, что этот коготь принадлежал древнему солнечному руху. Несмотря на то что упоминания об этих существах присутствуют в примитивных мифологических сказаниях тауренов, находка этого когтя предполагает тот факт, что, вероятно, подобное создание действительно существовало.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот окаменевший коготь был найден у южных берегов Тернистой долины. Экологи полагают, что этот коготь принадлежал древнему солнечному руху. Несмотря на то что упоминания об этих существах присутствуют в примитивных мифологических сказаниях тауренов, находка этого когтя предполагает тот факт, что, вероятно, подобное создание действительно существовало.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1753,'Самые большие из птиц-долгоногов, геру, весьма немногочисленны и редко встречаются.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Самые большие из птиц-долгоногов, геру, весьма немногочисленны и редко встречаются.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1754,'Это ростовая копия скелета Щелкозуба. Легендарный баран был чудом Каз Модана и объектом многих историй дворфийского фольклора. До сих пор экологи не способны объяснить огромный размер барана и его физическую выносливость.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Это ростовая копия скелета Щелкозуба. Легендарный баран был чудом Каз Модана и объектом многих историй дворфийского фольклора. До сих пор экологи не способны объяснить огромный размер барана и его физическую выносливость.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1755,'Найденное в отдаленных тропических лесах Кратера Ун\'Горо, это яйцо когда-то содержало в себе эмбрион девизавра. Генетический материал этого зверя оказался бесценен для экологов Лиги Исследователей, которые теперь как никогда близки к изобретению сыворотки от лишающего сил яда девизавров.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Найденное в отдаленных тропических лесах Кратера Ун\'Горо, это яйцо когда-то содержало в себе эмбрион девизавра. Генетический материал этого зверя оказался бесценен для экологов Лиги Исследователей, которые теперь как никогда близки к изобретению сыворотки от лишающего сил яда девизавров.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1756,'Этот неповрежденный скелет птерадона был найден в далеком Кратере Ун\'Горо. Исходя из структуры скелета, был сделан вывод, что подобный вид существ никогда раньше не встречался. Этот скелет, вероятно, был погребен под слоями плодородной земли этого региона много столетий назад.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот неповрежденный скелет птерадона был найден в далеком Кратере Ун\'Горо. Исходя из структуры скелета, был сделан вывод, что подобный вид существ никогда раньше не встречался. Этот скелет, вероятно, был погребен под слоями плодородной земли этого региона много столетий назад.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1757,'Поднятая из затопленных руин Сурамара, эта все еще работающая астролябия, была создана высокорожденными эльфами около двенадцати тысяч лет назад. Высокорожденные, одержимые магией, оккультными науками и астрономией, создали множество гениальных инструментов. Это приспособление позволяет нам получить неоценимое представление об уровне развития наук у древних ночных эльфов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Поднятая из затопленных руин Сурамара, эта все еще работающая астролябия, была создана высокорожденными эльфами около двенадцати тысяч лет назад. Высокорожденные, одержимые магией, оккультными науками и астрономией, создали множество гениальных инструментов. Это приспособление позволяет нам получить неоценимое представление об уровне развития наук у древних ночных эльфов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1758,'Эти образцы древней глиняной посуды были найдены при раскопках Ульдамана. Хотя на них не так много загадочных рун или иероглифов, они позволяют оценить мастерство изготовления этих повседневных предметов древней расы дворфов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эти образцы древней глиняной посуды были найдены при раскопках Ульдамана. Хотя на них не так много загадочных рун или иероглифов, они позволяют оценить мастерство изготовления этих повседневных предметов древней расы дворфов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1760,'Найденное в знойной пустыне Танарис, это необычное яйцо остается загадкой для современных экологов. Работы по определению его возраста позволяют предположить, что этому яйцу около тысячи лет. Несмотря на то что определенные элементы указывают на его принадлежность насекомовидному существу, его настоящее происхождение невозможно понять. Особей, откладывающих столь характерные яйца, все еще предстоит обнаружить.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Найденное в знойной пустыне Танарис, это необычное яйцо остается загадкой для современных экологов. Работы по определению его возраста позволяют предположить, что этому яйцу около тысячи лет. Несмотря на то что определенные элементы указывают на его принадлежность насекомовидному существу, его настоящее происхождение невозможно понять. Особей, откладывающих столь характерные яйца, все еще предстоит обнаружить.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1761,'Эти следы Второй войны служат грозным напоминанием о том, как опасно близка была орда к завоеванию Железных гор.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эти следы Второй войны служат грозным напоминанием о том, как опасно близка была орда к завоеванию Железных гор.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1772,'Вурмталак!\r\n\r\nТвой господин Нефариан дал мне повеление наказать тебя так, как я посчитаю нужным, если еще хоть кто-нибудь проберется внутрь крепости.\r\n\r\nНе забывай, кому ты подчиняешься, рептилия.\r\n\r\nСыну Чернорука: Мастеру меча и битвы. Единственному истинному Вождю.\r\n\r\n-Ренд') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вурмталак!\r\n\r\nТвой господин Нефариан дал мне повеление наказать тебя так, как я посчитаю нужным, если еще хоть кто-нибудь проберется внутрь крепости.\r\n\r\nНе забывай, кому ты подчиняешься, рептилия.\r\n\r\nСыну Чернорука: Мастеру меча и битвы. Единственному истинному Вождю.\r\n\r\n-Ренд',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1773,'Во все времена демонические существа пытались проникнуть в мир Титанов из Круговерти Пустоты, и Пантеон выбрал своего самого великого, Саргераса, чтобы он охранял границы миров. Благородный гигант из расплавленной бронзы, Саргерас выполнял свои обязательства несчетное количество тысячелетий, находя и уничтожая демонов везде, где возможно. Спустя века Саргерас столкнулся с двумя мощными демоническими расами, которые были помешаны на получении силы и господства над физической вселенной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во все времена демонические существа пытались проникнуть в мир Титанов из Круговерти Пустоты, и Пантеон выбрал своего самого великого, Саргераса, чтобы он охранял границы миров. Благородный гигант из расплавленной бронзы, Саргерас выполнял свои обязательства несчетное количество тысячелетий, находя и уничтожая демонов везде, где возможно. Спустя века Саргерас столкнулся с двумя мощными демоническими расами, которые были помешаны на получении силы и господства над физической вселенной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1774,'Эредары, коварная раса демонических чародеев, использовала магию своих колдунов, чтобы поработить множество миров. Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эредары, коварная раса демонических чародеев, использовала магию своих колдунов, чтобы поработить множество миров. Расы тех миров мутировали под влиянием злых сил эредаров и сами превращались в демонов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1775,'Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями. Неспособный понять такую развращенность, великий титан начал погружаться в отчаяние. Несмотря на свою растущую тревогу, Саргерас все же избавил вселенную от колдунов, заманив их в ловушку в Круговерти Пустоты.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на то что практически бесконечной силы Саргераса с избытком хватало, чтобы победить зловещих эредаров, он был весьма обеспокоен разрушением и всепоглощающим злом, распространяемыми этими созданиями. Неспособный понять такую развращенность, великий титан начал погружаться в отчаяние. Несмотря на свою растущую тревогу, Саргерас все же избавил вселенную от колдунов, заманив их в ловушку в Круговерти Пустоты.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1777,'Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу. Саргерас легко победил Натрезим, но их порча глубоко запала в его душу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нечестивые, коварные повелители ужаса обращали друг против друга целые народы, манипулируя их бездумной ненавистью и недоверием друг к другу. Саргерас легко победил Натрезим, но их порча глубоко запала в его душу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1778,'Когда сомнения и отчаяние полностью овладели Саргерасом, он потерял веру не только в свою миссию, но отказался от мыслей титанов об упорядоченной вселенной. В конечном счете он пришел к выводу, что сам порядок является глупостью и что хаос и порочность – единственно абсолютные понятия в этой темной, одинокой вселенной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда сомнения и отчаяние полностью овладели Саргерасом, он потерял веру не только в свою миссию, но отказался от мыслей титанов об упорядоченной вселенной. В конечном счете он пришел к выводу, что сам порядок является глупостью и что хаос и порочность – единственно абсолютные понятия в этой темной, одинокой вселенной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1779,'Его друзья-титаны пытались убедить его не совершать ошибки, пытались успокоить его разбушевавшиеся чувства, но он принимал их более чем оптимистичные верования за корыстные заблуждения. Покинув навсегда их ряды, Саргерас отправился на поиски своего собственного места во вселенной. Несмотря на то что Пантеон был опечален его уходом, даже титаны не могли предугадать того, как далеко зайдет их заблудший брат.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Его друзья-титаны пытались убедить его не совершать ошибки, пытались успокоить его разбушевавшиеся чувства, но он принимал их более чем оптимистичные верования за корыстные заблуждения. Покинув навсегда их ряды, Саргерас отправился на поиски своего собственного места во вселенной. Несмотря на то что Пантеон был опечален его уходом, даже титаны не могли предугадать того, как далеко зайдет их заблудший брат.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1780,'К тому времени, как безумие Саргераса поглотило остатки его некогда отважного духа, он уверовал в то, что титаны сами несут ответственность за ошибки своих созданий. Решив, в конечном счете, уничтожить плоды их трудов во всей вселенной, он захотел создать несокрушимую армию, которая огнем и мечом пройдет по вселенной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К тому времени, как безумие Саргераса поглотило остатки его некогда отважного духа, он уверовал в то, что титаны сами несут ответственность за ошибки своих созданий. Решив, в конечном счете, уничтожить плоды их трудов во всей вселенной, он захотел создать несокрушимую армию, которая огнем и мечом пройдет по вселенной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1781,'Даже титаническое тело Саргераса пострадало от порчи, что поразила его когда-то благородное сердце. Его глаза, волосы и борода горели пламенем, а его металлическая бронзовая кожа раскололась, открыв бездонное горнило пылающей ненависти.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Даже титаническое тело Саргераса пострадало от порчи, что поразила его когда-то благородное сердце. Его глаза, волосы и борода горели пламенем, а его металлическая бронзовая кожа раскололась, открыв бездонное горнило пылающей ненависти.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1782,'В своей ярости Саргерас разрушил темницы, в которых были заперты эредары и Натрезим, и выпустил отвратительных демонов на свободу. Эти коварные существа склонились пред необъятным гневом темного титана и предложили служить ему всеми доступными им злокозненными способами. Из рядов могучих эредаров Саргерас выбрал двух предводителей, которых поставил во главе своей демонической армии разрушения.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В своей ярости Саргерас разрушил темницы, в которых были заперты эредары и Натрезим, и выпустил отвратительных демонов на свободу. Эти коварные существа склонились пред необъятным гневом темного титана и предложили служить ему всеми доступными им злокозненными способами. Из рядов могучих эредаров Саргерас выбрал двух предводителей, которых поставил во главе своей демонической армии разрушения.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1783,'Кил\'джеден Искуситель был выбран для поиска самых темных рас во вселенной и присоединения их к армии Саргераса. Второй, Архимонд Осквернитель, был избран, чтобы вести огромную армию Саргераса в битву против тех, кто мог воспротивиться воле титана.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден Искуситель был выбран для поиска самых темных рас во вселенной и присоединения их к армии Саргераса. Второй, Архимонд Осквернитель, был избран, чтобы вести огромную армию Саргераса в битву против тех, кто мог воспротивиться воле титана.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1785,'Могущественный Архимонд также избрал для себя агентов. Призвав зловредных разрушителей и их жестокого предводителя, Маннорота Разрушителя, Архимонд надеялся создать военную элиту, которая искореняла бы все живое.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Могущественный Архимонд также избрал для себя агентов. Призвав зловредных разрушителей и их жестокого предводителя, Маннорота Разрушителя, Архимонд надеялся создать военную элиту, которая искореняла бы все живое.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1787,'Не знавшие том, что Саргерас намерен уничтожить плоды их бесчисленных трудов, титаны продолжали передвигаться от мира к миру, формируя и приводя в порядок те планеты, что они находили пригодными. В своем путешествии они случайно попали в небольшой мир, который его обитатели позже назвали Азеротом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не знавшие том, что Саргерас намерен уничтожить плоды их бесчисленных трудов, титаны продолжали передвигаться от мира к миру, формируя и приводя в порядок те планеты, что они находили пригодными. В своем путешествии они случайно попали в небольшой мир, который его обитатели позже назвали Азеротом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1790,'Эти силы хаоса бушевали и бились с колоссами-титанами на груди мира. Несмотря на то что элементали были настолько могущественны, что смертным даже представить невозможно, их объединенных сил было недостаточно, чтобы остановить могучих титанов. Один за другим повелители элементалей пали, а их силы отступили.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эти силы хаоса бушевали и бились с колоссами-титанами на груди мира. Несмотря на то что элементали были настолько могущественны, что смертным даже представить невозможно, их объединенных сил было недостаточно, чтобы остановить могучих титанов. Один за другим повелители элементалей пали, а их силы отступили.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1792,'Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму. Для создания бездонных подземных пещер титаны сотворили дворфоподобных земельников из магического живого камня. Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов. Многие столетия титаны придавали форму землям, пока не смогли сотворить совершенный континент.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Титаны наделили силой многие расы, чтобы те смогли помочь им придавать миру форму. Для создания бездонных подземных пещер титаны сотворили дворфоподобных земельников из магического живого камня. Чтобы помочь им осушить моря и поднять землю над уровнем моря, титаны создали огромных, но кротких морских великанов. Многие столетия титаны придавали форму землям, пока не смогли сотворить совершенный континент.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1793,'В центре континента титаны поместили озеро искрящейся энергии. Озеро, которое они назвали Источником Вечности, было источником жизни в мире. Его могущественная энергия питала корни мира и давала возможность жизни пустить побеги в его плодородной почве. Со временем травы, деревья, монстры и создания всех видов появились на первобытном континенте.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В центре континента титаны поместили озеро искрящейся энергии. Озеро, которое они назвали Источником Вечности, было источником жизни в мире. Его могущественная энергия питала корни мира и давала возможность жизни пустить побеги в его плодородной почве. Со временем травы, деревья, монстры и создания всех видов появились на первобытном континенте.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1794,'В честь сумерек, павших на мир в их последний день работы, титаны назвали этот континент Калимдором – "землей вечного звездного света".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В честь сумерек, павших на мир в их последний день работы, титаны назвали этот континент Калимдором – "землей вечного звездного света".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1795,'Удовлетворенные упорядочением этого небольшого мира и окончанием трудов, титаны приготовились покинуть Азерот. Однако перед своим уходом они поручили величайшим существам этого мира присматривать за Калимдором, поскольку любое враждебное вмешательство могло поколебать его идеальный баланс. В то время существовало множество родов драконов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Удовлетворенные упорядочением этого небольшого мира и окончанием трудов, титаны приготовились покинуть Азерот. Однако перед своим уходом они поручили величайшим существам этого мира присматривать за Калимдором, поскольку любое враждебное вмешательство могло поколебать его идеальный баланс. В то время существовало множество родов драконов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1796,'Но пять родов главенствовали над своими собратьями. Титаны избрали эти пять стай, чтобы те присматривали за расцветающим миром. Величайшие члены Пантеона отдали часть своей силы каждому из лидеров стай. Эти магические драконы (указанные ниже) стали известны как Великие аспекты или Великие драконы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но пять родов главенствовали над своими собратьями. Титаны избрали эти пять стай, чтобы те присматривали за расцветающим миром. Величайшие члены Пантеона отдали часть своей силы каждому из лидеров стай. Эти магические драконы (указанные ниже) стали известны как Великие аспекты или Великие драконы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1797,'Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму. Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы. Мужественный и благородный Ноздорму стал известен как Вневременный.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Аман-Тул, Великий Отец Пантеона, отдал часть своей вселенской силы огромному бронзовому дракону, Ноздорму. Великий Отец велел Ноздорму защищать само время и управлять извечными потоками рока и судьбы. Мужественный и благородный Ноздорму стал известен как Вневременный.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1798,'Эонар, титан-покровительница всего живого, отдала часть своей силы красной огромной Алекстразе. С тех пор Алекстраза зовется Хранительницей Жизни и охраняет всех созданий этого мира. За ее мудрость и безграничное сострадание ко всему живому Алекстраза была избрана Королевой драконов и возглавила свой род.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эонар, титан-покровительница всего живого, отдала часть своей силы красной огромной Алекстразе. С тех пор Алекстраза зовется Хранительницей Жизни и охраняет всех созданий этого мира. За ее мудрость и безграничное сострадание ко всему живому Алекстраза была избрана Королевой драконов и возглавила свой род.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1799,'Эонар также даровала младшей сестре Алекстразы, изящной зеленой драконице Изере, определенную власть над природой. Изера впала в вечный транс, именуемый "Сном Творения". Известная под именем Дремлющей, она следит за природой мира из царства Изумрудного Сна.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эонар также даровала младшей сестре Алекстразы, изящной зеленой драконице Изере, определенную власть над природой. Изера впала в вечный транс, именуемый "Сном Творения". Известная под именем Дремлющей, она следит за природой мира из царства Изумрудного Сна.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1800,'Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы. С того времени Малигос, известный как Хранитель Магии, хранит магию и тайные знания.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Титан Норганнон, хранитель знаний и владыка магии, даровал синему дракону Малигосу часть своей великой силы. С того времени Малигос, известный как Хранитель Магии, хранит магию и тайные знания.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1801,'Титан Каз\'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему черному змею Нелтариону. Великодушный Нелтарион, позже известный как Хранитель Земли, получил власть над почвой, камнем и подземными недрами. Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Титан Каз\'горот, ваятель и кузнец мира, даровал часть своей огромной силы могучему черному змею Нелтариону. Великодушный Нелтарион, позже известный как Хранитель Земли, получил власть над почвой, камнем и подземными недрами. Воплотив в себе силу мира, он стал самым могущественным сторонником Алекстразы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1802,'Получив могущество, пять Аспектов были уполномочены охранять мир в отсутствие титанов. Оставив драконов, готовых защищать их творение, титаны покинули Азерот навеки. К сожалению, Саргерас очень быстро узнал о существовании нового мира…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Получив могущество, пять Аспектов были уполномочены охранять мир в отсутствие титанов. Оставив драконов, готовых защищать их творение, титаны покинули Азерот навеки. К сожалению, Саргерас очень быстро узнал о существовании нового мира…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1803,'Высокорожденные довольно бездумно обращались с магией, в результате чего из источника Вечности начали расходиться волны, проникающие даже в самые дальние уголки Великой запредельной тьмы и привлекающие внимание тамошних обитателей. Вскоре и Саргерас – Великий враг всего живого и Разрушитель миров – почуял эти волны и устремился к их источнику.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Высокорожденные довольно бездумно обращались с магией, в результате чего из источника Вечности начали расходиться волны, проникающие даже в самые дальние уголки Великой запредельной тьмы и привлекающие внимание тамошних обитателей. Вскоре и Саргерас – Великий враг всего живого и Разрушитель миров – почуял эти волны и устремился к их источнику.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1804,'Когда Саргерас увидел юный мир Азерота и почуял энергию источника Вечности, в нем проснулся неутолимый голод, и великий темный бог Безымянной Бездны решил уничтожить этот мир и завладеть его силой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда Саргерас увидел юный мир Азерота и почуял энергию источника Вечности, в нем проснулся неутолимый голод, и великий темный бог Безымянной Бездны решил уничтожить этот мир и завладеть его силой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1805,'Собрав свою армию – великий Пылающий Легион, – Саргерас пошел на мирный Азерот войной. Легион состоял из миллионов кровожадных демонов, слетевшихся со всех концов Вселенной, и этим демонам не терпелось начать вторжение. Ближайшие помощники Саргераса, Архимонд Осквернитель и Маннорот Разрушитель, подготовили своих зловещих воинов к решительному удару.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Собрав свою армию – великий Пылающий Легион, – Саргерас пошел на мирный Азерот войной. Легион состоял из миллионов кровожадных демонов, слетевшихся со всех концов Вселенной, и этим демонам не терпелось начать вторжение. Ближайшие помощники Саргераса, Архимонд Осквернитель и Маннорот Разрушитель, подготовили своих зловещих воинов к решительному удару.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1807,'Как только все было готово, Саргерас начал вторжение в Азерот. Демоны Пылающего Легиона ворвались в мир через источник Вечности и осадили мирно спящие города ночных эльфов. Под предводительством Маннорота и Архимонда Легион промчался по землям Калимдора, оставляя за собой лишь боль и пепел.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Как только все было готово, Саргерас начал вторжение в Азерот. Демоны Пылающего Легиона ворвались в мир через источник Вечности и осадили мирно спящие города ночных эльфов. Под предводительством Маннорота и Архимонда Легион промчался по землям Калимдора, оставляя за собой лишь боль и пепел.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1808,'Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры. Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая все живое на своем пути. Демонические гончие Скверны наводнили сельскую местность. Разумеется, храбрые воины-калдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Демоны-чернокнижники призвали инферналов, которые обрушились на изящные шпили калимдорских храмов будто адские пылающие метеоры. Армия кровожадных убийц, называемых стражниками ужаса, прошла по калимдорским полям, уничтожая все живое на своем пути. Демонические гончие Скверны наводнили сельскую местность. Разумеется, храбрые воины-калдорай пытались защитить свои родные земли, но они не могли сдержать всю ярость Пылающего Легиона, и им пришлось шаг за шагом отступать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1809,'Искать спасения для своего застигнутого врасплох народа пришлось Малфуриону Ярости Бури. Родной брат Малфуриона, Иллидан, практиковал магию высокорожденных, и Малфуриона очень сильно беспокоила его растущая одержимость. Малфурион убедил брата отказаться от свого пагубного пристрастия и вместе с ним отправиться на поиски Кенария. Кроме того, братьям надлежало собрать силы для сопротивления демонам.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Искать спасения для своего застигнутого врасплох народа пришлось Малфуриону Ярости Бури. Родной брат Малфуриона, Иллидан, практиковал магию высокорожденных, и Малфуриона очень сильно беспокоила его растущая одержимость. Малфурион убедил брата отказаться от свого пагубного пристрастия и вместе с ним отправиться на поиски Кенария. Кроме того, братьям надлежало собрать силы для сопротивления демонам.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1810,'С братьями отправилась юная жрица Тиранда, служительница Элуны. И Малфурион, и Иллидан были влюблены в нее, однако сердце Тиранды принадлежало лишь Малфуриону. Иллидан ревновал девушку к своему брату и завидовал их любви, однако его душевные страдания не шли ни в какое сравнение с муками от магической зависимости.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С братьями отправилась юная жрица Тиранда, служительница Элуны. И Малфурион, и Иллидан были влюблены в нее, однако сердце Тиранды принадлежало лишь Малфуриону. Иллидан ревновал девушку к своему брату и завидовал их любви, однако его душевные страдания не шли ни в какое сравнение с муками от магической зависимости.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1811,'Зависимость Иллидана от магической энергии непрестанно мучила его, и он с трудом сдерживался, чтобы не броситься к источнику Вечности. Однако Тиранда все время была рядом и поддерживала его, так что в итоге они все же добрались до полубога-отшельника по имени Кенарий.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Зависимость Иллидана от магической энергии непрестанно мучила его, и он с трудом сдерживался, чтобы не броситься к источнику Вечности. Однако Тиранда все время была рядом и поддерживала его, так что в итоге они все же добрались до полубога-отшельника по имени Кенарий.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1812,'Кенарий жил на священных Лунных полянах на горе Хиджал. Он согласился помочь ночным эльфам, найти древних драконов и обратиться к ним за помощью. Драконы, в свою очередь, тоже решили не оставаться в стороне и, ведомые исполинской красной Алекстразой, отправились на войну с демонами и их адскими предводителями.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кенарий жил на священных Лунных полянах на горе Хиджал. Он согласился помочь ночным эльфам, найти древних драконов и обратиться к ним за помощью. Драконы, в свою очередь, тоже решили не оставаться в стороне и, ведомые исполинской красной Алекстразой, отправились на войну с демонами и их адскими предводителями.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1814,'Пока в самом сердце Азшары гремела битва, одурманенная королева с нетерпением дожидалась прибытия Саргераса, который готовился пройти сквозь источник Вечности и самолично ступить на землю Азерота. Его исполинская тень медленно приближалась к поверхности Источника, а Азшара тем временем собрала своих самых могущественных служителей, чтобы они объединили свои силы, прочитали одно заклинание и расширили портал настолько, чтобы Саргерас смог пройти через него.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Пока в самом сердце Азшары гремела битва, одурманенная королева с нетерпением дожидалась прибытия Саргераса, который готовился пройти сквозь источник Вечности и самолично ступить на землю Азерота. Его исполинская тень медленно приближалась к поверхности Источника, а Азшара тем временем собрала своих самых могущественных служителей, чтобы они объединили свои силы, прочитали одно заклинание и расширили портал настолько, чтобы Саргерас смог пройти через него.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1815,'Во время битвы на полях Калимдора произошло нечто ужасное. Подробности этого происшествия были утеряны, но известно лишь то, что дракон Нелтарион, аспект земли, в пылу битвы с Демонами вдруг сошел с ума. Он начал распадаться на части, по всей его черной шкуре вспыхивали языки пламени, и в итоге это разъяренное горящее чудовище назвало себя Смертокрылом и напало на своих собратьев, из-за чего пятеро драконов были вынуждены покинуть поле боя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во время битвы на полях Калимдора произошло нечто ужасное. Подробности этого происшествия были утеряны, но известно лишь то, что дракон Нелтарион, аспект земли, в пылу битвы с Демонами вдруг сошел с ума. Он начал распадаться на части, по всей его черной шкуре вспыхивали языки пламени, и в итоге это разъяренное горящее чудовище назвало себя Смертокрылом и напало на своих собратьев, из-за чего пятеро драконов были вынуждены покинуть поле боя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1816,'Внезапное предательство Смертокрыла повлекло за собой столь губительные последствия, что остальные драконы так никогда и не смогли оправиться от потрясения. Израненная и убитая горем Алекстраза и ее пятеро собратьев покинули поле боя, оставив своих смертных союзников один на один с многократно превосходящей их армией демонов. Малфуриону и его соратникам едва удалось выжить в последовавшем натиске.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Внезапное предательство Смертокрыла повлекло за собой столь губительные последствия, что остальные драконы так никогда и не смогли оправиться от потрясения. Израненная и убитая горем Алекстраза и ее пятеро собратьев покинули поле боя, оставив своих смертных союзников один на один с многократно превосходящей их армией демонов. Малфуриону и его соратникам едва удалось выжить в последовавшем натиске.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1817,'Малфурион был уверен, что демоны рвутся в этот мир из Источника Вечности, поэтому он стал настаивать на его уничтожении. Но так как именно Источник являлся залогом могущества и бессмертия Ночных эльфов, такое решение привело остальных в ужас. Однако Тиранда поняла весь замысел Малфуриона и убедила Кенария и его соратников напасть на храм Азшары и найти способ закрыть источник раз и навсегда.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Малфурион был уверен, что демоны рвутся в этот мир из Источника Вечности, поэтому он стал настаивать на его уничтожении. Но так как именно Источник являлся залогом могущества и бессмертия Ночных эльфов, такое решение привело остальных в ужас. Однако Тиранда поняла весь замысел Малфуриона и убедила Кенария и его соратников напасть на храм Азшары и найти способ закрыть источник раз и навсегда.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1828,'Немногие уцелевшие при взрыве эльфы собрались вместе, наспех сколотили несколько плотов и медленно поплыли к далекой земле. Милостью Элуны Великий Раскол пережили и Малфурион с Тирандой, и Кенарий. Измученные герои согласились стать предводителями своих выживших сородичей и обустроить для них новый дом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Немногие уцелевшие при взрыве эльфы собрались вместе, наспех сколотили несколько плотов и медленно поплыли к далекой земле. Милостью Элуны Великий Раскол пережили и Малфурион с Тирандой, и Кенарий. Измученные герои согласились стать предводителями своих выживших сородичей и обустроить для них новый дом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1829,'Они плыли в молчании, глядя на то, что осталось от их народа, и понимая, что в этом виноваты лишь они сами и их страсти. Конечно, после уничтожения Источника Саргерасу и Пылающему Легиону больше не было хода в этот мир, но цена, которую пришлось заплатить за это, была поистине ужасной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Они плыли в молчании, глядя на то, что осталось от их народа, и понимая, что в этом виноваты лишь они сами и их страсти. Конечно, после уничтожения Источника Саргерасу и Пылающему Легиону больше не было хода в этот мир, но цена, которую пришлось заплатить за это, была поистине ужасной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1832,'Иллидан тоже пережил Раскол и добрался до вершины Хиджала намного раньше Малфуриона и ночных эльфов. Он был одержим идеей сохранить в этом мире магию, поэтому вылил в горное озеро драгоценную воду из Источника Жизни, которую хранил в нескольких сосудах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Иллидан тоже пережил Раскол и добрался до вершины Хиджала намного раньше Малфуриона и ночных эльфов. Он был одержим идеей сохранить в этом мире магию, поэтому вылил в горное озеро драгоценную воду из Источника Жизни, которую хранил в нескольких сосудах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1833,'Воды горного озера вмиг напитались энергией Источника Вечности, и оно превратилось в новый источник. Иллидан ликовал: он считал, что это станет настоящим даром для будущих поколений, поэтому был несказанно удивлен, когда на него вдруг набросился его брат. Малфурион объяснил Иллидану, что в основе всей магии лежит хаос и что ее использование неизбежно приведет к одержимости и войнам. Иллидан, однако, не спешил отказываться от своей магической силы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Воды горного озера вмиг напитались энергией Источника Вечности, и оно превратилось в новый источник. Иллидан ликовал: он считал, что это станет настоящим даром для будущих поколений, поэтому был несказанно удивлен, когда на него вдруг набросился его брат. Малфурион объяснил Иллидану, что в основе всей магии лежит хаос и что ее использование неизбежно приведет к одержимости и войнам. Иллидан, однако, не спешил отказываться от своей магической силы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1834,'Малфурион знал, что планы его брата, одержимого жаждой могущества, не сулят ничего хорошего, поэтому он решил раз и навсегда избавиться от Иллидана. Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи. Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за пленником, чтобы тот не сбежал.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Малфурион знал, что планы его брата, одержимого жаждой могущества, не сулят ничего хорошего, поэтому он решил раз и навсегда избавиться от Иллидана. Вместе с Кенарием они заключили его в тюрьму под холмами, где Иллидану надлежало оставаться до конца его жизни, обессиленным и закованным в цепи. Малфурион поручил юной стражнице по имени Майев Песнь Теней следить за пленником, чтобы тот не сбежал.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1835,'Ночные эльфы не стали уничтожать новый Источник Вечности, чтобы не вызвать новой катастрофы. Однако Малфурион объявил, что ночные эльфы больше никогда не будут практиковать магию, после чего они под руководством Кенария стали изучать древнее искусство друидизма, которое помогло бы им исцелить истерзанную землю и вырастить новые леса у подножия горы Хиджал.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ночные эльфы не стали уничтожать новый Источник Вечности, чтобы не вызвать новой катастрофы. Однако Малфурион объявил, что ночные эльфы больше никогда не будут практиковать магию, после чего они под руководством Кенария стали изучать древнее искусство друидизма, которое помогло бы им исцелить истерзанную землю и вырастить новые леса у подножия горы Хиджал.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1836,'На протяжении многих лет ночные эльфы работали не покладая рук, чтобы восстановить то, что осталось от их древней родины. Они оставили свои разрушенные храмы и дороги зарастать и построили новые дома среди зеленых деревьев и тенистых холмов у подножия горы Хиджал. Мало-помалу из своих укрытий выбрались и драконы, пережившие Великий Раскол.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На протяжении многих лет ночные эльфы работали не покладая рук, чтобы восстановить то, что осталось от их древней родины. Они оставили свои разрушенные храмы и дороги зарастать и построили новые дома среди зеленых деревьев и тенистых холмов у подножия горы Хиджал. Мало-помалу из своих укрытий выбрались и драконы, пережившие Великий Раскол.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1837,'Алекстраза красная, Изера зеленая и Ноздорму бронзовый опустились на тихие поляны ночных эльфов и посмотрели на плоды их трудов. Малфурион, ставший могущественным верховным друидом, поприветствовал драконов и рассказал им о новом Источнике Вечности.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Алекстраза красная, Изера зеленая и Ноздорму бронзовый опустились на тихие поляны ночных эльфов и посмотрели на плоды их трудов. Малфурион, ставший могущественным верховным друидом, поприветствовал драконов и рассказал им о новом Источнике Вечности.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1838,'Эта новость встревожила великих драконов, потому что пока существовал источник, существовала и возможность того, что Пылающий Легион когда-нибудь снова вернется в этот мир. Малфурион и три дракона договорились вечно охранять Источник и решили сделать все возможное для того, чтобы демоны никогда больше не появились в этом мире.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эта новость встревожила великих драконов, потому что пока существовал источник, существовала и возможность того, что Пылающий Легион когда-нибудь снова вернется в этот мир. Малфурион и три дракона договорились вечно охранять Источник и решили сделать все возможное для того, чтобы демоны никогда больше не появились в этом мире.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1839,'Алекстраза Хранительница Жизни опустила в источник зачарованный желудь. Пробужденный могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Алекстраза Хранительница Жизни опустила в источник зачарованный желудь. Пробужденный могущественными водами, он вырос в огромное дерево, корни которого тянулись в самые недра Источника, а крона, казалось, достигала небес.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1840,'Огромное древо стало символом вечного союза ночных эльфов и природы, а его жизнетворная энергия впоследствии исцелила весь мир. Ночные эльфы дали своему Древу Жизни имя Нордрассил, что на их языке означало "корона жизни".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Огромное древо стало символом вечного союза ночных эльфов и природы, а его жизнетворная энергия впоследствии исцелила весь мир. Ночные эльфы дали своему Древу Жизни имя Нордрассил, что на их языке означало "корона жизни".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1841,'Ноздорму Вневременный наложил на Древо Жизни заклятье, которое сделало ночных эльфов бессмертными, вечно молодыми и невосприимчивыми к любым болезням.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ноздорму Вневременный наложил на Древо Жизни заклятье, которое сделало ночных эльфов бессмертными, вечно молодыми и невосприимчивыми к любым болезням.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1842,'Изера Дремлющая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон. Этот огромный мир, населенный духами, не подчинялся законам физического мира. Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Изера Дремлющая тоже зачаровала Древо Жизни, связав его со своим миром, астральным измерением, известным как Изумрудный Сон. Этот огромный мир, населенный духами, не подчинялся законам физического мира. Из своего Сна Изера могла управлять жизнью природы и развитием всего остального мира.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1843,'Древо Жизни связывало всех ночных эльфов-друидов, включая Малфуриона, с Изумрудным Сном. Заключая договор с драконами, они согласились периодически засыпать на целые века, чтобы их духи могли блуждать по бесконечным тропам сна Изеры. Конечно, друидов печалило то, что придется потерять столько лет своей жизни, но, тем не менее, они самоотверженно пошли на эту сделку.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Древо Жизни связывало всех ночных эльфов-друидов, включая Малфуриона, с Изумрудным Сном. Заключая договор с драконами, они согласились периодически засыпать на целые века, чтобы их духи могли блуждать по бесконечным тропам сна Изеры. Конечно, друидов печалило то, что придется потерять столько лет своей жизни, но, тем не менее, они самоотверженно пошли на эту сделку.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1846,'Малфурион и друиды не слушали речей Дат\'Ремара и объявили высокорожденным, что любое использование магии будет караться смертью. Однако Дат\'Ремар и его последователи все же попытались нарушить закон друидов, но попытка эта закончилась крахом, и в результате в Ясеневом лесу разразилась ужасная магическая буря.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Малфурион и друиды не слушали речей Дат\'Ремара и объявили высокорожденным, что любое использование магии будет караться смертью. Однако Дат\'Ремар и его последователи все же попытались нарушить закон друидов, но попытка эта закончилась крахом, и в результате в Ясеневом лесу разразилась ужасная магическая буря.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1848,'Высокорожденные, или Кель\'дорай, как их ранее называла Азшара, в конце концов достигли берегов восточных земель, которые люди позднее назовут Лордерон. Они планировали создать свое собственное королевство магов, Кель\'Талас, и отречься от поклонения луне и от ночного образа жизни, свойственных ночным эльфам. С тех пор и вовеки они станут поклоняться солнцу и будут известны как высшие эльфы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Высокорожденные, или Кель\'дорай, как их ранее называла Азшара, в конце концов достигли берегов восточных земель, которые люди позднее назовут Лордерон. Они планировали создать свое собственное королевство магов, Кель\'Талас, и отречься от поклонения луне и от ночного образа жизни, свойственных ночным эльфам. С тех пор и вовеки они станут поклоняться солнцу и будут известны как высшие эльфы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1849,'С уходом своих своевольных собратьев ночные эльфы вновь стали оберегать свою зачарованную родину. Друиды, чувствуя, что скоро должны уснуть, готовились ко сну и прощались со своими родными и близкими.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С уходом своих своевольных собратьев ночные эльфы вновь стали оберегать свою зачарованную родину. Друиды, чувствуя, что скоро должны уснуть, готовились ко сну и прощались со своими родными и близкими.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1850,'Тиранда, ставшая Верховной жрицей Элуны, умоляла своего возлюбленного Малфуриона не уходить в Изумрудный Сон Изеры. Но Малфурион, считавший своим долгом вступить на изменчивые тропы Спящей, попрощался со жрицей и поклялся, что они никогда не разлучатся, до тех пор пока хранят верность своей любви.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тиранда, ставшая Верховной жрицей Элуны, умоляла своего возлюбленного Малфуриона не уходить в Изумрудный Сон Изеры. Но Малфурион, считавший своим долгом вступить на изменчивые тропы Спящей, попрощался со жрицей и поклялся, что они никогда не разлучатся, до тех пор пока хранят верность своей любви.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1851,'Оставшись в одиночестве защищать Калимдор от опасностей нового мира, Тиранда собрала мощную армию своих сестер, ночных эльфиек. Бесстрашные, искусные воительницы, поклявшиеся защищать Калимдор, стали известны как Часовые. Хотя они предпочитали самостоятельно патрулировать тенистый Ясеневый лес, у них было множество союзников, которых они призывали во время опасностей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Оставшись в одиночестве защищать Калимдор от опасностей нового мира, Тиранда собрала мощную армию своих сестер, ночных эльфиек. Бесстрашные, искусные воительницы, поклявшиеся защищать Калимдор, стали известны как Часовые. Хотя они предпочитали самостоятельно патрулировать тенистый Ясеневый лес, у них было множество союзников, которых они призывали во время опасностей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1852,'Полубог Кенарий обитал неподалеку оттуда на Лунных полянах горы Хиджал. Его сыновья, известные как Хранители Рощ, наблюдали за ночными эльфами и регулярно помогали Часовым поддерживать мир на этих землях. Даже скромные дочери Кенария, дриады, стали появляться все чаще и чаще.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Полубог Кенарий обитал неподалеку оттуда на Лунных полянах горы Хиджал. Его сыновья, известные как Хранители Рощ, наблюдали за ночными эльфами и регулярно помогали Часовым поддерживать мир на этих землях. Даже скромные дочери Кенария, дриады, стали появляться все чаще и чаще.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1853,'Охрана Ясеневого леса занимала все время Тиранды, но она тосковала без Малфуриона. Шли века, друиды спали, а ее опасения насчет нового вторжения демонов росли. Она не могла избавиться от тревожного ощущения, что, возможно, Пылающий Легион все еще здесь, за пределами Великой тьмы неба, и что он готовится отомстить ночным эльфам и всему Азероту.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Охрана Ясеневого леса занимала все время Тиранды, но она тосковала без Малфуриона. Шли века, друиды спали, а ее опасения насчет нового вторжения демонов росли. Она не могла избавиться от тревожного ощущения, что, возможно, Пылающий Легион все еще здесь, за пределами Великой тьмы неба, и что он готовится отомстить ночным эльфам и всему Азероту.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1854,'Высшие эльфы, ведомые Дат\'ремаром, покинули Калимдор и миновали Водоворот с его бурями. Их флот много долгих лет плавал среди обломков старого мира, они открыли множество тайн и потерянных королевств. Дат\'ремар, взявший имя Солнечный Скиталец (или "тот, кто ходит весь день"), искал места с большей магической энергией, чтобы построить там новое королевство для своего народа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Высшие эльфы, ведомые Дат\'ремаром, покинули Калимдор и миновали Водоворот с его бурями. Их флот много долгих лет плавал среди обломков старого мира, они открыли множество тайн и потерянных королевств. Дат\'ремар, взявший имя Солнечный Скиталец (или "тот, кто ходит весь день"), искал места с большей магической энергией, чтобы построить там новое королевство для своего народа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1855,'В конце концов они ступили на берега королевства, которое люди позднее назовут Лордерон. Продвигаясь в глубь континента, высшие эльфы основали поселение на спокойных Тирисфальских лесах. Но через несколько лет многие из них начали сходить с ума. Возникло предположение, что что-то злое спало в недрах тех земель, но эти слухи так и не оправдались. Высшие эльфы собрали все свое добро и двинулись на север, к землям, богатым энергетическими линиями.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В конце концов они ступили на берега королевства, которое люди позднее назовут Лордерон. Продвигаясь в глубь континента, высшие эльфы основали поселение на спокойных Тирисфальских лесах. Но через несколько лет многие из них начали сходить с ума. Возникло предположение, что что-то злое спало в недрах тех земель, но эти слухи так и не оправдались. Высшие эльфы собрали все свое добро и двинулись на север, к землям, богатым энергетическими линиями.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1856,'В то время как высшие эльфы шли по гористым землям Лордерона, их путешествие становилось все более опасным. Поскольку они были отрезаны от животворных энергий Источника Вечности, многие из них начали болеть из-за холодного климата или умирать от голода. Но ужаснее всего было то, что теперь они были не бессмертны и не могли противостоять стихиям.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В то время как высшие эльфы шли по гористым землям Лордерона, их путешествие становилось все более опасным. Поскольку они были отрезаны от животворных энергий Источника Вечности, многие из них начали болеть из-за холодного климата или умирать от голода. Но ужаснее всего было то, что теперь они были не бессмертны и не могли противостоять стихиям.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1857,'Кроме того, они стали ниже ростом, а их кожа потеряла характерный фиолетовый оттенок. Несмотря на трудности, они смогли противостоять многим неведомым существам, каких в Калимдоре и не видывали. Они нашли племена диких людей, которые охотились в древних чащах. Но самую большую угрозу представляли собой алчные и хитрые лесные тролли Зул\'Амана.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кроме того, они стали ниже ростом, а их кожа потеряла характерный фиолетовый оттенок. Несмотря на трудности, они смогли противостоять многим неведомым существам, каких в Калимдоре и не видывали. Они нашли племена диких людей, которые охотились в древних чащах. Но самую большую угрозу представляли собой алчные и хитрые лесные тролли Зул\'Амана.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1859,'После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор. В глуши северных лесов они основали королевство Кель\'Талас и поклялись создать могущественную империю, которая будет во всем превосходить цивилизацию их собратьев, калдорай. К сожалению, эльфы вскоре узнали, что основали Кель\'Талас на развалинах древнего города троллей, который те до сих пор считали священным. Тролли почти сразу же начали атаковать эльфийские поселения.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После долгих лет странствий высшие эльфы, наконец, нашли земли, напоминавшие Калимдор. В глуши северных лесов они основали королевство Кель\'Талас и поклялись создать могущественную империю, которая будет во всем превосходить цивилизацию их собратьев, калдорай. К сожалению, эльфы вскоре узнали, что основали Кель\'Талас на развалинах древнего города троллей, который те до сих пор считали священным. Тролли почти сразу же начали атаковать эльфийские поселения.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1860,'Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить. Под командой Дат\'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом. Некоторые эльфы, помнившие древние предупреждения калдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Упрямые эльфы, не желавшие отдавать свои новые владения, использовали магию, оставшуюся от Источника Вечности, и заставили свирепых троллей отступить. Под командой Дат\'Ремара они сумели победить отряды Амани, которые десятикратно превосходили их числом. Некоторые эльфы, помнившие древние предупреждения калдорай, почувствовали, что использование магии может привлечь внимание изгнанного Пылающего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1861,'Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией. Они установили в разных точках Кель\'Таласа, на границах магического барьера, цепь Рунических камней. Рунические камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Поэтому они решили скрыть свои земли защитным барьером, который позволял бы им спокойно заниматься магией. Они установили в разных точках Кель\'Таласа, на границах магического барьера, цепь Рунических камней. Рунические камни не только скрывали магию эльфов от внеземных угроз, но и помогали отпугивать суеверных троллей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1862,'С течением времени Кель\'Талас сделался сияющим памятником трудам и магическому мастерству высших эльфов. Его прекрасные дворцы были созданы в том же архитектурном стиле, что и древние чертоги Калимдора, однако они великолепно вписывались в естественный ландшафт тех мест. Кель\'Талас стал сияющим самоцветом, который так хотели создать эльфы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С течением времени Кель\'Талас сделался сияющим памятником трудам и магическому мастерству высших эльфов. Его прекрасные дворцы были созданы в том же архитектурном стиле, что и древние чертоги Калимдора, однако они великолепно вписывались в естественный ландшафт тех мест. Кель\'Талас стал сияющим самоцветом, который так хотели создать эльфы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1863,'Правительством Кель\'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть. Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель. Под защитой барьера высшие эльфы отвергли былые предупреждения калдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правительством Кель\'Таласа стал совет Луносвета, хотя династия Солнечных Скитальцев также отчасти сохраняла политическую власть. Включавший в себя семерых величайших эльфийских лордов совет заботился о безопасности эльфов и эльфийских земель. Под защитой барьера высшие эльфы отвергли былые предупреждения калдорай и с преступной беспечностью продолжали использовать магию практически во всех аспектах своей жизни.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1864,'Почти четыре тысячи лет высшие эльфы спокойно жили в своем укромном королевстве. Тем не менее мстительные тролли сдаваться не собирались. В глуши лесов они строили планы и копили силы. В конце концов могучая армия троллей вышла из тени лесов и вновь осадила сияющие башни Кель\'Таласа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Почти четыре тысячи лет высшие эльфы спокойно жили в своем укромном королевстве. Тем не менее мстительные тролли сдаваться не собирались. В глуши лесов они строили планы и копили силы. В конце концов могучая армия троллей вышла из тени лесов и вновь осадила сияющие башни Кель\'Таласа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1865,'В то время как высшие эльфы сражались не на жизнь, а на смерть против яростного натиска троллей, разрозненные, ведущие кочевой образ жизни люди Лордерона боролись за объединение своих земель. Изначально племена людей постоянно совершали набеги на другие людские поселения, пренебрегая честью и не заботясь об объединении расы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В то время как высшие эльфы сражались не на жизнь, а на смерть против яростного натиска троллей, разрозненные, ведущие кочевой образ жизни люди Лордерона боролись за объединение своих земель. Изначально племена людей постоянно совершали набеги на другие людские поселения, пренебрегая честью и не заботясь об объединении расы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1866,'Но одно племя, известное как Арати, поняло, что тролли сделались слишком серьезной угрозой, чтобы продолжать их игнорировать. Арати хотели подчинить себе все племена, чтобы выступить единым фронтом против троллей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но одно племя, известное как Арати, поняло, что тролли сделались слишком серьезной угрозой, чтобы продолжать их игнорировать. Арати хотели подчинить себе все племена, чтобы выступить единым фронтом против троллей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1867,'За шесть лет хитрые Арати победили и перехитрили все вражеские племена. После каждой победы Арати предлагали завоеванным людям мир и равноправие, таким образом получая верность побежденных. В конце концов племя Арати включило в себя много других племен, а мощь их армии росла с огромной скоростью.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','За шесть лет хитрые Арати победили и перехитрили все вражеские племена. После каждой победы Арати предлагали завоеванным людям мир и равноправие, таким образом получая верность побежденных. В конце концов племя Арати включило в себя много других племен, а мощь их армии росла с огромной скоростью.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1868,'Убежденные в том, что они могут самостоятельно противостоять троллям или даже эльфам, военачальники Арати решили построить могучий город-крепость в южных регионах Лордерона. Город, названный Cтром, стал столицей государства Арати, Аратора. В то время как Аратор процветал, люди со всего огромного континента шли на юг, дабы жить под защитой Cтрома.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Убежденные в том, что они могут самостоятельно противостоять троллям или даже эльфам, военачальники Арати решили построить могучий город-крепость в южных регионах Лордерона. Город, названный Cтром, стал столицей государства Арати, Аратора. В то время как Аратор процветал, люди со всего огромного континента шли на юг, дабы жить под защитой Cтрома.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1869,'Объединенные под одним знаменем, людские племена создали сильную, жизнерадостную культуру. Торадин, король Аратора, знал, что таинственные эльфы на севере постоянно сражались с троллями, но отказался рисковать безопасностью своих людей ради скрытных незнакомцев. Много месяцев прошло, прежде чем слухи о близком поражении эльфов распространились с севера. Только тогда, когда измученные послы Кель\'Таласа добрались до Cтрома, Торадин осознал истинную угрозу, идущую от троллей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Объединенные под одним знаменем, людские племена создали сильную, жизнерадостную культуру. Торадин, король Аратора, знал, что таинственные эльфы на севере постоянно сражались с троллями, но отказался рисковать безопасностью своих людей ради скрытных незнакомцев. Много месяцев прошло, прежде чем слухи о близком поражении эльфов распространились с севера. Только тогда, когда измученные послы Кель\'Таласа добрались до Cтрома, Торадин осознал истинную угрозу, идущую от троллей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1870,'Эльфы сказали Торадину, что армия троллей неисчислима, что, уничтожив Кель\'Талас, они двинутся на юг. Будучи в отчаянии, эльфы, нуждавшиеся в военной помощи, быстро согласились обучить некоторых избранных людей искусству магии в обмен на помощь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эльфы сказали Торадину, что армия троллей неисчислима, что, уничтожив Кель\'Талас, они двинутся на юг. Будучи в отчаянии, эльфы, нуждавшиеся в военной помощи, быстро согласились обучить некоторых избранных людей искусству магии в обмен на помощь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1871,'Торадин, не доверявший любой магии, согласился помочь эльфам исключительно по необходимости. Практически немедленно эльфийские волшебники прибыли в Аратор и начали обучать группу людей магии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Торадин, не доверявший любой магии, согласился помочь эльфам исключительно по необходимости. Практически немедленно эльфийские волшебники прибыли в Аратор и начали обучать группу людей магии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1872,'Эльфы обнаружили, что хотя люди были неловки в обращении с магией, у них была потрясающая природная связь с ней. Эльфы обучили сотню людей самым азам своих магических тайн: не больше, чем было нужно для битвы с троллями. Убежденные в том, что их ученики-люди готовы вступить в бой, эльфы покинули Cтром и пошли на север вместе с могучей армией короля Торадина.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эльфы обнаружили, что хотя люди были неловки в обращении с магией, у них была потрясающая природная связь с ней. Эльфы обучили сотню людей самым азам своих магических тайн: не больше, чем было нужно для битвы с троллями. Убежденные в том, что их ученики-люди готовы вступить в бой, эльфы покинули Cтром и пошли на север вместе с могучей армией короля Торадина.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1873,'Объединившиеся эльфийские и человеческие армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор. Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей. Эльфийские властители решили, что пришло время ниспослать силы магии на врага.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Объединившиеся эльфийские и человеческие армии вступили в схватку с огромной армией троллей у подножья Альтеракских гор. Битва продолжалась много дней, но неослабевавшая армия Аратора не уставала и не отступала под натиском троллей. Эльфийские властители решили, что пришло время ниспослать силы магии на врага.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1874,'Сотня людских магов и множество эльфийских волшебников вызвали ярость небес и напустили пламя на армию троллей. Огонь стихий лишал троллей возможности исцеления ран, сжигая их изнутри и снаружи.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сотня людских магов и множество эльфийских волшебников вызвали ярость небес и напустили пламя на армию троллей. Огонь стихий лишал троллей возможности исцеления ран, сжигая их изнутри и снаружи.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1875,'Когда натиск армии троллей был сломлен и они попытались сбежать, армия Торадина начала преследование, беспощадно убивая всех троллей, которых удалось настичь. Тролли так никогда и не оправились от этого поражения, а в истории больше не будет единого народа троллей. Убежденные в том, что Кель\'Талас спасен от разрушения, эльфы поклялись в верности и дружбе Аратору и семье его короля Торадина. Люди и эльфы с тех пор были в мирных отношениях.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда натиск армии троллей был сломлен и они попытались сбежать, армия Торадина начала преследование, беспощадно убивая всех троллей, которых удалось настичь. Тролли так никогда и не оправились от этого поражения, а в истории больше не будет единого народа троллей. Убежденные в том, что Кель\'Талас спасен от разрушения, эльфы поклялись в верности и дружбе Аратору и семье его короля Торадина. Люди и эльфы с тех пор были в мирных отношениях.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1876,'Когда тролли были изгнаны из северных земель, эльфы Кель\'Таласа направили все свои усилия на воссоздание своего великолепного царства. Армия Аратора с победой вернулась домой, в южные земли Cтрома.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда тролли были изгнаны из северных земель, эльфы Кель\'Таласа направили все свои усилия на воссоздание своего великолепного царства. Армия Аратора с победой вернулась домой, в южные земли Cтрома.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1877,'Общество людей Аратора росло и процветало, но Торадин, боявшийся, что его королевство расколется, если оно будет расти дальше, сохранял Cтром центром Араторской империи. Через много лет спокойного развития и торговли могучий Торадин умер от старости, давая юному поколению Аратора возможность распространить власть империи дальше земель Cтрома.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Общество людей Аратора росло и процветало, но Торадин, боявшийся, что его королевство расколется, если оно будет расти дальше, сохранял Cтром центром Араторской империи. Через много лет спокойного развития и торговли могучий Торадин умер от старости, давая юному поколению Аратора возможность распространить власть империи дальше земель Cтрома.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1878,'Первая сотня магов, обученная эльфами использовать магию, развила свое могущество и начали глубже изучать тайны плетения заклинаний. Эти маги, изначально выбранные из-за их сильной воли и доблести, всегда очень осторожно практиковали свою магию; но они передали свою силу и тайны магии новому поколению, не имевшему никакого представления об ужасах войны или необходимости самоконтроля.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Первая сотня магов, обученная эльфами использовать магию, развила свое могущество и начали глубже изучать тайны плетения заклинаний. Эти маги, изначально выбранные из-за их сильной воли и доблести, всегда очень осторожно практиковали свою магию; но они передали свою силу и тайны магии новому поколению, не имевшему никакого представления об ужасах войны или необходимости самоконтроля.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1879,'Эти юные маги начали практиковать магию для собственной пользы, а не ради исполнения долга перед своими сородичами.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эти юные маги начали практиковать магию для собственной пользы, а не ради исполнения долга перед своими сородичами.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1880,'Империя росла и охватывала все новые земли, а юные маги двинулись на юг. Используя свои мистические силы, маги защищали своих собратьев от диких животных и сделали возможной постройку новых городов-государств в диких местах. Но в то время как их силы росли, маги становились все более высокомерными и все больше отдалялись от остальных людей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Империя росла и охватывала все новые земли, а юные маги двинулись на юг. Используя свои мистические силы, маги защищали своих собратьев от диких животных и сделали возможной постройку новых городов-государств в диких местах. Но в то время как их силы росли, маги становились все более высокомерными и все больше отдалялись от остальных людей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1881,'Второй город-государство Аратора, Даларан, был построен севернее Cтрома. Многие юные волшебники покинули ограничивавшие их границы Cтрома и отправились в Даларан, где они надеялись получить свободу в использовании заклинаний. Эти маги использовали свои силы, чтобы создать зачарованные башни Даларана, и с головой погрузились в исследования.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Второй город-государство Аратора, Даларан, был построен севернее Cтрома. Многие юные волшебники покинули ограничивавшие их границы Cтрома и отправились в Даларан, где они надеялись получить свободу в использовании заклинаний. Эти маги использовали свои силы, чтобы создать зачарованные башни Даларана, и с головой погрузились в исследования.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1882,'Жители Даларана спокойно отнеслись к деятельности магов и создали бурную экономику под их защитой. Но чем больше и больше магов практиковало свои искусства, тем больше ткань реальности вокруг Даларана слабела и рвалась.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Жители Даларана спокойно отнеслись к деятельности магов и создали бурную экономику под их защитой. Но чем больше и больше магов практиковало свои искусства, тем больше ткань реальности вокруг Даларана слабела и рвалась.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1883,'Зловещие шпионы Пылающего Легиона, которые были изгнаны во время обрушения Источника Вечности, были привлечены обратно в мир неосторожными заклинаниями магов Даларана. Хотя эти относительно слабые демоны не проявляли себя в полной мере, они создавали довольно большую неразбериху и хаос на улицах Даларана.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Зловещие шпионы Пылающего Легиона, которые были изгнаны во время обрушения Источника Вечности, были привлечены обратно в мир неосторожными заклинаниями магов Даларана. Хотя эти относительно слабые демоны не проявляли себя в полной мере, они создавали довольно большую неразбериху и хаос на улицах Даларана.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1884,'Большинство этих встреч с демонами были отдельными случаями, и правившие магократы делали все, что могли, чтобы хранить такие происшествия в тайне от народа. Самые могущественные маги были посланы на борьбу с неуловимыми демонами, но нередко они обнаруживали, что безнадежно уступают одиноким шпионам могучего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Большинство этих встреч с демонами были отдельными случаями, и правившие магократы делали все, что могли, чтобы хранить такие происшествия в тайне от народа. Самые могущественные маги были посланы на борьбу с неуловимыми демонами, но нередко они обнаруживали, что безнадежно уступают одиноким шпионам могучего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1885,'Через несколько месяцев суеверные простолюдины начали подозревать, что их правители-волшебники от них что-то скрывали. Слухи о революции пронеслись по всем улицам Даларана, в то время как подозрительные горожане начали сомневаться в действиях и принципах магов, которыми они раньше восхищались. Магократы, опасаясь, что крестьяне поднимут бунт и что Стром может предпринять что-то против них, обратились к одной группе, которая, как они надеялись, поймет их, – к эльфам.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Через несколько месяцев суеверные простолюдины начали подозревать, что их правители-волшебники от них что-то скрывали. Слухи о революции пронеслись по всем улицам Даларана, в то время как подозрительные горожане начали сомневаться в действиях и принципах магов, которыми они раньше восхищались. Магократы, опасаясь, что крестьяне поднимут бунт и что Стром может предпринять что-то против них, обратились к одной группе, которая, как они надеялись, поймет их, – к эльфам.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1886,'Услыхав от магократов вести о действиях демонов в Даларане, эльфы немедленно послали своих самых могущественных волшебников к людям. Эльфийские волшебники изучили течение энергии в Даларане и составили детальные отчеты о действиях демонов. Они заключили, что, хотя в мире пока не так много демонов, сам Легион будет по-прежнему представлять огромную угрозу, пока люди используют магию.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Услыхав от магократов вести о действиях демонов в Даларане, эльфы немедленно послали своих самых могущественных волшебников к людям. Эльфийские волшебники изучили течение энергии в Даларане и составили детальные отчеты о действиях демонов. Они заключили, что, хотя в мире пока не так много демонов, сам Легион будет по-прежнему представлять огромную угрозу, пока люди используют магию.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1887,'Совет Луносвета, правивший эльфами Кель\'Таласа, заключил секретный пакт с магократами, владыками Даларана. Эльфы рассказали лордам-магам об истории древнего Калимдора и Пылающем Легионе, который все еще угрожал миру. Они сообщили людям, что, пока те используют магию, им придется защищать своих граждан от коварных посланцев Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Совет Луносвета, правивший эльфами Кель\'Таласа, заключил секретный пакт с магократами, владыками Даларана. Эльфы рассказали лордам-магам об истории древнего Калимдора и Пылающем Легионе, который все еще угрожал миру. Они сообщили людям, что, пока те используют магию, им придется защищать своих граждан от коварных посланцев Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1888,'Магократы предложили решение – дать отдельным смертным воинам огромную силу, чтобы они использовали ее для вечной тайной борьбы с Легионом. Они настаивали на том, чтобы большая часть человечества никогда не узнала о Хранителях или угрозе нападения Легиона, поскольку иначе воцарится ужас и хаос. Эльфы согласились с предложением и основали тайное общество, наблюдавшее за отбором Хранителей и помогавшее сдерживать хаос.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Магократы предложили решение – дать отдельным смертным воинам огромную силу, чтобы они использовали ее для вечной тайной борьбы с Легионом. Они настаивали на том, чтобы большая часть человечества никогда не узнала о Хранителях или угрозе нападения Легиона, поскольку иначе воцарится ужас и хаос. Эльфы согласились с предложением и основали тайное общество, наблюдавшее за отбором Хранителей и помогавшее сдерживать хаос.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1890,'Сила Хранителя была столь велика, что только Совет Тирисфаля мог отбирать достойных этого титула. Когда Хранитель становился слишком стар или уставал от этой тайной войны против хаоса, Совет выбирал нового защитника и при определенных условиях формально передавал силу старого Хранителя новому.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сила Хранителя была столь велика, что только Совет Тирисфаля мог отбирать достойных этого титула. Когда Хранитель становился слишком стар или уставал от этой тайной войны против хаоса, Совет выбирал нового защитника и при определенных условиях формально передавал силу старого Хранителя новому.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1891,'Проходили века, Хранители защищали людей от невидимой угрозы Пылающего Легиона по всему Аратору и Кель\'Таласу. Аратор рос и процветал, а использование магии распространилось по всей империи. Тем временем Хранители пристально наблюдали: не появится ли признаков активности демонов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Проходили века, Хранители защищали людей от невидимой угрозы Пылающего Легиона по всему Аратору и Кель\'Таласу. Аратор рос и процветал, а использование магии распространилось по всей империи. Тем временем Хранители пристально наблюдали: не появится ли признаков активности демонов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1892,'В древние времена, после того как титаны покинули Азерот, их дети, известные как земельники, продолжали охранять и обустраивать глубины мира. Земельникам не было дела до наземных рас, они желали лишь проникать все глубже и глубже в землю.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В древние времена, после того как титаны покинули Азерот, их дети, известные как земельники, продолжали охранять и обустраивать глубины мира. Земельникам не было дела до наземных рас, они желали лишь проникать все глубже и глубже в землю.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1893,'Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников. Ошеломленные болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы. Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик. Погребенные в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда мир раскололся после взрыва Источника Вечности, это очень сильно задело земельников. Ошеломленные болью самой земли, земельники сделались непохожи на самих себя и закрылись в каменных чертогах, где некогда были созданы. Ульдаман, Ульдум, Ульдуар… это имена древних городов титанов, где земельники впервые обрели свой облик. Погребенные в недрах мира, земельники спокойно отдыхали почти восемь тысяч лет.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1894,'Неизвестно, что именно разбудило земельников, закрывшихся в Ульдамане, но в конце концов они очнулись от сна. Земельники обнаружили, что за время своего забытья сильно изменились. Их каменные шкуры разгладились и сделались мягкой кожей, а их власть над камнем и землей ослабла. Они стали смертными существами.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Неизвестно, что именно разбудило земельников, закрывшихся в Ульдамане, но в конце концов они очнулись от сна. Земельники обнаружили, что за время своего забытья сильно изменились. Их каменные шкуры разгладились и сделались мягкой кожей, а их власть над камнем и землей ослабла. Они стали смертными существами.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1895,'Назвав себя дворфами, последние земельники покинули Ульдаман и отправились исследовать мир. Их по-прежнему влекли уютные и безопасные подземелья, а потому они основали огромное королевство под самой высокой горой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Назвав себя дворфами, последние земельники покинули Ульдаман и отправились исследовать мир. Их по-прежнему влекли уютные и безопасные подземелья, а потому они основали огромное королевство под самой высокой горой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1896,'Они назвали свои земли Каз Модан, или "Гора Каза", в честь титана-кузнеца Каз\'горота. Соорудив алтарь своему отцу-титану, дворфы создали огромную кузницу в самом сердце горы. И город, росший вокруг кузницы, стал называться Стальгорн.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Они назвали свои земли Каз Модан, или "Гора Каза", в честь титана-кузнеца Каз\'горота. Соорудив алтарь своему отцу-титану, дворфы создали огромную кузницу в самом сердце горы. И город, росший вокруг кузницы, стал называться Стальгорн.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1897,'Дворфы, от природы любившие придавать формы самоцветам и камню, начали добывать в близлежащих горах драгоценные минералы. Довольные своими подземными трудами, дворфы не стремились общаться с наземными соседями.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дворфы, от природы любившие придавать формы самоцветам и камню, начали добывать в близлежащих горах драгоценные минералы. Довольные своими подземными трудами, дворфы не стремились общаться с наземными соседями.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1899,'Под бдительным присмотром Тирисфальского ордена Даларан стал центром обучения для всех волшебников. Магократы, правившие Далараном, основали Кирин-Тор, особое тайное общество, регистрировавшее и изучавшее каждое заклинание, артефакт или магический предмет, известный в то время.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Под бдительным присмотром Тирисфальского ордена Даларан стал центром обучения для всех волшебников. Магократы, правившие Далараном, основали Кирин-Тор, особое тайное общество, регистрировавшее и изучавшее каждое заклинание, артефакт или магический предмет, известный в то время.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1901,'Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании. Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров. Но в то время как экономика Аратора процветала, наиболее мощные ее элементы начали рушиться.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Город-государство Кул-Тирас, основанный на большом острове к югу от Лордерона, имел процветающую экономику, основанную на рыболовстве и мореплавании. Со временем у Кул-Тираса появился могучий флот торговых судов, плававших по всему известному миру в поисках экзотических товаров. Но в то время как экономика Аратора процветала, наиболее мощные ее элементы начали рушиться.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1903,'Лорды Cтрома, ища на диком севере чистоту и свет, решили оставить свой древний город. Далеко к северу от Даларана лорды Cтрома построили новый город-государство, названный Лордерон. Весь континент был назван в честь этого города. Лордерон стал местом религиозного паломничества и укрытием для тех, кто искал спокойствия и безопасности.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лорды Cтрома, ища на диком севере чистоту и свет, решили оставить свой древний город. Далеко к северу от Даларана лорды Cтрома построили новый город-государство, названный Лордерон. Весь континент был назван в честь этого города. Лордерон стал местом религиозного паломничества и укрытием для тех, кто искал спокойствия и безопасности.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1904,'Наследники Арати, оставшиеся в ветшающих стенах древнего Cтрома, решили отправиться на юг, за каменистые горы Каз Модана. Их странствия длились не один год, но наконец путешествие окончилось, и они поселились в северном регионе континента, который позднее назовут Азерот. В плодородной долине они основали королевство Штормград, быстро ставшее независимой силой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наследники Арати, оставшиеся в ветшающих стенах древнего Cтрома, решили отправиться на юг, за каменистые горы Каз Модана. Их странствия длились не один год, но наконец путешествие окончилось, и они поселились в северном регионе континента, который позднее назовут Азерот. В плодородной долине они основали королевство Штормград, быстро ставшее независимой силой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1905,'Несколько воинов, оставшихся в Строме, решили и дальше защищать древние стены. Стром более не был центром империи, но он превратился в новое государство – Стромгард. Хотя каждый город-государство сам по себе процветал, империя Аратор практически распалась. Каждое государство завело свои собственные обычаи и верования, и они начали все больше отдаляться друг от друга. Мечта короля Торадина об объединении человечества развеялась.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несколько воинов, оставшихся в Строме, решили и дальше защищать древние стены. Стром более не был центром империи, но он превратился в новое государство – Стромгард. Хотя каждый город-государство сам по себе процветал, империя Аратор практически распалась. Каждое государство завело свои собственные обычаи и верования, и они начали все больше отдаляться друг от друга. Мечта короля Торадина об объединении человечества развеялась.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1913,'Эгвин никогда так и не узнала, что она поступила именно так, как хотел Саргерас. Она неосознанно подписала приговор смертному миру, так как Саргерас во время своей физической смерти вселился духом в ослабленное тело Эгвин. Без ведома юной Хранительницы Саргерас оставался скрытым в темных уголках ее души многие годы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эгвин никогда так и не узнала, что она поступила именно так, как хотел Саргерас. Она неосознанно подписала приговор смертному миру, так как Саргерас во время своей физической смерти вселился духом в ослабленное тело Эгвин. Без ведома юной Хранительницы Саргерас оставался скрытым в темных уголках ее души многие годы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1914,'Дворфы Стальгорна многие века жили в спокойствии. Но их стало слишком много, им перестало хватать места в подземных городах. И хотя могучий король Модимус Старая Наковальня правил всеми дворфами мудро и справедливо, три мощные фракции появились в обществе дворфов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дворфы Стальгорна многие века жили в спокойствии. Но их стало слишком много, им перестало хватать места в подземных городах. И хотя могучий король Модимус Старая Наковальня правил всеми дворфами мудро и справедливо, три мощные фракции появились в обществе дворфов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1915,'Клан Бронзобородов под управлением тана Мадорана Бронзоборода имел хорошие связи с королем и был защитником Стальгорна. Клан Громового Молота, управляемый таном Кардросом Громовым Молотом, населял холмы и утесы у подножья горы и пытался добиться большей власти в городе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Клан Бронзобородов под управлением тана Мадорана Бронзоборода имел хорошие связи с королем и был защитником Стальгорна. Клан Громового Молота, управляемый таном Кардросом Громовым Молотом, населял холмы и утесы у подножья горы и пытался добиться большей власти в городе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1916,'Третья фракция, клан Черного Железа, была под командованием тана-чародея Тауриссана. Дворфы Черного Железа таились в самых глубоких тенях под горой и замышляли заговор против своих собратьев из клана Бронзобородов и клана Громового Молота.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Третья фракция, клан Черного Железа, была под командованием тана-чародея Тауриссана. Дворфы Черного Железа таились в самых глубоких тенях под горой и замышляли заговор против своих собратьев из клана Бронзобородов и клана Громового Молота.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1917,'Некоторое время три фракции поддерживали хрупкий мир, однако напряжение возросло, когда король Старая Наковальня скончался от старости. Три правящих клана вступили в войну за контроль над Стальгорном. Гражданская война дворфов многие годы пылала под землей. В конце концов клан Бронзобородов, имевший самую большую армию, изгнал кланы Черного Железа и Громового Молота из-под горы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Некоторое время три фракции поддерживали хрупкий мир, однако напряжение возросло, когда король Старая Наковальня скончался от старости. Три правящих клана вступили в войну за контроль над Стальгорном. Гражданская война дворфов многие годы пылала под землей. В конце концов клан Бронзобородов, имевший самую большую армию, изгнал кланы Черного Железа и Громового Молота из-под горы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1918,'Кардрос и воины Громового Молота отправились на север через пограничные ворота Дун Альгаз и основали свое собственное королевство под далекой горой Грим Батол. Там Громовые Молоты разбогатели и построили новые сокровищницы. Тауриссан и другие члены клана Черного Железа не были столь же удачливы. Униженные и разгневанные своим поражением, они поклялись отомстить Стальгорну. Уведя своих сородичей далеко на юг, Тауриссан основал город (названный в свою честь) под прекрасным Красногорьем.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кардрос и воины Громового Молота отправились на север через пограничные ворота Дун Альгаз и основали свое собственное королевство под далекой горой Грим Батол. Там Громовые Молоты разбогатели и построили новые сокровищницы. Тауриссан и другие члены клана Черного Железа не были столь же удачливы. Униженные и разгневанные своим поражением, они поклялись отомстить Стальгорну. Уведя своих сородичей далеко на юг, Тауриссан основал город (названный в свою честь) под прекрасным Красногорьем.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1919,'Процветание и прошедшие годы не уменьшили ненависти клана Черного Железа к своим собратьям. Тауриссан и его жена-волшебница Модгуд начали войну на два фронта против Стальгорна и Грим Батола. Клан Черного Железа хотел заполучить весь Каз Модан для себя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Процветание и прошедшие годы не уменьшили ненависти клана Черного Железа к своим собратьям. Тауриссан и его жена-волшебница Модгуд начали войну на два фронта против Стальгорна и Грим Батола. Клан Черного Железа хотел заполучить весь Каз Модан для себя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1920,'Армии Черного Железа атаковали крепости своих собратьев и практически захватили оба королевства. Но Мадоран Бронзобород в конце концов привел свой клан к окончательной победе над колдовской армией Тауриссана. Тауриссан и его слуги бежали в свой безопасный город, не зная о том, что происходило в Грим Батоле, где армия Модгуд тоже не особо успешно сражалась с Кардросом и его воинами из клана Громового Молота.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Армии Черного Железа атаковали крепости своих собратьев и практически захватили оба королевства. Но Мадоран Бронзобород в конце концов привел свой клан к окончательной победе над колдовской армией Тауриссана. Тауриссан и его слуги бежали в свой безопасный город, не зная о том, что происходило в Грим Батоле, где армия Модгуд тоже не особо успешно сражалась с Кардросом и его воинами из клана Громового Молота.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1921,'Столкнувшись с вражескими воинами, Модгуд использовала свои силы, чтобы вселить страх в их сердца. Тени двигались по ее команде, и темные существа вылезали из глубин земли, нападая на Громовых Молотов в их собственных дворцах. В конце концов Модгуд прорвалась через ворота и осадила саму крепость. Громовые Молоты сражались отчаянно, сам Кардрос был среди воинов, желая убить королеву-колдунью.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Столкнувшись с вражескими воинами, Модгуд использовала свои силы, чтобы вселить страх в их сердца. Тени двигались по ее команде, и темные существа вылезали из глубин земли, нападая на Громовых Молотов в их собственных дворцах. В конце концов Модгуд прорвалась через ворота и осадила саму крепость. Громовые Молоты сражались отчаянно, сам Кардрос был среди воинов, желая убить королеву-колдунью.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1922,'Потеряв свою королеву, воины клана Черного Железа бежали от ярости Громовых Молотов. Они бежали на юг, к крепости своего короля, но столкнулись с армией Стальгорна, пришедшей помочь Грим Батолу. Зажатые между двух армий, силы Черного Железа были полностью уничтожены.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Потеряв свою королеву, воины клана Черного Железа бежали от ярости Громовых Молотов. Они бежали на юг, к крепости своего короля, но столкнулись с армией Стальгорна, пришедшей помочь Грим Батолу. Зажатые между двух армий, силы Черного Железа были полностью уничтожены.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1923,'Объединенные армии Стальгорна и Грим Батола отправились на юг с целью уничтожить Тауриссана и клан Черного Железа раз и навсегда. Они не успели далеко уйти, когда гнев Тауриссана вызвал заклинание, приведшее к катаклизму. Желая призвать сверхъестественное существо, которое поможет ему победить, Тауриссан призвал древние силы, спавшие в глубинах мира, и к своему ужасу он обнаружил, что появившееся существо было ужаснее самых страшных ночных кошмаров.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Объединенные армии Стальгорна и Грим Батола отправились на юг с целью уничтожить Тауриссана и клан Черного Железа раз и навсегда. Они не успели далеко уйти, когда гнев Тауриссана вызвал заклинание, приведшее к катаклизму. Желая призвать сверхъестественное существо, которое поможет ему победить, Тауриссан призвал древние силы, спавшие в глубинах мира, и к своему ужасу он обнаружил, что появившееся существо было ужаснее самых страшных ночных кошмаров.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1926,'Увидев ужасное разрушение и огонь, распространившийся по южным горам, король Мадоран и король Кардрос остановили свои армии и спешно вернулись назад в свои королевства, не желая пасть жертвами ужасного гнева Рагнароса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Увидев ужасное разрушение и огонь, распространившийся по южным горам, король Мадоран и король Кардрос остановили свои армии и спешно вернулись назад в свои королевства, не желая пасть жертвами ужасного гнева Рагнароса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1927,'Клан Бронзобородов вернулся в Стальгорн и восстановил свой славный город. Громовой Молот также вернулся домой, в Грим Батол. Но смерть Модгуд осквернила крепость, и дворфы Громового Молота не могли уже там жить.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Клан Бронзобородов вернулся в Стальгорн и восстановил свой славный город. Громовой Молот также вернулся домой, в Грим Батол. Но смерть Модгуд осквернила крепость, и дворфы Громового Молота не могли уже там жить.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1928,'Горечь потери своего дома ожесточила их сердца. Король Бронзобород предложил дворфам Громового Молота место, где они бы могли жить в границах Стальгорна, но они отказались. Кардрос повел свой народ на север к землям Лордерона. Поселившись в буйно зеленеющих лесах Внутренних земель, клан Громового Молота построил город Заоблачный пик, где дворфы стали ближе к природе и даже приручили могучих грифонов, живших там.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Горечь потери своего дома ожесточила их сердца. Король Бронзобород предложил дворфам Громового Молота место, где они бы могли жить в границах Стальгорна, но они отказались. Кардрос повел свой народ на север к землям Лордерона. Поселившись в буйно зеленеющих лесах Внутренних земель, клан Громового Молота построил город Заоблачный пик, где дворфы стали ближе к природе и даже приручили могучих грифонов, живших там.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1929,'Желая восстановить отношения и торговлю со своими собратьями, дворфы Стальгорна построили две огромные арки, называемые Мост Тандола, между Каз Моданом и Лордероном. Поддерживаемые обоюдной торговлей, два королевства процветали. После смерти Мадорана и Кардроса их сыновья вместе построили две большие статуи в честь своих отцов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Желая восстановить отношения и торговлю со своими собратьями, дворфы Стальгорна построили две огромные арки, называемые Мост Тандола, между Каз Моданом и Лордероном. Поддерживаемые обоюдной торговлей, два королевства процветали. После смерти Мадорана и Кардроса их сыновья вместе построили две большие статуи в честь своих отцов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1930,'Две статуи должны были стоять на страже прохода в южные земли, покрытого застывшей лавой из-за близости всесжигающего Рагнароса. Они служили не только грозным предупреждением всем тем, кто решится напасть на дворфийские королевства, но также и напоминанием о цене, которую клан Черного Железа заплатил за свои преступления.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Две статуи должны были стоять на страже прохода в южные земли, покрытого застывшей лавой из-за близости всесжигающего Рагнароса. Они служили не только грозным предупреждением всем тем, кто решится напасть на дворфийские королевства, но также и напоминанием о цене, которую клан Черного Железа заплатил за свои преступления.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1931,'Два королевства некоторое время поддерживали довольно тесную связь, но на клан Громового Молота слишком сильно повлияли ужасы, свидетелями которых дворфы стали у Грим Батола. Вместо того чтобы создать огромное подземное царство, они обжили склоны Заоблачного пика. Идеологические различия между двумя оставшимися кланами дворфов в конце концов привели к отчуждению.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Два королевства некоторое время поддерживали довольно тесную связь, но на клан Громового Молота слишком сильно повлияли ужасы, свидетелями которых дворфы стали у Грим Батола. Вместо того чтобы создать огромное подземное царство, они обжили склоны Заоблачного пика. Идеологические различия между двумя оставшимися кланами дворфов в конце концов привели к отчуждению.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1932,'Хранительница Эгвин с течением времени становилась все могущественнее, используя энергии Тирисфаля, чтобы продлить свою жизнь. Самоуверенно надеясь, что она победила Саргераса, она продолжала охранять мир от приспешников короля демонов почти девятьсот лет. Но в конце концов Совет Тирисфаля объявил, что время ее службы подошло к концу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хранительница Эгвин с течением времени становилась все могущественнее, используя энергии Тирисфаля, чтобы продлить свою жизнь. Самоуверенно надеясь, что она победила Саргераса, она продолжала охранять мир от приспешников короля демонов почти девятьсот лет. Но в конце концов Совет Тирисфаля объявил, что время ее службы подошло к концу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1933,'Совет приказал Эгвин вернуться в Даларан, чтобы они могли избрать нового носителя силы Хранителя. Но Эгвин, никогда не доверявшая Совету до конца, решила сама выбрать преемника.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Совет приказал Эгвин вернуться в Даларан, чтобы они могли избрать нового носителя силы Хранителя. Но Эгвин, никогда не доверявшая Совету до конца, решила сама выбрать преемника.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1934,'Гордая Эгвин хотела родить сына, которому она передаст свою силу. Она не хотела, чтобы Тирисфальский орден манипулировал ее преемником так же, как они пытались манипулировать ей. Отправившись в южное государство Азерот, Эгвин нашла идеального мужчину, который мог бы стать отцом ее сына – искусного человека-мага по имени Ниелас Аран.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гордая Эгвин хотела родить сына, которому она передаст свою силу. Она не хотела, чтобы Тирисфальский орден манипулировал ее преемником так же, как они пытались манипулировать ей. Отправившись в южное государство Азерот, Эгвин нашла идеального мужчину, который мог бы стать отцом ее сына – искусного человека-мага по имени Ниелас Аран.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1935,'Аран был придворным чародеем и советником короля Азерота. Эгвин соблазнила волшебника и забеременела от него. Еще не рожденное дитя получило природную способность Ниеласа к магии, что позже определит трагическую судьбу этого ребенка. Ребенок также получил силу Тирисфаля, хотя она не проявилась до того, как он стал совершеннолетним.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Аран был придворным чародеем и советником короля Азерота. Эгвин соблазнила волшебника и забеременела от него. Еще не рожденное дитя получило природную способность Ниеласа к магии, что позже определит трагическую судьбу этого ребенка. Ребенок также получил силу Тирисфаля, хотя она не проявилась до того, как он стал совершеннолетним.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1936,'Прошло время, и Эгвин родила сына в укромной роще. Назвав мальчика Медив, что означало "хранитель секретов" на языке высших эльфов, Эгвин верила, что мальчик будет готов к тому, чтобы стать Хранителем. К сожалению, злой дух Саргераса, таившийся в ней, вселился в дитя, еще находившееся в ее чреве. Эгвин не знала, что новый Хранитель мира уже одержим его величайшим врагом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прошло время, и Эгвин родила сына в укромной роще. Назвав мальчика Медив, что означало "хранитель секретов" на языке высших эльфов, Эгвин верила, что мальчик будет готов к тому, чтобы стать Хранителем. К сожалению, злой дух Саргераса, таившийся в ней, вселился в дитя, еще находившееся в ее чреве. Эгвин не знала, что новый Хранитель мира уже одержим его величайшим врагом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1937,'Уверенная в том, что ее дитя здорово и невредимо, Эгвин отправила юного Медива ко двору Азерота и оставила его там, чтобы его взрастил его смертный отец и его народ. Сама же она ушла в глушь, готовая встретить все, что ее могло ожидать в загробной жизни. Медив вырос сильным пареньком, но не имел никакого представления о потенциальной мощи силы Тирисфаля, принадлежавшей ему по праву рождения.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уверенная в том, что ее дитя здорово и невредимо, Эгвин отправила юного Медива ко двору Азерота и оставила его там, чтобы его взрастил его смертный отец и его народ. Сама же она ушла в глушь, готовая встретить все, что ее могло ожидать в загробной жизни. Медив вырос сильным пареньком, но не имел никакого представления о потенциальной мощи силы Тирисфаля, принадлежавшей ему по праву рождения.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1938,'Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать. Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Ллейном и Андуином Лотаром, одним из последних сыновей рода Арати. Трое мальчишек постоянно попадали в переделки, но горожане их очень любили.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Саргерас выжидал подходящего момента, когда таящаяся в юноше сила даст о себе знать. Уже будучи подростком, Медив заработал себе популярность среди жителей Азерота своими выдающимися магическими способностями и часто отправлялся на поиски приключений вместе со своими друзьями – принцем Азерота Ллейном и Андуином Лотаром, одним из последних сыновей рода Арати. Трое мальчишек постоянно попадали в переделки, но горожане их очень любили.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1939,'Когда Медиву было четырнадцать, в нем проснулась великая сила, которая не могла ужиться с дремлющим внутри него духом Саргераса. Медив впал в глубокий сон, продлившийся не один год.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда Медиву было четырнадцать, в нем проснулась великая сила, которая не могла ужиться с дремлющим внутри него духом Саргераса. Медив впал в глубокий сон, продлившийся не один год.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1940,'Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллейн и Андуин стали правителями Азерота. Он желал использовать обретенные силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вернувшись к жизни, он обнаружил, что уже повзрослел, а его друзья Ллейн и Андуин стали правителями Азерота. Он желал использовать обретенные силы на благо своей родной земли, но злой дух Саргераса овладел его разумом и направил его на путь злодеяний.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1941,'Сердце Медива заполняла тьма, и Саргерас был доволен: почти все было готово для его повторного вторжения в этот мир, а последний Страж должен был помочь ему с легкостью осуществить все свои планы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сердце Медива заполняла тьма, и Саргерас был доволен: почти все было готово для его повторного вторжения в этот мир, а последний Страж должен был помочь ему с легкостью осуществить все свои планы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1943,'На этот раз не должно было быть никаких ошибок. Кил\'джеден решил, что нужно ослабить оборону Азерота еще до того, как Легион ступит на его земли. Расы смертных, такие как ночные эльфы и драконы, занятые борьбой с новым врагом, были бы уже неспособны противостоять нашествию Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На этот раз не должно было быть никаких ошибок. Кил\'джеден решил, что нужно ослабить оборону Азерота еще до того, как Легион ступит на его земли. Расы смертных, такие как ночные эльфы и драконы, занятые борьбой с новым врагом, были бы уже неспособны противостоять нашествию Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1944,'Именно тогда Кил\'джеден обнаружил покрытый густыми зарослями мир Дренора, который мирно парил по бескрайним просторам Великой запредельной тьмы. Дренор, родина поклонявшихся духам орков и миролюбивых дренеев, был миром настолько же безмятежным и тихим, насколько бескрайним.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Именно тогда Кил\'джеден обнаружил покрытый густыми зарослями мир Дренора, который мирно парил по бескрайним просторам Великой запредельной тьмы. Дренор, родина поклонявшихся духам орков и миролюбивых дренеев, был миром настолько же безмятежным и тихим, насколько бескрайним.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1945,'Благородные кланы орков странствовали по необъятным степям и охотились – больше ради развлечения, а дренеи начинали возводить города среди скал и горных вершин. Кил\'джеден решил, что, приложив немного усилий, из жителей Дренора можно сделать превосходных солдат для Пылающего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Благородные кланы орков странствовали по необъятным степям и охотились – больше ради развлечения, а дренеи начинали возводить города среди скал и горных вершин. Кил\'джеден решил, что, приложив немного усилий, из жителей Дренора можно сделать превосходных солдат для Пылающего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1946,'Из двух рас Кил\'джеден выбрал воинственных орков: их было легче привлечь под знамена Легиона. Он околдовал главного шамана орков Нер\'зула точно так же, как много лет назад Саргерас подчинил своей воле королеву Азшару. Коварный шаман стал исполнителем воли демона, пробуждая в орках жестокость и жажду сражения.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Из двух рас Кил\'джеден выбрал воинственных орков: их было легче привлечь под знамена Легиона. Он околдовал главного шамана орков Нер\'зула точно так же, как много лет назад Саргерас подчинил своей воле королеву Азшару. Коварный шаман стал исполнителем воли демона, пробуждая в орках жестокость и жажду сражения.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1947,'Вскоре он превратил эту миролюбивую расу в жестоких, кровожадных воинов. Нер\'зулу и его народу оставалось сделать последний роковой шаг: стать вестниками смерти, полностью посвятив себя войне. Но старый шаман понял, что для орков это означало вечное рабство, и ему удалось не поддаться воле демона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вскоре он превратил эту миролюбивую расу в жестоких, кровожадных воинов. Нер\'зулу и его народу оставалось сделать последний роковой шаг: стать вестниками смерти, полностью посвятив себя войне. Но старый шаман понял, что для орков это означало вечное рабство, и ему удалось не поддаться воле демона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1948,'Кил\'джедена разозлила непокорность Нер\'зула, и он стал искать другого орка, который смог бы заставить свой народ присоединиться к Легиону. Хитрому великому демону удалось-таки найти достойного кандидата – им стал тщеславный ученик Нер\'зула, Гул\'дан. Кил\'джеден пообещал ему невиданную силу в обмен на полное повиновение.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джедена разозлила непокорность Нер\'зула, и он стал искать другого орка, который смог бы заставить свой народ присоединиться к Легиону. Хитрому великому демону удалось-таки найти достойного кандидата – им стал тщеславный ученик Нер\'зула, Гул\'дан. Кил\'джеден пообещал ему невиданную силу в обмен на полное повиновение.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1949,'Юный орк охотно согласился быть учеником демона и вскоре стал одним из самых могущественных смертных волшебников в истории. Он учил других орков темным искусствам и пытался искоренить их древние ритуалы. Гул\'дан показал своим братьям волшебство, которое никто из них никогда не видел, ужасающую мощь, способную повсюду сеять смерть.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Юный орк охотно согласился быть учеником демона и вскоре стал одним из самых могущественных смертных волшебников в истории. Он учил других орков темным искусствам и пытался искоренить их древние ритуалы. Гул\'дан показал своим братьям волшебство, которое никто из них никогда не видел, ужасающую мощь, способную повсюду сеять смерть.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1950,'Стремясь укрепить свою власть над орками, Кил\'джеден помог Гул\'дану основать тайную секту под названием Совет Теней, чтобы манипулировать кланами и разносить по Дренору слухи о новой колдовской силе. Все больше орков овладевали искусством наложения чар, и безмятежные просторы Дренора окутывал мрак. Со временем бескрайние степи, служившие домом для орков не одно поколение, поблекли и превратились в безжизненные пустоши. Энергия демона медленно убивала этот мир.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Стремясь укрепить свою власть над орками, Кил\'джеден помог Гул\'дану основать тайную секту под названием Совет Теней, чтобы манипулировать кланами и разносить по Дренору слухи о новой колдовской силе. Все больше орков овладевали искусством наложения чар, и безмятежные просторы Дренора окутывал мрак. Со временем бескрайние степи, служившие домом для орков не одно поколение, поблекли и превратились в безжизненные пустоши. Энергия демона медленно убивала этот мир.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1954,'Во главе с Громом Адским Криком все вожди, кроме Дуротана, повиновались и тем самым обрекли себя на вечную службу Пылающему Легиону. Те, кого коснулась ярость Маннорота, пусть не желая того, превратили своих ничего не подозревающих собратьев в таких же рабов, какими стали сами.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во главе с Громом Адским Криком все вожди, кроме Дуротана, повиновались и тем самым обрекли себя на вечную службу Пылающему Легиону. Те, кого коснулась ярость Маннорота, пусть не желая того, превратили своих ничего не подозревающих собратьев в таких же рабов, какими стали сами.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1955,'Орки были обречены на вечную неутолимую жажду крови и обрушивали свою ярость на любого, кто стоял у них на пути. Гул\'дан почувствовал, что время пришло, и объединил воюющие кланы в одну неудержимую Орду.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орки были обречены на вечную неутолимую жажду крови и обрушивали свою ярость на любого, кто стоял у них на пути. Гул\'дан почувствовал, что время пришло, и объединил воюющие кланы в одну неудержимую Орду.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1956,'Но зная, что все вожди, в первую очередь Адский Крик и Оргрим Молот Рока, начнут борьбу за превосходство, Гул\'дан поставил во главу Орды своего вождя-марионетку. На эту роль он выбрал Чернорука Разрушителя, злобного и жестокого орка. Под командованием Чернорука Орда выдвинулась в первый пробный бой против дренеев.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но зная, что все вожди, в первую очередь Адский Крик и Оргрим Молот Рока, начнут борьбу за превосходство, Гул\'дан поставил во главу Орды своего вождя-марионетку. На эту роль он выбрал Чернорука Разрушителя, злобного и жестокого орка. Под командованием Чернорука Орда выдвинулась в первый пробный бой против дренеев.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1957,'Через несколько месяцев Орда истребила почти всех дренеев, живших на Дреноре. Лишь немногие сумели избежать гнева орков. Гул\'дан был доволен: его Орда была непобедима. Но он знал, что если им будет не с кем сражаться, непреодолимая жажда крови заставит их убивать друг друга и войско уничтожит само себя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Через несколько месяцев Орда истребила почти всех дренеев, живших на Дреноре. Лишь немногие сумели избежать гнева орков. Гул\'дан был доволен: его Орда была непобедима. Но он знал, что если им будет не с кем сражаться, непреодолимая жажда крови заставит их убивать друг друга и войско уничтожит само себя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1958,'Кил\'джеден знал, что Орда, наконец, готова. Орки стали мощнейшей силой Пылающего Легиона. Коварный демон рассказал обо всем своему повелителю, и Саргерас согласился, что час расплаты настал.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден знал, что Орда, наконец, готова. Орки стали мощнейшей силой Пылающего Легиона. Коварный демон рассказал обо всем своему повелителю, и Саргерас согласился, что час расплаты настал.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1959,'Кил\'джеден подготавливал Орду к нападению на Азерот, а Медив в это время продолжал сражаться с Саргерасом за свою душу. Король Ллейн, благородный правитель Штормграда, узнал о том, что тьма завладела душой его бывшего друга.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден подготавливал Орду к нападению на Азерот, а Медив в это время продолжал сражаться с Саргерасом за свою душу. Король Ллейн, благородный правитель Штормграда, узнал о том, что тьма завладела душой его бывшего друга.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1960,'Король Ллейн рассказал об этом Андуину Лотару, последнему потомку рода Арати, которого он сделал своим военачальником. Но никто из них не мог предположить, что беда, случившаяся с Медивом, станет причиной столь ужасных событий.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Король Ллейн рассказал об этом Андуину Лотару, последнему потомку рода Арати, которого он сделал своим военачальником. Но никто из них не мог предположить, что беда, случившаяся с Медивом, станет причиной столь ужасных событий.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1962,'Гул\'дан согласился сделать это и решил, что, как только Азерот будет повержен, он направится на поиски легендарной могилы и получит свою награду. Саргерас, уверенный в том, что Орда будет покорно служить ему, приказал начать вторжение.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гул\'дан согласился сделать это и решил, что, как только Азерот будет повержен, он направится на поиски легендарной могилы и получит свою награду. Саргерас, уверенный в том, что Орда будет покорно служить ему, приказал начать вторжение.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1963,'Общими усилиями Медив и волшебники Совета Теней открыли портал межу измерениями – Темный портал. Этот портал позволил армии Дренора попасть на Азерот. Гул\'дан послал через портал разведчиков, чтобы они исследовали земли, которые им предстояло завоевать. Вернувшись, они доложили Совету Теней, что можно начать вторжение.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Общими усилиями Медив и волшебники Совета Теней открыли портал межу измерениями – Темный портал. Этот портал позволил армии Дренора попасть на Азерот. Гул\'дан послал через портал разведчиков, чтобы они исследовали земли, которые им предстояло завоевать. Вернувшись, они доложили Совету Теней, что можно начать вторжение.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1964,'Дуротан, по-прежнему уверенный в том, что Гул\'дан приведет их народ к гибели, снова высказался против действий волшебников. Храбрый воин сказал, что они уничтожили чистый дух орков и что это безрассудное нападение на Азерот погубит их всех. Гул\'дан не мог пойти на риск, убив любимого всеми героя, и был вынужден отправить Дуротана вместе с его кланом Северного Волка в самые отдаленные области нового мира.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дуротан, по-прежнему уверенный в том, что Гул\'дан приведет их народ к гибели, снова высказался против действий волшебников. Храбрый воин сказал, что они уничтожили чистый дух орков и что это безрассудное нападение на Азерот погубит их всех. Гул\'дан не мог пойти на риск, убив любимого всеми героя, и был вынужден отправить Дуротана вместе с его кланом Северного Волка в самые отдаленные области нового мира.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1965,'За изгнанным кланом Северного Волка через портал последовали лишь несколько кланов. Орки быстро развернули базу в Черных Топях, темной болотистой местности на востоке королевства Штормград. Начав исследовать новую территорию, они тут же столкнулись с защитниками Штормграда.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','За изгнанным кланом Северного Волка через портал последовали лишь несколько кланов. Орки быстро развернули базу в Черных Топях, темной болотистой местности на востоке королевства Штормград. Начав исследовать новую территорию, они тут же столкнулись с защитниками Штормграда.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1966,'Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников. Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя битвы с людьми заканчивались довольно быстро, обе расы успели выяснить сильные и слабые стороны соперников. Ллейну и Лотару не удавалось получить точные сведения о численности орков, и они могли лишь догадываться о том, насколько могуч был их противник.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1967,'Через несколько лет большая часть Орды перебралась на Азерот, и Гул\'дан решил, что настало время нанести сокрушительный удар по человечеству. Орда обрушила всю свою мощь на ничего не подозревающих жителей королевства Штормград.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Через несколько лет большая часть Орды перебралась на Азерот, и Гул\'дан решил, что настало время нанести сокрушительный удар по человечеству. Орда обрушила всю свою мощь на ничего не подозревающих жителей королевства Штормград.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1968,'В то время как жители Азерота и Орда бились друг с другом по всему королевству, внутри обеих армий разгорались конфликты. Король Ллейн, убежденный в том, что звероподобные орки не в состоянии завоевать Азерот, упрямо отказывался покидать столицу Штормграда; Лотар же был уверен, что бой следует перенести на территорию, занятую противником, так что ему пришлось выбирать между своими убеждениями и верностью королю.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В то время как жители Азерота и Орда бились друг с другом по всему королевству, внутри обеих армий разгорались конфликты. Король Ллейн, убежденный в том, что звероподобные орки не в состоянии завоевать Азерот, упрямо отказывался покидать столицу Штормграда; Лотар же был уверен, что бой следует перенести на территорию, занятую противником, так что ему пришлось выбирать между своими убеждениями и верностью королю.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1970,'Убив тело Медива, Лотар и юный Кадгар, сами того не зная, изгнали дух Саргераса в бездну. А праведный дух Медива остался жив… и долгие годы скитался по астральному миру.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Убив тело Медива, Лотар и юный Кадгар, сами того не зная, изгнали дух Саргераса в бездну. А праведный дух Медива остался жив… и долгие годы скитался по астральному миру.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1971,'Хотя Медив был повержен, Орда по-прежнему брала верх над защитниками Штормграда. Но когда победа была уже у Орды в руках, один из самых могучих вождей орков, Оргрим Молот Рока, стал понимать, насколько изменились некогда миролюбивые кланы, жившие на Дреноре.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя Медив был повержен, Орда по-прежнему брала верх над защитниками Штормграда. Но когда победа была уже у Орды в руках, один из самых могучих вождей орков, Оргрим Молот Рока, стал понимать, насколько изменились некогда миролюбивые кланы, жившие на Дреноре.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1972,'Его старый друг Дуротан, вернувшийся из изгнания, напомнил ему о предательстве Гул\'дана. По приказу мстительного Гул\'дана Дуротан и вся его семья были убиты, в живых оставили лишь его юного сына. Но Молот Рока не знал о том, что сын Дуротана попал в плен к Адэласу Блэкмуру, одному из командиров армии людей, и стал его рабом. \r\n\r\nИменно этому юному орку суждено было стать величайшим вождем в истории своего народа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Его старый друг Дуротан, вернувшийся из изгнания, напомнил ему о предательстве Гул\'дана. По приказу мстительного Гул\'дана Дуротан и вся его семья были убиты, в живых оставили лишь его юного сына. Но Молот Рока не знал о том, что сын Дуротана попал в плен к Адэласу Блэкмуру, одному из командиров армии людей, и стал его рабом. \r\n\r\nИменно этому юному орку суждено было стать величайшим вождем в истории своего народа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1974,'Король Ллейн сильно недооценил мощь Орды и мог лишь беспомощно смотреть на то, как его королевство рассыпалось под натиском зеленокожих захватчиков. Вскоре и сам король был убит одним из лучших наемных убийц Совета Теней, полуорком Гароной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Король Ллейн сильно недооценил мощь Орды и мог лишь беспомощно смотреть на то, как его королевство рассыпалось под натиском зеленокожих захватчиков. Вскоре и сам король был убит одним из лучших наемных убийц Совета Теней, полуорком Гароной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1975,'Лотар и его войны, возвращавшиеся из Каражана, надеялись остановить кровопролитие и спасти свою некогда славную родину. Но было слишком поздно: когда они вернулись, их королевство лежало в руинах. Орда опустошала деревни и захватывала близлежащие земли. Лотар и его войско, вынужденные скрываться от врагов, поклялись вернуть свою родину любой ценой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лотар и его войны, возвращавшиеся из Каражана, надеялись остановить кровопролитие и спасти свою некогда славную родину. Но было слишком поздно: когда они вернулись, их королевство лежало в руинах. Орда опустошала деревни и захватывала близлежащие земли. Лотар и его войско, вынужденные скрываться от врагов, поклялись вернуть свою родину любой ценой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1977,'В первый раз за почти три тысячи лет разрозненные народы Аратора объединились под одним знаменем. Лорд Лотар был назначен главнокомандующим войск Альянса и начал подготовку своих воинов к нашествию Орды.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В первый раз за почти три тысячи лет разрозненные народы Аратора объединились под одним знаменем. Лорд Лотар был назначен главнокомандующим войск Альянса и начал подготовку своих воинов к нашествию Орды.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1978,'При поддержке своих помощников Утера Светоносного, адмирала Даэлина Праудмура и Туралиона, Лотар убедил получеловеческие народы Лордерона в необходимости противостоять надвигающемуся вторжению. Альянс также смог заручиться поддержкой дворфов из Стальгорна и некоторых высших эльфов из Кель\'Таласа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','При поддержке своих помощников Утера Светоносного, адмирала Даэлина Праудмура и Туралиона, Лотар убедил получеловеческие народы Лордерона в необходимости противостоять надвигающемуся вторжению. Альянс также смог заручиться поддержкой дворфов из Стальгорна и некоторых высших эльфов из Кель\'Таласа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1979,'Эльфы под предводительством Анастериана Солнечного Скитальца не хотели вмешиваться в предстоящий конфликт. Но они не могли отказать Лотару – последнему из рода Арати, который поддерживал их в прошлом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эльфы под предводительством Анастериана Солнечного Скитальца не хотели вмешиваться в предстоящий конфликт. Но они не могли отказать Лотару – последнему из рода Арати, который поддерживал их в прошлом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1980,'Орда под предводительством вождя Молота Рока привела под свои знамена огров из родного Дренора и лесных троллей Амани. Продолжая свое наступление, Орда легко подавила сопротивление дворфов из королевства Каз Модан и южных областей Лордерона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орда под предводительством вождя Молота Рока привела под свои знамена огров из родного Дренора и лесных троллей Амани. Продолжая свое наступление, Орда легко подавила сопротивление дворфов из королевства Каз Модан и южных областей Лордерона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1981,'Грандиозные битвы Второй войны сотрясали море и воздух. Каким-то образом Орде удалось завладеть могущественным артефактом – Душой Демона – и с его помощью подчинить себе Алекстразу, древнюю королеву драконов. Угрожая уничтожить отложенные ею яйца, Орда заставила Алекстразу отправить своих детей на войну. Благородные красные драконы были вынуждены сражаться на стороне Орды, и сражались они превосходно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Грандиозные битвы Второй войны сотрясали море и воздух. Каким-то образом Орде удалось завладеть могущественным артефактом – Душой Демона – и с его помощью подчинить себе Алекстразу, древнюю королеву драконов. Угрожая уничтожить отложенные ею яйца, Орда заставила Алекстразу отправить своих детей на войну. Благородные красные драконы были вынуждены сражаться на стороне Орды, и сражались они превосходно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1982,'Война бушевала на просторах Каз Модана, Лордерона и самого Азерота. Свирепая Орда сожгла дотла пограничные земли Кель\'Таласа, после чего эльфы наконец-таки присоединились к Альянсу. Война разрушила и разорила некогда процветавшие города Лордерона. Несмотря на превосходящие силы врага, Лотар и его союзники сумели сдержать наступление Орды.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Война бушевала на просторах Каз Модана, Лордерона и самого Азерота. Свирепая Орда сожгла дотла пограничные земли Кель\'Таласа, после чего эльфы наконец-таки присоединились к Альянсу. Война разрушила и разорила некогда процветавшие города Лордерона. Несмотря на превосходящие силы врага, Лотар и его союзники сумели сдержать наступление Орды.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1983,'Но в последние дни Второй войны, когда победа Орды казалась уже неизбежной, между двумя самыми могучими орками Азерота возникли небывалые раздоры. Когда Молот Рока готовился к решающей атаке на столицу Лордерона, которая должна была сокрушить последние силы Альянса, Гул\'дан и его сторонники покинули остальное войско и отправились в море.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но в последние дни Второй войны, когда победа Орды казалась уже неизбежной, между двумя самыми могучими орками Азерота возникли небывалые раздоры. Когда Молот Рока готовился к решающей атаке на столицу Лордерона, которая должна была сокрушить последние силы Альянса, Гул\'дан и его сторонники покинули остальное войско и отправились в море.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1985,'Жаждавший могущества, Гул\'дан отправился на поиски подводной Гробницы Саргераса, где он надеялся раскрыть тайну абсолютной силы. Гул\'дан уже обрек своих воинов на вечное рабство в Пылающем Легионе и о своем долге перед Молотом Рока он беспокоился меньше всего.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Жаждавший могущества, Гул\'дан отправился на поиски подводной Гробницы Саргераса, где он надеялся раскрыть тайну абсолютной силы. Гул\'дан уже обрек своих воинов на вечное рабство в Пылающем Легионе и о своем долге перед Молотом Рока он беспокоился меньше всего.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1986,'С помощью кланов Бушующего Шторма и Сумеречного Молота Гул\'дану удалось поднять Гробницу Саргераса с морского дна. Но когда он открыл древний склеп, его встретили полчища обезумевших демонов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','С помощью кланов Бушующего Шторма и Сумеречного Молота Гул\'дану удалось поднять Гробницу Саргераса с морского дна. Но когда он открыл древний склеп, его встретили полчища обезумевших демонов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1987,'Молот Рока желал наказать своенравных орков за столь дерзкое предательство и послал своих воинов убить Гул\'дана и вернуть остальных изменников. Обезумевшие демоны, которых столь опрометчиво освободил Гул\'дан, разорвали его на клочки. Потеряв своего командира, воины тотчас сдались на милость войска Молота Рока.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Молот Рока желал наказать своенравных орков за столь дерзкое предательство и послал своих воинов убить Гул\'дана и вернуть остальных изменников. Обезумевшие демоны, которых столь опрометчиво освободил Гул\'дан, разорвали его на клочки. Потеряв своего командира, воины тотчас сдались на милость войска Молота Рока.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1988,'Несмотря на то что восстание было подавлено, Орде не удалось оправиться от ужасных потерь. Предательство Гул\'дана не только придало Альянсу уверенности, но и обеспечило им время на перегруппировку и подготовку к ответной атаке.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на то что восстание было подавлено, Орде не удалось оправиться от ужасных потерь. Предательство Гул\'дана не только придало Альянсу уверенности, но и обеспечило им время на перегруппировку и подготовку к ответной атаке.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1990,'Войскам Туралиона удалось уничтожить Темный портал – волшебный портал в родной мир орков, Дренор. Орда, лишенная подкрепления и разрываемая на части внутренней враждой, наконец, пала перед мощью Альянса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Войскам Туралиона удалось уничтожить Темный портал – волшебный портал в родной мир орков, Дренор. Орда, лишенная подкрепления и разрываемая на части внутренней враждой, наконец, пала перед мощью Альянса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (1991,'Орки со всего мира были собраны вместе и помещены в лагеря для военнопленных. Но, хотя с Ордой было покончено, многие сомневались, что мир удастся сохранить надолго. Кадгар, ставший верховным магом, убедил глав Альянса построить Крепость Стражей Пустоты, чтобы охранять руины Темного портала и не допустить повторного вторжения из Дренора.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орки со всего мира были собраны вместе и помещены в лагеря для военнопленных. Но, хотя с Ордой было покончено, многие сомневались, что мир удастся сохранить надолго. Кадгар, ставший верховным магом, убедил глав Альянса построить Крепость Стражей Пустоты, чтобы охранять руины Темного портала и не допустить повторного вторжения из Дренора.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2005,'Кил\'джеден поставил беспомощный дух Нер\'зула перед последним выбором между службой Легиону и вечными муками. И вновь Нер\'зул принял условия демона. Кил\'джеден заточил его душу в глыбу прочного как алмаз льда, собранного в самых дальних пределах Круговерти Пустоты.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден поставил беспомощный дух Нер\'зула перед последним выбором между службой Легиону и вечными муками. И вновь Нер\'зул принял условия демона. Кил\'джеден заточил его душу в глыбу прочного как алмаз льда, собранного в самых дальних пределах Круговерти Пустоты.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2006,'Заточенный в ледяной тюрьме Нер\'зул почувствовал, что возможности его разума возросли тысячекратно. Наделенный огромной силой демона, он стал невероятно могущественным духом. В этот момент орк по имени Нер\'зул перестал существовать, и на свет явился Король-лич.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Заточенный в ледяной тюрьме Нер\'зул почувствовал, что возможности его разума возросли тысячекратно. Наделенный огромной силой демона, он стал невероятно могущественным духом. В этот момент орк по имени Нер\'зул перестал существовать, и на свет явился Король-лич.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2007,'Рыцари смерти и последователи клана Призрачной Луны, верные Нер\'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мертвых. Демоны позаботились о том, чтобы даже после смерти последователи Нер\'зула беспрекословно служили ему.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Рыцари смерти и последователи клана Призрачной Луны, верные Нер\'зулу, также подверглись трансформации: их разорвали на части, а затем превратили в костяных Королей Мертвых. Демоны позаботились о том, чтобы даже после смерти последователи Нер\'зула беспрекословно служили ему.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2008,'Когда пришло время, Кил\'джеден объяснил Королю-личу, зачем тот был создан. Нер\'зул должен был распространить в Азероте смертоносную чуму, которая истребила бы расу людей. Заразившиеся этой чумой умирали и превращались в нежить, отдавая свои души во власть железной воли Нер\'зула.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда пришло время, Кил\'джеден объяснил Королю-личу, зачем тот был создан. Нер\'зул должен был распространить в Азероте смертоносную чуму, которая истребила бы расу людей. Заразившиеся этой чумой умирали и превращались в нежить, отдавая свои души во власть железной воли Нер\'зула.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2009,'В случае успеха миссии по истреблению людей Кил\'джеден пообещал Нер\'зулу свободу от проклятия и новое здоровое тело.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В случае успеха миссии по истреблению людей Кил\'джеден пообещал Нер\'зулу свободу от проклятия и новое здоровое тело.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2010,'Несмотря на то что Нер\'Зул согласился сыграть свою роль, Кил\'джеден не был уверен в его преданности. Удерживая дух Короля-лича в заточении, демон мог не беспокоиться о его покорности, но, тем не менее, он предпочел не оставлять его без присмотра. Для этого Кил\'джеден приставил к Нер\'Зулу своих лучших демонов-стражников, повелителей ужаса, чтобы те охраняли его и следили за тем, чтобы он выполнил свою жуткую миссию.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на то что Нер\'Зул согласился сыграть свою роль, Кил\'джеден не был уверен в его преданности. Удерживая дух Короля-лича в заточении, демон мог не беспокоиться о его покорности, но, тем не менее, он предпочел не оставлять его без присмотра. Для этого Кил\'джеден приставил к Нер\'Зулу своих лучших демонов-стражников, повелителей ужаса, чтобы те охраняли его и следили за тем, чтобы он выполнил свою жуткую миссию.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2012,'Кил\'джеден отправил Нер\'зула обратно на Азерот. Его ледяная тюрьма пронеслась по ночному небу и упала на заснеженный северный континент Нордскол, погрузившись глубоко в ледник Ледяной Короны. После падения кристалл принял форму трона, а дух Нер\'зула, заключенный в нем, вскоре пробудился.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден отправил Нер\'зула обратно на Азерот. Его ледяная тюрьма пронеслась по ночному небу и упала на заснеженный северный континент Нордскол, погрузившись глубоко в ледник Ледяной Короны. После падения кристалл принял форму трона, а дух Нер\'зула, заключенный в нем, вскоре пробудился.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2013,'Из глубин Ледяного Трона Нер\'зул направил свой могучий разум ко всем обитателям Нордскола. Без особых усилий он подчинил своей воле многих существ, включая ледяных троллей и свирепых вендиго. Силы его духа были практически безграничны, и с их помощью он создал небольшую армию, которую собрал в бесконечных лабиринтах Ледяной Короны.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Из глубин Ледяного Трона Нер\'зул направил свой могучий разум ко всем обитателям Нордскола. Без особых усилий он подчинил своей воле многих существ, включая ледяных троллей и свирепых вендиго. Силы его духа были практически безграничны, и с их помощью он создал небольшую армию, которую собрал в бесконечных лабиринтах Ледяной Короны.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2014,'Совершенствуя свои навыки под неусыпным надзором повелителей ужаса, Король-лич вскоре сумел дотянуться до небольшого поселения людей на самом краю Драконьего Погоста. На нем Нер\'зул и решил испытать свои силы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Совершенствуя свои навыки под неусыпным надзором повелителей ужаса, Король-лич вскоре сумел дотянуться до небольшого поселения людей на самом краю Драконьего Погоста. На нем Нер\'зул и решил испытать свои силы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2015,'Нер\'зул выпустил на просторы ледяной пустыни чуму нежити, зародившуюся глубоко внутри Ледяного Трона. Направляя ее силами одного лишь разума, он привел ее в поселение людей. Спустя три дня все его жители погибли, но вскоре восстали, превратившись в ужасных зомби. Нер\'зул чувствовал их мысли и настроения так же ясно, как свои.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нер\'зул выпустил на просторы ледяной пустыни чуму нежити, зародившуюся глубоко внутри Ледяного Трона. Направляя ее силами одного лишь разума, он привел ее в поселение людей. Спустя три дня все его жители погибли, но вскоре восстали, превратившись в ужасных зомби. Нер\'зул чувствовал их мысли и настроения так же ясно, как свои.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2016,'Яростный диссонанс чужих душ, наполнивший разум бывшего шамана, еще более увеличил его силу. Нер\'зул буквально пожирал души умерших. Но вскоре контроль над зомби наскучил Нер\'зулу – слишком уж это было просто.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Яростный диссонанс чужих душ, наполнивший разум бывшего шамана, еще более увеличил его силу. Нер\'зул буквально пожирал души умерших. Но вскоре контроль над зомби наскучил Нер\'зулу – слишком уж это было просто.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2017,'Следующие месяцы он провел, испытывая чуму нежити на оставшихся людях Нордскола, пока не поработил их всех. Армия нежити росла с каждым днем, и он понял, что пришло время для настоящего испытания.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Следующие месяцы он провел, испытывая чуму нежити на оставшихся людях Нордскола, пока не поработил их всех. Армия нежити росла с каждым днем, и он понял, что пришло время для настоящего испытания.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2018,'Тем временем остатки Орды боролись за выживание в истерзанных войной южных землях. Гром Адский Крик со своим кланом Песни Войны сумел избежать плена, а вот клан Кровавой Глазницы в полном составе, вместе с вождем Мертвым Глазом, был заключен в лордеронские лагеря для военнопленных. Последовала череда бунтов, но начальникам лагерей вскоре удалось восстановить порядок среди заключенных.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тем временем остатки Орды боролись за выживание в истерзанных войной южных землях. Гром Адский Крик со своим кланом Песни Войны сумел избежать плена, а вот клан Кровавой Глазницы в полном составе, вместе с вождем Мертвым Глазом, был заключен в лордеронские лагеря для военнопленных. Последовала череда бунтов, но начальникам лагерей вскоре удалось восстановить порядок среди заключенных.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2020,'Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некрос надеялся вновь объединить Орду и продолжить завоевание Азерота. Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Планируя нанести удар Альянсу силами своей армии и могучих красных драконов, Некрос надеялся вновь объединить Орду и продолжить завоевание Азерота. Но его надеждам не суждено было сбыться: небольшая группа бойцов сопротивления, возглавляемая магом Ронином, смогла уничтожить Душу Демона и освободить королеву драконов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2021,'Разъяренные драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти. Грандиозные планы Некроса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных. Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Разъяренные драконы Алекстразы разрушили Грим Батол и сожгли большую часть орков Драконьей Пасти. Грандиозные планы Некроса рухнули; войска Альянса окружили уцелевших орков и заключили их в лагерь для военнопленных. Поражение Драконьей Пасти ознаменовало конец Орды и кровожадности орков.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2022,'Шли месяцы, и все больше орков попадали в лагеря для военнопленных. В них стало не хватать места, и Альянс был вынужден строить новые лагеря на равнинах к югу от Альтеракских гор. Чтобы содержать их, королю Теренасу пришлось ввести новые налоги.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Шли месяцы, и все больше орков попадали в лагеря для военнопленных. В них стало не хватать места, и Альянс был вынужден строить новые лагеря на равнинах к югу от Альтеракских гор. Чтобы содержать их, королю Теренасу пришлось ввести новые налоги.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2023,'Эти налоги и постоянные споры по поводу границ вызвали недовольство среди населения. Казалось, что хрупкий союз, который люди заключили в тяжелый час, может развалиться в любой момент.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эти налоги и постоянные споры по поводу границ вызвали недовольство среди населения. Казалось, что хрупкий союз, который люди заключили в тяжелый час, может развалиться в любой момент.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2024,'Среди политической неразберихи многие начальники лагерей стали замечать изменения в поведении пленных орков. Число попыток побега и даже драк между заключенными резко уменьшилось. Орки стали спокойными и безразличными.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Среди политической неразберихи многие начальники лагерей стали замечать изменения в поведении пленных орков. Число попыток побега и даже драк между заключенными резко уменьшилось. Орки стали спокойными и безразличными.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2025,'Это было невероятно, но орки, некогда считавшиеся самой воинственной расой, ступавшей на земли Азерота, потеряли желание сражаться. Они становились все более вялыми, чем совершенно сбили с толку предводителей Альянса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Это было невероятно, но орки, некогда считавшиеся самой воинственной расой, ступавшей на земли Азерота, потеряли желание сражаться. Они становились все более вялыми, чем совершенно сбили с толку предводителей Альянса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2026,'Некоторые считали, что виной этому какое-то заболевание, которому подвержены только орки. Но верховный маг Антонидас из Даларана предложил другое объяснение. Изучив те немногие материалы по истории орков, которые ему удалось найти, Антонидас узнал, что несколько поколений этого народа находилось под влиянием демонов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Некоторые считали, что виной этому какое-то заболевание, которому подвержены только орки. Но верховный маг Антонидас из Даларана предложил другое объяснение. Изучив те немногие материалы по истории орков, которые ему удалось найти, Антонидас узнал, что несколько поколений этого народа находилось под влиянием демонов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2027,'Он полагал, что орки подверглись пагубному влиянию еще до первого вторжения на Азерот. Демоны ввели что-то в их кровь, и те стали невероятно сильны, выносливы и агрессивны.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Он полагал, что орки подверглись пагубному влиянию еще до первого вторжения на Азерот. Демоны ввели что-то в их кровь, и те стали невероятно сильны, выносливы и агрессивны.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2028,'Антонидас предположил, что спокойствие орков вызвано не болезнью, а отсутствием черной магии, которая превращала их в грозных и безжалостных воинов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Антонидас предположил, что спокойствие орков вызвано не болезнью, а отсутствием черной магии, которая превращала их в грозных и безжалостных воинов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2029,'Несмотря на то что причина стала ясна, Антонидасу не удалось найти лекарства, чтобы вывести орков из этого состояния. Кроме того, многие маги и некоторые лидеры Альянса полагали, что пытаться излечить орков – не самая благоразумная идея. Размышляя над проблемой, Антонидас пришел к выводу, что лекарство для орков, каким бы оно ни было, должно врачевать душу, а не тело.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на то что причина стала ясна, Антонидасу не удалось найти лекарства, чтобы вывести орков из этого состояния. Кроме того, многие маги и некоторые лидеры Альянса полагали, что пытаться излечить орков – не самая благоразумная идея. Размышляя над проблемой, Антонидас пришел к выводу, что лекарство для орков, каким бы оно ни было, должно врачевать душу, а не тело.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2030,'Адэлас Блэкмур, руководитель всех лагерей для военнопленных, наблюдал за орками из своей крепости Дарнхольд. Один из орков пользовался его особым вниманием: молодой сирота, пойманный почти восемнадцать лет назад. Блэкмур воспитал орчонка как своего раба, назвал его Траллом и обучил тактике, философии и фехтованию. Тралл даже пробовал себя в качестве гладиатора. Блэкмур пытался сделать из юного орка орудие убийства.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Адэлас Блэкмур, руководитель всех лагерей для военнопленных, наблюдал за орками из своей крепости Дарнхольд. Один из орков пользовался его особым вниманием: молодой сирота, пойманный почти восемнадцать лет назад. Блэкмур воспитал орчонка как своего раба, назвал его Траллом и обучил тактике, философии и фехтованию. Тралл даже пробовал себя в качестве гладиатора. Блэкмур пытался сделать из юного орка орудие убийства.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2031,'Несмотря на тяжелое детство, Тралл вырос сильным и умным орком; он осознавал, что участь раба – не для него. Повзрослев, он узнал многое об истории своего народа, представителей которого он почти не видел: после поражения в войне практически все орки попали в лагеря для военнопленных. Ходили слухи, что вождю Молоту Рока удалось бежать из Лордерона. И лишь один клан орков все еще оставался на свободе, скрываясь от бдительных глаз Альянса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на тяжелое детство, Тралл вырос сильным и умным орком; он осознавал, что участь раба – не для него. Повзрослев, он узнал многое об истории своего народа, представителей которого он почти не видел: после поражения в войне практически все орки попали в лагеря для военнопленных. Ходили слухи, что вождю Молоту Рока удалось бежать из Лордерона. И лишь один клан орков все еще оставался на свободе, скрываясь от бдительных глаз Альянса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2032,'Находчивый, но неопытный Тралл решил бежать от Блэкмура и отправиться на поиски своих собратьев. Путешествуя от одного лагеря к другому, Тралл обнаружил, что некогда могучие и воинственные орки превратились в совершенно безжизненных существ. Не сумев найти среди них могучих воинов, о которых он так много слышал, Тралл отправился искать последнего непобежденного вождя Грома Адского Крика.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Находчивый, но неопытный Тралл решил бежать от Блэкмура и отправиться на поиски своих собратьев. Путешествуя от одного лагеря к другому, Тралл обнаружил, что некогда могучие и воинственные орки превратились в совершенно безжизненных существ. Не сумев найти среди них могучих воинов, о которых он так много слышал, Тралл отправился искать последнего непобежденного вождя Грома Адского Крика.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2033,'Несмотря на постоянные преследования со стороны людей, душа Адского Крика была по-прежнему полна неутолимой жажды боя. Вместе со своим верным кланом Песни Войны он продолжал партизанскую войну против поработителей своего народа. К несчастью, он так и не нашел способ вернуть пленным оркам их жизненную энергию. Юного Тралла завораживал идеализм Адского Крика и воинские традиции Орды.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на постоянные преследования со стороны людей, душа Адского Крика была по-прежнему полна неутолимой жажды боя. Вместе со своим верным кланом Песни Войны он продолжал партизанскую войну против поработителей своего народа. К несчастью, он так и не нашел способ вернуть пленным оркам их жизненную энергию. Юного Тралла завораживал идеализм Адского Крика и воинские традиции Орды.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2034,'В поисках правды о своих предках Тралл отправился на север, где обнаружил легендарный клан Северного Волка. Там ему рассказали, как Гул\'дан отправил Северного Волка в изгнание в самом начале Первой войны. Тралл также узнал, что он – сын и наследник храброго орка Дуротана, вождя Северного Волка, погибшего на этих пустынных просторах почти двадцать лет назад.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В поисках правды о своих предках Тралл отправился на север, где обнаружил легендарный клан Северного Волка. Там ему рассказали, как Гул\'дан отправил Северного Волка в изгнание в самом начале Первой войны. Тралл также узнал, что он – сын и наследник храброго орка Дуротана, вождя Северного Волка, погибшего на этих пустынных просторах почти двадцать лет назад.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2035,'Под руководством мудрого шамана Дрек\'Тара Тралл изучил древнюю культуру своего народа, которая была почти полностью забыта при правлении коварного Гул\'дана. Со временем Тралл сам стал могучим шаманом и занял свое законное место вождя клана. Исполненный силы самих стихий, Тралл отправился в путь, чтобы освободить свой народ и снять с него демоническое проклятие.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Под руководством мудрого шамана Дрек\'Тара Тралл изучил древнюю культуру своего народа, которая была почти полностью забыта при правлении коварного Гул\'дана. Со временем Тралл сам стал могучим шаманом и занял свое законное место вождя клана. Исполненный силы самих стихий, Тралл отправился в путь, чтобы освободить свой народ и снять с него демоническое проклятие.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2036,'В ходе своих путешествий Тралл встретил старого вождя Оргрима Молота Рока, который долгие годы жил отшельником. Молот Рока был близким другом отца Тралла. Он решил помочь юному орку освободить плененные кланы. При поддержке опытных воинов Траллу удалось вернуть Орду к жизни и стать ее духовным учителем.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В ходе своих путешествий Тралл встретил старого вождя Оргрима Молота Рока, который долгие годы жил отшельником. Молот Рока был близким другом отца Тралла. Он решил помочь юному орку освободить плененные кланы. При поддержке опытных воинов Траллу удалось вернуть Орду к жизни и стать ее духовным учителем.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2037,'Символом перерождения орков стал поход Тралла на крепость Дарнхольд и освобождение из лагерей всех пленных; зловещим планам Блэкмура не суждено было сбыться. Но эта победа далась дорогой ценой: во время осады одного из лагерей в бою погиб Молот Рока.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Символом перерождения орков стал поход Тралла на крепость Дарнхольд и освобождение из лагерей всех пленных; зловещим планам Блэкмура не суждено было сбыться. Но эта победа далась дорогой ценой: во время осады одного из лагерей в бою погиб Молот Рока.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2038,'Тралл взял легендарный боевой молот Молота Рока и надел свои черные доспехи; теперь он стал новым предводителем Орды. Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него. Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал все возможное, чтобы его народ никогда больше не испытал на себе гнета рабства.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тралл взял легендарный боевой молот Молота Рока и надел свои черные доспехи; теперь он стал новым предводителем Орды. Следующие несколько месяцев его маленькое неуловимое войско совершало набеги на лагеря военнопленных Альянса; войско Альянса было бессильно против него. Под руководством своего лучшего друга и наставника, Грома Адского Крика, Тралл делал все возможное, чтобы его народ никогда больше не испытал на себе гнета рабства.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2039,'Пока Тралл был занят освобождением своих собратьев в Лордероне, Нер\'зул продолжал строить базу в Нордсколе. Над Ледяной Короной он возвел огромную крепость, в которой трудились легионы мертвецов. Но нашлась одна империя, готовая противостоять растущему могуществу Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Пока Тралл был занят освобождением своих собратьев в Лордероне, Нер\'зул продолжал строить базу в Нордсколе. Над Ледяной Короной он возвел огромную крепость, в которой трудились легионы мертвецов. Но нашлась одна империя, готовая противостоять растущему могуществу Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2042,'Несмотря на невосприимчивость воинов Неруба к чуме, Нер\'зулу удалось воскресить пауков-воинов и подчинить их своей воле. Нер\'зул отдал дань уважения их силе и храбрости, позаимствовав их необычный архитектурный стиль для строительства своих крепостей и сооружений.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на невосприимчивость воинов Неруба к чуме, Нер\'зулу удалось воскресить пауков-воинов и подчинить их своей воле. Нер\'зул отдал дань уважения их силе и храбрости, позаимствовав их необычный архитектурный стиль для строительства своих крепостей и сооружений.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2043,'Избавившись от всех противников, Король-лич мог, наконец, приступить к выполнению своей истинной миссии в этом мире. Он устремил свои помыслы к землям людей, выискивая тех, в чьих душах скрывалась тьма, тех, кто слышал его зловещий зов…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Избавившись от всех противников, Король-лич мог, наконец, приступить к выполнению своей истинной миссии в этом мире. Он устремил свои помыслы к землям людей, выискивая тех, в чьих душах скрывалась тьма, тех, кто слышал его зловещий зов…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2044,'Немало могущественных людей услышали зов Короля-лича из Нордскола. Среди них оказался Кел\'Тузад, верховный даларанский маг, один из старейшин Кирин-Тора, совета Даларана. В течение многих лет его считали отступником за желание изучать запретные искусства некромантии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Немало могущественных людей услышали зов Короля-лича из Нордскола. Среди них оказался Кел\'Тузад, верховный даларанский маг, один из старейшин Кирин-Тора, совета Даларана. В течение многих лет его считали отступником за желание изучать запретные искусства некромантии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2045,'Он хотел знать как можно больше о мире магии и темных чудес, но ограниченность и старомодность взглядов коллег разочаровывала его. Когда верховный маг услышал таинственный голос из Нордскола, он приложил все свои силы, чтобы ответить на этот зов. Кел\'Тузад был убежден, что Кирин-Тор слишком слаб, чтобы овладеть силой и знаниями, заключенными в темных искусствах, и поэтому сам решил стать учеником могущественного Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Он хотел знать как можно больше о мире магии и темных чудес, но ограниченность и старомодность взглядов коллег разочаровывала его. Когда верховный маг услышал таинственный голос из Нордскола, он приложил все свои силы, чтобы ответить на этот зов. Кел\'Тузад был убежден, что Кирин-Тор слишком слаб, чтобы овладеть силой и знаниями, заключенными в темных искусствах, и поэтому сам решил стать учеником могущественного Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2046,'Кел\'Тузад оставил учение Кирин-Тора и навсегда покинул Даларан, отказавшись от всех своих богатств и высокого положения в обществе. Повинуясь голосу Короля-лича, звучащему в его мыслях, он продал все, что у него было, и спрятал свои богатства. Он проделал долгий путь по суше и морю – и наконец достиг ледяных берегов Нордскола.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кел\'Тузад оставил учение Кирин-Тора и навсегда покинул Даларан, отказавшись от всех своих богатств и высокого положения в обществе. Повинуясь голосу Короля-лича, звучащему в его мыслях, он продал все, что у него было, и спрятал свои богатства. Он проделал долгий путь по суше и морю – и наконец достиг ледяных берегов Нордскола.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2048,'После долгих месяцев блуждания по суровым снежным пустошам Кел\'Тузад, наконец, добрался до Ледяной Короны. Он смело подошел к темной крепости Нер\'зула, и, к его удивлению, стражники-нежить молча расступились – так, словно мага здесь ждали.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После долгих месяцев блуждания по суровым снежным пустошам Кел\'Тузад, наконец, добрался до Ледяной Короны. Он смело подошел к темной крепости Нер\'зула, и, к его удивлению, стражники-нежить молча расступились – так, словно мага здесь ждали.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2049,'Кел\'Тузад спустился глубоко под замерзшую землю и добрался до сердца ледника. Там, в бесконечных ледяных пещерах, он преклонился перед Ледяным Троном и преподнес свою душу темному повелителю нежити.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кел\'Тузад спустился глубоко под замерзшую землю и добрался до сердца ледника. Там, в бесконечных ледяных пещерах, он преклонился перед Ледяным Троном и преподнес свою душу темному повелителю нежити.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2050,'Король-лич был доволен новобранцем. Он пообещал Кел\'Тузаду бессмертие и невиданную силу в обмен на преданность и покорность. Кел\'Тузад жаждал получить эту силу и знание темных искусств и с радостью принял свою первую великую миссию – отправиться в мир людей и основать новую религию, последователи которой должны поклоняться Королю-личу как богу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Король-лич был доволен новобранцем. Он пообещал Кел\'Тузаду бессмертие и невиданную силу в обмен на преданность и покорность. Кел\'Тузад жаждал получить эту силу и знание темных искусств и с радостью принял свою первую великую миссию – отправиться в мир людей и основать новую религию, последователи которой должны поклоняться Королю-личу как богу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2051,'Чтобы Кел\'Тузаду было легче справиться со своим заданием, Нер\'зул оставил ему человеческую внешность. Престарелому, но тем не менее умевшему привлечь к себе сторонников магу предстояло использовать свой дар убеждения и иллюзии, чтобы внушить угнетенным жителям Лордерона веру и надежду. После этого он должен был показать им, насколько лучше они могли бы жить под властью нового короля.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Чтобы Кел\'Тузаду было легче справиться со своим заданием, Нер\'зул оставил ему человеческую внешность. Престарелому, но тем не менее умевшему привлечь к себе сторонников магу предстояло использовать свой дар убеждения и иллюзии, чтобы внушить угнетенным жителям Лордерона веру и надежду. После этого он должен был показать им, насколько лучше они могли бы жить под властью нового короля.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2052,'Кел\'Тузад вернулся в Лордерон в новом обличии и через три года, благодаря богатству и уму, собрал вокруг себя тайное братство. Это братство, которое он назвал Культом Проклятых, обещало всем своим служителям абсолютное равенство и вечную жизнь в Азероте в обмен на службу и покорность Нер\'зулу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кел\'Тузад вернулся в Лордерон в новом обличии и через три года, благодаря богатству и уму, собрал вокруг себя тайное братство. Это братство, которое он назвал Культом Проклятых, обещало всем своим служителям абсолютное равенство и вечную жизнь в Азероте в обмен на службу и покорность Нер\'зулу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2053,'Шли месяцы; к Кел\'Тузаду приходили все новые и новые приверженцы Культа Проклятых. Кел\'Тузад на удивление легко добился своей цели: многие потеряли веру в Священный Свет и стали поклоняться темному владыке Нер\'зулу. Культ Проклятых становился все более влиятельным, но благодаря Кел\'Тузаду власти Лордерона все еще не замечали перемен…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Шли месяцы; к Кел\'Тузаду приходили все новые и новые приверженцы Культа Проклятых. Кел\'Тузад на удивление легко добился своей цели: многие потеряли веру в Священный Свет и стали поклоняться темному владыке Нер\'зулу. Культ Проклятых становился все более влиятельным, но благодаря Кел\'Тузаду власти Лордерона все еще не замечали перемен…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2054,'Довольный успехами Кел\'Тузада в Лордероне, Король-лич готовился к нападению на людскую цивилизацию. Нер\'зул поместил сгустки энергии чумы в передвижные артефакты, именовавшиеся котлами чумы, и приказал Кел\'Тузаду перенести их в Лордерон, где их нужно было спрятать в селениях последователей Культа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Довольный успехами Кел\'Тузада в Лордероне, Король-лич готовился к нападению на людскую цивилизацию. Нер\'зул поместил сгустки энергии чумы в передвижные артефакты, именовавшиеся котлами чумы, и приказал Кел\'Тузаду перенести их в Лордерон, где их нужно было спрятать в селениях последователей Культа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2055,'Котлы должны были находиться под охраной служителей Культа, а впоследствии использоваться в качестве источников чумы, разносящих по всем деревням и городам на севере Лордерона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Котлы должны были находиться под охраной служителей Культа, а впоследствии использоваться в качестве источников чумы, разносящих по всем деревням и городам на севере Лордерона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2056,'План Короля-лича сработал идеально. Многие северные деревни чума поразила почти мгновенно. Как и в Нордсколе, жители, заразившиеся чумой, умирали и восставали из мертвых верными рабами Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','План Короля-лича сработал идеально. Многие северные деревни чума поразила почти мгновенно. Как и в Нордсколе, жители, заразившиеся чумой, умирали и восставали из мертвых верными рабами Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2057,'Члены Культа, созданного Кел\'Тузадом, добровольно желали умереть и стать слугами своего темного повелителя. Они жаждали получить бессмертие через нежизнь. По мере распространения чумы северные земли наводняли полчища беспощадных зомби. Кел\'Тузад назвал новую армию Плетью Короля-лича. Этой армии предстояло покорить Лордерон и стереть человечество с лица земли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Члены Культа, созданного Кел\'Тузадом, добровольно желали умереть и стать слугами своего темного повелителя. Они жаждали получить бессмертие через нежизнь. По мере распространения чумы северные земли наводняли полчища беспощадных зомби. Кел\'Тузад назвал новую армию Плетью Короля-лича. Этой армии предстояло покорить Лордерон и стереть человечество с лица земли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2064,'После долгих месяцев приготовлений Культ Проклятых под предводительством Кел\'Тузада нанес первый удар, выпустив чуму на земли Лордерона. Утер и его паладины обследовали зараженные территории в надежде найти способ остановить чуму; но, несмотря на все их старания, болезнь продолжала распространяться, угрожая полностью уничтожить Альянс.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После долгих месяцев приготовлений Культ Проклятых под предводительством Кел\'Тузада нанес первый удар, выпустив чуму на земли Лордерона. Утер и его паладины обследовали зараженные территории в надежде найти способ остановить чуму; но, несмотря на все их старания, болезнь продолжала распространяться, угрожая полностью уничтожить Альянс.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2065,'Полчища нежити продолжали свое шествие по землям Лордерона, и принц Артас, единственный сын Теренаса, решил выступить против них. Артасу удалось убить Кел\'Тузада, но ряды нежити пополнялись с каждым павшим солдатом, защищавшим свои земли. Враги казались непобедимыми, и Артас впал в отчаяние; ему пришлось идти на крайние меры. В конце концов он узнал от солдат, что начал терять свои человеческие качества.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Полчища нежити продолжали свое шествие по землям Лордерона, и принц Артас, единственный сын Теренаса, решил выступить против них. Артасу удалось убить Кел\'Тузада, но ряды нежити пополнялись с каждым павшим солдатом, защищавшим свои земли. Враги казались непобедимыми, и Артас впал в отчаяние; ему пришлось идти на крайние меры. В конце концов он узнал от солдат, что начал терять свои человеческие качества.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2066,'Страх и решимость Артаса привели его к погибели. Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича. Надеясь спасти свой народ, Артас взял в руки проклятый рунический клинок, Ледяную Скорбь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Страх и решимость Артаса привели его к погибели. Он желал уничтожить угрозу своей земле и ради этого добрался до источника чумы в Нордсколе, но сам пал жертвой могущества Короля-лича. Надеясь спасти свой народ, Артас взял в руки проклятый рунический клинок, Ледяную Скорбь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2067,'Меч дал Артасу невиданную силу, но забрал его душу, превратив принца в одного из самых могущественных рыцарей смерти, подданных Короля-лича. Потеряв душу и рассудок, Артас возглавил Плеть и повел армию против своего собственного королевства. Артас убил своего отца, короля Теренаса, и бросил поверженное королевство Лордерон к ногам Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Меч дал Артасу невиданную силу, но забрал его душу, превратив принца в одного из самых могущественных рыцарей смерти, подданных Короля-лича. Потеряв душу и рассудок, Артас возглавил Плеть и повел армию против своего собственного королевства. Артас убил своего отца, короля Теренаса, и бросил поверженное королевство Лордерон к ногам Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2068,'Хотя Артас сокрушил всех, кого теперь считал своими врагами, его не переставал преследовать дух Кел\'Тузада. Призрак сказал, что Артас должен помочь вернуть его к жизни, чтобы продолжить выполнение плана Короля-лича. Для этого Артас должен был принести останки Кел\'Тузада к волшебному Солнечному Колодцу, сокрытому в королевстве высших эльфов Кель\'Таласе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя Артас сокрушил всех, кого теперь считал своими врагами, его не переставал преследовать дух Кел\'Тузада. Призрак сказал, что Артас должен помочь вернуть его к жизни, чтобы продолжить выполнение плана Короля-лича. Для этого Артас должен был принести останки Кел\'Тузада к волшебному Солнечному Колодцу, сокрытому в королевстве высших эльфов Кель\'Таласе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2069,'Войско Плети под предводительством Артаса вторглось в Кель\'Талас и окружило немногочисленную армию эльфов. Сильвана Ветрокрылая, предводительница следопытов Луносвета, храбро вступила в неравный бой с врагом, но Артас истребил всю армию высших эльфов и добрался до Солнечного Колодца. В подтверждение своего превосходства безжалостный Артас воскресил Сильвану как банши, чтобы она вечно служила поработителю Кель\'Таласа.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Войско Плети под предводительством Артаса вторглось в Кель\'Талас и окружило немногочисленную армию эльфов. Сильвана Ветрокрылая, предводительница следопытов Луносвета, храбро вступила в неравный бой с врагом, но Артас истребил всю армию высших эльфов и добрался до Солнечного Колодца. В подтверждение своего превосходства безжалостный Артас воскресил Сильвану как банши, чтобы она вечно служила поработителю Кель\'Таласа.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2070,'Затем Артас погрузил останки Кел\'Тузада в священные воды Солнечного Колодца. Могучие воды Вечности были осквернены этим злодеянием, но Кел\'Тузад воскрес и вернулся в этот мир могущественным личом. Кел\'Тузад, чьи силы теперь многократно возросли, объяснил, в чем состоял следующий этап плана Короля-лича.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Затем Артас погрузил останки Кел\'Тузада в священные воды Солнечного Колодца. Могучие воды Вечности были осквернены этим злодеянием, но Кел\'Тузад воскрес и вернулся в этот мир могущественным личом. Кел\'Тузад, чьи силы теперь многократно возросли, объяснил, в чем состоял следующий этап плана Короля-лича.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2071,'Когда Артас со своей армией нежити повернул на юг, в землях Кель\'Таласа уже не осталось ни одного живого эльфа. Славного королевства высших эльфов, просуществовавшего более девяти тысяч лет, больше не существовало.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда Артас со своей армией нежити повернул на юг, в землях Кель\'Таласа уже не осталось ни одного живого эльфа. Славного королевства высших эльфов, просуществовавшего более девяти тысяч лет, больше не существовало.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2072,'Как только Кел\'Тузад вернулся к жизни, Артас повел Плеть на юг, к Даларану. Там лич должен был найти книгу заклинаний Медива и с ее помощью вернуть в этот мир Архимонда. После этого Архимонд должен был возглавить Легион и повести его в решающий бой. Даже волшебники Кирин-Тора не смогли помешать Артасу завладеть книгой Медива, и Кел\'Тузаду оставалось лишь прочесть заклинание.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Как только Кел\'Тузад вернулся к жизни, Артас повел Плеть на юг, к Даларану. Там лич должен был найти книгу заклинаний Медива и с ее помощью вернуть в этот мир Архимонда. После этого Архимонд должен был возглавить Легион и повести его в решающий бой. Даже волшебники Кирин-Тора не смогли помешать Артасу завладеть книгой Медива, и Кел\'Тузаду оставалось лишь прочесть заклинание.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2074,'Среди всего этого хаоса появился таинственный пророк, который стал для смертных спасителем и наставником. Этим пророком оказался не кто иной, как сам Медив, последний Страж, чудесным образом вернувшийся из Бездны, чтобы искупить все свои грехи. Медив поведал Орде и Альянсу о смертельной опасности, которая им грозит, и убеждал их объединить свои силы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Среди всего этого хаоса появился таинственный пророк, который стал для смертных спасителем и наставником. Этим пророком оказался не кто иной, как сам Медив, последний Страж, чудесным образом вернувшийся из Бездны, чтобы искупить все свои грехи. Медив поведал Орде и Альянсу о смертельной опасности, которая им грозит, и убеждал их объединить свои силы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2075,'Орки и люди, враждовавшие не одно поколение, не хотели и слушать его. Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора. Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию калдорай.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орки и люди, враждовавшие не одно поколение, не хотели и слушать его. Медиву пришлось общаться с каждой расой по отдельности, обманом заставить их пересечь море и ступить на легендарную землю Калимдора. Вскоре орки и люди обнаружили скрывавшуюся долгое время цивилизацию калдорай.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2076,'Орков, отправившихся в путь через Степи Калимдора под предводительством Тралла, преследовали неудачи. Они заключили союз с Кэрном Кровавым Копытом и его могучими тауренами-воинами, но при этом многих орков стала одолевать жажда крови, мучившая их на протяжении многих лет. Гром Адский Крик, лучший лейтенант Тралла, предал Орду и позволил своим самым низменным инстинктам взять верх над собой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орков, отправившихся в путь через Степи Калимдора под предводительством Тралла, преследовали неудачи. Они заключили союз с Кэрном Кровавым Копытом и его могучими тауренами-воинами, но при этом многих орков стала одолевать жажда крови, мучившая их на протяжении многих лет. Гром Адский Крик, лучший лейтенант Тралла, предал Орду и позволил своим самым низменным инстинктам взять верх над собой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2077,'Пробираясь через Ясеневый лес, Адский Крик и его верные воины Песни Войны наткнулись на древних ночных эльфов-Часовых. Полубог Кенарий решил, что орки вновь возжаждали войны, и хотел прогнать их из своих земель. Но Адский Крик со своими воинами, преисполненные сверхъестественной ярости и злобы, убили Кенария и осквернили древние леса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Пробираясь через Ясеневый лес, Адский Крик и его верные воины Песни Войны наткнулись на древних ночных эльфов-Часовых. Полубог Кенарий решил, что орки вновь возжаждали войны, и хотел прогнать их из своих земель. Но Адский Крик со своими воинами, преисполненные сверхъестественной ярости и злобы, убили Кенария и осквернили древние леса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2078,'В конечном итоге Адский Крик сумел восстановить свою честь, победив вместе с Траллом Маннорота – демона, обрекшего орков на вечную жажду крови. Смерть Маннорота положила конец ужасному проклятию орков.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В конечном итоге Адский Крик сумел восстановить свою честь, победив вместе с Траллом Маннорота – демона, обрекшего орков на вечную жажду крови. Смерть Маннорота положила конец ужасному проклятию орков.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2080,'Призвав на помощь Малфуриона Ярость Бури, свою давнюю любовь, Тиранда укрепила оборону и вынудила Легион отступить. Малфурион заставил саму природу восстать против армий Легиона и Плети.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Призвав на помощь Малфуриона Ярость Бури, свою давнюю любовь, Тиранда укрепила оборону и вынудила Легион отступить. Малфурион заставил саму природу восстать против армий Легиона и Плети.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2081,'В поисках друидов, которых еще не удалось пробудить, Малфурион наткнулся на древнюю тюрьму, в которой он заточил своего брата Иллидана. Тиранда освободила его в надежде, что он присоединится к ним в битве с Легионом. Некоторое время Иллидан помогал им, но затем бежал, решив, что личные цели для него важнее.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В поисках друидов, которых еще не удалось пробудить, Малфурион наткнулся на древнюю тюрьму, в которой он заточил своего брата Иллидана. Тиранда освободила его в надежде, что он присоединится к ним в битве с Легионом. Некоторое время Иллидан помогал им, но затем бежал, решив, что личные цели для него важнее.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2082,'Ночные эльфы собрались с силами и, полные решимости, вступили в сражение с Пылающим Легионом. Легион всегда желал завладеть Источником Вечности, который питал Древо Жизни и был сердцем королевства ночных эльфов. Если бы Легиону удалось захватить Древо, демоны могли бы в буквальном смысле разорвать мир на части.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ночные эльфы собрались с силами и, полные решимости, вступили в сражение с Пылающим Легионом. Легион всегда желал завладеть Источником Вечности, который питал Древо Жизни и был сердцем королевства ночных эльфов. Если бы Легиону удалось захватить Древо, демоны могли бы в буквальном смысле разорвать мир на части.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2083,'Во время атаки Легиона на Ясеневый лес Иллидан был освобожден из своей тюрьмы, где он провел в заточении десять тысяч лет. Сначала Иллидан пытался помочь своим товарищам, но вскоре он принял свое истинное обличие и поглотил энергию могущественного волшебного артефакта под названием Череп Гул\'дана.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во время атаки Легиона на Ясеневый лес Иллидан был освобожден из своей тюрьмы, где он провел в заточении десять тысяч лет. Сначала Иллидан пытался помочь своим товарищам, но вскоре он принял свое истинное обличие и поглотил энергию могущественного волшебного артефакта под названием Череп Гул\'дана.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2084,'Череп Гул\'дана дал Иллидану демонический облик и огромную силу. Кроме того, он получил часть воспоминаний Гул\'дана, главным образом о Гробнице Саргераса – подземелье на острове, где, по слухам, находились останки Титана Мрака Саргераса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Череп Гул\'дана дал Иллидану демонический облик и огромную силу. Кроме того, он получил часть воспоминаний Гул\'дана, главным образом о Гробнице Саргераса – подземелье на острове, где, по слухам, находились останки Титана Мрака Саргераса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2085,'Вновь получив силу и возможность свободно странствовать по миру, Иллидан отправился на поиски своей судьбы; но на этом пути он столкнулся с Кил\'джеденом, который сделал Иллидану предложение, от которого тот не мог отказаться. Кил\'джеден был разгневан поражением Архимонда у горы Хиджал, но ему предстояли более важные дела, чем отмщение.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вновь получив силу и возможность свободно странствовать по миру, Иллидан отправился на поиски своей судьбы; но на этом пути он столкнулся с Кил\'джеденом, который сделал Иллидану предложение, от которого тот не мог отказаться. Кил\'джеден был разгневан поражением Архимонда у горы Хиджал, но ему предстояли более важные дела, чем отмщение.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2086,'Кил\'джеден понимал, что Король-лич, его собственное творение, достиг слишком большого могущества, и управлять им уже невозможно, а потому он приказал Иллидану убить Нер\'зула, уничтожив Плеть раз и навсегда. Взамен он пообещал Иллидану невиданную силу и почетное место среди повелителей Пылающего Легиона.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кил\'джеден понимал, что Король-лич, его собственное творение, достиг слишком большого могущества, и управлять им уже невозможно, а потому он приказал Иллидану убить Нер\'зула, уничтожив Плеть раз и навсегда. Взамен он пообещал Иллидану невиданную силу и почетное место среди повелителей Пылающего Легиона.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2087,'Иллидан согласился и тотчас отправился на поиски Ледяного Трона, чтобы уничтожить этот ледяной сосуд, в котором хранилась душа Короля-лича. Иллидан знал, что для этого ему понадобится могущественный артефакт. Использовав знания, перешедшие к нему с воспоминаниями Гул\'дана, Иллидан отправился к Гробнице Саргераса за останками Титана Мрака.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Иллидан согласился и тотчас отправился на поиски Ледяного Трона, чтобы уничтожить этот ледяной сосуд, в котором хранилась душа Короля-лича. Иллидан знал, что для этого ему понадобится могущественный артефакт. Использовав знания, перешедшие к нему с воспоминаниями Гул\'дана, Иллидан отправился к Гробнице Саргераса за останками Титана Мрака.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2088,'Иллидан потревожил своих старых должников высокорожденных и выманил из подводных убежищ змееподобных существ – наг. Наги во главе с леди Вайш помогли Иллидану добраться до Таинственных островов, где, по слухам, находилась Гробница Саргераса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Иллидан потревожил своих старых должников высокорожденных и выманил из подводных убежищ змееподобных существ – наг. Наги во главе с леди Вайш помогли Иллидану добраться до Таинственных островов, где, по слухам, находилась Гробница Саргераса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2089,'Когда Иллидан, сопровождаемый нагами, отправился в путь, его начала преследовать Майев Песнь Теней. Майев была тюремным стражником Иллидана десять тысяч лет и страстно желала вернуть его в заточение. Но Иллидан, перехитрив Майев и ее Смотрящих, сумел завладеть Оком Саргераса. Найдя могущественное Око, Иллидан отправился в бывший город волшебников – Даларан.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда Иллидан, сопровождаемый нагами, отправился в путь, его начала преследовать Майев Песнь Теней. Майев была тюремным стражником Иллидана десять тысяч лет и страстно желала вернуть его в заточение. Но Иллидан, перехитрив Майев и ее Смотрящих, сумел завладеть Оком Саргераса. Найдя могущественное Око, Иллидан отправился в бывший город волшебников – Даларан.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2090,'Забрав энергию силовых линий города, Иллидан воспользовался Оком, чтобы нанести магический удар по цитадели Ледяной Короны в далеком Нордсколе. Этот удар сокрушил защиту Короля-лича и поставил под угрозу саму крышу мироздания. В последний момент разрушительное заклятие Иллидана было остановлено, когда его брат Малфурион и жрица Тиранда пришли на помощь Майев.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Забрав энергию силовых линий города, Иллидан воспользовался Оком, чтобы нанести магический удар по цитадели Ледяной Короны в далеком Нордсколе. Этот удар сокрушил защиту Короля-лича и поставил под угрозу саму крышу мироздания. В последний момент разрушительное заклятие Иллидана было остановлено, когда его брат Малфурион и жрица Тиранда пришли на помощь Майев.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2091,'Зная, что Кил\'джеден будет недоволен его неудавшейся попыткой разрушить Ледяной Трон, Иллидан бежал в безжизненный мир, называемый Запределье: последние остатки Дренора, бывшей родины орков. Там он хотел укрыться от гнева Кил\'джедена и обдумать свои дальнейшие планы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Зная, что Кил\'джеден будет недоволен его неудавшейся попыткой разрушить Ледяной Трон, Иллидан бежал в безжизненный мир, называемый Запределье: последние остатки Дренора, бывшей родины орков. Там он хотел укрыться от гнева Кил\'джедена и обдумать свои дальнейшие планы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2092,'Остановив Иллидана, Малфурион и Тиранда вернулись на родину, в Ясеневый лес, дабы охранять свой народ. Однако Майев не согласилась отступить так просто – она последовала за Иллиданам в Запределье, чтобы покарать его.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Остановив Иллидана, Малфурион и Тиранда вернулись на родину, в Ясеневый лес, дабы охранять свой народ. Однако Майев не согласилась отступить так просто – она последовала за Иллиданам в Запределье, чтобы покарать его.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2093,'На этот раз Плеть превратила практически весь Лордерон и Кель\'Талас в ядовитые Чумные земли. Там осталось лишь несколько очагов сопротивления Альянса. Один из них, состоявший в основном из высших эльфов, возглавлял последний представитель династии Солнечного Скитальца – принц Кель\'тас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На этот раз Плеть превратила практически весь Лордерон и Кель\'Талас в ядовитые Чумные земли. Там осталось лишь несколько очагов сопротивления Альянса. Один из них, состоявший в основном из высших эльфов, возглавлял последний представитель династии Солнечного Скитальца – принц Кель\'тас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2094,'Кель, опытный маг, был обеспокоен слабостью Альянса. Его подданные, высшие эльфы, огорченные потерей своей родины, назвали себя эльфами крови – в память о своем погибшем народе. Лишенные энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кель, опытный маг, был обеспокоен слабостью Альянса. Его подданные, высшие эльфы, огорченные потерей своей родины, назвали себя эльфами крови – в память о своем погибшем народе. Лишенные энергии Солнечного Колодца, они ценой огромных страданий сдерживали дальнейшее наступление Плети.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2095,'Когда Кель понял, что не сможет найти средство от магической зависимости своего народа, он совершил непоправимое. Вспомнив об общих предках-высокорожденных, он встал на сторону Иллидана и его спутников-наг. Остальные предводители Альянса объявили эльфов крови предателями и изгнали их навсегда.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда Кель понял, что не сможет найти средство от магической зависимости своего народа, он совершил непоправимое. Вспомнив об общих предках-высокорожденных, он встал на сторону Иллидана и его спутников-наг. Остальные предводители Альянса объявили эльфов крови предателями и изгнали их навсегда.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2096,'Келю и его подданным не оставалось ничего, кроме как отправиться в Запределье вслед за леди Вайш и сразиться с Майев, которой удалось снова поймать Иллидана. Объединив силы, наги и эльфы крови справились с Майев и освободили его. Обосновавшись в Запределье, Иллидан начал копить силы для следующего удара по Королю-личу и его цитадели Ледяной Короны.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Келю и его подданным не оставалось ничего, кроме как отправиться в Запределье вслед за леди Вайш и сразиться с Майев, которой удалось снова поймать Иллидана. Объединив силы, наги и эльфы крови справились с Майев и освободили его. Обосновавшись в Запределье, Иллидан начал копить силы для следующего удара по Королю-личу и его цитадели Ледяной Короны.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2097,'Король-лич Нер\'зул знал, что времени у него мало. Заключенный в Ледяном Троне, он подозревал что Кил\'джеден попытается уничтожить его. Заклятие Иллидана необратимо повредило Трон, и с каждым днем Король-лич становился все слабее. В надежде на спасение он призвал к себе своего величайшего смертного слугу – рыцаря смерти Артаса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Король-лич Нер\'зул знал, что времени у него мало. Заключенный в Ледяном Троне, он подозревал что Кил\'джеден попытается уничтожить его. Заклятие Иллидана необратимо повредило Трон, и с каждым днем Король-лич становился все слабее. В надежде на спасение он призвал к себе своего величайшего смертного слугу – рыцаря смерти Артаса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2098,'Несмотря на нехватку сил, вызванную слабостью повелителя, Артас все же ввязался в братоубийственную войну в Лордероне. Тогда половина его уцелевших войск во главе с банши Сильваной Ветрокрылой вышла из-под его контроля и взяла власть в свои руки. Призванный своим господином, Артас был вынужден передать командование Плетью своему заместителю Кел\'Тузаду, а война тем временем охватывала все новые области Чумных земель.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на нехватку сил, вызванную слабостью повелителя, Артас все же ввязался в братоубийственную войну в Лордероне. Тогда половина его уцелевших войск во главе с банши Сильваной Ветрокрылой вышла из-под его контроля и взяла власть в свои руки. Призванный своим господином, Артас был вынужден передать командование Плетью своему заместителю Кел\'Тузаду, а война тем временем охватывала все новые области Чумных земель.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2099,'В конечном итоге Сильвана и ее мятежники, назвавшие себя Отрекшимися, объявили руины столицы Лордерона своей собственностью. В подземельях под этими руинами они обустроили собственную крепость, поклявшись победить Плеть и изгнать из своих земель Кел\'Тузада.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В конечном итоге Сильвана и ее мятежники, назвавшие себя Отрекшимися, объявили руины столицы Лордерона своей собственностью. В подземельях под этими руинами они обустроили собственную крепость, поклявшись победить Плеть и изгнать из своих земель Кел\'Тузада.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2100,'Ослабевший, но исполненный решимости спасти своего господина, Артас добрался в Нордскол – и обнаружил там наг Иллидана с эльфами крови. Стремясь опередить обнаруженные силы врага, Артас со своими союзниками из Неруба направился к Ледяному Трону.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ослабевший, но исполненный решимости спасти своего господина, Артас добрался в Нордскол – и обнаружил там наг Иллидана с эльфами крови. Стремясь опередить обнаруженные силы врага, Артас со своими союзниками из Неруба направился к Ледяному Трону.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2101,'Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона. Своим руническим мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из нее зачарованный шлем и доспехи Нер\'зула.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Даже практически оставшись без сил, Артас сумел опередить Иллидана и первым добраться до Ледяного Трона. Своим руническим мечом, Ледяной Скорбью, Артас разрушил ледяную тюрьму, а потом забрал из нее зачарованный шлем и доспехи Нер\'зула.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2102,'Водрузив на свою голову шлем, Артас стал новым Королем-личом. Души Нер\'зула и Артаса слились воедино, обретя небывалое могущество. Увидев, что Артас стал самым грозным существом в истории этого мира, Иллидан со своими войсками был вынужден бежать обратно в Запределье.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Водрузив на свою голову шлем, Артас стал новым Королем-личом. Души Нер\'зула и Артаса слились воедино, обретя небывалое могущество. Увидев, что Артас стал самым грозным существом в истории этого мира, Иллидан со своими войсками был вынужден бежать обратно в Запределье.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2103,'Сейчас Король-лич Артас пребывает в Нордсколе. Говорят, что он собирается восстановить Ледяную Корону. Его верный помощник Кел\'Тузад командует силами Плети в Чумных землях. Сильвана же со своими Отрекшимися удерживает лишь Тирисфальские леса – небольшую часть растерзанного войной королевства.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сейчас Король-лич Артас пребывает в Нордсколе. Говорят, что он собирается восстановить Ледяную Корону. Его верный помощник Кел\'Тузад командует силами Плети в Чумных землях. Сильвана же со своими Отрекшимися удерживает лишь Тирисфальские леса – небольшую часть растерзанного войной королевства.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2104,'Хотя смертные расы и одержали победу, их мир был растерзан войной. Плеть и Пылающий Легион практически уничтожили все народы Лордерона и почти закончили свою работу в Калимдоре. Леса нуждались в восстановлении, обиды – в забвении, а разоренные земли – в новых жителях. Война нанесла тяжелые раны каждой из рас, но все они нашли силы объединиться и начать новую жизнь. Первым шагом к ней было перемирие между Альянсом и Ордой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя смертные расы и одержали победу, их мир был растерзан войной. Плеть и Пылающий Легион практически уничтожили все народы Лордерона и почти закончили свою работу в Калимдоре. Леса нуждались в восстановлении, обиды – в забвении, а разоренные земли – в новых жителях. Война нанесла тяжелые раны каждой из рас, но все они нашли силы объединиться и начать новую жизнь. Первым шагом к ней было перемирие между Альянсом и Ордой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2105,'Тралл привел орков на материк Калимдор, где они обрели новую родину с помощью своих братьев-тауренов. Стремясь вернуть былое величие, орки назвали свой дом Дуротаром в честь убитого отца Тралла.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тралл привел орков на материк Калимдор, где они обрели новую родину с помощью своих братьев-тауренов. Стремясь вернуть былое величие, орки назвали свой дом Дуротаром в честь убитого отца Тралла.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2106,'Когда проклятие демонов было снято, Орда превратилась из безжалостной военной машины в относительно свободный союз, направленный не столько на захват новых земель, сколько на жизнь и процветание. Тралл и его орки предвкушали начало новой мирной эры, получая помощь от благородных тауренов и хитрых троллей из племени Черного Копья.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда проклятие демонов было снято, Орда превратилась из безжалостной военной машины в относительно свободный союз, направленный не столько на захват новых земель, сколько на жизнь и процветание. Тралл и его орки предвкушали начало новой мирной эры, получая помощь от благородных тауренов и хитрых троллей из племени Черного Копья.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2107,'Уцелевшие войска Альянса под командованием Джайны Праудмур осели в южном Калимдоре. На восточном краю Пылевых топей они построили укрепленный портовый город Терамор, в котором люди и дворфы объединили усилия ради выживания в этой негостеприимной земле. Хотя жители Дуротара и Терамора и сохраняли непрочное перемирие, оно не могло длиться вечно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уцелевшие войска Альянса под командованием Джайны Праудмур осели в южном Калимдоре. На восточном краю Пылевых топей они построили укрепленный портовый город Терамор, в котором люди и дворфы объединили усилия ради выживания в этой негостеприимной земле. Хотя жители Дуротара и Терамора и сохраняли непрочное перемирие, оно не могло длиться вечно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2108,'Мир между орками и людьми был нарушен с прибытием огромного флота Альянса под командованием отца Джайны, Великого адмирала Даэлина Праудмура. Этот флот покинул Лордерон перед самым падением королевства. В течение долгих месяцев плавания адмирал Праудмур искал любых уцелевших союзников по Альянсу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мир между орками и людьми был нарушен с прибытием огромного флота Альянса под командованием отца Джайны, Великого адмирала Даэлина Праудмура. Этот флот покинул Лордерон перед самым падением королевства. В течение долгих месяцев плавания адмирал Праудмур искал любых уцелевших союзников по Альянсу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2109,'Флот Праудмура представлял серьезную угрозу стабильности в регионе. Будучи знаменитым героем Второй войны, отец Джайны всей душой ненавидел Орду. Он твердо решил уничтожить Дуротар прежде, чем орки закрепятся на этой земле.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Флот Праудмура представлял серьезную угрозу стабильности в регионе. Будучи знаменитым героем Второй войны, отец Джайны всей душой ненавидел Орду. Он твердо решил уничтожить Дуротар прежде, чем орки закрепятся на этой земле.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2110,'Адмирал поставил Джайну перед страшным выбором: выступить против новообретенных союзников-орков или сразиться с собственным отцом в надежде сохранить хрупкий мир между Альянсом и Ордой. После сильных душевных метаний Джайна выбрала последнее и встала на сторону Тралла.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Адмирал поставил Джайну перед страшным выбором: выступить против новообретенных союзников-орков или сразиться с собственным отцом в надежде сохранить хрупкий мир между Альянсом и Ордой. После сильных душевных метаний Джайна выбрала последнее и встала на сторону Тралла.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2111,'К сожалению, адмирал Праудмур умер в бою, не успев помириться с Джайной и узнать, что орки перестали быть кровожадными чудовищами. В награду за помощь орки позволили Джайне и ее подданным беспрепятственно вернуться в Терамор.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К сожалению, адмирал Праудмур умер в бою, не успев помириться с Джайной и узнать, что орки перестали быть кровожадными чудовищами. В награду за помощь орки позволили Джайне и ее подданным беспрепятственно вернуться в Терамор.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2131,'Тром-ка, воин. Меня не интересуют твои подвиги – это все дела прошлого. Когда ты последний раз $gубивал:убивала; человека? Наверняка давно. Ты теряешь хватку без дела.$b$bМне $gнужен напарник:нужна напарница;. А взамен я дам тебе то, что тебе нужно, – полезную тренировку. Когда до тебя дойдет, что я дело говорю, – приходи. Я буду ждать тебя под навесом прямо возле Логова.$b$b-Франг, наставник воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тром-ка, воин. Меня не интересуют твои подвиги – это все дела прошлого. Когда ты последний раз $gубивал:убивала; человека? Наверняка давно. Ты теряешь хватку без дела.$b$bМне $gнужен напарник:нужна напарница;. А взамен я дам тебе то, что тебе нужно, – полезную тренировку. Когда до тебя дойдет, что я дело говорю, – приходи. Я буду ждать тебя под навесом прямо возле Логова.$b$b-Франг, наставник воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2151,'Ареллас Огненный Лист\r\nГлавный волшебник Алого ордена\r\nГражданин Кель\'Таласа\r\nОбречен на вечную битву с некромантом Дисальвеном') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ареллас Огненный Лист\r\nГлавный волшебник Алого ордена\r\nГражданин Кель\'Таласа\r\nОбречен на вечную битву с некромантом Дисальвеном',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2152,'Адмирал Бареан Вествинд\r\nКомандующий флотом Алого марша\r\nГражданин Кул-Тираса\r\nПропал без вести у берегов Нордскола') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Адмирал Бареан Вествинд\r\nКомандующий флотом Алого марша\r\nГражданин Кул-Тираса\r\nПропал без вести у берегов Нордскола',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2153,'Доргар Камнелоб\r\nВоин Алого ордена\r\nВластитель Красных пещер\r\nПоследний раз был замечен в горах Альтерака') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Доргар Камнелоб\r\nВоин Алого ордена\r\nВластитель Красных пещер\r\nПоследний раз был замечен в горах Альтерака',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2171,'Феллари Быстрая Стрела\r\nКапитан следопытов Алого ордена\r\nЖительница Кель\'Таласа\r\nПропала без вести в Серебряном бору') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Феллари Быстрая Стрела\r\nКапитан следопытов Алого ордена\r\nЖительница Кель\'Таласа\r\nПропала без вести в Серебряном бору',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2172,'Феррен Маркус\r\nАббат Монастыря Алого ордена\r\nГражданин Стратхольма\r\nПогиб при обороне монастыря во время Первого летнего штурма') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Феррен Маркус\r\nАббат Монастыря Алого ордена\r\nГражданин Стратхольма\r\nПогиб при обороне монастыря во время Первого летнего штурма',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2174,'Холия Солнечный Щит\r\nЗащитница Алого ордена\r\nПогибла при покушении на повелителя ужаса Белтериса') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Холия Солнечный Щит\r\nЗащитница Алого ордена\r\nПогибла при покушении на повелителя ужаса Белтериса',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2176,'Орман из Стромгарда\r\nПервый капитан-генерал Алого ордена\r\nГражданин Стромгарда\r\nПропал без вести на леднике Ледяной Короны') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Орман из Стромгарда\r\nПервый капитан-генерал Алого ордена\r\nГражданин Стромгарда\r\nПропал без вести на леднике Ледяной Короны',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2178,'Яна Кровавое Копье\r\nВторой предводитель убийц Алого ордена\r\nЖительница Даларана \r\nПропала без вести в Тирисфальских лесах') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Яна Кровавое Копье\r\nВторой предводитель убийц Алого ордена\r\nЖительница Даларана \r\nПропала без вести в Тирисфальских лесах',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2191,'Около 16 000 лет назад, задолго до того как ночные эльфы навлекли на себя гнев Пылающего Легиона, большая часть Калимдора принадлежала троллям. Они основали две империи: Гурубаши в юго-восточных джунглях и Амани в центре материка.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Около 16 000 лет назад, задолго до того как ночные эльфы навлекли на себя гнев Пылающего Легиона, большая часть Калимдора принадлежала троллям. Они основали две империи: Гурубаши в юго-восточных джунглях и Амани в центре материка.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2192,'Далеко на севере, в области, сейчас известной под названием Нордскол, жили малочисленные племена, образовавшие государство Гундрак, но так и не сравнившиеся со своими южными сородичами.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Далеко на севере, в области, сейчас известной под названием Нордскол, жили малочисленные племена, образовавшие государство Гундрак, но так и не сравнившиеся со своими южными сородичами.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2193,'Хотя империи Гурубаши и Амани недолюбливали друг друга, конфликты между ними были редкостью. Их общим врагом был Аз\'Акир – цивилизация насекомоподобных существ с дальнего запада. Разумные насекомые отличались невероятной агрессивностью и стремились искоренить все остальные формы жизни Калимдора.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хотя империи Гурубаши и Амани недолюбливали друг друга, конфликты между ними были редкостью. Их общим врагом был Аз\'Акир – цивилизация насекомоподобных существ с дальнего запада. Разумные насекомые отличались невероятной агрессивностью и стремились искоренить все остальные формы жизни Калимдора.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2196,'После изгнания коварных насекомых две империи вернулись к обычной жизни. Победа в войне практически не изменила их границ. Впрочем, в древних рукописях упоминается некое племя, покинувшее в те годы империю Амани и основавшее собственное поселение в самом сердце темного континента.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После изгнания коварных насекомых две империи вернулись к обычной жизни. Победа в войне практически не изменила их границ. Впрочем, в древних рукописях упоминается некое племя, покинувшее в те годы империю Амани и основавшее собственное поселение в самом сердце темного континента.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2197,'Легенда гласит, что эти храбрые первопроходцы обнаружили источник Вечности, наделивший их невероятной силой. Есть предположение, что именно от них произошли ночные эльфы, но точно это не известно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Легенда гласит, что эти храбрые первопроходцы обнаружили источник Вечности, наделивший их невероятной силой. Есть предположение, что именно от них произошли ночные эльфы, но точно это не известно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2203,'Годы после Великого Раскола были для троллей самыми тяжелыми. Их разрозненные королевства были охвачены голодом и страхом. Тролли Гурубаши в отчаянии искали помощи у древних мистических сил. Все тролли имели общих многочисленных богов, но на призывы Гурубаши откликнулся самый темный и мрачный из них.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Годы после Великого Раскола были для троллей самыми тяжелыми. Их разрозненные королевства были охвачены голодом и страхом. Тролли Гурубаши в отчаянии искали помощи у древних мистических сил. Все тролли имели общих многочисленных богов, но на призывы Гурубаши откликнулся самый темный и мрачный из них.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2204,'Хаккар Свежеватель Душ – жестокий и кровожадный дух – решил прийти на помощь троллям. Открыв Гурубаши секреты крови, он помог им захватить большую часть Тернистой долины и несколько островов Южных морей. Но за свою помощь Хаккар потребовал очень дорогую цену.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хаккар Свежеватель Душ – жестокий и кровожадный дух – решил прийти на помощь троллям. Открыв Гурубаши секреты крови, он помог им захватить большую часть Тернистой долины и несколько островов Южных морей. Но за свою помощь Хаккар потребовал очень дорогую цену.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2205,'Кровожадный бог требовал ежедневного приношения множества жертв. Он мечтал явиться в реальный мир и выпить кровь всех живых существ. Но в конце концов Гурубаши поняли, что за создание им помогает, и восстали против него. Самые сильные племена пошли войной на Хаккара и его верных жрецов Атал\'ай.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кровожадный бог требовал ежедневного приношения множества жертв. Он мечтал явиться в реальный мир и выпить кровь всех живых существ. Но в конце концов Гурубаши поняли, что за создание им помогает, и восстали против него. Самые сильные племена пошли войной на Хаккара и его верных жрецов Атал\'ай.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2206,'О страшной войне между слугами Хаккара и остальными троллями Гурубаши говорят только шепотом. От магии, которую обрушивали друг на друга злой бог и его мятежные дети, содрогалась земля. В самый последний момент троллям удалось изгнать Хаккара из мира, убив его аватару.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','О страшной войне между слугами Хаккара и остальными троллями Гурубаши говорят только шепотом. От магии, которую обрушивали друг на друга злой бог и его мятежные дети, содрогалась земля. В самый последний момент троллям удалось изгнать Хаккара из мира, убив его аватару.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2207,'Даже его жрецы из племени Атал\'ай, были изгнаны из столицы Зул\'Гуруба в северные топи. Там, посреди болот, они воздвигли огромный Храм Атал\'Хаккара и продолжили дело своего павшего хозяина…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Даже его жрецы из племени Атал\'ай, были изгнаны из столицы Зул\'Гуруба в северные топи. Там, посреди болот, они воздвигли огромный Храм Атал\'Хаккара и продолжили дело своего павшего хозяина…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2208,'После гражданской войны пути оставшихся троллей Гурубаши разошлись. Племена Дробителей Черепов, Кровавого Скальпа и Черного Копья племена нашли свое пристанище в джунглях Тернистой долины. На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернется в мир и поглотит его.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После гражданской войны пути оставшихся троллей Гурубаши разошлись. Племена Дробителей Черепов, Кровавого Скальпа и Черного Копья племена нашли свое пристанище в джунглях Тернистой долины. На руинах империи воцарился хрупкий мир, но в народной памяти осталось пророчество о том, что однажды Хаккар вернется в мир и поглотит его.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2211,'Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны\r\n\r\nПроклятие нашего народа началось с Грома – и им же закончилось.\r\nНа нашем древнем языке его имя означает "Сердце великана". Он заслужил его, вступив в поединок с демоном Манноротом\r\nи купив нам свободу ценой собственной крови.\r\n\r\nЛок\'тар огар, старший брат. Да пребудет вечно клан Песни Войны. \r\n\r\n-Тралл, Вождь Орды') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Здесь покоится Громмаш Адский Крик, вождь клана Песни Войны\r\n\r\nПроклятие нашего народа началось с Грома – и им же закончилось.\r\nНа нашем древнем языке его имя означает "Сердце великана". Он заслужил его, вступив в поединок с демоном Манноротом\r\nи купив нам свободу ценой собственной крови.\r\n\r\nЛок\'тар огар, старший брат. Да пребудет вечно клан Песни Войны. \r\n\r\n-Тралл, Вождь Орды',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2212,'О, я проклят! Когда-то я был великим магом огров Черной Вершины. Но я бросил вызов Арроку Роковому Смертному Воплю – и он украл мою магию, а потом наслал на меня проклятье. Теперь мне приходится скитаться по залам Ордамара, подобно жалкой твари!\r\n\r\nПомоги мне! Найди Аррока и укради у него мою магию! Это будет нелегко, потому что Аррок прячется. Чтобы выманить его, нужно очень важное событие.\r\n\r\nТаким событием могла бы быть смерть его ближайшего помощника, вождя Омокка.\r\n\r\nПрочти, и ты поймешь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','О, я проклят! Когда-то я был великим магом огров Черной Вершины. Но я бросил вызов Арроку Роковому Смертному Воплю – и он украл мою магию, а потом наслал на меня проклятье. Теперь мне приходится скитаться по залам Ордамара, подобно жалкой твари!\r\n\r\nПомоги мне! Найди Аррока и укради у него мою магию! Это будет нелегко, потому что Аррок прячется. Чтобы выманить его, нужно очень важное событие.\r\n\r\nТаким событием могла бы быть смерть его ближайшего помощника, вождя Омокка.\r\n\r\nПрочти, и ты поймешь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2213,'Вождь Омокк правит Черной Вершиной с помощью магии Аррока. Аррок наложил на Омокка заклятие, которое убивает любого огра, бросившего ему вызов. Омокк применял это заклятье много раз, а черепа его жертв складывал на месте силы над своим жилищем.\r\n\r\nВот куда ты должен идти, чтобы встретится с Арроком.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вождь Омокк правит Черной Вершиной с помощью магии Аррока. Аррок наложил на Омокка заклятие, которое убивает любого огра, бросившего ему вызов. Омокк применял это заклятье много раз, а черепа его жертв складывал на месте силы над своим жилищем.\r\n\r\nВот куда ты должен идти, чтобы встретится с Арроком.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2214,'Найди наконечник Грубой силы в лагере Изрубленного Щита. Эти глупцы часто прячут их под свои лежанки возле входа во владения Черной Вершины.\r\n\r\nКогда у тебя будет наконечник, иди к вождю Омокку, убей его, а потом насади на наконечник его голову.\r\n\r\nТогда ты будешь готов к настоящему делу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Найди наконечник Грубой силы в лагере Изрубленного Щита. Эти глупцы часто прячут их под свои лежанки возле входа во владения Черной Вершины.\r\n\r\nКогда у тебя будет наконечник, иди к вождю Омокку, убей его, а потом насади на наконечник его голову.\r\n\r\nТогда ты будешь готов к настоящему делу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2215,'Найди место силы над владениями Черной Вершины, за Паучим лабиринтом. Там навалены черепа врагов и соперников Аррока. Вот туда-то ты и должен воткнуть наконечник с головой Омокка!\r\n\r\nКогда голова будет на месте, Аррок точно придет… но сначала он пришлет своих приспешников. Убей их – и он придет сам.\r\n\r\nУбей Аррока и возьми мою магию обратно. Когда я вновь обрету ее, я тебя вознагражу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Найди место силы над владениями Черной Вершины, за Паучим лабиринтом. Там навалены черепа врагов и соперников Аррока. Вот туда-то ты и должен воткнуть наконечник с головой Омокка!\r\n\r\nКогда голова будет на месте, Аррок точно придет… но сначала он пришлет своих приспешников. Убей их – и он придет сам.\r\n\r\nУбей Аррока и возьми мою магию обратно. Когда я вновь обрету ее, я тебя вознагражу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2216,'Удачи тебе. Вот тебе подсказка, как справится с приспешниками Аррока:\r\n\r\nЗаклятие Омокка, убивающее огров, останется в силе даже после гибели самого Омокка. В бою с приспешниками Аррока пробуди силу в голове Омокка – и она, может быть, убьет твоих врагов!\r\n\r\nСпособ что надо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Удачи тебе. Вот тебе подсказка, как справится с приспешниками Аррока:\r\n\r\nЗаклятие Омокка, убивающее огров, останется в силе даже после гибели самого Омокка. В бою с приспешниками Аррока пробуди силу в голове Омокка – и она, может быть, убьет твоих врагов!\r\n\r\nСпособ что надо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2217,'На добрую память о Джесс Моралес') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На добрую память о Джесс Моралес',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2233,'Агашам!$b$bВместе мы будем гораздо сильнее, чем все племена тауренов вместе взятые! Все же мы настаиваем на вашем полном подчинении. Помните, ваш народ получит вознаграждение только после воплощения наших замыслов!$b$bПодпись:$b$bВестник Рекс') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Агашам!$b$bВместе мы будем гораздо сильнее, чем все племена тауренов вместе взятые! Все же мы настаиваем на вашем полном подчинении. Помните, ваш народ получит вознаграждение только после воплощения наших замыслов!$b$bПодпись:$b$bВестник Рекс',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2234,'Агашам!$b$bСкоро наши агенты из Лордерона встретятся с вашими посланниками. Мы сообщим вам, как только найдем подходящее место для встречи.$b$bПодпись:$b$bВестник Гракус') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Агашам!$b$bСкоро наши агенты из Лордерона встретятся с вашими посланниками. Мы сообщим вам, как только найдем подходящее место для встречи.$b$bПодпись:$b$bВестник Гракус',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2251,'Враги… со всех сторон.$B$BПо глазам вижу. Древобрюхи – зло. Враг.$B$BНужно защитить племя. Защитить клан Зимней Спячки. Выгнать врагов с нашей земли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Враги… со всех сторон.$B$BПо глазам вижу. Древобрюхи – зло. Враг.$B$BНужно защитить племя. Защитить клан Зимней Спячки. Выгнать врагов с нашей земли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2271,'Натака, в Тысяче Игл все хорошо. Кентавры вот только иногда нападают, но это нельзя назвать реальной угрозой. Впрочем, говорят, что в последнее время кланы кентавров объединяются.\r\n\r\nМы все понимаем, к чему может привести объединение такого безжалостного народа, как кентавры… Я стараюсь не думать об этом, ты же знаешь… их ненависть вечна… даже друг к другу.\r\n\r\n-Дозорный утесов Долгорог') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Натака, в Тысяче Игл все хорошо. Кентавры вот только иногда нападают, но это нельзя назвать реальной угрозой. Впрочем, говорят, что в последнее время кланы кентавров объединяются.\r\n\r\nМы все понимаем, к чему может привести объединение такого безжалостного народа, как кентавры… Я стараюсь не думать об этом, ты же знаешь… их ненависть вечна… даже друг к другу.\r\n\r\n-Дозорный утесов Долгорог',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2292,'Король Ллейн I из дома Ринн\r\n\r\nВластительный лорд Штормграда\r\n\r\nЗащитник Азерота') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Король Ллейн I из дома Ринн\r\n\r\nВластительный лорд Штормграда\r\n\r\nЗащитник Азерота',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2293,'Командующий флотами Альянса\r\n\r\nДруг Штормграда') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Командующий флотами Альянса\r\n\r\nДруг Штормграда',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2294,'Леди Мара Фордрагон\r\n\r\nВысший клирик Штормграда\r\n\r\nПокровительница беженцев, наводнивших Лордерон после Первой войны.\r\n\r\nОна была светлой матерью нашего будущего. Да упокоится она в Свете.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Леди Мара Фордрагон\r\n\r\nВысший клирик Штормграда\r\n\r\nПокровительница беженцев, наводнивших Лордерон после Первой войны.\r\n\r\nОна была светлой матерью нашего будущего. Да упокоится она в Свете.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2297,'Глядя правым оком на золотой рассвет, Мать-Земля распростерла свои нежные руки над золотыми равнинами. Там, где легла тень от ее рук, из земли восстал благородный народ. Это Шу\'хало, нареченные тауренами, вышли вознести благодарность и молитвы своей любящей матери. Там, в бескрайних полях рассвета, дети земли поклялись восхвалять ее имя до скончания времен.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глядя правым оком на золотой рассвет, Мать-Земля распростерла свои нежные руки над золотыми равнинами. Там, где легла тень от ее рук, из земли восстал благородный народ. Это Шу\'хало, нареченные тауренами, вышли вознести благодарность и молитвы своей любящей матери. Там, в бескрайних полях рассвета, дети земли поклялись восхвалять ее имя до скончания времен.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2298,'Странствуя по полям рассвета, дети земли слышали мрачный шепот из подземных недр. Этот шепот рассказывал им про войну и обман. Многие Шу\'хало попали под его чары и впустили зло в свои души. Они отвернулись от своих добрых братьев и утратили первозданную чистоту.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Странствуя по полям рассвета, дети земли слышали мрачный шепот из подземных недр. Этот шепот рассказывал им про войну и обман. Многие Шу\'хало попали под его чары и впустили зло в свои души. Они отвернулись от своих добрых братьев и утратили первозданную чистоту.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2299,'Увидев падение своих детей, Мать-Земля не выдержала такого горя. Она вырвала свои глаза и бросила их на бескрайний небосвод. С тех пор Ан\'ше и Му\'ша, словно бы желая утешить друг друга, гоняются друг за другом по небу. Поэтому день и сменяет ночь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Увидев падение своих детей, Мать-Земля не выдержала такого горя. Она вырвала свои глаза и бросила их на бескрайний небосвод. С тех пор Ан\'ше и Му\'ша, словно бы желая утешить друг друга, гоняются друг за другом по небу. Поэтому день и сменяет ночь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2300,'Но даже ослепнув, Мать-Земля не могла оставаться безучастной. Ветер доносил до ее ушей вести обо всем, что происходило на рассветных равнинах. Ее любящее сердце всегда пребывало с ее детьми, как и ее великая мудрость.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но даже ослепнув, Мать-Земля не могла оставаться безучастной. Ветер доносил до ее ушей вести обо всем, что происходило на рассветных равнинах. Ее любящее сердце всегда пребывало с ее детьми, как и ее великая мудрость.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2304,'Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь.$b$bЖелание Му\'ша исполнилось, и она зачала от Апа\'ро ребенка, который родился темной ночью. Он получил имя Ценарион и бродил по звездной тропе между пробуждающимся миром и небесным царством.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Умница луна договорилась с великим оленем, что освободит его в обмен на его любовь.$b$bЖелание Му\'ша исполнилось, и она зачала от Апа\'ро ребенка, который родился темной ночью. Он получил имя Ценарион и бродил по звездной тропе между пробуждающимся миром и небесным царством.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2305,'Прошло время, и Ценарион стал сильным, как его великий отец. Брат деревьев и звезд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета. Все живое склонялось перед его грацией и красотой. Никого на свете не было мудрее сына луны и белого оленя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прошло время, и Ценарион стал сильным, как его великий отец. Брат деревьев и звезд, этот великий охотник странствовал по миру, напевая умиротворяющую песню рассвета. Все живое склонялось перед его грацией и красотой. Никого на свете не было мудрее сына луны и белого оленя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2306,'Со временем Ценарион стал другом Шу\'хало и рассказывал им о мире. Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Со временем Ценарион стал другом Шу\'хало и рассказывал им о мире. Дети земли назвали его своим братом и поклялись помогать ему в заботе о полях жизни и любимых созданиях Матери-Земли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2307,'Ценарион научил детей земли разговаривать с деревьями и травами. Шу\'хало стали друидами и совершили множество чудес, приносящих земле здоровье. Многие поколения Шу\'хало охотились вместе с Ценарионом и хранили землю от темных сил.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ценарион научил детей земли разговаривать с деревьями и травами. Шу\'хало стали друидами и совершили множество чудес, приносящих земле здоровье. Многие поколения Шу\'хало охотились вместе с Ценарионом и хранили землю от темных сил.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2308,'Когда рассветные туманы рассеялись, наступили дни, которые мы помним. Ценарион ушел по своим неизбывным путям. Из за его ухода Шу\'хало, нареченные тауренами, впали в отчаянье и забыли многое из того, чему он учил. Сменилось поколение, и они разучились говорить с деревьями и травами. И тогда их ушей вновь начали достигать темные голоса из недр земли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Когда рассветные туманы рассеялись, наступили дни, которые мы помним. Ценарион ушел по своим неизбывным путям. Из за его ухода Шу\'хало, нареченные тауренами, впали в отчаянье и забыли многое из того, чему он учил. Сменилось поколение, и они разучились говорить с деревьями и травами. И тогда их ушей вновь начали достигать темные голоса из недр земли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2309,'Дети земли не слушали темных голосов, но их постигло страшное проклятье. Из темных западных земель пришли орды кровожадных существ – кентавров. Каннибалы и разрушители, кентавры набросились на Шу\'хало, как саранча. Даже благословение Матери-Земли не помогло смелым охотника одолеть эту напасть.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дети земли не слушали темных голосов, но их постигло страшное проклятье. Из темных западных земель пришли орды кровожадных существ – кентавров. Каннибалы и разрушители, кентавры набросились на Шу\'хало, как саранча. Даже благословение Матери-Земли не помогло смелым охотника одолеть эту напасть.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2310,'Шу\'хало навсегда покинули родные земли и стали кочевать по бескрайним равнинам. Но они хранят надежду, что их племена найдут новое пристанище под сенью любящих рук Матери-Земли.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Шу\'хало навсегда покинули родные земли и стали кочевать по бескрайним равнинам. Но они хранят надежду, что их племена найдут новое пристанище под сенью любящих рук Матери-Земли.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2311,'Этот скелет птерадона был найден в Кратере Ун\'Горо. Глядя на его структуру, мы можем сделать вывод, что перед нами новый, неизвестный науке вид. Скелет мог пролежать под слоем богатой почвы Ун\'Горо много столетий.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот скелет птерадона был найден в Кратере Ун\'Горо. Глядя на его структуру, мы можем сделать вывод, что перед нами новый, неизвестный науке вид. Скелет мог пролежать под слоем богатой почвы Ун\'Горо много столетий.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2413,'Снег ослепляет…$B$BПлемя нужно защитить. Дать им силу. Быть сильным.$B$BНе знаю…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Снег ослепляет…$B$BПлемя нужно защитить. Дать им силу. Быть сильным.$B$BНе знаю…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2414,'Огненная вода.$B$BСделай еще. Еще огненной воды.$B$BОгненная вода дает силу. Помогает побеждать врагов.$B$BУ Зимней Спячки нет союзников. Но есть сила.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Огненная вода.$B$BСделай еще. Еще огненной воды.$B$BОгненная вода дает силу. Помогает побеждать врагов.$B$BУ Зимней Спячки нет союзников. Но есть сила.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2415,'Больше. Еще больше… $B$BКлан Зимней Спячки… не… слабый…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Больше. Еще больше… $B$BКлан Зимней Спячки… не… слабый…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2431,'Дата занесения: нет данных\r\n\r\nИмя: Натанос Маррис, человек, предводитель следопытов Лордерона.\r\n\r\nТема:\r\n\r\nХочу отметить несогласие Кель\'таса Солнечного Скитальца с моим решением принять Натаноса Марриса в наши ряды. Следует отметить, что Натанос, несмотря на свое человеческое происхождение, является одним из самых талантливых следопытов, которых мне доводилось обучать.\r\n\r\n(продолжение следует)') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дата занесения: нет данных\r\n\r\nИмя: Натанос Маррис, человек, предводитель следопытов Лордерона.\r\n\r\nТема:\r\n\r\nХочу отметить несогласие Кель\'таса Солнечного Скитальца с моим решением принять Натаноса Марриса в наши ряды. Следует отметить, что Натанос, несмотря на свое человеческое происхождение, является одним из самых талантливых следопытов, которых мне доводилось обучать.\r\n\r\n(продолжение следует)',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2432,'Я никогда так не гордился своим ремеслом, как в последние несколько лет. Спрос на услуги убийц, шпионов и разведчиков высок как никогда. На первый взгляд может показаться, что нас кормит война. Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу.$B$BМне передали, что ты $gпоявился:появилась; в наших краях и хочешь кое-чему научиться. Когда будет время, приходи к стойлам позади аббатства.$B$B-Джорик Керридан, наставник разбойников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я никогда так не гордился своим ремеслом, как в последние несколько лет. Спрос на услуги убийц, шпионов и разведчиков высок как никогда. На первый взгляд может показаться, что нас кормит война. Но ни в одну войну мы не процветали так, как процветаем сейчас, когда мирное время подходит к концу.$B$BМне передали, что ты $gпоявился:появилась; в наших краях и хочешь кое-чему научиться. Когда будет время, приходи к стойлам позади аббатства.$B$B-Джорик Керридан, наставник разбойников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2433,'Готов спорить, что ты сначала $gрешил:решила;, будто это настоящее письмо от короля или кого-то там еще. Видишь ли, я знаю толк в фальшивых письмах. Мне надо было убедиться, что ты точно прочтешь это послание, а как еще этого добиться?$B$BЯ нахожусь в Старой Наковальне, рядом с огненной ямой. Как будешь $gготов:готова;, приходи, поговорим. Было бы любопытно с тобой познакомиться.$B$B-Сольм Харгрин, наставник разбойников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Готов спорить, что ты сначала $gрешил:решила;, будто это настоящее письмо от короля или кого-то там еще. Видишь ли, я знаю толк в фальшивых письмах. Мне надо было убедиться, что ты точно прочтешь это послание, а как еще этого добиться?$B$BЯ нахожусь в Старой Наковальне, рядом с огненной ямой. Как будешь $gготов:готова;, приходи, поговорим. Было бы любопытно с тобой познакомиться.$B$B-Сольм Харгрин, наставник разбойников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2435,'$gБрат, Сестра;, я надеюсь, ты получил эту руну. Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине.\r\n\r\nЯ знаю, как важно для нас держаться вместе, особенно в такое неспокойное время. Загляни ко мне, когда будет свободное время.\r\n\r\n-Сольм Харгрин, наставник разбойников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','$gБрат, Сестра;, я надеюсь, ты получил эту руну. Хочу сообщить тебе, что я в Старой Наковальне, что в Холодной долине.\r\n\r\nЯ знаю, как важно для нас держаться вместе, особенно в такое неспокойное время. Загляни ко мне, когда будет свободное время.\r\n\r\n-Сольм Харгрин, наставник разбойников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2437,'Сал\'ах, друг мой. Я надеюсь, ты $gполучил:получила; мой знак. Меня попросили помочь тебе. Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила. Если тебе нужны знания, обращайся ко мне.\r\n\r\nВ наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга. По-другому мы не сможем сохранить Тельдрассил и наше ремесло. \r\n\r\nПриходи, когда сможешь.\r\n\r\n-Фрагун Шепот Тени, наставник разбойников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сал\'ах, друг мой. Я надеюсь, ты $gполучил:получила; мой знак. Меня попросили помочь тебе. Я нахожусь в Тенистой долине, среди ветвей великого Альдрассила. Если тебе нужны знания, обращайся ко мне.\r\n\r\nВ наше неспокойное время все благоразумные мастера тонких искусств должны держаться друг друга. По-другому мы не сможем сохранить Тельдрассил и наше ремесло. \r\n\r\nПриходи, когда сможешь.\r\n\r\n-Фрагун Шепот Тени, наставник разбойников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2438,'Приветствую тебя, $gбрат:сестра;. Изувеченная Длань выражает тебе свое почтение и надеется, что в нашей долине ты найдешь, где применить свое ремесло. Учти: мы пристально следим за твоими успехами и неудачами.$B$BМне поручено оценить твое мастерство и сообщить, когда ты будешь $gготов:готова; к серьезным делам.$B$BКак будет время, навести меня в глубинах Логова.$B$B-Руаг, наставник разбойников.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую тебя, $gбрат:сестра;. Изувеченная Длань выражает тебе свое почтение и надеется, что в нашей долине ты найдешь, где применить свое ремесло. Учти: мы пристально следим за твоими успехами и неудачами.$B$BМне поручено оценить твое мастерство и сообщить, когда ты будешь $gготов:готова; к серьезным делам.$B$BКак будет время, навести меня в глубинах Логова.$B$B-Руаг, наставник разбойников.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2439,'Скажи-ка мне, |3-6($c), ты когда-нибудь $gслышал:слышала; боевой клич орков? А может быть, ты $gзащищал:защищала; свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким? Жутковато звучит, не правда ли?$B$BЧто ж, тебе пригодится моя помощь. Меня можно найти в североземском аббатстве. Мои знания стоят недешево, но если ты достаточно $gопытен:опытна;, я могу научить тебя приемам и хитростям, которые помогут тебе защищать Штормград и наши земли.$B$BЛлан Бишер, наставник воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Скажи-ка мне, |3-6($c), ты когда-нибудь $gслышал:слышала; боевой клич орков? А может быть, ты $gзащищал:защищала; свой дом от гноллов, желающих перегрызть глотку тебе и твоим близким? Жутковато звучит, не правда ли?$B$BЧто ж, тебе пригодится моя помощь. Меня можно найти в североземском аббатстве. Мои знания стоят недешево, но если ты достаточно $gопытен:опытна;, я могу научить тебя приемам и хитростям, которые помогут тебе защищать Штормград и наши земли.$B$BЛлан Бишер, наставник воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2440,'ВНИМАНИЕ:$BНемедленно свяжись с Траном Корманом. Он находится на объекте А3, известном местному населению как "Старая Наковальня". После успешного контакта с Корманом продолжай подготовку к войне за возвращение нашего Гномрегана!$B$BВсе твои действия и усилия должны быть направлены на выполнение этих указаний. Сделав все, что нужно, ты получишь новое задание.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','ВНИМАНИЕ:$BНемедленно свяжись с Траном Корманом. Он находится на объекте А3, известном местному населению как "Старая Наковальня". После успешного контакта с Корманом продолжай подготовку к войне за возвращение нашего Гномрегана!$B$BВсе твои действия и усилия должны быть направлены на выполнение этих указаний. Сделав все, что нужно, ты получишь новое задание.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2441,'Во многих племенах способность разговаривать с умершими предками считается очень ценным даром. Но ты, |3-6($c), $gдолжен:должна; помнить, что твой дар не менее ценен. Те, кто говорит с духами, не могут поднять тяжелое оружие или вытерпеть телесные страдания, причиняемые тайной магией. Ты – можешь. Ты $gсильный:сильная;. Я помогу тебе стать еще сильнее. Ищи меня в Лагере Нараче.$B$B-Харутт Громовой Рог, наставник воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во многих племенах способность разговаривать с умершими предками считается очень ценным даром. Но ты, |3-6($c), $gдолжен:должна; помнить, что твой дар не менее ценен. Те, кто говорит с духами, не могут поднять тяжелое оружие или вытерпеть телесные страдания, причиняемые тайной магией. Ты – можешь. Ты $gсильный:сильная;. Я помогу тебе стать еще сильнее. Ищи меня в Лагере Нараче.$B$B-Харутт Громовой Рог, наставник воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2442,'Клянусь бородой Магни, $N, нам нужно многое обсудить, а времени очень мало. Как можно скорее найди меня в Старой Наковальне, что в Холодной долине. Там и начнем обучение.$B$BЯ мог бы открыть тебе секреты быстроты движений… но об этом говорить еще рано. Сначала тебе нужно научиться правильно держать топор, привыкнуть к весу доспехов и запаху пота, заливающему лицо в тяжелом бою… Для начала этого будет достаточно.$B$B-Тран Корман, наставник воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Клянусь бородой Магни, $N, нам нужно многое обсудить, а времени очень мало. Как можно скорее найди меня в Старой Наковальне, что в Холодной долине. Там и начнем обучение.$B$BЯ мог бы открыть тебе секреты быстроты движений… но об этом говорить еще рано. Сначала тебе нужно научиться правильно держать топор, привыкнуть к весу доспехов и запаху пота, заливающему лицо в тяжелом бою… Для начала этого будет достаточно.$B$B-Тран Корман, наставник воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2443,'Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы. Но ты-то так не думаешь, |3-6($c)? Клинки – наша магия, щиты – наши обереги, броня – наша мудрость.$B$BБудучи мертвыми, мы сохраняем и умножаем свою силу. Ищи меня в таверне в Могильнике. Там мы обо всем и поговорим.$B$B-Даннал Штерн, наставник воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Многие наши соплеменники считают, что тайная магия и чародейство – единственные источники силы. Но ты-то так не думаешь, |3-6($c)? Клинки – наша магия, щиты – наши обереги, броня – наша мудрость.$B$BБудучи мертвыми, мы сохраняем и умножаем свою силу. Ищи меня в таверне в Могильнике. Там мы обо всем и поговорим.$B$B-Даннал Штерн, наставник воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2444,'Надеюсь, ты <получил/получила> мой знак, $s. Я пишу тебе, потому что нашему народу нужны мечники, копьеносцы и другие отважные воины. С тех пор как нам стало известно о других расах Азерота, мы еще больше нуждаемся в сильных защитниках.\r\n\r\nЭто твой путь. Твое призвание. Я расскажу тебе больше, но только при встрече с глазу на глаз. Ищи меня на нижнем уровне Альдрассила.\r\n\r\n-Алайссия, наставница воинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Надеюсь, ты <получил/получила> мой знак, $s. Я пишу тебе, потому что нашему народу нужны мечники, копьеносцы и другие отважные воины. С тех пор как нам стало известно о других расах Азерота, мы еще больше нуждаемся в сильных защитниках.\r\n\r\nЭто твой путь. Твое призвание. Я расскажу тебе больше, но только при встрече с глазу на глаз. Ищи меня на нижнем уровне Альдрассила.\r\n\r\n-Алайссия, наставница воинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2445,'Существует четыре правила магии:$B$B Магия могущественна.$B Магия развращает.$B Магия порождает зависимость.$B Магия притягивает обитателей Круговерти Пустоты к тому, кто ее применяет.$B$BЭти правила неизменны. Этим правилам ты $gдолжен:должна; будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…$B$BЕсли у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства. Я буду ждать тебя на втором этаже.$B$BКельден Бремен, наставник магов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Существует четыре правила магии:$B$B Магия могущественна.$B Магия развращает.$B Магия порождает зависимость.$B Магия притягивает обитателей Круговерти Пустоты к тому, кто ее применяет.$B$BЭти правила неизменны. Этим правилам ты $gдолжен:должна; будешь подчинить всю свою жизнь, если захочешь продолжить путь магов…$B$BЕсли у тебя хватит глупости не внять этому предупреждению, приходи ко мне в библиотечное крыло Североземского аббатства. Я буду ждать тебя на втором этаже.$B$BКельден Бремен, наставник магов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2446,'Кому: Всем новым студентам тайных искусств$BВы должны явиться к своему преподавателю, гному Маррайку Нуррибиту, и находиться в его распоряжении до того момента, пока вы не будете призваны на помощь своему народу в освоении новых земель. Будьте готовы к предельно жестким экзаменам и изнурительным тренировкам одновременно с поиском жилья и (или) установкой контактов с местным населением.$B$BС вопросами по поводу ваших обязанностей и возможностей обращайтесь к Маррику Нуррибиту.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Кому: Всем новым студентам тайных искусств$BВы должны явиться к своему преподавателю, гному Маррайку Нуррибиту, и находиться в его распоряжении до того момента, пока вы не будете призваны на помощь своему народу в освоении новых земель. Будьте готовы к предельно жестким экзаменам и изнурительным тренировкам одновременно с поиском жилья и (или) установкой контактов с местным населением.$B$BС вопросами по поводу ваших обязанностей и возможностей обращайтесь к Маррику Нуррибиту.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2448,'Поздравляю с пробуждением! Все хитрости и премудрости тайной магии будут твоими – если, конечно, у тебя хватит силенок их удержать.$B$BКак будешь готов, ступай к Май\'ах.$B$BОна расскажет тебе про такую магию и заклинания, с которыми тебе любой враг не страшен!$B$BМай\'ах живет возле Логова, в Долине Испытаний. Ты придешь, ее найдешь, а она тебе силу даст. А потом ты покажешь всем остальным, что ты крутишь магией как хочешь, а не наоборот.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Поздравляю с пробуждением! Все хитрости и премудрости тайной магии будут твоими – если, конечно, у тебя хватит силенок их удержать.$B$BКак будешь готов, ступай к Май\'ах.$B$BОна расскажет тебе про такую магию и заклинания, с которыми тебе любой враг не страшен!$B$BМай\'ах живет возле Логова, в Долине Испытаний. Ты придешь, ее найдешь, а она тебе силу даст. А потом ты покажешь всем остальным, что ты крутишь магией как хочешь, а не наоборот.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2449,'Частенько последователи Священного Света запугивают тех, кто интересуется настоящей силой, пытаясь убедить их, что тайная магия непознаваема. Но не все, что приходит извне, является злом. Не все сущности стремятся подчинить себе других. Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами.$B$BОб этом я хотела бы поговорить с тобой. Жду тебя на кладбище справа от аббатства.$B$B-Друзилла ла Салле, наставница чернокнижников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Частенько последователи Священного Света запугивают тех, кто интересуется настоящей силой, пытаясь убедить их, что тайная магия непознаваема. Но не все, что приходит извне, является злом. Не все сущности стремятся подчинить себе других. Если у тебя будет достаточно силы, те же самые сущности станут твоими слугами.$B$BОб этом я хотела бы поговорить с тобой. Жду тебя на кладбище справа от аббатства.$B$B-Друзилла ла Салле, наставница чернокнижников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2450,'ВНИМАНИЕ:$B$BНичего не говори! Не оглядывайся! За тобой могут следить.$B$B$N, меня зовут Аламар Гримм. Я обучаю тех, кого интересует мудрость и сила из… из других миров. Меня попросили связаться с тобой и предложить тебе услуги учителя.$B$BКогда будешь $gготов:готова;, ищи меня на задворках Старой Наковальни.$B$B-Аламар Мрачнн, наставник чернокнижников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','ВНИМАНИЕ:$B$BНичего не говори! Не оглядывайся! За тобой могут следить.$B$B$N, меня зовут Аламар Гримм. Я обучаю тех, кого интересует мудрость и сила из… из других миров. Меня попросили связаться с тобой и предложить тебе услуги учителя.$B$BКогда будешь $gготов:готова;, ищи меня на задворках Старой Наковальни.$B$B-Аламар Мрачнн, наставник чернокнижников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2451,'$N, я пишу это послание самыми могущественными чернилами, какие только могу создать. Они принесут проклятье любому, кроме тебя. Я вызываю могущественных демонов Круговерти Пустоты просто для развлечения. Я убиваю своих врагов, пока они спят. Ты уже видел могущество, которое можно обрести на моем пути. Мои братья этому рады.$B$BКогда освоишься, найдешь меня в глубине Логова. Нам надо поговорить о важных вещях.$B$B-Нарток, наставник чернокнижников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','$N, я пишу это послание самыми могущественными чернилами, какие только могу создать. Они принесут проклятье любому, кроме тебя. Я вызываю могущественных демонов Круговерти Пустоты просто для развлечения. Я убиваю своих врагов, пока они спят. Ты уже видел могущество, которое можно обрести на моем пути. Мои братья этому рады.$B$BКогда освоишься, найдешь меня в глубине Логова. Нам надо поговорить о важных вещях.$B$B-Нарток, наставник чернокнижников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2453,'Могучие воины защищают наши дома. Мудрые шаманы охраняют наши души и ведут нас по дороге предков. Друиды сообщают нам волю Матери-Земли.$B$BНо ты – $gохотник:охотница;, а это призвание объединяет в себе умения воинов, шаманов и друидов. Такие, как ты, являются сердце нашего народа. К тебе будут обращаться за советом и защитой. Я должен удостоверится, что ты $gготов:готова; к этому. Приходи в Лагерь Нараче.$B$B-Ланко Дальний Выстрел, наставник охотников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Могучие воины защищают наши дома. Мудрые шаманы охраняют наши души и ведут нас по дороге предков. Друиды сообщают нам волю Матери-Земли.$B$BНо ты – $gохотник:охотница;, а это призвание объединяет в себе умения воинов, шаманов и друидов. Такие, как ты, являются сердце нашего народа. К тебе будут обращаться за советом и защитой. Я должен удостоверится, что ты $gготов:готова; к этому. Приходи в Лагерь Нараче.$B$B-Ланко Дальний Выстрел, наставник охотников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2454,'Теперь ты в хороших руках. Джен\'шан знает, что ты любишь охотиться, и готова тебя научить… если ты будешь слушать.$B$BПриходи в Долину Испытаний. Джен\'шан будет учить тебя охотиться и покажет, какими могущественными бывают настоящие охотники.$B$B-Джен\'шан, наставница охотников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Теперь ты в хороших руках. Джен\'шан знает, что ты любишь охотиться, и готова тебя научить… если ты будешь слушать.$B$BПриходи в Долину Испытаний. Джен\'шан будет учить тебя охотиться и покажет, какими могущественными бывают настоящие охотники.$B$B-Джен\'шан, наставница охотников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2455,'Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь? Умения охотника требует недюжинной смекалки и огромного терпения.\r\n\r\nПуть охотника не из легких, это точно. Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа. Потому я тебе и пишу.\r\n\r\nПриходи в Старую Наковальню, что в Холодной долине. Я буду ждать тебя там.\r\n\r\n-Торгас Угрюмсон, наставник охотников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Укрощение зверей, меткая стрельба, чтение следов – как научиться всему этому за такую короткую жизнь? Умения охотника требует недюжинной смекалки и огромного терпения.\r\n\r\nПуть охотника не из легких, это точно. Тебе нужно много тренироваться, чтобы достичь уровня самого неуклюжего ружейника из нашего народа. Потому я тебе и пишу.\r\n\r\nПриходи в Старую Наковальню, что в Холодной долине. Я буду ждать тебя там.\r\n\r\n-Торгас Угрюмсон, наставник охотников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2456,'Элуна с тобой, $N. Ветер прошептал мне твое имя, и я очень рада, что могу принять участие в обучении следующего поколения охотников.\r\n\r\nЯ знаю, что ты сейчас где-то недалеко от Альдрассила. Я буду ждать там.\r\n\r\nНаши старейшины поручили мне подготовить всех новых охотников к грядущим испытаниям. Ты входишь в их число. До встречи.\r\n\r\n-Аянна Вечнобродка, наставница охотников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Элуна с тобой, $N. Ветер прошептал мне твое имя, и я очень рада, что могу принять участие в обучении следующего поколения охотников.\r\n\r\nЯ знаю, что ты сейчас где-то недалеко от Альдрассила. Я буду ждать там.\r\n\r\nНаши старейшины поручили мне подготовить всех новых охотников к грядущим испытаниям. Ты входишь в их число. До встречи.\r\n\r\n-Аянна Вечнобродка, наставница охотников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2457,'Приятно слышать, что $gодин:одна; из $gбратьев:сестер; Джен\'шан $gявился:явилась; в долину испытать свои способности. Джен\'шан ждет этого с нетерпением!$B$BНе мне тебе рассказывать, $gкакой ты сильный и ловкий охотник:какая ты сильная и ловкая охотница;. Дело Джен\'шан – сделать тебя еще более $gсильным и ловким:сильной и ловкой;.$B$BНайди Джен\'шан в Долине Испытаний. Она научит тебя, как укрощать самых сильных зверей.$B$B-Джен\'шан, наставница охотников') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приятно слышать, что $gодин:одна; из $gбратьев:сестер; Джен\'шан $gявился:явилась; в долину испытать свои способности. Джен\'шан ждет этого с нетерпением!$B$BНе мне тебе рассказывать, $gкакой ты сильный и ловкий охотник:какая ты сильная и ловкая охотница;. Дело Джен\'шан – сделать тебя еще более $gсильным и ловким:сильной и ловкой;.$B$BНайди Джен\'шан в Долине Испытаний. Она научит тебя, как укрощать самых сильных зверей.$B$B-Джен\'шан, наставница охотников',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2460,'Приветствую тебя, $gмолодой:молодая; |3-6($c). Ветер нашептал мне, что ты $gпришел:пришла;. Земля рассказала о твоей силе. И теперь древние духи говорят о том, что ты $gготов:готова; учиться. Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас. Если хочешь, я научу тебя большему.$B$BИщи меня в Лагере Нараче на плато Красного Облака – нам есть, о чем поговорить.$B$B-Мила Рассветная Странница, наставница шаманов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую тебя, $gмолодой:молодая; |3-6($c). Ветер нашептал мне, что ты $gпришел:пришла;. Земля рассказала о твоей силе. И теперь древние духи говорят о том, что ты $gготов:готова; учиться. Наш народ нуждается в мудрых и могущественных наставниках – и находит их среди нас. Если хочешь, я научу тебя большему.$B$BИщи меня в Лагере Нараче на плато Красного Облака – нам есть, о чем поговорить.$B$B-Мила Рассветная Странница, наставница шаманов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2461,'Лок-тар, $gбрат:сестра;. Стихии указали на тебя и поручили мне показать тебе путь шамана. Духи наших предков смотрят на нас и гордятся тем, что ты $gвступил:вступила; в наши ряды.\r\n\r\nКогда будешь $gготов:готова;, найди меня у входа в Логово. Я обучаю там наших собратьев. Да будет тебе попутный ветер.\r\n\r\n-Шикрик, наставница шаманов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лок-тар, $gбрат:сестра;. Стихии указали на тебя и поручили мне показать тебе путь шамана. Духи наших предков смотрят на нас и гордятся тем, что ты $gвступил:вступила; в наши ряды.\r\n\r\nКогда будешь $gготов:готова;, найди меня у входа в Логово. Я обучаю там наших собратьев. Да будет тебе попутный ветер.\r\n\r\n-Шикрик, наставница шаманов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2462,'Привет тебе, $gбрат:сестра;. Духи говорят, ты $gготов:готова; нам помочь. Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня.$B$BСтупай к Шикрик, наставнице орочьих шаманов в Долине Испытаний. Она уже знает о тебе. Пусть наши предки гордятся тобой. Да согреет тебя огонь, и да будет тебе попутный ветер.$B$B-Иши-йо') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Привет тебе, $gбрат:сестра;. Духи говорят, ты $gготов:готова; нам помочь. Ты очень здорово управляешься со стихиями – гораздо лучше, чем когда только начинал учиться у меня.$B$BСтупай к Шикрик, наставнице орочьих шаманов в Долине Испытаний. Она уже знает о тебе. Пусть наши предки гордятся тобой. Да согреет тебя огонь, и да будет тебе попутный ветер.$B$B-Иши-йо',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2463,'Надеюсь, это письмо дошло до тебя, |3-6($c). Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота.$B$BНикогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несет скверну в наши дома.$B$BМеня назначили твоим наставником на первое время. Когда будешь $gготов:готова;, ищи меня в Аббатстве Североземья.$B$B-Брат Самуэль, наставник паладинов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Надеюсь, это письмо дошло до тебя, |3-6($c). Я обращаюсь к тебе с гордостью, потому что немногие обладают столь крепкой верой и готовы войти в число величайших защитников Азерота.$B$BНикогда не забывай, твой главный долг – сражаться с теми, кто угрожает нашему миру и несет скверну в наши дома.$B$BМеня назначили твоим наставником на первое время. Когда будешь $gготов:готова;, ищи меня в Аббатстве Североземья.$B$B-Брат Самуэль, наставник паладинов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2464,'Одни боятся нас больше, чем драконов. Другие завидуют нам больше, чем самым искусным кузнецам. Третьи превозносят нас за подвиги на поле боя. Четвертые преклоняются перед нашей верой. А пятым просто обидно, что мы можем с легкостью перепить любого из них! Но помни, |3-6($c), что на самом деле мы – величайшие защитники Азерота. Божественный Свет дает нам тем больше силы, чем больше мы служим ему. Я расскажу тебе больше, когда ты освоишься. Ищи меня в Старой Наковальне над долиной.$B$B-Бромос Груммнер, наставник паладинов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Одни боятся нас больше, чем драконов. Другие завидуют нам больше, чем самым искусным кузнецам. Третьи превозносят нас за подвиги на поле боя. Четвертые преклоняются перед нашей верой. А пятым просто обидно, что мы можем с легкостью перепить любого из них! Но помни, |3-6($c), что на самом деле мы – величайшие защитники Азерота. Божественный Свет дает нам тем больше силы, чем больше мы служим ему. Я расскажу тебе больше, когда ты освоишься. Ищи меня в Старой Наковальне над долиной.$B$B-Бромос Груммнер, наставник паладинов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2465,'Секрет успеха жреца – в его связи с миром. Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред. Но к этому ты $gдолжен прийти сам:должна прийти сама;.$B$BКогда ты это осознаешь, тебе понадобятся новые способности и заклинания. Вот с этим я могу тебе помочь. Приходи в библиотечное крыло Аббатства Североземья.$B$B-Жрица Анетта, наставница жрецов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Секрет успеха жреца – в его связи с миром. Мудрость и сострадание позволят тебе помогать тем, кто действительно в этом нуждается, а поспешность и необдуманные решения причинят только вред. Но к этому ты $gдолжен прийти сам:должна прийти сама;.$B$BКогда ты это осознаешь, тебе понадобятся новые способности и заклинания. Вот с этим я могу тебе помочь. Приходи в библиотечное крыло Аббатства Североземья.$B$B-Жрица Анетта, наставница жрецов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2466,'В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть <одним из сыновей/одной из дочерей> Стальгорна. Лига Исследователей с каждым днем все более продвигается вперед, находя давно потерянные ответы на еще более древние вопросы. А еще теперь среди нас есть ты, <способный/способная> помочь в борьбе с троггами и всеми другими врагами.\r\n\r\nНайди меня, когда у тебя будет время. Я буду в Старой Наковальне, что находится выше по склону.\r\n\r\n- Брансток Халдер, наставник жрецов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В это время, когда Божественный Свет согревает наши души, а каждый день дарит нам новые открытия, особенно хорошо быть <одним из сыновей/одной из дочерей> Стальгорна. Лига Исследователей с каждым днем все более продвигается вперед, находя давно потерянные ответы на еще более древние вопросы. А еще теперь среди нас есть ты, <способный/способная> помочь в борьбе с троггами и всеми другими врагами.\r\n\r\nНайди меня, когда у тебя будет время. Я буду в Старой Наковальне, что находится выше по склону.\r\n\r\n- Брансток Халдер, наставник жрецов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2467,'Рад, что твоя душа не попала в Пустоту, $N. Я полагаю, ты стоишь усилий, затраченных на написание этого свитка.$B$BПомни: людей, которых ты $gзнал и любил:знала и любила;, больше нет в живых! Ты $gдолжен:должна; пронести этот груз через все свое дальнейшее существование. Советую тебе смириться с этим с самого начала.$B$BЕсли ты $gготов:готова; к испытаниям, найди меня в церкви Могильника.$B$B- Темный священник Дьюстен, наставник жрецов') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Рад, что твоя душа не попала в Пустоту, $N. Я полагаю, ты стоишь усилий, затраченных на написание этого свитка.$B$BПомни: людей, которых ты $gзнал и любил:знала и любила;, больше нет в живых! Ты $gдолжен:должна; пронести этот груз через все свое дальнейшее существование. Советую тебе смириться с этим с самого начала.$B$BЕсли ты $gготов:готова; к испытаниям, найди меня в церкви Могильника.$B$B- Темный священник Дьюстен, наставник жрецов',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2468,'Надеюсь, этот знак застанет тебя в добром здравии, $N. Духи поведали мне о твоем приходе, и я сразу же стала писать это письмо. Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел.$B$BПосле всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи. Когда будешь $gготов:готова;, разыщи меня в Альдрассиле, на втором уровне.$B$B-Шанда, наставница жрецов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Надеюсь, этот знак застанет тебя в добром здравии, $N. Духи поведали мне о твоем приходе, и я сразу же стала писать это письмо. Хочу скорее передать тебе часть моих знаний и направить тебя на верный путь, пока ты готовишься покинуть Тельдрассил для более важных дел.$B$BПосле всего что случилось за последние несколько лет, очень многие народы Азерота нуждаются в нашей помощи. Когда будешь $gготов:готова;, разыщи меня в Альдрассиле, на втором уровне.$B$B-Шанда, наставница жрецов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2471,'Тысячелетиями мы скрывались от чужаков. Я буду первой из нас, кто признает, что в прошлом мы ошибались. Нельзя было открывать людям магию. Я не отрицаю этого, но и не желаю приговаривать нас к заточению за промахи предшественников. Совместное существование Кель\'дорай и других народов этого мира может принести много пользы. Мы должны учиться терпимости.\r\n\r\n(продолжение следует)') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Тысячелетиями мы скрывались от чужаков. Я буду первой из нас, кто признает, что в прошлом мы ошибались. Нельзя было открывать людям магию. Я не отрицаю этого, но и не желаю приговаривать нас к заточению за промахи предшественников. Совместное существование Кель\'дорай и других народов этого мира может принести много пользы. Мы должны учиться терпимости.\r\n\r\n(продолжение следует)',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2472,'Настоящим я отказываю Кел\'Тасу в просьбах касательно Натаноса Марриса. Он будет бесценным союзником. Помяните мое слово.\r\n\r\nПодписано:\r\n\r\nСильвана Ветрокрылая\r\nПредводитель следопытов Луносвета.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Настоящим я отказываю Кел\'Тасу в просьбах касательно Натаноса Марриса. Он будет бесценным союзником. Помяните мое слово.\r\n\r\nПодписано:\r\n\r\nСильвана Ветрокрылая\r\nПредводитель следопытов Луносвета.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2491,'Гриш, твоя просьба об отпуске удовлетворена. Посылаю тебе на смену таурена-воина, чтобы он занял твой пост, пока ты будешь проводить время с семьей. Через неделю доложи о возвращении!$B$B-Землепряд Маггран') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гриш, твоя просьба об отпуске удовлетворена. Посылаю тебе на смену таурена-воина, чтобы он занял твой пост, пока ты будешь проводить время с семьей. Через неделю доложи о возвращении!$B$B-Землепряд Маггран',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2512,'Озрик, ниже приведен перечень доспехов, которые нам требуются: \r\n\r\n10 Панцирных Рубах\r\n20 Шлемов\r\n30 Накладок на Доспех\r\n15 Бронированных Ботинок\r\n\r\nМы, как обычно, у тебя в долгу. И если Западный Край когда-нибудь избавится от досаждающих ему воров, я сочту себя просто обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эту страну.\r\n\r\n-Льюис\r\nИнтендант, Сторожевой Холм.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Озрик, ниже приведен перечень доспехов, которые нам требуются: \r\n\r\n10 Панцирных Рубах\r\n20 Шлемов\r\n30 Накладок на Доспех\r\n15 Бронированных Ботинок\r\n\r\nМы, как обычно, у тебя в долгу. И если Западный Край когда-нибудь избавится от досаждающих ему воров, я сочту себя просто обязанным пригласить тебя в наш дом на вкусный обед, достойный былой щедрости, что некогда прославляла эту страну.\r\n\r\n-Льюис\r\nИнтендант, Сторожевой Холм.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2531,'Этот трехстраничный документ пуст.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Этот трехстраничный документ пуст.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2551,'Лайо, мы получили щедрую помощь от этого доброго странника. Я направил его к тебе в Силитус. Используй его способности во благо себе и раскрой все нужные тебе тайны. Круг с нетерпением ждет новостей о твоих успехах.$B$BДа убережет тебя Кенарий…$BРабин') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лайо, мы получили щедрую помощь от этого доброго странника. Я направил его к тебе в Силитус. Используй его способности во благо себе и раскрой все нужные тебе тайны. Круг с нетерпением ждет новостей о твоих успехах.$B$BДа убережет тебя Кенарий…$BРабин',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2575,'Пиршество$B$BОбычай устраивать на этот праздник пиршества тянется корнями в глубь самой легенды. Она гласит, что, когда Дедушка Зима шел по Азероту, укрывая его снегами, тех, кто приветствовал его появление, он осыпал дарами. И потому традиция пировать на Зимний Покров объединила между собой общины, члены которых совместно вкушали на пиру разные яства. Обычно обновление и перерождение земли приветствовали весельем и празднеством в течение целого дня.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Пиршество$B$BОбычай устраивать на этот праздник пиршества тянется корнями в глубь самой легенды. Она гласит, что, когда Дедушка Зима шел по Азероту, укрывая его снегами, тех, кто приветствовал его появление, он осыпал дарами. И потому традиция пировать на Зимний Покров объединила между собой общины, члены которых совместно вкушали на пиру разные яства. Обычно обновление и перерождение земли приветствовали весельем и празднеством в течение целого дня.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2596,'Используй силу Амулета духов, чтобы они выдали себя, и забери у них камни! Затем вставь камни в Амулет Духов и верни его мне. Когда у меня будет Амулет Соединения, я стану достаточно силен, чтобы изменить жизнь племен, и мы наконец-то сможем жить по заветам предков!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Используй силу Амулета духов, чтобы они выдали себя, и забери у них камни! Затем вставь камни в Амулет Духов и верни его мне. Когда у меня будет Амулет Соединения, я стану достаточно силен, чтобы изменить жизнь племен, и мы наконец-то сможем жить по заветам предков!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2605,'Credit\'s Main:$bQuest scripter\'s:$b$b==============================$b$bShultz. Thesleby. Rest of !rpg Team.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Credit\'s Main:$bQuest scripter\'s:$b$b==============================$b$bShultz. Thesleby. Rest of !rpg Team.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2632,'<Вы не можете разобрать надписи на этих страницах.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Вы не можете разобрать надписи на этих страницах.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2634,'<Письмена на странице кружатся и перемещаются. Вам кажется, будто книга дразнит вас.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Письмена на странице кружатся и перемещаются. Вам кажется, будто книга дразнит вас.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2661,'<HTML>\r\n<BODY>\r\n<H1 align="center">ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\r\n<BR/>\r\n<P align="right">Тром\'ка! В этой</P>\r\n<P align="right">книге ты найдешь</P>\r\n<P align="right">подробный перечень</P>\r\n<P align="right">воинских званий</P>\r\n<P align="right">Орды и</P>\r\n<P align="right">жалкого Альянса.</P>\r\n<P align="right">Сначала в списках идет</P>\r\n<P align="right">Орда, а затем Альянс,</P>\r\n<P align="right">и для обеих сторон перечислены офицерские и рядовые звания. Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">ВОИНСКИЕ ЗВАНИЯ ОРДЫ И АЛЬЯНСА</H1>\r\n<BR/>\r\n<BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRankHorde" align="left"/>\r\n<BR/>\r\n<P align="right">Тром\'ка! В этой</P>\r\n<P align="right">книге ты найдешь</P>\r\n<P align="right">подробный перечень</P>\r\n<P align="right">воинских званий</P>\r\n<P align="right">Орды и</P>\r\n<P align="right">жалкого Альянса.</P>\r\n<P align="right">Сначала в списках идет</P>\r\n<P align="right">Орда, а затем Альянс,</P>\r\n<P align="right">и для обеих сторон перечислены офицерские и рядовые звания. Как и подобает, вверху списка располагаются старшие чины, а младшие – ниже.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2662,'<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Верховный Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Лейтенант-генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Защитник</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Верховный Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Вождь</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Лейтенант-генерал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Защитник</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2663,'<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Центурион</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Легионер</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Кровавый страж</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadgesPvPRank06" align="left"/><BR/>\r\n<P align="right">Каменный Страж</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Центурион</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Легионер</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Кровавый страж</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadgesPvPRank06" align="left"/><BR/>\r\n<P align="right">Каменный Страж</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2664,'<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВЫЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Высший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Старший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Рубака</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Разведчик</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВЫЕ ЗВАНИЯ ОРДЫ</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Высший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Старший Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Рубака</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Разведчик</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2665,'<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Главнокомандующий</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Фельдмаршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Маршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Командор</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Лейтенант-командор</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 1</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank14" align="left"/><BR/>\r\n<P align="right">Главнокомандующий</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank13" align="left"/><BR/>\r\n<P align="right">Фельдмаршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank12" align="left"/><BR/>\r\n<P align="right">Маршал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank11" align="left"/><BR/>\r\n<P align="right">Командор</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank10" align="left"/><BR/>\r\n<P align="right">Лейтенант-командор</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2671,'Симон Совратительница:\r\n\r\nСимон ты застанешь за осквернением Кратера Ун\'Горо. Не поддавайся на ее уловки. Приближайся к ней с осторожностью, а потом вступай в бой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Симон Совратительница:\r\n\r\nСимон ты застанешь за осквернением Кратера Ун\'Горо. Не поддавайся на ее уловки. Приближайся к ней с осторожностью, а потом вступай в бой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2672,'Клинфран Безумный:\r\n\r\nКлинфран блуждает по Пылающим степям. Приближайся к нему с осторожностью и вынуди его показать истинное лицо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Клинфран Безумный:\r\n\r\nКлинфран блуждает по Пылающим степям. Приближайся к нему с осторожностью и вынуди его показать истинное лицо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2673,'Соленор Душегуб:\r\n\r\nВ безводных землях Силитуса рыщет наш враг, Соленор Душегуб. Он дьявольски хитер и очень опасен. Подберись к нему и вынуди его принять свой облик.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Соленор Душегуб:\r\n\r\nВ безводных землях Силитуса рыщет наш враг, Соленор Душегуб. Он дьявольски хитер и очень опасен. Подберись к нему и вынуди его принять свой облик.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2674,'Арториус Судьбоносный:\r\n\r\nВсему, чего Арториус касается в Зимних Ключах, он приносит смерть и разрушение. Найди его и убей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Арториус Судьбоносный:\r\n\r\nВсему, чего Арториус касается в Зимних Ключах, он приносит смерть и разрушение. Найди его и убей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2675,'Знай, $gохотник:охотница;, эти демоны дерутся только по своим правилам. Если им покажется, что одолеть тебя нельзя, они сбегут.\r\n\r\nИДИ К НИМ $gОДИН:ОДНА;.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Знай, $gохотник:охотница;, эти демоны дерутся только по своим правилам. Если им покажется, что одолеть тебя нельзя, они сбегут.\r\n\r\nИДИ К НИМ $gОДИН:ОДНА;.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2779,'Артишок клана Северного Волка: Повести о славе Грозовой Вершины\r\n-Автор Вандар Грозовая Вершина\r\n\r\nЧто такое клан Северного Волка? Ответ прост: клан Северного Волка – сборище дикарей, жаждущих низвергнуть нас, своих законных повелителей.\r\n\r\nОн, подобно артишоку, окружен колючим и твердым защитным слоем, сняв который, можно добраться до сердцевины и съесть ее с доброй чесночной подливой.\r\n\r\nВкусно!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Артишок клана Северного Волка: Повести о славе Грозовой Вершины\r\n-Автор Вандар Грозовая Вершина\r\n\r\nЧто такое клан Северного Волка? Ответ прост: клан Северного Волка – сборище дикарей, жаждущих низвергнуть нас, своих законных повелителей.\r\n\r\nОн, подобно артишоку, окружен колючим и твердым защитным слоем, сняв который, можно добраться до сердцевины и съесть ее с доброй чесночной подливой.\r\n\r\nВкусно!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2780,'Глава 1 – Линия фронта\r\n\r\nПередние линии обороны Клана Северного Волка состоят из воинов клана. Эти воины отправляются на передовую из крепости капитана Гальвангара под названием гарнизон Стылой Крови. Проще всего расправиться с этой линией обороны, разрушив гарнизон.\r\n\r\nОсади крепость и убей капитана Гальвангара. После этого передовые линии падут.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глава 1 – Линия фронта\r\n\r\nПередние линии обороны Клана Северного Волка состоят из воинов клана. Эти воины отправляются на передовую из крепости капитана Гальвангара под названием гарнизон Стылой Крови. Проще всего расправиться с этой линией обороны, разрушив гарнизон.\r\n\r\nОсади крепость и убей капитана Гальвангара. После этого передовые линии падут.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2781,'Глава 2 – Стылая Кровь и Смотровая башня\r\n\r\nКогда ты разделаешься с первым слоем "артишока", тебе будет открыт второй. Если уничтожить Башни Северного Волка, стоящие у линии фронта, то ослабнут вражеские легионеры и патрули с задних флангов.\r\n\r\nЭти башни сильно укреплены, и в каждой из них находится по одному из элитных командоров Дрек\'Тара. Их надо убить. Так ты ускоришь крах обороны клана Северного Волка.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глава 2 – Стылая Кровь и Смотровая башня\r\n\r\nКогда ты разделаешься с первым слоем "артишока", тебе будет открыт второй. Если уничтожить Башни Северного Волка, стоящие у линии фронта, то ослабнут вражеские легионеры и патрули с задних флангов.\r\n\r\nЭти башни сильно укреплены, и в каждой из них находится по одному из элитных командоров Дрек\'Тара. Их надо убить. Так ты ускоришь крах обороны клана Северного Волка.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2782,'Глава 3 – Четыре командора\r\n\r\nЕсли ты следовал мудрым советам этого руководства, то сейчас двое из командоров Дрек\'Тара уже мертвы. Так держать, солдат! Решимость врага уже пошатнулась. Теперь нужно окончательно разделаться с командным звеном неприятеля и убить двух оставшихся командоров.\r\n\r\nКогда будут убиты все четыре командора, в рядах легионеров Северного Волка, охраняющих Крепость Северного Волка наступит сумятица – ведь командовать ими будет некому. Можно брать голыми руками!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глава 3 – Четыре командора\r\n\r\nЕсли ты следовал мудрым советам этого руководства, то сейчас двое из командоров Дрек\'Тара уже мертвы. Так держать, солдат! Решимость врага уже пошатнулась. Теперь нужно окончательно разделаться с командным звеном неприятеля и убить двух оставшихся командоров.\r\n\r\nКогда будут убиты все четыре командора, в рядах легионеров Северного Волка, охраняющих Крепость Северного Волка наступит сумятица – ведь командовать ими будет некому. Можно брать голыми руками!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2783,'Глава 4 – Восточная и Западная башни Северного Волка\r\n\r\nТеперь от победы тебя отделает только один рубеж – самые преданные и сильные стражи Дрек\'Тара, стражи Северного Волка.\r\n\r\nИх присылают из резервных отрядов, что содержатся в Восточной и Западной Башнях Северного Волка. Уничтожь эти башни – и увидишь, как позорно побегут оставшиеся Стражи.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глава 4 – Восточная и Западная башни Северного Волка\r\n\r\nТеперь от победы тебя отделает только один рубеж – самые преданные и сильные стражи Дрек\'Тара, стражи Северного Волка.\r\n\r\nИх присылают из резервных отрядов, что содержатся в Восточной и Западной Башнях Северного Волка. Уничтожь эти башни – и увидишь, как позорно побегут оставшиеся Стражи.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2784,'Эпилог\r\n\r\n"Сдобрить сердцевину артишока маслом с чесноком и майонезом. Запивать блюдо лучше крепким, выдержанным элем."\r\n\r\nТеперь Дрек\'Тар совсем один, если не считать двух болванов-подопечных по обе руки. Захвати Приют Северного Волка и убей Дрек\'Тара. Когда Генерал падет, его земли наконец-то перейдут к их истинному владельцу – Грозовой Вершине.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эпилог\r\n\r\n"Сдобрить сердцевину артишока маслом с чесноком и майонезом. Запивать блюдо лучше крепким, выдержанным элем."\r\n\r\nТеперь Дрек\'Тар совсем один, если не считать двух болванов-подопечных по обе руки. Захвати Приют Северного Волка и убей Дрек\'Тара. Когда Генерал падет, его земли наконец-то перейдут к их истинному владельцу – Грозовой Вершине.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2785,'Мы призываем тебя, Занза Зулдазара.\r\n\r\nБлагослови тех, что помощи твоей ищут, Лоа Занза. Благослови тех, что хотят помочь Зандаларскому\r\nнароду.\r\n\r\nПомоги нам в эти трудные времена. Помоги нам, Лоа. Дай нам силу сразить врагов наших. Дай нам силу сокрушить Кровавого Бога еще раз.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы призываем тебя, Занза Зулдазара.\r\n\r\nБлагослови тех, что помощи твоей ищут, Лоа Занза. Благослови тех, что хотят помочь Зандаларскому\r\nнароду.\r\n\r\nПомоги нам в эти трудные времена. Помоги нам, Лоа. Дай нам силу сразить врагов наших. Дай нам силу сокрушить Кровавого Бога еще раз.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2787,'Имя его принесло Свет во тьму Азерота.$B$BДоблесть его победила всякое отчаяние.$B$BСеребряная Длань не могла сделать большего,$B$Bчем дать миру рыцаря, что отдал миру себя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Имя его принесло Свет во тьму Азерота.$B$BДоблесть его победила всякое отчаяние.$B$BСеребряная Длань не могла сделать большего,$B$Bчем дать миру рыцаря, что отдал миру себя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2788,'Он не искал себе почет и славу$B$Bи не хотел сородичами править.$B$BРешил он биться за Лордерон,$B$Bчтоб после уж народ его жил в мире.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Он не искал себе почет и славу$B$Bи не хотел сородичами править.$B$BРешил он биться за Лордерон,$B$Bчтоб после уж народ его жил в мире.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2789,'Рассказ о добродетели его$B$Bсо смертью рыцаря не будет завершен.$B$BЕго мы чтим и воздаем хвалу!$B$BПусть Утер в славе почиет и в Свете!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Рассказ о добродетели его$B$Bсо смертью рыцаря не будет завершен.$B$BЕго мы чтим и воздаем хвалу!$B$BПусть Утер в славе почиет и в Свете!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2790,'Имя его не умрет.$BЖертва его всегда$Bнам будет указывать путь.$B$BОковы, что крепко держали$Bчесть, отвагу и смелость,$Bнас не стесняют теперь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Имя его не умрет.$BЖертва его всегда$Bнам будет указывать путь.$B$BОковы, что крепко держали$Bчесть, отвагу и смелость,$Bнас не стесняют теперь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2791,'Слышишь ли ты его крик?$BКлич боевой за Орду:$BПобеда или смерть!$B$BДолжны мы вовек запомнить,$Bкак отважно презрел он смерть.$BМечты его воплотились.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Слышишь ли ты его крик?$BКлич боевой за Орду:$BПобеда или смерть!$B$BДолжны мы вовек запомнить,$Bкак отважно презрел он смерть.$BМечты его воплотились.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2792,'Здесь опасность кругом!$BЖаждут враги заковать$Bнас обратно в оковы.$B$BПомни же в яростной битве$Bо том, кто свой выполнил долг.$BАдский Крик вечно живет!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Здесь опасность кругом!$BЖаждут враги заковать$Bнас обратно в оковы.$B$BПомни же в яростной битве$Bо том, кто свой выполнил долг.$BАдский Крик вечно живет!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2807,'День 1\r\nНаше странствие закончено. Мы наконец-то дошли до Силитуса, где и свяжемся с ними. Мы пришли сюда из самых разных мест, чтобы сообща свершить великое дело.\r\n\r\nВоздух весь наполнен предвкушениями. Завтра мы целиком посвятим себя строительству сооружения, которое позволит нам общаться с НИМИ.\r\n\r\nЗавтра мы будем возводить ветровой камень!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 1\r\nНаше странствие закончено. Мы наконец-то дошли до Силитуса, где и свяжемся с ними. Мы пришли сюда из самых разных мест, чтобы сообща свершить великое дело.\r\n\r\nВоздух весь наполнен предвкушениями. Завтра мы целиком посвятим себя строительству сооружения, которое позволит нам общаться с НИМИ.\r\n\r\nЗавтра мы будем возводить ветровой камень!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2808,'День 2\r\nМы долго спорили о том, где следует возводить Ветровой Камень. Даже мудрейшие из нас не могут сказать наверняка, что за место описано в древнем пророчестве.\r\n\r\nЯ примкнул к тем, кто считает, что строить надо на севере, и время несомненно докажет нашу правоту. Доводы, что энергетические линии якобы пересекаются там под плохим углом, наивны и глупы. \r\n\r\nМы уже собираем с великой поспешностью все, что нужно для строительства.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 2\r\nМы долго спорили о том, где следует возводить Ветровой Камень. Даже мудрейшие из нас не могут сказать наверняка, что за место описано в древнем пророчестве.\r\n\r\nЯ примкнул к тем, кто считает, что строить надо на севере, и время несомненно докажет нашу правоту. Доводы, что энергетические линии якобы пересекаются там под плохим углом, наивны и глупы. \r\n\r\nМы уже собираем с великой поспешностью все, что нужно для строительства.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2809,'День 15\r\nНаше упорство себя оправдало. Мы первыми завершили установку Ветрового Камня. Останься с нами другие глупцы, на это ушло бы меньше недели!\r\n\r\nЗавтра мы приступим к ритуалам призыва самого Барона Казума. Он потребовал, чтобы его вызвали первым, и перечить ему мы не можем, поскольку в гневе он скор на расправу.\r\n\r\nЯ надеюсь, что он будет очень нами доволен.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День 15\r\nНаше упорство себя оправдало. Мы первыми завершили установку Ветрового Камня. Останься с нами другие глупцы, на это ушло бы меньше недели!\r\n\r\nЗавтра мы приступим к ритуалам призыва самого Барона Казума. Он потребовал, чтобы его вызвали первым, и перечить ему мы не можем, поскольку в гневе он скор на расправу.\r\n\r\nЯ надеюсь, что он будет очень нами доволен.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2810,'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nПоиски предателя Ортелла продвигаются наилучшим образом. Наши разведчики узнали, что он скрывается в лабиринте пещер Западного Края.\r\n\r\nПредательство Ортелла прощать нельзя, а его побег ставит под угрозу всю нашу организацию.\r\n\r\nЛюбой, кто станет утаивать сведения о местонахождении Ортелла, будет должным образом наказан.\r\n\r\n-Эверан Сумеречный Владыка') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nПоиски предателя Ортелла продвигаются наилучшим образом. Наши разведчики узнали, что он скрывается в лабиринте пещер Западного Края.\r\n\r\nПредательство Ортелла прощать нельзя, а его побег ставит под угрозу всю нашу организацию.\r\n\r\nЛюбой, кто станет утаивать сведения о местонахождении Ортелла, будет должным образом наказан.\r\n\r\n-Эверан Сумеречный Владыка',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2811,'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nВ связи с текущим положением дел в Силитусе, всякое распространение текстов Истинно Верующего отныне должно проводиться в сопровождении не менее чем четырех вооруженных бойцов Сумеречного Молота.\r\n\r\nВсе, уличенные в нарушении этого нового приказа, будут без промедления наказаны.\r\n\r\n-Д\'Сак Сумеречный Владыка.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nВ связи с текущим положением дел в Силитусе, всякое распространение текстов Истинно Верующего отныне должно проводиться в сопровождении не менее чем четырех вооруженных бойцов Сумеречного Молота.\r\n\r\nВсе, уличенные в нарушении этого нового приказа, будут без промедления наказаны.\r\n\r\n-Д\'Сак Сумеречный Владыка.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2812,'Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nНиже описан порядок применения Ветровых Камней для связи с нашими повелителями из Совета Бездны.\r\n\r\nВсякое неподобающее использование Ветровых Камней будет караться самым жестоким образом.\r\n\r\n-Хранитель Хавунт из культа Сумеречного Молота') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Для немедленного распространения среди всех членов Сумеречного Молота.\r\n\r\nНиже описан порядок применения Ветровых Камней для связи с нашими повелителями из Совета Бездны.\r\n\r\nВсякое неподобающее использование Ветровых Камней будет караться самым жестоким образом.\r\n\r\n-Хранитель Хавунт из культа Сумеречного Молота',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2813,'Храмовники Бездны\r\n\r\nТебе, как новичку, разрешается обращаться к Храмовникам Бездны для проведения обычных ритуалов. Не забывай надевать подобающее убранство при обращении с Ветровыми Камнями, чтобы на тебя не подействовали наши защитные чары.\r\n\r\nЕсли вдруг случится нечто непредвиденное в отсутствие старших, тебе разрешается вызвать Храмовника Бездны.\r\n\r\nЗа подробностями о проведении соответствующих ритуалов призыва обращайся к выпуску Истинно Верующего за прошлый месяц.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Храмовники Бездны\r\n\r\nТебе, как новичку, разрешается обращаться к Храмовникам Бездны для проведения обычных ритуалов. Не забывай надевать подобающее убранство при обращении с Ветровыми Камнями, чтобы на тебя не подействовали наши защитные чары.\r\n\r\nЕсли вдруг случится нечто непредвиденное в отсутствие старших, тебе разрешается вызвать Храмовника Бездны.\r\n\r\nЗа подробностями о проведении соответствующих ритуалов призыва обращайся к выпуску Истинно Верующего за прошлый месяц.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2814,'Герцоги Бездны\r\n\r\nТолько послушникам, имеющим медальон статуса, разрешено обращаться к Герцогам Бездны. Медальоны статуса могут использовать лишь те, кому они были выданы изначально.\r\n\r\nЧлены Сумеречного Молота, замешанные в неправомерном общении с Герцогами бездны либо в использовании без разрешения медальонов статуса будут наказаны мной лично.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Герцоги Бездны\r\n\r\nТолько послушникам, имеющим медальон статуса, разрешено обращаться к Герцогам Бездны. Медальоны статуса могут использовать лишь те, кому они были выданы изначально.\r\n\r\nЧлены Сумеречного Молота, замешанные в неправомерном общении с Герцогами бездны либо в использовании без разрешения медальонов статуса будут наказаны мной лично.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2815,'Высокий Совет Лордов Бездны\r\n\r\nОбращаться к Принцу Скальдреноксу, Верховному маршалу Круговерту, Барону Казуму или Лорду Скволу позволено лишь Сумеречным Лордом.\r\n\r\nНи при каких обстоятельствах нижние чины Сумеречного Молота не могут начать общение с Высоким Советом. Любой чужак, застигнутый за использованием с этой целью ветровых камней, будет испепелен на месте.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Высокий Совет Лордов Бездны\r\n\r\nОбращаться к Принцу Скальдреноксу, Верховному маршалу Круговерту, Барону Казуму или Лорду Скволу позволено лишь Сумеречным Лордом.\r\n\r\nНи при каких обстоятельствах нижние чины Сумеречного Молота не могут начать общение с Высоким Советом. Любой чужак, застигнутый за использованием с этой целью ветровых камней, будет испепелен на месте.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2817,'Дела культа, том 127\r\n\r\nВоистину, это счастливый день! Нас испытали в Силитусе, и мы прошли испытание!\r\n\r\nРассказы о разгроме нашего северного лагеря могут наполнить страхом сердца неверных, но для нас эта резня эта не должна быть несчастьем, нет!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дела культа, том 127\r\n\r\nВоистину, это счастливый день! Нас испытали в Силитусе, и мы прошли испытание!\r\n\r\nРассказы о разгроме нашего северного лагеря могут наполнить страхом сердца неверных, но для нас эта резня эта не должна быть несчастьем, нет!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2819,'Дела культа, том 233\r\n\r\nНам снова выпала редкая возможность, о братья мои и сестры! Круг Кенария, мерзостный культ почитателей природы, посылает на нас своих приспешников. Они хотят воспрепятствовать нам добыть красные камни-приманки. Мы не можем этого допустить!\r\n\r\nКрасные камни очень нужны нашим новым союзникам. Нельзя, чтобы шавки из Круга Кенария добились своего. Держитесь, преданные друзья мои. Держитесь!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дела культа, том 233\r\n\r\nНам снова выпала редкая возможность, о братья мои и сестры! Круг Кенария, мерзостный культ почитателей природы, посылает на нас своих приспешников. Они хотят воспрепятствовать нам добыть красные камни-приманки. Мы не можем этого допустить!\r\n\r\nКрасные камни очень нужны нашим новым союзникам. Нельзя, чтобы шавки из Круга Кенария добились своего. Держитесь, преданные друзья мои. Держитесь!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2820,'Как узнать, что они любят нас?\r\n\r\nНекоторым непонятно, как могут Древние Боги и их приспешники любить нас. Не они ли нас убивают? Не они ли причиняют всем нам боль и страдания? Разве есть в сердцах таких жестоких существ место любви?\r\n\r\nОтвет на эти вопросы очень прост. Так прост, что его излишне даже произносить.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Как узнать, что они любят нас?\r\n\r\nНекоторым непонятно, как могут Древние Боги и их приспешники любить нас. Не они ли нас убивают? Не они ли причиняют всем нам боль и страдания? Разве есть в сердцах таких жестоких существ место любви?\r\n\r\nОтвет на эти вопросы очень прост. Так прост, что его излишне даже произносить.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2821,'Вера. Вера – вот наш неиссякаемый источник радости порабощения. Вера согреет нас в самые холодные ночи Силитуса. Вера дарует нам благодать Господ, когда настанут Последние Дни.\r\n\r\nВера спасет нас.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вера. Вера – вот наш неиссякаемый источник радости порабощения. Вера согреет нас в самые холодные ночи Силитуса. Вера дарует нам благодать Господ, когда настанут Последние Дни.\r\n\r\nВера спасет нас.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2829,'Дорогой дневник, сегодня мой злейший враг Нарайн Причудень пытался меня обмануть, послав вместо себя друзей на казнь. На СВОЮ казнь. Ты можешь в это поверить?$B$BЯ, несмотря ни на что, разрабатывал свой дьявольский план, чтобы выманить его из этой проклятой хижины, а он выкинул такое! Да что там… Больше писать не могу, слишком зол. Продолжу позже.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, сегодня мой злейший враг Нарайн Причудень пытался меня обмануть, послав вместо себя друзей на казнь. На СВОЮ казнь. Ты можешь в это поверить?$B$BЯ, несмотря ни на что, разрабатывал свой дьявольский план, чтобы выманить его из этой проклятой хижины, а он выкинул такое! Да что там… Больше писать не могу, слишком зол. Продолжу позже.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2830,'Дорогой дневник, написав последнюю запись, я вышел из убежища в сильном гневе. Ох, как же я был зол. Хочу, придумать для своих прислужников новую униформу, что отражала бы мою ярость. Мне уже лучше, но чего-то не хватает. Скоро вернусь…') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, написав последнюю запись, я вышел из убежища в сильном гневе. Ох, как же я был зол. Хочу, придумать для своих прислужников новую униформу, что отражала бы мою ярость. Мне уже лучше, но чего-то не хватает. Скоро вернусь…',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2831,'Дорогой дневник, теперь я в порядке. Я бил своего прислужника до тех пор, пока он не начал рыдать, словно девчонка.$B$BХм… Что-то на душе тоскливо. Минутку! Демоны! Я же ЗЛОЙ гений! Злой, понимаешь? Как я в себе разочарован. Скоро вернусь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, теперь я в порядке. Я бил своего прислужника до тех пор, пока он не начал рыдать, словно девчонка.$B$BХм… Что-то на душе тоскливо. Минутку! Демоны! Я же ЗЛОЙ гений! Злой, понимаешь? Как я в себе разочарован. Скоро вернусь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2832,'Дорогой дневник, я обнял прислужника и сказал, что очень им доволен. Теперь мне лучше. Только никому ни слова, дневничок.$B$BТак о чем я? Ах, да, НАРАЙН! Р-р-р!!! Ненавижу его. Ведь это он так выделывался на каждом экзамене, когда мы учились в Гномреганском Институте Механики.$B$BОтчислили меня, значит? Гномреган, насколько мне известно, получил по заслугам!$B$BНа сегодня все. Спокойной ночи, дневник!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, я обнял прислужника и сказал, что очень им доволен. Теперь мне лучше. Только никому ни слова, дневничок.$B$BТак о чем я? Ах, да, НАРАЙН! Р-р-р!!! Ненавижу его. Ведь это он так выделывался на каждом экзамене, когда мы учились в Гномреганском Институте Механики.$B$BОтчислили меня, значит? Гномреган, насколько мне известно, получил по заслугам!$B$BНа сегодня все. Спокойной ночи, дневник!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2833,'Дорогой дневник, наверное, я старею. Я совершенно забыл, что говорил тебе о Нарайне и его обмане. Как бы то ни было, я так разозлился, когда увидел вместо самого Нарайна его копию, что приказал Номеру Два умертвить глупца!$B$BПотом я сел в свой ветролет и начал вырывать страницы из его драгоценной, глупой, идиотской книге на драконьем. Что за бахвальство? Кто сейчас читает на драконьем? Как я его ненавижу!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, наверное, я старею. Я совершенно забыл, что говорил тебе о Нарайне и его обмане. Как бы то ни было, я так разозлился, когда увидел вместо самого Нарайна его копию, что приказал Номеру Два умертвить глупца!$B$BПотом я сел в свой ветролет и начал вырывать страницы из его драгоценной, глупой, идиотской книге на драконьем. Что за бахвальство? Кто сейчас читает на драконьем? Как я его ненавижу!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2834,'Дорогой дневник, прости, я заснул. Когда я в ярости летал и разбрасывал листы из этой глупой книги, то увидел под собой в Теснине Зловещего Шепота демона и решил сделать из страниц первой главы магическое торнадо, чтобы разорвать его тело на миллион кусочков! Я слово заново родился. Магия + бумага = веселье.$B$BЭтот случай меня изрядно развеселил, и я решил полететь в Восточные королевства. Первой моей остановкой были Огненные Недра. Нарайн постоянно о них твердил! "А вот когда я был в Огненных Недрах, да в Рагнаросе..."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогой дневник, прости, я заснул. Когда я в ярости летал и разбрасывал листы из этой глупой книги, то увидел под собой в Теснине Зловещего Шепота демона и решил сделать из страниц первой главы магическое торнадо, чтобы разорвать его тело на миллион кусочков! Я слово заново родился. Магия + бумага = веселье.$B$BЭтот случай меня изрядно развеселил, и я решил полететь в Восточные королевства. Первой моей остановкой были Огненные Недра. Нарайн постоянно о них твердил! "А вот когда я был в Огненных Недрах, да в Рагнаросе..."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2835,'И знаешь что? Если уж ему так там нравится, пусть попробует восстановить главу из книги, отправившись в Огненные Недра и покопавшись в куче пепла! Ха!$B$BПока я там летал, обнаружил пресмыкающихся механиков в Лаборатории Виктора Нефариуса – им могут пригодиться Драконьи штуки. Сбросить бомбы!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И знаешь что? Если уж ему так там нравится, пусть попробует восстановить главу из книги, отправившись в Огненные Недра и покопавшись в куче пепла! Ха!$B$BПока я там летал, обнаружил пресмыкающихся механиков в Лаборатории Виктора Нефариуса – им могут пригодиться Драконьи штуки. Сбросить бомбы!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2836,'Это стало неплохой забавой. Мне так понравилось рвать проклятую книгу на куски!$B$BДальше уже дело пошло просто.$B$BОдна глава отправилась в Подгород, обиталище зловонных мертвецов и место, где я пробовал самый, пожалуй, лучший чили. Другая – в Штормград, столицу сыра. Дневник, а ты не пробовал заедать сыром из Штормграда, чили из Подгорода? Эй? Там, никак, тревога.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Это стало неплохой забавой. Мне так понравилось рвать проклятую книгу на куски!$B$BДальше уже дело пошло просто.$B$BОдна глава отправилась в Подгород, обиталище зловонных мертвецов и место, где я пробовал самый, пожалуй, лучший чили. Другая – в Штормград, столицу сыра. Дневник, а ты не пробовал заедать сыром из Штормграда, чили из Подгорода? Эй? Там, никак, тревога.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2837,'Я в это время уже начал уставать – и потому развернул ветролет и направился домой, но по пути сделал еще две остановки. Я пролетел мимо Владыки Каззака и его демонов в Гниющем Шраме (он этого терпеть не может) и сбросил груз в трубу Ониксии.$B$BУстал. Пойду спать.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я в это время уже начал уставать – и потому развернул ветролет и направился домой, но по пути сделал еще две остановки. Я пролетел мимо Владыки Каззака и его демонов в Гниющем Шраме (он этого терпеть не может) и сбросил груз в трубу Ониксии.$B$BУстал. Пойду спать.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2856,'<HTML>\r\n<BODY>\r\n<H1 align="center"> ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Рыцарь-защитник</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Рыцарь-капитан</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Рыцарь-лейтенант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\r\n<P align="right">Рыцарь</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center"> ОФИЦЕРСКИЕ ЗВАНИЯ АЛЬЯНСА</H1><BR/>\r\n<P align="center">Часть 2</P>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank09" align="left"/><BR/>\r\n<P align="right">Рыцарь-защитник</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank08" align="left"/><BR/>\r\n<P align="right">Рыцарь-капитан</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank07" align="left"/><BR/>\r\n<P align="right">Рыцарь-лейтенант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank06" align="left"/><BR/>\r\n<P align="right">Рыцарь</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2857,'<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Старший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Младший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Капрал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Рядовой</P><BR/><BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">РЯДОВОЙ И СЕРЖАНТСКИЙ СОСТАВ АЛЬЯНСА</H1><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank05" align="left"/><BR/>\r\n<P align="right">Старший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank04" align="left"/><BR/>\r\n<P align="right">Сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank03" align="left"/><BR/>\r\n<P align="right">Младший сержант</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank02" align="left"/><BR/>\r\n<P align="right">Капрал</P><BR/><BR/>\r\n<IMG src="Interface\\PvPRankBadges\\PvPRank01" align="left"/><BR/>\r\n<P align="right">Рядовой</P><BR/><BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2858,'<HTML>\n<BODY>\n<H1 align="center">\nЭнтони Рэй Старк\n</H1>\n<H2 align="center">\n1961 – 2005\n</H2>\n</BODY>\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\n<BODY>\n<H1 align="center">\nЭнтони Рэй Старк\n</H1>\n<H2 align="center">\n1961 – 2005\n</H2>\n</BODY>\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2872,'Обращаюсь ко всем мужчинам и женщинам, способным держать в руках оружие:\r\n\r\nПлеть вновь объединила свои силы, и мы вместе должны дать ей достойный отпор, отбросив в сторону все наши разногласия.\r\n\r\nКаждый, кто готов сражаться, должен прийти на сбор к часовне Последней Надежды, что в Восточных чумных землях. Вместе мы победим.\r\n\r\nХранитель архивов\r\nСеребряного Рассвета') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Обращаюсь ко всем мужчинам и женщинам, способным держать в руках оружие:\r\n\r\nПлеть вновь объединила свои силы, и мы вместе должны дать ей достойный отпор, отбросив в сторону все наши разногласия.\r\n\r\nКаждый, кто готов сражаться, должен прийти на сбор к часовне Последней Надежды, что в Восточных чумных землях. Вместе мы победим.\r\n\r\nХранитель архивов\r\nСеребряного Рассвета',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2878,'Моя дорогая Эмили!$b$bНесколько дней назад мы снялись с лагеря в этом покинутом Светом месте и по приказу короля отправились домой. Даже эти мрачные пейзажи не могли омрачить моей радости, ибо я знал, что после тяжелого путешествия ты наконец-то сможешь заключить меня в обьятья.$b$bСегодня мы добрались до берега, но обнаружили, что от наших кораблей остались одни лишь дымящиеся угли; лишенные единственного шанса вернуться домой, мы вынуждены идти в самое сердце этой бескрайней пустыни.$b$bЭмили, ради тебя я отправлялся в самые дальние уголки этого мира, а теперь… теперь я всей душой желаю повернуть время вспять и вновь оказаться рядом с тобой.$b$bКаждое мгновение я думаю о тебе. Любимая, мысли о тебе согревают мою душу в этом ледяном краю, и никто никогда не отнимет их у меня.$b$bМаксвелл') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Моя дорогая Эмили!$b$bНесколько дней назад мы снялись с лагеря в этом покинутом Светом месте и по приказу короля отправились домой. Даже эти мрачные пейзажи не могли омрачить моей радости, ибо я знал, что после тяжелого путешествия ты наконец-то сможешь заключить меня в обьятья.$b$bСегодня мы добрались до берега, но обнаружили, что от наших кораблей остались одни лишь дымящиеся угли; лишенные единственного шанса вернуться домой, мы вынуждены идти в самое сердце этой бескрайней пустыни.$b$bЭмили, ради тебя я отправлялся в самые дальние уголки этого мира, а теперь… теперь я всей душой желаю повернуть время вспять и вновь оказаться рядом с тобой.$b$bКаждое мгновение я думаю о тебе. Любимая, мысли о тебе согревают мою душу в этом ледяном краю, и никто никогда не отнимет их у меня.$b$bМаксвелл',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2880,'Милая Ройбен!\r\n\r\nЗнаю, скорее всего ты никогда не получишь это письмо, но мне просто нечем больше заняться. Мне надо как-то отвлечься от этих чудовищных звуков, доносящихся из-за крепостных стен, окружающих Дольный Очаг. Нежить окружила нашу деревню и не собирается отступать, а нам поручено защищать жителей и ждать подкрепления.\r\n\r\nВ последнем сражении я сломал ногу и теперь совершенно беспомощен; мне остается только сидеть и ждать, когда наша оборона падет. Вокруг только стоны и смерть… это ужасно. Страх повсюду, даже в воздухе.\r\n\r\nНа нашей стороне сражается принц Артас. Если бы не он, нам бы уже давно пришел конец. Его преданность и любовь к родине завораживает; я с радостью буду сражаться и погибну рядом с ним.\r\n\r\nБой идет уже у наших ворот, и я не могу больше сидеть тут, жалея сломанную ногу. Нам нужен каждый, кто может держать в руках меч. Надеюсь, эти строки ты будешь читать в лучшие времена.\r\n\r\nТвой друг,\r\nЛеагрем') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Милая Ройбен!\r\n\r\nЗнаю, скорее всего ты никогда не получишь это письмо, но мне просто нечем больше заняться. Мне надо как-то отвлечься от этих чудовищных звуков, доносящихся из-за крепостных стен, окружающих Дольный Очаг. Нежить окружила нашу деревню и не собирается отступать, а нам поручено защищать жителей и ждать подкрепления.\r\n\r\nВ последнем сражении я сломал ногу и теперь совершенно беспомощен; мне остается только сидеть и ждать, когда наша оборона падет. Вокруг только стоны и смерть… это ужасно. Страх повсюду, даже в воздухе.\r\n\r\nНа нашей стороне сражается принц Артас. Если бы не он, нам бы уже давно пришел конец. Его преданность и любовь к родине завораживает; я с радостью буду сражаться и погибну рядом с ним.\r\n\r\nБой идет уже у наших ворот, и я не могу больше сидеть тут, жалея сломанную ногу. Нам нужен каждый, кто может держать в руках меч. Надеюсь, эти строки ты будешь читать в лучшие времена.\r\n\r\nТвой друг,\r\nЛеагрем',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2881,'$b$bЛюбезная Гелиана!$b$bЖаль вас разочаровывать, но я, Варгус, все еще пребываю в добром здравии. Мне надоело быть посмешищем для всех и бродить по деревням в этих шутовских доспехах.$b$bТеперь нам приказали отправиться в Андорал за зерном или еще за чем-то там. Скажите, пожалуйста, какое мне дело до зерна в Андорале? Да вся эта служба в армии – просто бред сумасшедшего.$b$bБудьте уверены, тетя Гелиана, что я вернусь, и ваше наследство будет моим; даже если я буду истекать кровью и умирать от голода, моя злоба не даст мне умереть.$b$bВаргус$b$b') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','$b$bЛюбезная Гелиана!$b$bЖаль вас разочаровывать, но я, Варгус, все еще пребываю в добром здравии. Мне надоело быть посмешищем для всех и бродить по деревням в этих шутовских доспехах.$b$bТеперь нам приказали отправиться в Андорал за зерном или еще за чем-то там. Скажите, пожалуйста, какое мне дело до зерна в Андорале? Да вся эта служба в армии – просто бред сумасшедшего.$b$bБудьте уверены, тетя Гелиана, что я вернусь, и ваше наследство будет моим; даже если я буду истекать кровью и умирать от голода, моя злоба не даст мне умереть.$b$bВаргус$b$b',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2882,'Моя дорогая Амелия!$b$bТо, что я увидел сегодня, навсегда останется в моей памяти.$b$bСтратхольм охвачен огнем… и в этом наша вина.$b$bСегодня ночью мы вышли на городские улицы, и наш принц велел нам врываться в дома мирных жителей и… убивать их, пока они спят. Принц Артас сказал, что они поражены чумой и их нужно лишить жизни, пока они не сделали то же самое с нами.$b$bНачалась резня. Сотни людей погибли от рук тех, кто поклялся их защищать. Я просто не мог на это смотреть и сбежал.$b$bДа, я теперь дезертир, но у меня не поднялась рука совершить столь ужасное злодеяние. Смотря на лица этих несчастных, обреченных на смерть горожан, я видел тебя… и наших детей… И если противостоять подобной жестокости – предательство, значит так тому и быть.$b$bНадеюсь, мне удастся вернуться к тебе вовремя, но на дорогах сейчас небезопасно. Передай детям, что я люблю их.$b$bДжеймс$b$b') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Моя дорогая Амелия!$b$bТо, что я увидел сегодня, навсегда останется в моей памяти.$b$bСтратхольм охвачен огнем… и в этом наша вина.$b$bСегодня ночью мы вышли на городские улицы, и наш принц велел нам врываться в дома мирных жителей и… убивать их, пока они спят. Принц Артас сказал, что они поражены чумой и их нужно лишить жизни, пока они не сделали то же самое с нами.$b$bНачалась резня. Сотни людей погибли от рук тех, кто поклялся их защищать. Я просто не мог на это смотреть и сбежал.$b$bДа, я теперь дезертир, но у меня не поднялась рука совершить столь ужасное злодеяние. Смотря на лица этих несчастных, обреченных на смерть горожан, я видел тебя… и наших детей… И если противостоять подобной жестокости – предательство, значит так тому и быть.$b$bНадеюсь, мне удастся вернуться к тебе вовремя, но на дорогах сейчас небезопасно. Передай детям, что я люблю их.$b$bДжеймс$b$b',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2883,'Самла!$b$bПринц Артас ведет нас все дальше и дальше на север, и у меня на сердце становится совсем тяжело. Когда-то в этом молодом паладине ярко сиял Свет, а теперь я чувствую, как его поглощает тьма. От его былого рвения и бесстрашия не осталось и следа, его преследует что-то ужасное; как бы мне хотелось знать, что это…$b$bСкоро мы выберемся из этой ледяной пустыни. Многие солдаты замерзли насмерть и пали от когтей местных хищников, но Артас говорит, что если наши поиски увенчаются успехом, всему этому кошмару придет конец. Но его слова не придали мне никакой уверенности: после окончания речи на лице Артаса появилась мрачная улыбка, от которой у меня на душе стало еще холоднее.$b$bМолись за нас, Самла, и за наш мир,$b$bТоргал$b$b') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Самла!$b$bПринц Артас ведет нас все дальше и дальше на север, и у меня на сердце становится совсем тяжело. Когда-то в этом молодом паладине ярко сиял Свет, а теперь я чувствую, как его поглощает тьма. От его былого рвения и бесстрашия не осталось и следа, его преследует что-то ужасное; как бы мне хотелось знать, что это…$b$bСкоро мы выберемся из этой ледяной пустыни. Многие солдаты замерзли насмерть и пали от когтей местных хищников, но Артас говорит, что если наши поиски увенчаются успехом, всему этому кошмару придет конец. Но его слова не придали мне никакой уверенности: после окончания речи на лице Артаса появилась мрачная улыбка, от которой у меня на душе стало еще холоднее.$b$bМолись за нас, Самла, и за наш мир,$b$bТоргал$b$b',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2884,'Дорогая Памела!$b$bЗавтра мы доберемся до Андорала, и, боюсь, я не буду тебе больше писать. Нежить не знает усталости, а мы… мы – всего лишь люди. Нам их не победить. Но не надо печалиться, любовь моя: хотя нам и суждено погибнуть, наша надежда остается. Свет победит!$b$bИ мне греет душу мысль о том, что, когда наша защита падет и враг сокрушит нас, страх смерти не будет терзать меня. Все мои мысли будут о тебе, дорогая, и моя душа обретет покой.$b$bКристоф') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогая Памела!$b$bЗавтра мы доберемся до Андорала, и, боюсь, я не буду тебе больше писать. Нежить не знает усталости, а мы… мы – всего лишь люди. Нам их не победить. Но не надо печалиться, любовь моя: хотя нам и суждено погибнуть, наша надежда остается. Свет победит!$b$bИ мне греет душу мысль о том, что, когда наша защита падет и враг сокрушит нас, страх смерти не будет терзать меня. Все мои мысли будут о тебе, дорогая, и моя душа обретет покой.$b$bКристоф',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2885,'Приветствую тебя, <имя>. Мне удалось-таки узнать кое-что из той записки.\r\n\r\nО Джеймсе выяснилось немногое. Но зато о семье Амелии мне удалось разузнать больше.\r\n\r\nОна и ее дети не пережили войну, а вот ее брат, Александр Кальдер, выжил; найти его ты можешь в Заброшенном гроте, что в Стальгорне; там он изучает зловещую магию Пылающего легиона.\r\n\r\nЕще она близко общалась с сестрой, Дези Холодная, которая теперь живет в Оргриммаре и занимается проблемой Низины Арати.\r\n\r\nКогда будешь поблизости, найди одного из них. Уверен, им будет интересно узнать об Амелии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую тебя, <имя>. Мне удалось-таки узнать кое-что из той записки.\r\n\r\nО Джеймсе выяснилось немногое. Но зато о семье Амелии мне удалось разузнать больше.\r\n\r\nОна и ее дети не пережили войну, а вот ее брат, Александр Кальдер, выжил; найти его ты можешь в Заброшенном гроте, что в Стальгорне; там он изучает зловещую магию Пылающего легиона.\r\n\r\nЕще она близко общалась с сестрой, Дези Холодная, которая теперь живет в Оргриммаре и занимается проблемой Низины Арати.\r\n\r\nКогда будешь поблизости, найди одного из них. Уверен, им будет интересно узнать об Амелии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2886,'Приветствую тебя, $n. Думаю, тебя заинтересуют результаты моего расследования.$b$bОказывается, и у Ройбена, и у Леагрема есть родные. Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами.$b$bБывшую жену Ройбена, Джоанну Вайтхолл, ты найдешь в Квартале Воинов Подгорода; там она проводит большую часть времени. А вот как она воспримет твою новость – это вопрос.$b$bЧто касается Леагрема – у него есть тетя, которая теперь хозяйка сиротского приюта в Штормграде.$b$bКакой бы путь в жизни ты ни $gвыбрал:выбрала;, желаю удачи во всех твоих делах.$b$b') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую тебя, $n. Думаю, тебя заинтересуют результаты моего расследования.$b$bОказывается, и у Ройбена, и у Леагрема есть родные. Советую навестить кого-нибудь из них, даже если они и знают, что случилось с пропавшими солдатами.$b$bБывшую жену Ройбена, Джоанну Вайтхолл, ты найдешь в Квартале Воинов Подгорода; там она проводит большую часть времени. А вот как она воспримет твою новость – это вопрос.$b$bЧто касается Леагрема – у него есть тетя, которая теперь хозяйка сиротского приюта в Штормграде.$b$bКакой бы путь в жизни ты ни $gвыбрал:выбрала;, желаю удачи во всех твоих делах.$b$b',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2887,'$N, надеюсь, это письмо дойдет до тебя. Мне пришлось попотеть, чтобы выяснить хоть что-то об авторах той записки, что ты <обнаружил/обнаружила>.\r\n\r\nОтец Самла возглавляет паломничество верующих отрекшихся и троллей, к Громовому Утесу. Его зовут Майлз Уэльш, а найти его и его друзей-нежить можно на прудах Видений.\r\n\r\nУ Торгала в живых осталась сестра, Элисса Дюма. Насколько мне удалось выяснить, она живет отшельником в Храме Луны в Дарнассе.\r\n\r\nДумаю, тебе стоит навестить кого-нибудь из них, <имя>. Быть может, они не знают о том, что случилось с Торгалом и Самлой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','$N, надеюсь, это письмо дойдет до тебя. Мне пришлось попотеть, чтобы выяснить хоть что-то об авторах той записки, что ты <обнаружил/обнаружила>.\r\n\r\nОтец Самла возглавляет паломничество верующих отрекшихся и троллей, к Громовому Утесу. Его зовут Майлз Уэльш, а найти его и его друзей-нежить можно на прудах Видений.\r\n\r\nУ Торгала в живых осталась сестра, Элисса Дюма. Насколько мне удалось выяснить, она живет отшельником в Храме Луны в Дарнассе.\r\n\r\nДумаю, тебе стоит навестить кого-нибудь из них, <имя>. Быть может, они не знают о том, что случилось с Торгалом и Самлой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2888,'Хранитель передал мне найденное тобой письмо, <имя>, и я хочу сообщить тебе кое-какие новости.\r\n\r\nПоследний оставшийся в живых член семьи "Варгус" находится в Силитусе, в Крепости Кенария. Зовут его Гарон Хатчинс.\r\n\r\nКогда в следующий раз будешь в пустыне, навести его. Ему может быть интересно то, что нам удалось узнать.\r\n') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Хранитель передал мне найденное тобой письмо, <имя>, и я хочу сообщить тебе кое-какие новости.\r\n\r\nПоследний оставшийся в живых член семьи "Варгус" находится в Силитусе, в Крепости Кенария. Зовут его Гарон Хатчинс.\r\n\r\nКогда в следующий раз будешь в пустыне, навести его. Ему может быть интересно то, что нам удалось узнать.\r\n',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2889,'Приветствую. Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты <нашел/нашла> у Плети. Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего.\r\n\r\nСестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте. Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом. Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Приветствую. Мне, наконец, удалось выкроить время, чтобы изучить послание, которое ты <нашел/нашла> у Плети. Это было нелегко, и вот результаты моих трудов – информация о живом родственнике погибшего.\r\n\r\nСестру Максвелла зовут Зарена Кромвинд, она – кузнец в Пиратской бухте. Не знаю, насколько они с братом были близки, но тебе стоит заглянуть к ней, если вдруг окажешься рядом. Сейчас такая информация выясняется очень редко, так что ты можешь сделать доброе дело.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2890,'Мне, наконец, удалось найти кое-какие сведения о солдате, с которым ты сражался. Его родословная сохранилась очень плохо, так что мне пришлось постараться.$b$bПредставляешь, что выяснилось: управляющий Ален в часовне Последней Надежды, оказывается, сын Кристофа! Ты можешь облегчить его боль, если расскажешь, что случилось с его отцом. Так что, если будешь на службе у Серебряного Рассвета, поговори с ним. Сделай доброе дело.$b$b') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мне, наконец, удалось найти кое-какие сведения о солдате, с которым ты сражался. Его родословная сохранилась очень плохо, так что мне пришлось постараться.$b$bПредставляешь, что выяснилось: управляющий Ален в часовне Последней Надежды, оказывается, сын Кристофа! Ты можешь облегчить его боль, если расскажешь, что случилось с его отцом. Так что, если будешь на службе у Серебряного Рассвета, поговори с ним. Сделай доброе дело.$b$b',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2892,'Лежит здесь батрак; он смел очень был. Сражаться хотел, но лишь газы пустил.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лежит здесь батрак; он смел очень был. Сражаться хотел, но лишь газы пустил.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2905,'Вот урна с прахом. Внутри – останки моего рассудка, моей страсти и моего честолюбия. Все это погибло, уничтожило само себя. Пусть все, чья нога ступит на пустынные земли Адского Пламени, помнят этого раба. Он сражался за Альянс, храбро бился за Орду, но отплатили ему за это лишь злостью и жестокостью; все, чем он дорожил, у него отнимали. Пусть те, кто пожинают плоды его стараний, познают его гнев. Быть может, не в этой жизни, но им придется поплатиться за свое бездушие. Клянусь, справедливость восторжествует. Я отомщу за свои страдания.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вот урна с прахом. Внутри – останки моего рассудка, моей страсти и моего честолюбия. Все это погибло, уничтожило само себя. Пусть все, чья нога ступит на пустынные земли Адского Пламени, помнят этого раба. Он сражался за Альянс, храбро бился за Орду, но отплатили ему за это лишь злостью и жестокостью; все, чем он дорожил, у него отнимали. Пусть те, кто пожинают плоды его стараний, познают его гнев. Быть может, не в этой жизни, но им придется поплатиться за свое бездушие. Клянусь, справедливость восторжествует. Я отомщу за свои страдания.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2910,'\r\nСлухи о том, что ночные эльфы помогают дренеям, оказались правдой. Они хотят соорудить новую базу в Лесной Песне, к северу от Сатирнаара. Нам нужно приготовиться к нападению до того, как полная луна озарит своим светом этот никчемный мир. Если мы сейчас сокрушим их, они никогда больше не посмеют топтать наши земли!\r\n\r\nС уважением,\r\n\r\nГорганнон\r\n\r\np.s. – И хватит тратить кровавые чернила на любовные письма моим суккубам! В наши дни непорочные ночные эльфийки – большая редкость.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','\r\nСлухи о том, что ночные эльфы помогают дренеям, оказались правдой. Они хотят соорудить новую базу в Лесной Песне, к северу от Сатирнаара. Нам нужно приготовиться к нападению до того, как полная луна озарит своим светом этот никчемный мир. Если мы сейчас сокрушим их, они никогда больше не посмеют топтать наши земли!\r\n\r\nС уважением,\r\n\r\nГорганнон\r\n\r\np.s. – И хватит тратить кровавые чернила на любовные письма моим суккубам! В наши дни непорочные ночные эльфийки – большая редкость.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2911,'Диатор,\r\n\r\nНадеюсь, это письмо все-таки достигнет тебя. Эти демоны невероятно глупы. Они способны думать лишь о своих когтях, хлыстах и шипах на головах, которыми они то и дело норовят что-нибудь проткнуть. И я не мог положиться на инферналов, иначе бы письмо сгорело.\r\n\r\nКак я скучаю по тем временам, когда мы использовали орков! У них была хоть капля мозгов, и они могли подчиняться приказам. Быть может, нам удастся завладеть несколькими местными рабами?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Диатор,\r\n\r\nНадеюсь, это письмо все-таки достигнет тебя. Эти демоны невероятно глупы. Они способны думать лишь о своих когтях, хлыстах и шипах на головах, которыми они то и дело норовят что-нибудь проткнуть. И я не мог положиться на инферналов, иначе бы письмо сгорело.\r\n\r\nКак я скучаю по тем временам, когда мы использовали орков! У них была хоть капля мозгов, и они могли подчиняться приказам. Быть может, нам удастся завладеть несколькими местными рабами?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2912,'Думаю, пришло время начать завоевание младших рас. Застава Расщепленного Дерева на северо-западе – весьма заманчивая добыча. Нам нужно приготовиться к нападению до того, как полная луна озарит своим светом этот никчемный мир. Если мы сейчас подчиним их себе, они навсегда запомнят, что значило слово \'Орда\' в былые времена.\r\n\r\nГорганнон\r\n\r\np.s. – И хватит тратить кровавые чернила на любовные письма моим суккубам! В наши дни непорочные ночные эльфийки – большая редкость.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Думаю, пришло время начать завоевание младших рас. Застава Расщепленного Дерева на северо-западе – весьма заманчивая добыча. Нам нужно приготовиться к нападению до того, как полная луна озарит своим светом этот никчемный мир. Если мы сейчас подчиним их себе, они навсегда запомнят, что значило слово \'Орда\' в былые времена.\r\n\r\nГорганнон\r\n\r\np.s. – И хватит тратить кровавые чернила на любовные письма моим суккубам! В наши дни непорочные ночные эльфийки – большая редкость.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2913,'На волосок от смерти,$BНеустрашим он был.$BТолпой напали черти,$BНо он их победил!$B$BС той битвы стародавней$BНи меч, ни копий твердь$BДворфа сего славного$BНе сумели одолеть') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','На волосок от смерти,$BНеустрашим он был.$BТолпой напали черти,$BНо он их победил!$B$BС той битвы стародавней$BНи меч, ни копий твердь$BДворфа сего славного$BНе сумели одолеть',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2914,'…но она это уже знала. Она продала свою душу и выбрала жизнь изгоя. Она думала, что месть того стоит.$B$BИ вот, незнакомец предлагает ей вернуть себе доброе имя, и все, что он просит взамен, – довериться ему.$B$B"Я согласна," – сказала Катрейн. "Терять мне уже нечего".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','…но она это уже знала. Она продала свою душу и выбрала жизнь изгоя. Она думала, что месть того стоит.$B$BИ вот, незнакомец предлагает ей вернуть себе доброе имя, и все, что он просит взамен, – довериться ему.$B$B"Я согласна," – сказала Катрейн. "Терять мне уже нечего".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2916,'Вазруден!\r\n\r\nС тех пор как вновь открылся Темный портал, Оплот Чести и Траллмар стали получать значительную поддержку из Азерота. Судя по всему, они готовятся напасть на крепость, но нам еще нужно справиться с Пылающим Легионом. Это никуда не годится!\r\n\r\nНи в коем случае нельзя подвергать опасности операцию в Кузне Крови! Орки Скверны, которых там создают, – залог нашего успеха. Усиль защиту крепости и расставь стражников по всему периметру!\r\n\r\nПоверь, будет лучше, если мне не придется навещать тебя лично.\r\n\r\n-- Иллидан') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вазруден!\r\n\r\nС тех пор как вновь открылся Темный портал, Оплот Чести и Траллмар стали получать значительную поддержку из Азерота. Судя по всему, они готовятся напасть на крепость, но нам еще нужно справиться с Пылающим Легионом. Это никуда не годится!\r\n\r\nНи в коем случае нельзя подвергать опасности операцию в Кузне Крови! Орки Скверны, которых там создают, – залог нашего успеха. Усиль защиту крепости и расставь стражников по всему периметру!\r\n\r\nПоверь, будет лучше, если мне не придется навещать тебя лично.\r\n\r\n-- Иллидан',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2927,'PS: нашему магистру прислали из Запределья ответ на вопрос Тралла. Ответ утвердительный.$B$B<На письме стоит печать Леди Сильваны Ветрокрылой>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','PS: нашему магистру прислали из Запределья ответ на вопрос Тралла. Ответ утвердительный.$B$B<На письме стоит печать Леди Сильваны Ветрокрылой>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2941,'Леди Лиадрин!\r\n\r\nУ нас возникли некоторые проблемы с пойманным существом, и в результате пострадало очень ценное оборудование. Мне удалось восстановить контроль над ним, хоть и немалыми усилиями. Составленный мной рапорт об этом инциденте был направлен верховному магистру Роммату, но он до сих пор мне не ответил. Боюсь, что без некоторых материалов, которые были утрачены, я не смогу продолжать свои исследования, а вы понимаете, насколько они важны для ваших рыцарей.\r\n\r\nНадеюсь, вы сможете помочь мне получить некоторые из материалов, перечисленных ниже. Любая помощь будет принята с благодарностью.\r\n\r\nМагистр Асталор Кровавая Клятва') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Леди Лиадрин!\r\n\r\nУ нас возникли некоторые проблемы с пойманным существом, и в результате пострадало очень ценное оборудование. Мне удалось восстановить контроль над ним, хоть и немалыми усилиями. Составленный мной рапорт об этом инциденте был направлен верховному магистру Роммату, но он до сих пор мне не ответил. Боюсь, что без некоторых материалов, которые были утрачены, я не смогу продолжать свои исследования, а вы понимаете, насколько они важны для ваших рыцарей.\r\n\r\nНадеюсь, вы сможете помочь мне получить некоторые из материалов, перечисленных ниже. Любая помощь будет принята с благодарностью.\r\n\r\nМагистр Асталор Кровавая Клятва',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2942,'* 40 отрезов рунической ткани\r\n* 6 слитков арканита\r\n* 10 солнечников\r\n* 5 темных рун\r\n* 150 золотых') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','* 40 отрезов рунической ткани\r\n* 6 слитков арканита\r\n* 10 солнечников\r\n* 5 темных рун\r\n* 150 золотых',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2975,'Глупый,\r\n\r\nнайди еду. Синие вкусные. Лантрезор говорит, они хорошие. Неси еду Глыбу. Сначала ест Глыб, потом ест глупый. Ясно? Быстро, а то Глыб будет есть тебя.\r\n\r\n-Глыб') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Глупый,\r\n\r\nнайди еду. Синие вкусные. Лантрезор говорит, они хорошие. Неси еду Глыбу. Сначала ест Глыб, потом ест глупый. Ясно? Быстро, а то Глыб будет есть тебя.\r\n\r\n-Глыб',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2979,'Корень олембы довольно часто встречается в лесу Тероккар. Ищи выступающие над землей корни деревьев олембы, из которых этот лес и состоит.\r\n\r\nКлюква растет только в Зангартопи. Ее можно найти возле крепости Анго\'рош, что в северо-западной части болота. Опасайся огров, охраняющих эти ценные ягоды.\r\n\r\nТелаарский папоротник, наверное, самое легкодоступное растение в списке. Его можно найти в котловине Телаари к югу от Гарадара. Листья находятся возле воды. \r\n\r\nПоследнее растение есть только в Острогорье к северу от Зангартопи. Драконий шип растет на вершинах скалистых утесов у входа в ущелья Острогорья. Ты поймешь, о чем я говорю, когда увидишь эти горы: утесы похожи на ряды огромных острых зубов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Корень олембы довольно часто встречается в лесу Тероккар. Ищи выступающие над землей корни деревьев олембы, из которых этот лес и состоит.\r\n\r\nКлюква растет только в Зангартопи. Ее можно найти возле крепости Анго\'рош, что в северо-западной части болота. Опасайся огров, охраняющих эти ценные ягоды.\r\n\r\nТелаарский папоротник, наверное, самое легкодоступное растение в списке. Его можно найти в котловине Телаари к югу от Гарадара. Листья находятся возле воды. \r\n\r\nПоследнее растение есть только в Острогорье к северу от Зангартопи. Драконий шип растет на вершинах скалистых утесов у входа в ущелья Острогорья. Ты поймешь, о чем я говорю, когда увидишь эти горы: утесы похожи на ряды огромных острых зубов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2984,'*В конце невообразимо скучной книги, в которой изложена всякая ученая бессмыслица, на последней странице написано неразборчивым почерком…*\r\n\r\nПростите, шеф. Судя по всему, от Пустоверти скоро ничего не останется. Возможно, взрыв поглотит и все остальное Запределье.\r\n\r\nЯ не уверен на все сто, но, по-моему, во всем виноваты эти эльфы крови с их темными делишками в Манагорнах.\r\n\r\nХорошо, что вы строите эту ракету!\r\n\r\n-- Медноклеппер\r\n\r\np.s. – а в ракете случайно не найдется места для меня? Вам наверняка понадобится хороший пустолог во время путешествия по Круговерти Пустоты!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','*В конце невообразимо скучной книги, в которой изложена всякая ученая бессмыслица, на последней странице написано неразборчивым почерком…*\r\n\r\nПростите, шеф. Судя по всему, от Пустоверти скоро ничего не останется. Возможно, взрыв поглотит и все остальное Запределье.\r\n\r\nЯ не уверен на все сто, но, по-моему, во всем виноваты эти эльфы крови с их темными делишками в Манагорнах.\r\n\r\nХорошо, что вы строите эту ракету!\r\n\r\n-- Медноклеппер\r\n\r\np.s. – а в ракете случайно не найдется места для меня? Вам наверняка понадобится хороший пустолог во время путешествия по Круговерти Пустоты!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2988,'Эта странная, ни на что не похожая вещь, видимо, является специально разработанным устройством.\r\n\r\nСудя по внешнему виду, ей уже кто-то воспользовался.\r\n\r\nА судя по количеству трупов вокруг, ее предназначение далеко не мирное.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эта странная, ни на что не похожая вещь, видимо, является специально разработанным устройством.\r\n\r\nСудя по внешнему виду, ей уже кто-то воспользовался.\r\n\r\nА судя по количеству трупов вокруг, ее предназначение далеко не мирное.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2989,'Командир,\r\n\r\nКод нужно доставить Зулухеду. Он будет охранять его до дальнейших распоряжений.\r\n\r\n-Владыка Иллидан Ярость Бури') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Командир,\r\n\r\nКод нужно доставить Зулухеду. Он будет охранять его до дальнейших распоряжений.\r\n\r\n-Владыка Иллидан Ярость Бури',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2991,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Вольный перевод...</P>\r\n<BR/>\r\n<P>Во имя света, во имя солнечного света,</P>\r\n<P>Дети крови,</P>\r\n<P>Наши враги побеждают.</P>\r\n<P>Дети крови,</P>\r\n<P>Во имя света,</P>\r\n<P>Слабеющие дети крови,</P>\r\n<P>Они побеждают.</P>\r\n<P>О, дети крови,</P>\r\n<P>Во имя солнечного света.</P>\r\n<P>Слабеющие дети крови,</P>\r\n<P>Они побеждают.</P>\r\n<P>О, дети крови,</P>\r\n<P>Во имя солнечного света,</P>\r\n<P>Солнце.</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Вольный перевод...</P>\r\n<BR/>\r\n<P>Во имя света, во имя солнечного света,</P>\r\n<P>Дети крови,</P>\r\n<P>Наши враги побеждают.</P>\r\n<P>Дети крови,</P>\r\n<P>Во имя света,</P>\r\n<P>Слабеющие дети крови,</P>\r\n<P>Они побеждают.</P>\r\n<P>О, дети крови,</P>\r\n<P>Во имя солнечного света.</P>\r\n<P>Слабеющие дети крови,</P>\r\n<P>Они побеждают.</P>\r\n<P>О, дети крови,</P>\r\n<P>Во имя солнечного света,</P>\r\n<P>Солнце.</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2992,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Текст на талассийском...</P>\r\n<BR/>\r\n<P>Анар\'ала, анар\'ала белоре,</P>\r\n<P>Син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала,</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре.</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре,</P>\r\n<P>Белоре.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Текст на талассийском...</P>\r\n<BR/>\r\n<P>Анар\'ала, анар\'ала белоре,</P>\r\n<P>Син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала,</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре.</P>\r\n<P>Шинду син\'дорай,</P>\r\n<P>Шинду фалла на.</P>\r\n<P>Син\'дорай,</P>\r\n<P>Анар\'ала белоре,</P>\r\n<P>Белоре.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2993,'Дорогая советница,\r\n\r\nПривлечь великанов долины Призрачной Луны на нашу сторону – ваша задача. Я не сомневаюсь, что вы с ней справитесь. Используйте ваше эльфийское обаяние, пусть они посмотрят на мир с нашей точки зрения. Если это не сработает, истребите их всех до одного…\r\n\r\n-Владыка Иллидан Ярость Бури') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дорогая советница,\r\n\r\nПривлечь великанов долины Призрачной Луны на нашу сторону – ваша задача. Я не сомневаюсь, что вы с ней справитесь. Используйте ваше эльфийское обаяние, пусть они посмотрят на мир с нашей точки зрения. Если это не сработает, истребите их всех до одного…\r\n\r\n-Владыка Иллидан Ярость Бури',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (2996,'ОТКАЗ ОТ ОТВЕТСТВЕННОСТИ.\r\n\r\nПИЛОТ-ИСПЫТАТЕЛЬ ПОНИМАЕТ И ОСОЗНАЕТ ВОЗМОЖНОСТЬ ТРАВМ, УВЕЧИЙ И СМЕРТИ В РЕЗУЛЬТАТЕ: РАСЩЕПЛЕНИЯ, ЭЛЕКТРИЧЕСКОГО УДАРА, ПОВРЕЖДЕНИЯ ЖИЗНЕННО ВАЖНЫХ ОРГАНОВ ТУПЫМ УДАРОМ, ПОЕДАНИЯ МЕСТНОЙ ФАУНОЙ ИЛИ НАСТУПЛЕНИЯ ПРОСТРАНСТВЕННО-ВРЕМЕННОГО ПАРДОКСА ПРИ ИСПОЛЬЗОВАНИИ КОНДЕНСАТОРИЯ ЗЕФИРА (ДАЛЕЕ "УСТРОЙСТВА"). ТАКИМ ОБРАЗОМ, ПИЛОТ-ИСПЫТАТЕЛЬ ДОБРОВОЛЬНО СОГЛАШАЕТСЯ ВОЙТИ В УСТРОЙСТВО И ВЗЯТЬ НА СЕБЯ УКАЗАННЫЙ ВЫШЕ РИСК.\r\n\r\nПИЛОТ-ИСПЫТАТЕЛЬ ОТКАЗЫВАЕТСЯ ОТ ЛЮБЫХ ПРЕТЕНЗИЙ К ТАЛЛИ БЫСТРОЦАПУ И ЕГО СЕМЬЕ ПО ПОВОДУ ЛЮБЫХ ТРАВМ ИЛИ УЩЕРБА ЗДОРОВЬЮ И В СЛУЧАЕ СМЕРТИ СОГЛАШАЕТСЯ ПЕРЕДАТЬ СВОИ ОСТАНКИ ВО ВЛАДЕНИЕ БЫСТРОЦАПА ДЛЯ ИЗУЧЕНИЯ.\r\n\r\nподпись,\r\nX:___$N') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','ОТКАЗ ОТ ОТВЕТСТВЕННОСТИ.\r\n\r\nПИЛОТ-ИСПЫТАТЕЛЬ ПОНИМАЕТ И ОСОЗНАЕТ ВОЗМОЖНОСТЬ ТРАВМ, УВЕЧИЙ И СМЕРТИ В РЕЗУЛЬТАТЕ: РАСЩЕПЛЕНИЯ, ЭЛЕКТРИЧЕСКОГО УДАРА, ПОВРЕЖДЕНИЯ ЖИЗНЕННО ВАЖНЫХ ОРГАНОВ ТУПЫМ УДАРОМ, ПОЕДАНИЯ МЕСТНОЙ ФАУНОЙ ИЛИ НАСТУПЛЕНИЯ ПРОСТРАНСТВЕННО-ВРЕМЕННОГО ПАРДОКСА ПРИ ИСПОЛЬЗОВАНИИ КОНДЕНСАТОРИЯ ЗЕФИРА (ДАЛЕЕ "УСТРОЙСТВА"). ТАКИМ ОБРАЗОМ, ПИЛОТ-ИСПЫТАТЕЛЬ ДОБРОВОЛЬНО СОГЛАШАЕТСЯ ВОЙТИ В УСТРОЙСТВО И ВЗЯТЬ НА СЕБЯ УКАЗАННЫЙ ВЫШЕ РИСК.\r\n\r\nПИЛОТ-ИСПЫТАТЕЛЬ ОТКАЗЫВАЕТСЯ ОТ ЛЮБЫХ ПРЕТЕНЗИЙ К ТАЛЛИ БЫСТРОЦАПУ И ЕГО СЕМЬЕ ПО ПОВОДУ ЛЮБЫХ ТРАВМ ИЛИ УЩЕРБА ЗДОРОВЬЮ И В СЛУЧАЕ СМЕРТИ СОГЛАШАЕТСЯ ПЕРЕДАТЬ СВОИ ОСТАНКИ ВО ВЛАДЕНИЕ БЫСТРОЦАПА ДЛЯ ИЗУЧЕНИЯ.\r\n\r\nподпись,\r\nX:___$N',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3005,'Дух ястреба\r\n\r\nВ книге очень благосклонно отзываются о ястребе; возможно, он когда-то был в союзе с вороном. Дух сокола – древний символ мести араккоа, поэтому его часто призывали те, кто пострадал от рук злодеев. Если ты пробудишь духа ястреба заклинанием постепенного лечения, он даст тебе свои силы, и враги сами будут получать урон, нападая на тебя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дух ястреба\r\n\r\nВ книге очень благосклонно отзываются о ястребе; возможно, он когда-то был в союзе с вороном. Дух сокола – древний символ мести араккоа, поэтому его часто призывали те, кто пострадал от рук злодеев. Если ты пробудишь духа ястреба заклинанием постепенного лечения, он даст тебе свои силы, и враги сами будут получать урон, нападая на тебя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3006,'Во имя нашего великого владыки… Во славу Иллидана!\r\n\r\nМоргор,\r\n\r\nЯ посылаю вам этого несчастного, чтобы он служил Иллидану. Рыцарем смерти он стать никогда не сможет, но некоторые его навыки могут прийтись вам по душе. Заставьте его подчиняться вам. Сделайте из него настоящего воина Иллидари.\r\n\r\nА если он подведет вас… Если проявит хоть малейшую слабость… Избавьтесь от него. Отправьте его на рудники!\r\n\r\nЛорд Терон Кровожад') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во имя нашего великого владыки… Во славу Иллидана!\r\n\r\nМоргор,\r\n\r\nЯ посылаю вам этого несчастного, чтобы он служил Иллидану. Рыцарем смерти он стать никогда не сможет, но некоторые его навыки могут прийтись вам по душе. Заставьте его подчиняться вам. Сделайте из него настоящего воина Иллидари.\r\n\r\nА если он подведет вас… Если проявит хоть малейшую слабость… Избавьтесь от него. Отправьте его на рудники!\r\n\r\nЛорд Терон Кровожад',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3007,'Не отчаивайся. Твой огр где-то поблизости.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не отчаивайся. Твой огр где-то поблизости.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3008,'Опустите меч, булаву и копье. Кристаллы велели нам решить дело миром.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Опустите меч, булаву и копье. Кристаллы велели нам решить дело миром.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3009,'Выпьешь пива – и все нипочем!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Выпьешь пива – и все нипочем!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3010,'Две головы лучше, чем одна! Потому что у тебя всегда есть рядом друг.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Две головы лучше, чем одна! Потому что у тебя всегда есть рядом друг.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3011,'Мудрость имеет много обличий, но исходит она всегда от кристаллов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мудрость имеет много обличий, но исходит она всегда от кристаллов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3012,'Будь оптимистичнее! При должном воображении жирное брюхо может превратиться в милое пузико.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Будь оптимистичнее! При должном воображении жирное брюхо может превратиться в милое пузико.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3014,'Счастливые числа: 13 9 17 4 n') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Счастливые числа: 13 9 17 4 n',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3015,'Твоя любовь к танцам многих веселит.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Твоя любовь к танцам многих веселит.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3016,'Ты $gособенный:особенная;, и неважно, что говорят тебе друзья, родственники, товарищи, незнакомцы или твоя совесть.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ты $gособенный:особенная;, и неважно, что говорят тебе друзья, родственники, товарищи, незнакомцы или твоя совесть.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3017,'Если другого выхода нет, надо линять.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Если другого выхода нет, надо линять.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3019,'Внимание: эти потроха не предназначены для употребления в пищу людьми.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Внимание: эти потроха не предназначены для употребления в пищу людьми.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3021,'Не буди спящего гронна.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не буди спящего гронна.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3022,'Это послание доставлено вам Эксплуатационным комитетом Огри\'лы. Сделано в Прибамбасске.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Это послание доставлено вам Эксплуатационным комитетом Огри\'лы. Сделано в Прибамбасске.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3023,'Смысл жизни в том, что… (остальная часть письма случайно съедена)') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Смысл жизни в том, что… (остальная часть письма случайно съедена)',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3024,'Извините, но в этот раз вы проиграли. Попробуйте еще раз.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Извините, но в этот раз вы проиграли. Попробуйте еще раз.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3025,'Сегодня у тебя появится враг, и ты сразу же его убьешь.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сегодня у тебя появится враг, и ты сразу же его убьешь.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3027,'Ищи в жизни возвышенный путь. Так ты избежишь встречи с отбросами общества.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ищи в жизни возвышенный путь. Так ты избежишь встречи с отбросами общества.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3030,'Не может быть, чтобы влияние Маннорота дошло до Запределья, ведь этот монстр мертв уже много лет. Боюсь, у нас появился новый демон, по силе не уступающий Маннороту… И он может привлечь местных орков на свою сторону.\r\n\r\nЯ продолжу изучать кровь орков Кровавой Глазницы, но прошу тебя как можно быстрее начать поиски. Хотя, боюсь, они могут завести тебя в Цитадель Адского Пламени.\r\n\r\nТвой ученый друг,\r\nАптекарь Албрек') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не может быть, чтобы влияние Маннорота дошло до Запределья, ведь этот монстр мертв уже много лет. Боюсь, у нас появился новый демон, по силе не уступающий Маннороту… И он может привлечь местных орков на свою сторону.\r\n\r\nЯ продолжу изучать кровь орков Кровавой Глазницы, но прошу тебя как можно быстрее начать поиски. Хотя, боюсь, они могут завести тебя в Цитадель Адского Пламени.\r\n\r\nТвой ученый друг,\r\nАптекарь Албрек',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3031,'Слушай сюда, Бадд!\r\n\r\nЭто последний болван, которого я тебе посылаю; надо еще – плати! \r\n\r\nБольше никаких отмазок! \r\n\r\nГрифта') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Слушай сюда, Бадд!\r\n\r\nЭто последний болван, которого я тебе посылаю; надо еще – плати! \r\n\r\nБольше никаких отмазок! \r\n\r\nГрифта',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3032,'Гарн!\r\n\r\nДумаю, важность твоей миссии у тебя сомнений не вызывает. Ты должен защитить драгоценный груз любой ценой. Как я и обещал, в случае успеха тебя ждет щедрая награда.\r\n\r\nПусть твои "товарищи" держат язык за зубами, а ты приглядывай за командой, и тогда все пройдет как по маслу. Когда все выполнишь, сообщи мне.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гарн!\r\n\r\nДумаю, важность твоей миссии у тебя сомнений не вызывает. Ты должен защитить драгоценный груз любой ценой. Как я и обещал, в случае успеха тебя ждет щедрая награда.\r\n\r\nПусть твои "товарищи" держат язык за зубами, а ты приглядывай за командой, и тогда все пройдет как по маслу. Когда все выполнишь, сообщи мне.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3033,'Старейшина, я послал тебе на помощь большое войско, но ты должен соблюдать осторожность. Твоя первостепенная задача – не дать этим мерзавцам из Альянса продвинуться вглубь наших земель. Некоторые особо безрассудные люди уже начали строить большое здание на границе Степи.\r\n\r\nДай им понять, что за пределами их проклятого Терамора им не рады. И напоследок предупреждаю тебя, старейшина: не позволяй ограм из Папоротников узнать о твоих планах. У этих животных нет ни капли благоразумия.\r\n\r\n- Агашем') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Старейшина, я послал тебе на помощь большое войско, но ты должен соблюдать осторожность. Твоя первостепенная задача – не дать этим мерзавцам из Альянса продвинуться вглубь наших земель. Некоторые особо безрассудные люди уже начали строить большое здание на границе Степи.\r\n\r\nДай им понять, что за пределами их проклятого Терамора им не рады. И напоследок предупреждаю тебя, старейшина: не позволяй ограм из Папоротников узнать о твоих планах. У этих животных нет ни капли благоразумия.\r\n\r\n- Агашем',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3039,'Не надо рыдать у могилы моей, \r\nЗнай: меня нет давно уже в ней.\r\n\r\nЯ – ветер, летящий над морем и сушей, \r\nСнегами Нордскола, лесной темной гущей.\r\n\r\nЯ – капли дождя на зеленых ветвях, \r\nПросторных лугах и полях.\r\n\r\nЯ – ласковый шепот вечерней зари, \r\nЧто в джунглях далеких, как пламя, горит.\r\n\r\nЯ – бой барабана, я – звон курантов,\r\nЯ – топот копыт на просторах Награнда.\r\n\r\nЯ – звезды, светящие в каждый дом,\r\nКогда в Дарнассе все спят крепким сном.\r\n\r\nЯ – звонкое пение птиц на заре,\r\nЯ – все чудеса, что есть на земле.\r\n\r\nНе надо рыдать у могилы моей, \r\nНе умер я, нет. Я живых всех живей!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не надо рыдать у могилы моей, \r\nЗнай: меня нет давно уже в ней.\r\n\r\nЯ – ветер, летящий над морем и сушей, \r\nСнегами Нордскола, лесной темной гущей.\r\n\r\nЯ – капли дождя на зеленых ветвях, \r\nПросторных лугах и полях.\r\n\r\nЯ – ласковый шепот вечерней зари, \r\nЧто в джунглях далеких, как пламя, горит.\r\n\r\nЯ – бой барабана, я – звон курантов,\r\nЯ – топот копыт на просторах Награнда.\r\n\r\nЯ – звезды, светящие в каждый дом,\r\nКогда в Дарнассе все спят крепким сном.\r\n\r\nЯ – звонкое пение птиц на заре,\r\nЯ – все чудеса, что есть на земле.\r\n\r\nНе надо рыдать у могилы моей, \r\nНе умер я, нет. Я живых всех живей!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3040,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Итак, $N, вот список вещей, необходимых мне для создания нашего нового суперсекретного... эээ... супероружия. Для начала назовем его "ультрасовременный прототип укорачивающего излучателя Умейки".</P>\r\n<BR/>\r\n<P>Поверь, по сравнению с этим изобретением наш старый-добрый увеличитель будет казаться детской игрушкой!</P>\r\n<BR/>\r\n<P>Впрочем, не стоит сейчас мечтать о славе. Просто добудь мне все необходимое – и мы с тобой будем купаться в золоте!</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Итак, $N, вот список вещей, необходимых мне для создания нашего нового суперсекретного... эээ... супероружия. Для начала назовем его "ультрасовременный прототип укорачивающего излучателя Умейки".</P>\r\n<BR/>\r\n<P>Поверь, по сравнению с этим изобретением наш старый-добрый увеличитель будет казаться детской игрушкой!</P>\r\n<BR/>\r\n<P>Впрочем, не стоит сейчас мечтать о славе. Просто добудь мне все необходимое – и мы с тобой будем купаться в золоте!</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3041,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Инструменты</H1>\r\n<BR/>\r\n<P>Итак, для начала тебе придется найти мои инструменты. Никакими другими орудиями не выполнить столь тонкую работу!</P>\r\n<BR/>\r\n<P>Я тебе не рассказывала, как мне пришлось спасаться бегством с насосной станции? Там-то я и оставила мои чудесные инструменты... Нет, ну ты же понимаешь, речь шла о моей жизни! Помню только, что в последний момент я успела спрятать их под восточным насосом.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Инструменты</H1>\r\n<BR/>\r\n<P>Итак, для начала тебе придется найти мои инструменты. Никакими другими орудиями не выполнить столь тонкую работу!</P>\r\n<BR/>\r\n<P>Я тебе не рассказывала, как мне пришлось спасаться бегством с насосной станции? Там-то я и оставила мои чудесные инструменты... Нет, ну ты же понимаешь, речь шла о моей жизни! Помню только, что в последний момент я успела спрятать их под восточным насосом.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3042,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Перегруженный конденсатор</H1>\r\n<BR/>\r\n<P>Эту штуковину может смонстрячить любой инженер, способный держать в руках отвертку. Да я бы сама ее сделала, были бы у меня инструменты. Но у меня их нет, как ты помнишь; смотри пункт первый.</P>\r\n<BR/>\r\n<P>Так что умри, но достань мне перегруженный конденсатор. Мы без него как без рук! Если уж совсем не будет иного выхода – возвращайся на южные земли и купи его на аукционе. </P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Перегруженный конденсатор</H1>\r\n<BR/>\r\n<P>Эту штуковину может смонстрячить любой инженер, способный держать в руках отвертку. Да я бы сама ее сделала, были бы у меня инструменты. Но у меня их нет, как ты помнишь; смотри пункт первый.</P>\r\n<BR/>\r\n<P>Так что умри, но достань мне перегруженный конденсатор. Мы без него как без рук! Если уж совсем не будет иного выхода – возвращайся на южные земли и купи его на аукционе. </P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3043,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Горсть песка Рокнара</H1>\r\n<BR/>\r\n<P>Последний компонент будет нелегко достать, но ты же понимаешь – линзы бластера нужно полировать только самым лучшим песком. А стрясти его можно только с первоклассного элементаля. </P>\r\n<BR/>\r\n<P>Пожалуй, Рокнар сгодится для этой цели. В последний раз его видели на юго-востоке, возле Студеного Предела, где он бродил между Уну\'пе и Стонущим Зиккуратом. Проделай дырку в его ледяной броне и доберись до каменистого сердца, в котором найдется для нас пригоршня песка.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Горсть песка Рокнара</H1>\r\n<BR/>\r\n<P>Последний компонент будет нелегко достать, но ты же понимаешь – линзы бластера нужно полировать только самым лучшим песком. А стрясти его можно только с первоклассного элементаля. </P>\r\n<BR/>\r\n<P>Пожалуй, Рокнар сгодится для этой цели. В последний раз его видели на юго-востоке, возле Студеного Предела, где он бродил между Уну\'пе и Стонущим Зиккуратом. Проделай дырку в его ледяной броне и доберись до каменистого сердца, в котором найдется для нас пригоршня песка.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3044,'Первая вахта, седьмая склянка\r\nСедрик снова рылся в шкафу для рома. Наказан.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Первая вахта, седьмая склянка\r\nСедрик снова рылся в шкафу для рома. Наказан.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3053,'Утренняя вахта, первая склянка\r\nПожар в каюте капитана. Все подняты по тревоге. Выбрасываем порох за борт.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Утренняя вахта, первая склянка\r\nПожар в каюте капитана. Все подняты по тревоге. Выбрасываем порох за борт.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3054,'Легенды о роге неистовства стихий давным-давно ходили среди таунка. Поколения героев выросли на этих преданиях, и, возмужав, отправлялись на его поиски младые сыны, но тщетны были их усилия. Был среди них и отважный воин Штормовое Копыто, что отринул семью и родной край ради погони за мечтой.\r\n\r\nСражаясь со стужей и яростными элементалями Ледяного Клинка, Штормовое Копыто в одиночку покорил неприступную гору, где на вершине ждал его сам Северный Ветер. Зная, что повелитель бурь не отдаст рог без боя, могучий рыцарь бросил ему вызов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Легенды о роге неистовства стихий давным-давно ходили среди таунка. Поколения героев выросли на этих преданиях, и, возмужав, отправлялись на его поиски младые сыны, но тщетны были их усилия. Был среди них и отважный воин Штормовое Копыто, что отринул семью и родной край ради погони за мечтой.\r\n\r\nСражаясь со стужей и яростными элементалями Ледяного Клинка, Штормовое Копыто в одиночку покорил неприступную гору, где на вершине ждал его сам Северный Ветер. Зная, что повелитель бурь не отдаст рог без боя, могучий рыцарь бросил ему вызов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3055,'Пять дней без передышки Штормовое Копыто сражался с ветром. И вот, на закате шестого дня, он наконец изгнал его с Вершины Ледяного Клинка. Теперь рог принадлежал ему! Израненный и усталый, Штормовое Копыто отправился в обратный путь.\r\n\r\nНо Северный Ветер не собирался сдаваться. Он призвал к себе армию младших элементалей и напал на Штормовое Копыто, когда тот уже приближался к родному дому. Утомленный долгой битвой воин не смог оказать достойного сопротивления и пал жертвой мести Северного Ветра, который отобрал у него рог и разломал его на две части. Из этих обломков он сделал две блестящие безделушки и подарил их своим верным союзникам, могущественным вождям горлоков.\r\n\r\n<На этом месте текст обрывается, но под ним кто-то – возможно, сам укротитель ветров Барах – сделал следующее дополнение:>\r\n\r\nПо повелению Северного Ветра великие горлоки передавали эти реликвии из поколения в поколения, от отца к сыну. И в настоящий момент обломки рога хранятся у вождя Бурблгубля и вождя Гурглбугля.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Пять дней без передышки Штормовое Копыто сражался с ветром. И вот, на закате шестого дня, он наконец изгнал его с Вершины Ледяного Клинка. Теперь рог принадлежал ему! Израненный и усталый, Штормовое Копыто отправился в обратный путь.\r\n\r\nНо Северный Ветер не собирался сдаваться. Он призвал к себе армию младших элементалей и напал на Штормовое Копыто, когда тот уже приближался к родному дому. Утомленный долгой битвой воин не смог оказать достойного сопротивления и пал жертвой мести Северного Ветра, который отобрал у него рог и разломал его на две части. Из этих обломков он сделал две блестящие безделушки и подарил их своим верным союзникам, могущественным вождям горлоков.\r\n\r\n<На этом месте текст обрывается, но под ним кто-то – возможно, сам укротитель ветров Барах – сделал следующее дополнение:>\r\n\r\nПо повелению Северного Ветра великие горлоки передавали эти реликвии из поколения в поколения, от отца к сыну. И в настоящий момент обломки рога хранятся у вождя Бурблгубля и вождя Гурглбугля.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3057,'<HTML>\r\n<BODY>\r\n<H1 align="center">Разыскивается: Хеминг Эрнестуэй</H1>\r\n<H1 align="center">ЗА ПРЕСТУПЛЕНИЯ ПРОТИВ ПРИРОДЫ!</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\obj_nesingwary_256" align="center"/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">Фоторобот Уничтожителя в естественной среде обитания: среди адского пламени подземного мира.</H1>\r\n<BR/>\r\n<H1 align="left">Последнее известное местонахождение: Награнд, Запределье</H1>\r\n<BR/>\r\n<H1 align="left">Также известен как: Участник Великой Охоты, Мясник Бесплодных земель, Потрошитель Тернистой долины, Убийца стариков, Хеминг, Эрни, Дуцл, Дядька-добытчик, Уничтожитель.</H1>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<H1 align="center">Разыскивается: Хеминг Эрнестуэй</H1>\r\n<H1 align="center">ЗА ПРЕСТУПЛЕНИЯ ПРОТИВ ПРИРОДЫ!</H1>\r\n<BR/>\r\n<IMG src="Interface\\Pictures\\obj_nesingwary_256" align="center"/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<BR/>\r\n<H1 align="center">Фоторобот Уничтожителя в естественной среде обитания: среди адского пламени подземного мира.</H1>\r\n<BR/>\r\n<H1 align="left">Последнее известное местонахождение: Награнд, Запределье</H1>\r\n<BR/>\r\n<H1 align="left">Также известен как: Участник Великой Охоты, Мясник Бесплодных земель, Потрошитель Тернистой долины, Убийца стариков, Хеминг, Эрни, Дуцл, Дядька-добытчик, Уничтожитель.</H1>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3065,'Верные слуги повелителей элементалей, НАШЕ ВРЕМЯ ПРИШЛО.\r\n\r\nСлишком долго таились мы в тенях, выжидали, прислуживали нашим хозяевам, дожидаясь неизбежного. Теперь, когда в ночи запылало жертвенное пламя Рагнароса, мы в силах начать войну и низвергнуть мир в пучину хаоса!\r\n\r\nПовелитель Огня заточен в нашем мире, он лишен своей подлинной силы, но все равно могуч. Если сыщется ему достойный противник, то начнется великая война элементалей, которая приведет к долгожданному концу света.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Верные слуги повелителей элементалей, НАШЕ ВРЕМЯ ПРИШЛО.\r\n\r\nСлишком долго таились мы в тенях, выжидали, прислуживали нашим хозяевам, дожидаясь неизбежного. Теперь, когда в ночи запылало жертвенное пламя Рагнароса, мы в силах начать войну и низвергнуть мир в пучину хаоса!\r\n\r\nПовелитель Огня заточен в нашем мире, он лишен своей подлинной силы, но все равно могуч. Если сыщется ему достойный противник, то начнется великая война элементалей, которая приведет к долгожданному концу света.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3066,'Нептулону служит великий Повелитель Холода по имени Ахун. Он собирается с силами, чтобы начать войну против Рагнароса. Ему осталось лишь найти врата в наш мир; мы с радостью ему поможем. У нас есть союзники. Мы выбрали поле боя. У нас в достатке могущества и силы воли.\r\n\r\nМы проведем последние переговоры с нашими новыми союзниками и гостями в тихом, укромном местечке, в Ясеневом лесу.\r\n\r\nНе успеют жалкие смертные напраздноваться вдоволь, как Ахун сразится с Рагнаросом под сенью Черной горы. Когда сойдутся эти силы, весь мир содрогнется.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Нептулону служит великий Повелитель Холода по имени Ахун. Он собирается с силами, чтобы начать войну против Рагнароса. Ему осталось лишь найти врата в наш мир; мы с радостью ему поможем. У нас есть союзники. Мы выбрали поле боя. У нас в достатке могущества и силы воли.\r\n\r\nМы проведем последние переговоры с нашими новыми союзниками и гостями в тихом, укромном местечке, в Ясеневом лесу.\r\n\r\nНе успеют жалкие смертные напраздноваться вдоволь, как Ахун сразится с Рагнаросом под сенью Черной горы. Когда сойдутся эти силы, весь мир содрогнется.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3068,'Лок\'тар огар! Победа или смерть – вот девиз, который объединяет меня с Ордой, ибо это самая фундаментальная и непреложная истина для любого воина.\r\n\r\nЯ с гордостью отдам за вождя свою кровь до последней капли. Я – инструмент в руках вождя, его верное оружие.\r\n\r\nС этого мига и до самой смерти я живу и умру – за Орду!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Лок\'тар огар! Победа или смерть – вот девиз, который объединяет меня с Ордой, ибо это самая фундаментальная и непреложная истина для любого воина.\r\n\r\nЯ с гордостью отдам за вождя свою кровь до последней капли. Я – инструмент в руках вождя, его верное оружие.\r\n\r\nС этого мига и до самой смерти я живу и умру – за Орду!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3072,'Мы долго ждали этого момента. Наши повелители выступят друг против друга, и эта славная битва раздерет Азерот на части.\r\n\r\nМы дождались конца времен, братья. Не опускайте оружия. Боритесь до конца. Победа будет за нами!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы долго ждали этого момента. Наши повелители выступят друг против друга, и эта славная битва раздерет Азерот на части.\r\n\r\nМы дождались конца времен, братья. Не опускайте оружия. Боритесь до конца. Победа будет за нами!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3074,'Моя Королева!\r\n\r\nМы обнаружили, что синие драконы более не блокируют пересечение силовых линий в Садах Лунного Покоя. Они пытались разрушить замковый камень с помощью волноловов, но вместо того, чтобы отвести энергию назад, в нексус, они воспользовались ей, чтобы сбежать назад, в Лазуритовое святилище драконов, заключив в земле остатки силы.\r\n\r\nПолагаю, вы понимаете, какое ужасное воздействие оказали пучки магической энергии, пронзившие землю. Пострадали древние обитатели лесов, Калу\'аки и прочие существа, обитающие в этих краях. К счастью для нас, $gстоящий перед вами:стоящая перед вами:r; |3-6($r) по имени $n, уже $gразобрался:разобралась; с источником этих бед.\r\n\r\nПо моему скромному мнению, $N может пригодится Храму Драконьего Покоя в решении проблем, с которыми мы сейчас столкнулись. Нижайше прошу рассмотреть $gего:ее; кандидатуру в качестве нашего союзника.\r\n\r\nС глубочайшим уважением,\r\n\r\nЭтас Похититель Солнца\r\nВерховный маг и член Шести') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Моя Королева!\r\n\r\nМы обнаружили, что синие драконы более не блокируют пересечение силовых линий в Садах Лунного Покоя. Они пытались разрушить замковый камень с помощью волноловов, но вместо того, чтобы отвести энергию назад, в нексус, они воспользовались ей, чтобы сбежать назад, в Лазуритовое святилище драконов, заключив в земле остатки силы.\r\n\r\nПолагаю, вы понимаете, какое ужасное воздействие оказали пучки магической энергии, пронзившие землю. Пострадали древние обитатели лесов, Калу\'аки и прочие существа, обитающие в этих краях. К счастью для нас, $gстоящий перед вами:стоящая перед вами:r; |3-6($r) по имени $n, уже $gразобрался:разобралась; с источником этих бед.\r\n\r\nПо моему скромному мнению, $N может пригодится Храму Драконьего Покоя в решении проблем, с которыми мы сейчас столкнулись. Нижайше прошу рассмотреть $gего:ее; кандидатуру в качестве нашего союзника.\r\n\r\nС глубочайшим уважением,\r\n\r\nЭтас Похититель Солнца\r\nВерховный маг и член Шести',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3077,'А\'туза ползла по широкому подземному туннелю, стараясь производить как можно меньше шума и оборачиваясь на каждый звук, доносившийся из-за спины. "Где же он..." – раздраженно пробормотала она, и тут же резко остановилась, почувствовав какое-то движение за спиной. Ее глаза настороженно сузились, и в воздухе повис звон стали, извлеченной из ножен. \r\n\r\n"Я-то думал, что разбойники предпочитают подкрадываться сзади к своей жертве," – раздался хриплый голос, эхом откликнувшийся от стен пустой пещеры. Она молниеносно развернулась, и ее меч яростно обрушился на окованный железом щит. "Я думала, что паладинам полагается быть смиренными," – парировала она с самоуверенной ухмылкой на устах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','А\'туза ползла по широкому подземному туннелю, стараясь производить как можно меньше шума и оборачиваясь на каждый звук, доносившийся из-за спины. "Где же он..." – раздраженно пробормотала она, и тут же резко остановилась, почувствовав какое-то движение за спиной. Ее глаза настороженно сузились, и в воздухе повис звон стали, извлеченной из ножен. \r\n\r\n"Я-то думал, что разбойники предпочитают подкрадываться сзади к своей жертве," – раздался хриплый голос, эхом откликнувшийся от стен пустой пещеры. Она молниеносно развернулась, и ее меч яростно обрушился на окованный железом щит. "Я думала, что паладинам полагается быть смиренными," – парировала она с самоуверенной ухмылкой на устах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3078,'Наклонившись вперед, А\'туза громко начала считать вслух, пока невидимый кокон не лопнул с характерным звуком. "Двенадцать секунд? По-моему, ты способен на большее," – съязвила она. \r\n\r\nТонкие, костлявые пальцы умело проникли под его броню, расстегивая кирасу и обнажая грудь. "Не бойся, милый Маркус, это еще только начало. Я всего лишь разогреваюсь..." Он обвил руками то, что осталось от ее талии и провел пальцем по позвонкам, вызвав нервный смешок...\r\n\r\n<Остаток книги зачитан настолько, что текст практически невозможно разобрать.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наклонившись вперед, А\'туза громко начала считать вслух, пока невидимый кокон не лопнул с характерным звуком. "Двенадцать секунд? По-моему, ты способен на большее," – съязвила она. \r\n\r\nТонкие, костлявые пальцы умело проникли под его броню, расстегивая кирасу и обнажая грудь. "Не бойся, милый Маркус, это еще только начало. Я всего лишь разогреваюсь..." Он обвил руками то, что осталось от ее талии и провел пальцем по позвонкам, вызвав нервный смешок...\r\n\r\n<Остаток книги зачитан настолько, что текст практически невозможно разобрать.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3106,'1. Если вас не устраивает эффективность яда, удвойте количество ингредиентов или уменьшите их наполовину. \r\n2. Если яд не работает так, как задумано, вы совершили вдвое больше ошибок, чем предполагаете.\r\n3. Опыты, опыты и еще раз опыты (из гномов получаются отличные подопытные).\r\n4. Яды должны быть просты в использовании и трудны в поиске противоядия. \r\n5. Экспериментируйте с ингредиентами в поисках неожиданных сочетаний.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','1. Если вас не устраивает эффективность яда, удвойте количество ингредиентов или уменьшите их наполовину. \r\n2. Если яд не работает так, как задумано, вы совершили вдвое больше ошибок, чем предполагаете.\r\n3. Опыты, опыты и еще раз опыты (из гномов получаются отличные подопытные).\r\n4. Яды должны быть просты в использовании и трудны в поиске противоядия. \r\n5. Экспериментируйте с ингредиентами в поисках неожиданных сочетаний.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3113,'1. Отрастите пышную бороду, дабы она скрывала несовершенство ваших лиц от Света. \r\n\r\n2. Очищайте руки в молоке кобылиц, ибо дарам достойно быть принятыми только из мягких и нежных рук. \r\n\r\n3. Омывайте тело свое в реках, позволяя великим дарам Света очистить вашу кожу.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','1. Отрастите пышную бороду, дабы она скрывала несовершенство ваших лиц от Света. \r\n\r\n2. Очищайте руки в молоке кобылиц, ибо дарам достойно быть принятыми только из мягких и нежных рук. \r\n\r\n3. Омывайте тело свое в реках, позволяя великим дарам Света очистить вашу кожу.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3114,'4. Регулярно меняйте одеяния, дабы ваш облик и запах не оскорбил служителей Света.\r\n\r\n5. Держите осанку – не позволяйте усталости и лени согнуть вашу спину. \r\n\r\n<Список наставлений продолжается еще на нескольких листах>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','4. Регулярно меняйте одеяния, дабы ваш облик и запах не оскорбил служителей Света.\r\n\r\n5. Держите осанку – не позволяйте усталости и лени согнуть вашу спину. \r\n\r\n<Список наставлений продолжается еще на нескольких листах>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3115,'Обращение верховного настоятеля Ландгрена. \n\nНекоторым может показаться, что в дни скорби и гнева следует отречься от всего и посвятить себя только благополучию семьи и родного дома, но чувство это ложно. Отринув факел веры, отгоняющий тьму от наших душ, сердца ваших близких очень скоро окажутся беспомощными перед отчаянием и страхом. Чувство сытости, тепла и уюта, которое можно купить за деньги, не сможет спасти вашу семью от внутренней опустошенности, которая завладеет душами, ежели те забудут о своих обязательствах перед Светом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Обращение верховного настоятеля Ландгрена. \n\nНекоторым может показаться, что в дни скорби и гнева следует отречься от всего и посвятить себя только благополучию семьи и родного дома, но чувство это ложно. Отринув факел веры, отгоняющий тьму от наших душ, сердца ваших близких очень скоро окажутся беспомощными перед отчаянием и страхом. Чувство сытости, тепла и уюта, которое можно купить за деньги, не сможет спасти вашу семью от внутренней опустошенности, которая завладеет душами, ежели те забудут о своих обязательствах перед Светом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3116,'Обратитесь к церкви. Трудности, возникающие от отсутствия благ насущных, только укрепят вашу душу, изгонят бесов и поднимут вас на новый уровень духовного совершенства. Не стыдитесь бурчания голодных животов, царапин от камней на босых подошвах и мурашек на озябшей коже. Гордо идите по пути Света и внимайте ему всей душой. Страдания приближают вас к золотым чертогам святости, которые открыты для тех, кто крепок духом и телом. \r\n\r\nОткажитесь от ублажения плоти и приблизьтесь к истинному пониманию Света.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Обратитесь к церкви. Трудности, возникающие от отсутствия благ насущных, только укрепят вашу душу, изгонят бесов и поднимут вас на новый уровень духовного совершенства. Не стыдитесь бурчания голодных животов, царапин от камней на босых подошвах и мурашек на озябшей коже. Гордо идите по пути Света и внимайте ему всей душой. Страдания приближают вас к золотым чертогам святости, которые открыты для тех, кто крепок духом и телом. \r\n\r\nОткажитесь от ублажения плоти и приблизьтесь к истинному пониманию Света.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3119,'Очищайте тело трудом. Очищайте душу молитвами. Очищайте ваших врагов огнем и мечом. Не избегайте боли, ибо она – ваш союзник. Примите ее, ибо боль едина для всех, верующих и неверных. \r\n\r\nСопротивление путям Света есть признак несовершенства души, который должен быть искоренен из плоти нашего сообщества.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Очищайте тело трудом. Очищайте душу молитвами. Очищайте ваших врагов огнем и мечом. Не избегайте боли, ибо она – ваш союзник. Примите ее, ибо боль едина для всех, верующих и неверных. \r\n\r\nСопротивление путям Света есть признак несовершенства души, который должен быть искоренен из плоти нашего сообщества.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3126,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Наши молитвы услышаны. Верховный настоятель был поражен силой гласа Света, его чистотой и убежденностью. </P>\r\n<BR/>\r\n<P>Лишь самые преданные воины отправятся с нами на Север и войдут в историю под именем Алого Натиска.</P>\r\n<BR/>\r\n<P>Мы начинаем наступление на Нордскол! Скверна Плети угрожает захватить власть над миром и погубить все живое. Настало время дать ей отпор! Скоро мы будем стоять у подножия трона самого Короля-лича! </P>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Наши молитвы услышаны. Верховный настоятель был поражен силой гласа Света, его чистотой и убежденностью. </P>\r\n<BR/>\r\n<P>Лишь самые преданные воины отправятся с нами на Север и войдут в историю под именем Алого Натиска.</P>\r\n<BR/>\r\n<P>Мы начинаем наступление на Нордскол! Скверна Плети угрожает захватить власть над миром и погубить все живое. Настало время дать ей отпор! Скоро мы будем стоять у подножия трона самого Короля-лича! </P>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3129,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>С трепетом взираю я на Новый Авалон, ибо мне кажется, что вижу его в последний раз. Наша судьба решится в Нордсколе, но меня обуревает гнетущее чувство неминуемой беды. Я надеюсь, что наши грядущие деяния очистят мою душу от смятений. Я должна выбросить сомнения прочь из головы.</P>\r\n<BR/>\r\n<P>Нас ждет Багровый Рассвет.</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>С трепетом взираю я на Новый Авалон, ибо мне кажется, что вижу его в последний раз. Наша судьба решится в Нордсколе, но меня обуревает гнетущее чувство неминуемой беды. Я надеюсь, что наши грядущие деяния очистят мою душу от смятений. Я должна выбросить сомнения прочь из головы.</P>\r\n<BR/>\r\n<P>Нас ждет Багровый Рассвет.</P>\r\n<BR/>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3157,'Скор\'зад осторожно выглянул из-за колонны. Как он и ожидал, она парила в одиночестве по центру комнаты. Правильно ли он поступил, придя столь поздно ночью в покои банши? Если бы некроманты обнаружили его здесь, то закопали бы обратно под землю. Что хуже всего – он не был уверен во взаимности своих чувств, а мадам Сиднари славилась вспыльчивым нравом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Скор\'зад осторожно выглянул из-за колонны. Как он и ожидал, она парила в одиночестве по центру комнаты. Правильно ли он поступил, придя столь поздно ночью в покои банши? Если бы некроманты обнаружили его здесь, то закопали бы обратно под землю. Что хуже всего – он не был уверен во взаимности своих чувств, а мадам Сиднари славилась вспыльчивым нравом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3158,'Но узрев свою богиню во всей красе, зомби отбросил последние сомнения. Ее тонкий профиль все еще хранил изящные, эльфийские черты как напоминание о прошлой жизни, но теперь ее лицо было испещрено струпьями и червоточинами. Багровую, почти прозрачную кожу едва прикрывали лохмотья истлевшего савана, оставляя мало простора для воображения. Ее безногое тело буквально светилось энергией, исходившей от синеватой сферы, зависшей в нескольких футах от холодного, гранитного пола. Скор\'зад заставил себя слегка расслабиться и облегченно вытер пот вперемешку со слизью, сочившейся из треснувшей кожи над бровью.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Но узрев свою богиню во всей красе, зомби отбросил последние сомнения. Ее тонкий профиль все еще хранил изящные, эльфийские черты как напоминание о прошлой жизни, но теперь ее лицо было испещрено струпьями и червоточинами. Багровую, почти прозрачную кожу едва прикрывали лохмотья истлевшего савана, оставляя мало простора для воображения. Ее безногое тело буквально светилось энергией, исходившей от синеватой сферы, зависшей в нескольких футах от холодного, гранитного пола. Скор\'зад заставил себя слегка расслабиться и облегченно вытер пот вперемешку со слизью, сочившейся из треснувшей кожи над бровью.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3159,'Не заметив его присутствия, она проплыла над полом к единственному окну, открывавшему великолепный вид на поле битвы. Пред ней предстала великолепная картина смерти и разрушений. Всего шесть часов назад эти земли содрогались от криков убиенных младенцев, но сейчас над полем царила замогильная тишина.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Не заметив его присутствия, она проплыла над полом к единственному окну, открывавшему великолепный вид на поле битвы. Пред ней предстала великолепная картина смерти и разрушений. Всего шесть часов назад эти земли содрогались от криков убиенных младенцев, но сейчас над полем царила замогильная тишина.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3160,'Ветер развевал ее длинные волосы, играя змееподобными локонами, обрамляющими пустые глазницы. Скор\'зад внезапно осознал, что в порыве страсти слишком сильно высунулся из-за колонны, и в ужасе отшатнулся, боясь, что Темная Плакальщица может его увидеть. Она и впрямь почувствовала движение у себя за спиной, но ему незачем было волноваться.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ветер развевал ее длинные волосы, играя змееподобными локонами, обрамляющими пустые глазницы. Скор\'зад внезапно осознал, что в порыве страсти слишком сильно высунулся из-за колонны, и в ужасе отшатнулся, боясь, что Темная Плакальщица может его увидеть. Она и впрямь почувствовала движение у себя за спиной, но ему незачем было волноваться.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3161,'"Скор\'зад!" – позвала она. – "Я ждала тебя. Сегодня ты храбро сражался." Банши бросила на него томный взгляд, позволяя трепещущим лоскуткам савана слегка сползти с гниющего плеча. "Подойди сюда. Настало время... вознаградить тебя за отвагу."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Скор\'зад!" – позвала она. – "Я ждала тебя. Сегодня ты храбро сражался." Банши бросила на него томный взгляд, позволяя трепещущим лоскуткам савана слегка сползти с гниющего плеча. "Подойди сюда. Настало время... вознаградить тебя за отвагу."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3162,'<Похоже, следующие несколько страниц намертво склеились.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Похоже, следующие несколько страниц намертво склеились.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3165,'Диодор Проклятый. Человек-некромант, один из первых приверженцев культа Проклятых и герой Первой войны. Возглавил войска Плети и привел их к победе по время Первого и второго летнего штурма Монастыря Алого ордена. Был убит во время третьего штурма, успешно отраженного Алым орденом, который наконец-то смог вычислить его тактику.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Диодор Проклятый. Человек-некромант, один из первых приверженцев культа Проклятых и герой Первой войны. Возглавил войска Плети и привел их к победе по время Первого и второго летнего штурма Монастыря Алого ордена. Был убит во время третьего штурма, успешно отраженного Алым орденом, который наконец-то смог вычислить его тактику.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3166,'Киркессен Жаждущий. Могущественный лич, правая рука самого Короля-лича. Ветеран бесчисленных сражений, Киркессен лично спланировал и возглавил Кровавую осаду часовни Последней Надежды. Несмотря на численное превосходство, его войска были разбиты и понесли значительные потери. Лорд Максвелл Тиросс не простил Киркессену этой ошибки и лично лишил его права на физическое обличье.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Киркессен Жаждущий. Могущественный лич, правая рука самого Короля-лича. Ветеран бесчисленных сражений, Киркессен лично спланировал и возглавил Кровавую осаду часовни Последней Надежды. Несмотря на численное превосходство, его войска были разбиты и понесли значительные потери. Лорд Максвелл Тиросс не простил Киркессену этой ошибки и лично лишил его права на физическое обличье.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3167,'Западный Нордскол – Данные воздушной топографической разведки из Ледяной Короны показывают, что сообщение с Лич-лордом Хладолютом прервано. "В последний раз Хладолюта видели за пультом управления некрополем, Талрамасом, пролетавшим над Борейской тундрой в рамках выполнения сверхсекретного задания," – докладывает офицер разведки Плети, инженер Каромон. – "Наши данные свидетельствуют о том, что его кристаллы связи целы и работают, но он... хранит гробовое молчание."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Западный Нордскол – Данные воздушной топографической разведки из Ледяной Короны показывают, что сообщение с Лич-лордом Хладолютом прервано. "В последний раз Хладолюта видели за пультом управления некрополем, Талрамасом, пролетавшим над Борейской тундрой в рамках выполнения сверхсекретного задания," – докладывает офицер разведки Плети, инженер Каромон. – "Наши данные свидетельствуют о том, что его кристаллы связи целы и работают, но он... хранит гробовое молчание."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3169,'Разлом Смерти, Восточные королевства – На этой неделе инструктор Разувий довольно резко высказался по поводу многочисленных случаев неподчинения и нарушения субординации в войсках. Цитирую, "Любой рыцарь смерти, осмелившийся предать Плеть, будет обречен на вечные страдания, по сравнению с которыми смерть покажется недостижимым блаженством. Я лично прослежу за этим."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Разлом Смерти, Восточные королевства – На этой неделе инструктор Разувий довольно резко высказался по поводу многочисленных случаев неподчинения и нарушения субординации в войсках. Цитирую, "Любой рыцарь смерти, осмелившийся предать Плеть, будет обречен на вечные страдания, по сравнению с которыми смерть покажется недостижимым блаженством. Я лично прослежу за этим."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3171,'Драконий Погост – Принц Валанар объявил об открывшейся вакансии для исключительного рыцаря смерти, которому надлежит отправиться в Драконий Погост, находящийся в центре Нордскола, и возглавить элитный отряд солдат, который окажет сопротивление роду красных драконов. "Ваше обучение практически завершено, – сказал он в недавнем обращении к войскам. – Настало время выступить против защитников смертных! Мы покажем им истинное значение названия "Драконий Погост!"') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Драконий Погост – Принц Валанар объявил об открывшейся вакансии для исключительного рыцаря смерти, которому надлежит отправиться в Драконий Погост, находящийся в центре Нордскола, и возглавить элитный отряд солдат, который окажет сопротивление роду красных драконов. "Ваше обучение практически завершено, – сказал он в недавнем обращении к войскам. – Настало время выступить против защитников смертных! Мы покажем им истинное значение названия "Драконий Погост!"',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3172,'Алекстраза, Королева красных драконов и самый могущественный враг Плети в Нордсколе, набирает собственную армию. Ходят слухи, что она готова заключить союз с родом синих драконов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Алекстраза, Королева красных драконов и самый могущественный враг Плети в Нордсколе, набирает собственную армию. Ходят слухи, что она готова заключить союз с родом синих драконов.',`Text_loc8`);
