INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3192,'Имя: $N\r\nСтатус: g$жив:жива;\r\nПримечание: несет отвественность за смерть сотен рыцарей Алого Натиска. Все всякого сомнения, это только начало.\r\n\r\n<В книге несколько сотен страниц.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Имя: $N\r\nСтатус: g$жив:жива;\r\nПримечание: несет отвественность за смерть сотен рыцарей Алого Натиска. Все всякого сомнения, это только начало.\r\n\r\n<В книге несколько сотен страниц.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3211,'Трупеус – хороший повар из Акеруса, готовит вкусную еду. Он гордится тем, что кормит великую Плеть. Не зли Трупеуса, а то он не даст тебе еды.\r\n\r\nПравила:\r\n\r\nРыцари смерти едят первыми, вурдалаки потом.\r\n\r\nНе ешь сразу за вурдалаком. Сначала помой за ним тарелку.\r\n\r\nМожно добавлять в пищу своих червей и личинок. Трупеус не обидится.\r\n\r\nПоймал крысу? Принеси Трупеусу!\r\n\r\nМожно есть людей и эльфов. У эльфов – диетическое мясо.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Трупеус – хороший повар из Акеруса, готовит вкусную еду. Он гордится тем, что кормит великую Плеть. Не зли Трупеуса, а то он не даст тебе еды.\r\n\r\nПравила:\r\n\r\nРыцари смерти едят первыми, вурдалаки потом.\r\n\r\nНе ешь сразу за вурдалаком. Сначала помой за ним тарелку.\r\n\r\nМожно добавлять в пищу своих червей и личинок. Трупеус не обидится.\r\n\r\nПоймал крысу? Принеси Трупеусу!\r\n\r\nМожно есть людей и эльфов. У эльфов – диетическое мясо.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3212,'Перемешай еду. Если найдешь салфетку – Трупеусу будет стыдно.\r\n\r\nМожно приносить обратно недостаточно сгнившую пищу. У Трупеуса есть три свободные подмышки.\r\n\r\nМожно есть руками, можно есть с ножа. Нельзя есть руки и ножи. \r\n\r\nЗомби нужна разнообразная пища. Мозгами сыт не будешь.\r\n\r\nНе ешь сам себя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Перемешай еду. Если найдешь салфетку – Трупеусу будет стыдно.\r\n\r\nМожно приносить обратно недостаточно сгнившую пищу. У Трупеуса есть три свободные подмышки.\r\n\r\nМожно есть руками, можно есть с ножа. Нельзя есть руки и ножи. \r\n\r\nЗомби нужна разнообразная пища. Мозгами сыт не будешь.\r\n\r\nНе ешь сам себя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3226,'Добро пожаловать, новые солдаты Плети! Чувствуете ли вы восторг освобождения от смертных предрассудков и презренных желаний плоти? Отныне вам не надо тратить время на сон, укрывать свое тело от причуд стихий, беспокоиться о красе волос и ногтей. Не правда ли, это восхитительно?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Добро пожаловать, новые солдаты Плети! Чувствуете ли вы восторг освобождения от смертных предрассудков и презренных желаний плоти? Отныне вам не надо тратить время на сон, укрывать свое тело от причуд стихий, беспокоиться о красе волос и ногтей. Не правда ли, это восхитительно?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3227,'Однако, в жизни нежити есть несколько незначительных деталей, на которые вам необходимо обратить внимание.\r\nВсегда следите за состоянием своей плоти. Гниющие конечности, несомненно, могут напугать противника, но рука, отвалившаяся в разгар боя, может повлиять на его исход не в вашу пользу. \r\nПривыкайте к своему запаху. Это не вонь, это аромат.\r\nИзбегайте живых существ, особенно собак.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Однако, в жизни нежити есть несколько незначительных деталей, на которые вам необходимо обратить внимание.\r\nВсегда следите за состоянием своей плоти. Гниющие конечности, несомненно, могут напугать противника, но рука, отвалившаяся в разгар боя, может повлиять на его исход не в вашу пользу. \r\nПривыкайте к своему запаху. Это не вонь, это аромат.\r\nИзбегайте живых существ, особенно собак.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3228,'Следите за речью. Если вы потеряете нижнюю челюсть, это может привести к переводу на менее почетную должность, на которой ваша косноязыкость будет не столь заметна.\r\nК сожалению, алкогольные напитки больше не будут оказывать на вас желаемого эффекта.\r\nПринимайте кровавые ванны каждый день (добавлять пену не рекомендуется). \r\nИзбегайте пастельных тонов в одежде. Они не подходят под цвет вашей кожи. \r\nЭти штаны больше не будут вас полнить.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Следите за речью. Если вы потеряете нижнюю челюсть, это может привести к переводу на менее почетную должность, на которой ваша косноязыкость будет не столь заметна.\r\nК сожалению, алкогольные напитки больше не будут оказывать на вас желаемого эффекта.\r\nПринимайте кровавые ванны каждый день (добавлять пену не рекомендуется). \r\nИзбегайте пастельных тонов в одежде. Они не подходят под цвет вашей кожи. \r\nЭти штаны больше не будут вас полнить.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3231,'Струпы и язвы\r\n\r\nОтдайте дань вашему переменчивому настроению и выразите его с помощью слегка покрытых коростой, гниющих ран, щедро покрывающих все тело. Однако не позволяйте им засыхать полностью! Зажившая рана – это признак дурного вкуса.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Струпы и язвы\r\n\r\nОтдайте дань вашему переменчивому настроению и выразите его с помощью слегка покрытых коростой, гниющих ран, щедро покрывающих все тело. Однако не позволяйте им засыхать полностью! Зажившая рана – это признак дурного вкуса.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3232,'Черви и насекомые\r\n\r\nОх, неужели вы откажетесь завести себе нескольких домашних животных? Они неприхотливы, мало едят и прекрасно дополняют ваш разлагающийся облик. Однако если в вас завелись пчелы или осы, немедленно обратитесь на ближайшую скотобойню для дезинфекции.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Черви и насекомые\r\n\r\nОх, неужели вы откажетесь завести себе нескольких домашних животных? Они неприхотливы, мало едят и прекрасно дополняют ваш разлагающийся облик. Однако если в вас завелись пчелы или осы, немедленно обратитесь на ближайшую скотобойню для дезинфекции.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3233,'Недостающие конечности\r\n\r\nЕсли в разгар боя у вас отвалилась рука или нога, не спешите ее подбирать! Сражайтесь тем, что осталось. Наши специалисты подберут вам наилучшую замену, идеально отвечающую всем особенностям вашей анатомии. Но это будет после драки; пока же, в худшем случае, позаимствуйте недостающую часть тела у своего коллеги!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Недостающие конечности\r\n\r\nЕсли в разгар боя у вас отвалилась рука или нога, не спешите ее подбирать! Сражайтесь тем, что осталось. Наши специалисты подберут вам наилучшую замену, идеально отвечающую всем особенностям вашей анатомии. Но это будет после драки; пока же, в худшем случае, позаимствуйте недостающую часть тела у своего коллеги!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3234,'Каннибализм\r\n\r\nВо избежание поедания своих же коллег, выждите пять секунд после того, как тело упало на землю, и только после этого приступайте к трапезе. Осторожно, не спутайте мертвые тела со спящими послушниками!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Каннибализм\r\n\r\nВо избежание поедания своих же коллег, выждите пять секунд после того, как тело упало на землю, и только после этого приступайте к трапезе. Осторожно, не спутайте мертвые тела со спящими послушниками!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3235,'Запись 1:\r\n\r\nВерховный генерал нашла отличный источник вербовки среди крестьян! Теперь флот Ордена растет с каждым днем, и в наших рядах нет недостатка в крепких воинах. Мы готовы нанести удар по Нордсколу и завершить эту бесконечную войну. И все же положение наше оставляет желать лучшего. Бастион Алого ордена объят пламенем, и я не могу не ощущать дыхание смерти у себя за спиной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 1:\r\n\r\nВерховный генерал нашла отличный источник вербовки среди крестьян! Теперь флот Ордена растет с каждым днем, и в наших рядах нет недостатка в крепких воинах. Мы готовы нанести удар по Нордсколу и завершить эту бесконечную войну. И все же положение наше оставляет желать лучшего. Бастион Алого ордена объят пламенем, и я не могу не ощущать дыхание смерти у себя за спиной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3236,'Запись 15:\r\n\r\nАббендис сошла с ума. Она собирается расколоть Орден и напасть на цитадель Короля-лича с горсткой преданных рыцарей. Значит ли это, что она намерена бросить Новый Авалон и Длань Тира на откуп судьбе и забрать на край света наших последних защитников?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 15:\r\n\r\nАббендис сошла с ума. Она собирается расколоть Орден и напасть на цитадель Короля-лича с горсткой преданных рыцарей. Значит ли это, что она намерена бросить Новый Авалон и Длань Тира на откуп судьбе и забрать на край света наших последних защитников?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3237,'Запись 23:\r\n\r\nЭто было солнечное утро, отражавшееся в блеске лопат и мотыг, вздымавшихся над полем, где мужчины и женщины трудились не покладая рук. Но потом на нас пала тень некрополя, и то был не Наксрамас. Плеть разбила лагерь недалеко от нашего укрепления, Аббендис приказала нам сражаться до последней капли крови. Неужели я клялся в верности Ордену только для того, чтобы погибнуть, покрывая бегство нашего генерала?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 23:\r\n\r\nЭто было солнечное утро, отражавшееся в блеске лопат и мотыг, вздымавшихся над полем, где мужчины и женщины трудились не покладая рук. Но потом на нас пала тень некрополя, и то был не Наксрамас. Плеть разбила лагерь недалеко от нашего укрепления, Аббендис приказала нам сражаться до последней капли крови. Неужели я клялся в верности Ордену только для того, чтобы погибнуть, покрывая бегство нашего генерала?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3238,'<Меж последних страниц дневника лежит неаккуратно сложенная карта. Похоже, автор собирался обогнуть вплавь северо-восточное побережье Лордерона и достичь Тирисфальских лесов!>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Меж последних страниц дневника лежит неаккуратно сложенная карта. Похоже, автор собирался обогнуть вплавь северо-восточное побережье Лордерона и достичь Тирисфальских лесов!>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3239,'Я вас предупреждал: если в следующем походе мне снова придется проводить большую часть времени за чисткой сапог, кому-то придется за это ответить! С этого момента дежурства в отхожих местах будут удвоены как по времени, так и по количеству служащих! \r\n\r\n--Инструктор Разувий') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я вас предупреждал: если в следующем походе мне снова придется проводить большую часть времени за чисткой сапог, кому-то придется за это ответить! С этого момента дежурства в отхожих местах будут удвоены как по времени, так и по количеству служащих! \r\n\r\n--Инструктор Разувий',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3240,'О, величайшая ирония! Смертные приписывают нежити самые жалкие проявления своего существования – рабское покорство, жестокость и равнодушие. Да, мы служим! Но смертные служат не меньше нас. Они поклоняются королям, богам, друидам, жрецам, людям и зверям. Мы же повинуемся только могучей воле Короля-лича, которая объединяет и сплочает всех нас!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','О, величайшая ирония! Смертные приписывают нежити самые жалкие проявления своего существования – рабское покорство, жестокость и равнодушие. Да, мы служим! Но смертные служат не меньше нас. Они поклоняются королям, богам, друидам, жрецам, людям и зверям. Мы же повинуемся только могучей воле Короля-лича, которая объединяет и сплочает всех нас!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3241,'Вся история человечества пронизана свидетельствами жестокости, предательства, ненависти и эгоизма. Для Плети же существует только результативность и единство. Мы служим Королю-личу в жизни и продолжаем служить ему после смерти. Он – единственный властелин, который ведет нас к победе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вся история человечества пронизана свидетельствами жестокости, предательства, ненависти и эгоизма. Для Плети же существует только результативность и единство. Мы служим Королю-личу в жизни и продолжаем служить ему после смерти. Он – единственный властелин, который ведет нас к победе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3242,'Наша плоть мертва, но наше единство живет. Могущественная Плеть – это один народ, один разум, одна душа. Истинная смерть живет в бессердечных взглядах стражей, что бросают на произвол судьбы беженцев из собственной страны, оставляют увечных на поле боя. Разве люди едины? Только холодом своих сердец.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наша плоть мертва, но наше единство живет. Могущественная Плеть – это один народ, один разум, одна душа. Истинная смерть живет в бессердечных взглядах стражей, что бросают на произвол судьбы беженцев из собственной страны, оставляют увечных на поле боя. Разве люди едины? Только холодом своих сердец.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3243,'Так поднимем же наши знамена и низвергнем врагов! Пусть их сломленные тела примкнут к нашей армии, и вскоре все живые существа склонят колени перед Ледяным Троном!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Так поднимем же наши знамена и низвергнем врагов! Пусть их сломленные тела примкнут к нашей армии, и вскоре все живые существа склонят колени перед Ледяным Троном!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3244,'Наконец-то я заслужил милость настоятеля! Сегодня мне было позволено посещать Некроситет. Это будет первой ступенькой на пути к моему величию!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наконец-то я заслужил милость настоятеля! Сегодня мне было позволено посещать Некроситет. Это будет первой ступенькой на пути к моему величию!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3245,'Я не ожидал, что дела в Некроситете настолько запущены. Повсюду валяются груды исследовательских материалов и свитков, порой совершенно заляпанных воском от чадящих свечей. Духи, големы и демоны неприкаянно бродят по коридорам. Надо сказать, я ожидал большей ответственности от столь опытных некромантов!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я не ожидал, что дела в Некроситете настолько запущены. Повсюду валяются груды исследовательских материалов и свитков, порой совершенно заляпанных воском от чадящих свечей. Духи, големы и демоны неприкаянно бродят по коридорам. Надо сказать, я ожидал большей ответственности от столь опытных некромантов!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3246,'Сегодня в школу ворвалась группа бандитов и попыталась проникнуть в склепы. Подумайте только, пока они сражались с небольшой группой защитников в фойе, стоящие рядом студенты даже пальцем не пошевелили, чтобы помочь своим учителям! Их силы хватило бы на то, чтобы одолеть небольшую армию – а они продолжали свои занятия, будто ничего не не происходило! Какие болваны!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сегодня в школу ворвалась группа бандитов и попыталась проникнуть в склепы. Подумайте только, пока они сражались с небольшой группой защитников в фойе, стоящие рядом студенты даже пальцем не пошевелили, чтобы помочь своим учителям! Их силы хватило бы на то, чтобы одолеть небольшую армию – а они продолжали свои занятия, будто ничего не не происходило! Какие болваны!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3247,'Во время урока в классе темного магистра Гандлинга случилось еще одно происшествие. Захватчики проникли в Некроситет через смотровую комнату и достигли склепов, а этот псих спрятался за книжным шкафом и хихикал, глядя, как убивают наших школьных управляющих, одного за другим. Затем он вдруг выбежал вперед и заорал: "У нас идут занятия!". Он что, совершенно съехал с катушек? Все, я перевожусь в Стратхольм!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Во время урока в классе темного магистра Гандлинга случилось еще одно происшествие. Захватчики проникли в Некроситет через смотровую комнату и достигли склепов, а этот псих спрятался за книжным шкафом и хихикал, глядя, как убивают наших школьных управляющих, одного за другим. Затем он вдруг выбежал вперед и заорал: "У нас идут занятия!". Он что, совершенно съехал с катушек? Все, я перевожусь в Стратхольм!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3248,'Меня приняли на место Тузадинского некроманта в Стратхольм! Странное тут место. Не понимаю, почему никто не гасит огни. А сумасбродная система зиккуратов, связанная с вратами скотобойни, меня совершенно озадачила. Если цель в том, чтобы не подпускать никого к скотобойне – почему бы просто не запереть ворота?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Меня приняли на место Тузадинского некроманта в Стратхольм! Странное тут место. Не понимаю, почему никто не гасит огни. А сумасбродная система зиккуратов, связанная с вратами скотобойни, меня совершенно озадачила. Если цель в том, чтобы не подпускать никого к скотобойне – почему бы просто не запереть ворота?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3249,'Теперь я начинаю понимать, в чем причина всех этих недоразумений. Это наглый, заносчивый урод на гнилой кобыле, который провозглашает себя "Бароном" Ривендером, повелителем Стратхольма. По-моему, этот парень перепутал плеть с личным зоопарком, потому что каждое утро он проводит среди послушников, миньонов и големов, строя их в отряды и распределяя по разным кварталам города!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Теперь я начинаю понимать, в чем причина всех этих недоразумений. Это наглый, заносчивый урод на гнилой кобыле, который провозглашает себя "Бароном" Ривендером, повелителем Стратхольма. По-моему, этот парень перепутал плеть с личным зоопарком, потому что каждое утро он проводит среди послушников, миньонов и големов, строя их в отряды и распределяя по разным кварталам города!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3250,'После завершения ежедневного баронского парада по городу шатаются множество бездельников, круша и сжигая все вокруг. Я не раз говорил ему: "Заприте ворота!", но он продолжает настаивать, что его миньоны защитят скотобойню. В общем, мне это надоело. Немедленно собираю вещички и уматываю через задние ворота!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После завершения ежедневного баронского парада по городу шатаются множество бездельников, круша и сжигая все вокруг. Я не раз говорил ему: "Заприте ворота!", но он продолжает настаивать, что его миньоны защитят скотобойню. В общем, мне это надоело. Немедленно собираю вещички и уматываю через задние ворота!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3251,'Похоже, моего побега никто не заметил. Судя по клубам дыма, поднимающимся со стороны города, я ушел как нельзя вовремя. Сколько времени потрачено зря в этом Стратхольме! Небольшим утешением может служить только печатка Барона, которую я украл у этого мерзавца. Полагаю, столь благородное украшение с личным баронским гербом поможет мне уютно обосноваться в Наксрамасе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Похоже, моего побега никто не заметил. Судя по клубам дыма, поднимающимся со стороны города, я ушел как нельзя вовремя. Сколько времени потрачено зря в этом Стратхольме! Небольшим утешением может служить только печатка Барона, которую я украл у этого мерзавца. Полагаю, столь благородное украшение с личным баронским гербом поможет мне уютно обосноваться в Наксрамасе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3252,'Сегодня я устроился на работу на военную фабрику великой Плети! Деятельность в Наксрамасе бьет ключом. К сожалению, я обнаружил, что здесь используются какие-то непонятные механизмы для питания критически важных телепортов, но, очевидно, до более элегантного решения они не додумались. Я уже задумался о том, какие выгоды могло бы принести мне такое изобретение... но присутствие этого назойливого неруба не дает мне сосредоточиться!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Сегодня я устроился на работу на военную фабрику великой Плети! Деятельность в Наксрамасе бьет ключом. К сожалению, я обнаружил, что здесь используются какие-то непонятные механизмы для питания критически важных телепортов, но, очевидно, до более элегантного решения они не додумались. Я уже задумался о том, какие выгоды могло бы принести мне такое изобретение... но присутствие этого назойливого неруба не дает мне сосредоточиться!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3253,'Неруб все никак не угомонится. То и дело я слышу его жуткий, монотонный голос, взывающий ко мне. Постоянно приглашает зайти к нему "заняться исследованиями". В последнее время я прячусь от него в сломанной трубе за комнатой Глута – это единственное место, где я могу побыть в одиночестве. Мой мозг скоро лопнет!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Неруб все никак не угомонится. То и дело я слышу его жуткий, монотонный голос, взывающий ко мне. Постоянно приглашает зайти к нему "заняться исследованиями". В последнее время я прячусь от него в сломанной трубе за комнатой Глута – это единственное место, где я могу побыть в одиночестве. Мой мозг скоро лопнет!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3254,'И как эти жалкий набор суповых костей и гниющих трупов собирается покорить весь Азерот? Они не в состоянии даже уберечь свои тела от распадания! А я не могу и надеяться на то, что мне удастся воплотить в жизнь мои планы, пока этот мерзкий нерубыц таскается за мной по пятам и отравляет все мое существование!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','И как эти жалкий набор суповых костей и гниющих трупов собирается покорить весь Азерот? Они не в состоянии даже уберечь свои тела от распадания! А я не могу и надеяться на то, что мне удастся воплотить в жизнь мои планы, пока этот мерзкий нерубыц таскается за мной по пятам и отравляет все мое существование!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3255,'Я уже начинаю привыкать к неожиданным нападениям во время работы. Сегодня очередная банда искателей приключений ворвалась в некрополь и стала убивать моих коллег. Увы, пали даже отважные служители культа Фарлины, прежде чем этот мерзкий паук позволил мне с ней поговорить! Ненавижу это место! Стану нежитью – сразу унесу отсюда ноги. А пока что – пора взять в руки оружие!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я уже начинаю привыкать к неожиданным нападениям во время работы. Сегодня очередная банда искателей приключений ворвалась в некрополь и стала убивать моих коллег. Увы, пали даже отважные служители культа Фарлины, прежде чем этот мерзкий паук позволил мне с ней поговорить! Ненавижу это место! Стану нежитью – сразу унесу отсюда ноги. А пока что – пора взять в руки оружие!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3256,'После нескольких попыток послужить Плети я осознал, что моим требованиям не отвечают даже самые высшие эшелоны данной организации. Учитывая неотъемлемое отсутствие гибкости, присущее любому социальному строю, усилия по внедрению перемен не приносят желаемого эффекта.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','После нескольких попыток послужить Плети я осознал, что моим требованиям не отвечают даже самые высшие эшелоны данной организации. Учитывая неотъемлемое отсутствие гибкости, присущее любому социальному строю, усилия по внедрению перемен не приносят желаемого эффекта.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3257,'К счастью, данная организация предоставляет возможности для трудоустройства даже увечным, неизлечимо больным или – как в моем случае – усопшим индивидуумам.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К счастью, данная организация предоставляет возможности для трудоустройства даже увечным, неизлечимо больным или – как в моем случае – усопшим индивидуумам.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3258,'Мне пришлось познать на себе одну истину: ледяное прикосновение смерти не приносит ничего, кроме разочарования. Да, теперь я свободен от смертных обязательств, но не испытываю от этого облегчения, ибо мне больше нечем его испытывать. Я просто существую. Я могу лишь надеяться погибнуть вновь, в эпической битве, от руки благородного и чистого духом воина.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мне пришлось познать на себе одну истину: ледяное прикосновение смерти не приносит ничего, кроме разочарования. Да, теперь я свободен от смертных обязательств, но не испытываю от этого облегчения, ибо мне больше нечем его испытывать. Я просто существую. Я могу лишь надеяться погибнуть вновь, в эпической битве, от руки благородного и чистого духом воина.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3259,'Некрополь был отозван назад, к Ледяной Короне. Мы получили подкрепление и продовольствие, и город снова ожил! Но я изменился. Я чувствую себя более собранным. Более живым, чем когда-либо. Меня восхищает совершенство моего Господина. Теперь я знаю, в чем заключается мой долг, и когда воины придут, им придется пережить встречу со мной.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Некрополь был отозван назад, к Ледяной Короне. Мы получили подкрепление и продовольствие, и город снова ожил! Но я изменился. Я чувствую себя более собранным. Более живым, чем когда-либо. Меня восхищает совершенство моего Господина. Теперь я знаю, в чем заключается мой долг, и когда воины придут, им придется пережить встречу со мной.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3260,'Моооооооооззззг. Моооооооосссссзззззг. МОООЗЗЗЗЗССССГ!!!\r\n\r\n<И так еще на сорок страниц.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Моооооооооззззг. Моооооооосссссзззззг. МОООЗЗЗЗЗССССГ!!!\r\n\r\n<И так еще на сорок страниц.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3279,'Прислужники, слушайте зов вашего повелителя! Король-лич даровал Дракуру всю власть над армиями Плети в Зул\'Драке. Наш приказ – убить всех!$B$BУМЕРЕТЬ ДОЛЖНЫ ВСЕ!$B$BВсе трупы будут обрабатываться в Мертвых полях и посылаться к Принцу Навариусу в Зерамас для превращения в воинов Плети! Ничто не должно пропасть зря!$B$BСкоро мы будем пить кровь пророков и станем самым сильными! Плеть раздавит Зул\'Драк и Гундрак!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Прислужники, слушайте зов вашего повелителя! Король-лич даровал Дракуру всю власть над армиями Плети в Зул\'Драке. Наш приказ – убить всех!$B$BУМЕРЕТЬ ДОЛЖНЫ ВСЕ!$B$BВсе трупы будут обрабатываться в Мертвых полях и посылаться к Принцу Навариусу в Зерамас для превращения в воинов Плети! Ничто не должно пропасть зря!$B$BСкоро мы будем пить кровь пророков и станем самым сильными! Плеть раздавит Зул\'Драк и Гундрак!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3301,'<Дальнейшие записи дневника разобрать невозможно.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Дальнейшие записи дневника разобрать невозможно.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3302,'Задай вопрос магу!\r\n\r\nВ: Друзья говорят, что занятия магией не придадут мне популярности среди девушек, потому что все маги – слабые и вялые. Это правда? \r\n-Джимми Таунсенд по прозвищу "Хиляк"') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Задай вопрос магу!\r\n\r\nВ: Друзья говорят, что занятия магией не придадут мне популярности среди девушек, потому что все маги – слабые и вялые. Это правда? \r\n-Джимми Таунсенд по прозвищу "Хиляк"',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3303,'О: Не волнуйся, Джимми. Твои друзья пали жертвой стереотипов, в формировании которых повинны некоторые ленивые маги, злоупотребляющие нездоровой пищей. Ничто не мешает тебе поддерживать отличную физическую форму, и в то же самое время совершенствоваться в искусстве управления основами вселенной. Даже члены Кирин-Тор находят время в своем плотном расписании для силовых упражнений, которые, вкупе со строгой диетой, дают потрясающие результаты.\r\nА напоследок спроси себя – какая девушка сможет пройти мимо парня, владеющего искусством Превращения?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','О: Не волнуйся, Джимми. Твои друзья пали жертвой стереотипов, в формировании которых повинны некоторые ленивые маги, злоупотребляющие нездоровой пищей. Ничто не мешает тебе поддерживать отличную физическую форму, и в то же самое время совершенствоваться в искусстве управления основами вселенной. Даже члены Кирин-Тор находят время в своем плотном расписании для силовых упражнений, которые, вкупе со строгой диетой, дают потрясающие результаты.\r\nА напоследок спроси себя – какая девушка сможет пройти мимо парня, владеющего искусством Превращения?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3304,'В: Родители не одобряют мой выбор профессии. Они говорят, что волшебство опасно и может привести к зависимости от более "тяжелых" форм магии – например, демонологии. А я не хочу продавать свою душу непонятно кому!\r\n-Джозеф Винтерс\r\n\r\nО: Страхи твоих родителей абсолютно необоснованны. Наверняка они просто услышали какую-нибудь байку о волшебнике, который увлекся некромантией или поклонением демонам, но подобных случаев не было за всю историю магии. Постарайся убедить маму и папу, что им совершенно не о чем волноваться.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В: Родители не одобряют мой выбор профессии. Они говорят, что волшебство опасно и может привести к зависимости от более "тяжелых" форм магии – например, демонологии. А я не хочу продавать свою душу непонятно кому!\r\n-Джозеф Винтерс\r\n\r\nО: Страхи твоих родителей абсолютно необоснованны. Наверняка они просто услышали какую-нибудь байку о волшебнике, который увлекся некромантией или поклонением демонам, но подобных случаев не было за всю историю магии. Постарайся убедить маму и папу, что им совершенно не о чем волноваться.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3305,'В: Я лишь недавно начал изучать магию, и мои друзья постоянно издеваются надо мной. Они только и делают, что просят меня сотворить им какую-нибудь еду, питье или телепорт за два квартала. Когда уже они начнут меня бояться? \r\n-Грегори Адамс по прозвищу "Тряпка"\r\n\r\nО: Как только ты выучишь заклинание "Oгненная глыба".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В: Я лишь недавно начал изучать магию, и мои друзья постоянно издеваются надо мной. Они только и делают, что просят меня сотворить им какую-нибудь еду, питье или телепорт за два квартала. Когда уже они начнут меня бояться? \r\n-Грегори Адамс по прозвищу "Тряпка"\r\n\r\nО: Как только ты выучишь заклинание "Oгненная глыба".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3306,'Многие считают магов замкнутыми и необщительными эгоистами, но это совершенно не так. Большинство волшебников – очень заботливые и внимательные к нуждам других люди. Они посвящают себя изучению тайных знаний, чтобы служить на благо другим. Хотите знать, чем маг может вам помочь? Спросите меня!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Многие считают магов замкнутыми и необщительными эгоистами, но это совершенно не так. Большинство волшебников – очень заботливые и внимательные к нуждам других люди. Они посвящают себя изучению тайных знаний, чтобы служить на благо другим. Хотите знать, чем маг может вам помочь? Спросите меня!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3307,'Допустим, вы боитесь выступать перед публикой. Представьте себе вашу аудиторию в виде стада овец. Не помогает? Обратитесь к магу, и он действительно превратит ваших слушателей в баранов! \r\n\r\nПопросите вашего друга-волшебника наложить на вас чары медлительности и наслаждайтесь спокойным течением времени. Очень рекомендую подобные чары на скачках!\r\n\r\nСамый удобный способ добраться до нужного места – это телепортация. И помните – ничто так не понижает ваши шансы у противоположного пола, как исходящий от вас ЗДП. (запах дракона пустоты).') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Допустим, вы боитесь выступать перед публикой. Представьте себе вашу аудиторию в виде стада овец. Не помогает? Обратитесь к магу, и он действительно превратит ваших слушателей в баранов! \r\n\r\nПопросите вашего друга-волшебника наложить на вас чары медлительности и наслаждайтесь спокойным течением времени. Очень рекомендую подобные чары на скачках!\r\n\r\nСамый удобный способ добраться до нужного места – это телепортация. И помните – ничто так не понижает ваши шансы у противоположного пола, как исходящий от вас ЗДП. (запах дракона пустоты).',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3308,'Друг мага никогда не будет страдать от голода, жажды и ожирения – ведь волшебная пища не содержит трансгенных жиров.\r\n\r\nВы все еще думаете, что эль лучше всего охлаждать в замороженной кружке? Вы просто еще не видели кружку из чистого льда! \r\n\r\nИсследования показывают, что самые шедевральные произведения искусства были созданы под магическим воздействием.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Друг мага никогда не будет страдать от голода, жажды и ожирения – ведь волшебная пища не содержит трансгенных жиров.\r\n\r\nВы все еще думаете, что эль лучше всего охлаждать в замороженной кружке? Вы просто еще не видели кружку из чистого льда! \r\n\r\nИсследования показывают, что самые шедевральные произведения искусства были созданы под магическим воздействием.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3309,'Попросите знакомого мага создать снежную бурю на праздник Зимнего Покрова. (Внимание: нахождение в центре магической снежной бури может привести к обморожению и смерти.)\r\n\r\nИ самое главное, никогда не забывайте о том, что магам все нипочем!\r\n\r\nЭтот буклет напечатан на волшебной бумаге.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Попросите знакомого мага создать снежную бурю на праздник Зимнего Покрова. (Внимание: нахождение в центре магической снежной бури может привести к обморожению и смерти.)\r\n\r\nИ самое главное, никогда не забывайте о том, что магам все нипочем!\r\n\r\nЭтот буклет напечатан на волшебной бумаге.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3350,'А когда, наконец, он отважился посмотреть по сторонам, дерева больше не было. На его месте стояла прекрасная ночная эльфийка. "Сработало!" – воскликнул бедняга. – "У меня получилось превратить дерево! Я стал настоящим волшебником!" \r\n\r\nНочная эльфийка растерянно оглянулась и, наконец, поняла в чем дело. "Я друид, глупышка!" – улыбнулась она. – "Мы меняем форму по своему желанию".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','А когда, наконец, он отважился посмотреть по сторонам, дерева больше не было. На его месте стояла прекрасная ночная эльфийка. "Сработало!" – воскликнул бедняга. – "У меня получилось превратить дерево! Я стал настоящим волшебником!" \r\n\r\nНочная эльфийка растерянно оглянулась и, наконец, поняла в чем дело. "Я друид, глупышка!" – улыбнулась она. – "Мы меняем форму по своему желанию".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3351,'Бангледорф зарделся от стыда и сделал шаг назад, но споткнулся о подол своего плаща. Сопровождаемый издевательским смехом, он напялил на голову свою остроконечную шляпу и побрел в свою комнату, повесив голову.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Бангледорф зарделся от стыда и сделал шаг назад, но споткнулся о подол своего плаща. Сопровождаемый издевательским смехом, он напялил на голову свою остроконечную шляпу и побрел в свою комнату, повесив голову.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3352,'Ночная эльфийка долго смотрела ему вслед, думая о незадачливом волшебнике. Но когда она уже собралась уходить, ее нога зацепилась за что-то, чего раньше не было. Изумленная, она посмотрела на землю и обнаружила роскошный куст магорозы, расцветающий во всей своей красе. Девушка восторженно обернулась, чтобы окликнуть Бангледорфа, но юного мага уже и след простыл.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ночная эльфийка долго смотрела ему вслед, думая о незадачливом волшебнике. Но когда она уже собралась уходить, ее нога зацепилась за что-то, чего раньше не было. Изумленная, она посмотрела на землю и обнаружила роскошный куст магорозы, расцветающий во всей своей красе. Девушка восторженно обернулась, чтобы окликнуть Бангледорфа, но юного мага уже и след простыл.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3360,'Все школы магии зачастую пересекаются для плетения крайне могущественных заклинаний, использующих различные источники силы. Это очень опасные заклятия для начинающих, поэтому вы познакомитесь с ними только на старших курсах. \r\n\r\n	Для начала вам придется усвоить основы всех школ магии. Помните, что волшебство – это не игрушка. Не занимайтесь магией без присмотра преподавателя.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Все школы магии зачастую пересекаются для плетения крайне могущественных заклинаний, использующих различные источники силы. Это очень опасные заклятия для начинающих, поэтому вы познакомитесь с ними только на старших курсах. \r\n\r\n	Для начала вам придется усвоить основы всех школ магии. Помните, что волшебство – это не игрушка. Не занимайтесь магией без присмотра преподавателя.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3366,'<Написано рукой верховного мага Ансарема Руноплета>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Написано рукой верховного мага Ансарема Руноплета>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3367,'Созидание – это наука о сотворении существ и объектов. Вам приходилось когда-нибудь умирать от жажды или испытывать муки голода? Эти неудобства неведомы магам, искусным в созидании. Призвать ломоть свежего хлеба или стакан воды – что может быть проще даже для начинающего волшебника?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Созидание – это наука о сотворении существ и объектов. Вам приходилось когда-нибудь умирать от жажды или испытывать муки голода? Эти неудобства неведомы магам, искусным в созидании. Призвать ломоть свежего хлеба или стакан воды – что может быть проще даже для начинающего волшебника?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3368,'Более опытные заклинатели могут создать сразу несколько стаканов воды – или даже бочку. А некоторые бесстрашные маги призывали потоки воды, забыв про создание вместилища – и таким образом создавали водяных элементалей. Элементали – в отличие от гончих скверны – это лучшие друзья волшебника: они не ведают страха в бою, всегда готовы вас выслушать и к тому же приятны на вкус!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Более опытные заклинатели могут создать сразу несколько стаканов воды – или даже бочку. А некоторые бесстрашные маги призывали потоки воды, забыв про создание вместилища – и таким образом создавали водяных элементалей. Элементали – в отличие от гончих скверны – это лучшие друзья волшебника: они не ведают страха в бою, всегда готовы вас выслушать и к тому же приятны на вкус!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3369,'Среди волшебников, специализирующихся на школе созидания, можно выделить несколько ярких личностей. Капитан Балинда Каменный Очаг – превосходный пример боевого мага, использующего созидание на поле битвы. Однако, среди наиболее известных созидателей нашего времени нельзя не упомянуть верховного мага Нилеаса Арана. Он известен не только выдающимися способностями созидать нескольких элементалей одновременно, но и своим знаменитым рецептом магического игристого сидра.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Среди волшебников, специализирующихся на школе созидания, можно выделить несколько ярких личностей. Капитан Балинда Каменный Очаг – превосходный пример боевого мага, использующего созидание на поле битвы. Однако, среди наиболее известных созидателей нашего времени нельзя не упомянуть верховного мага Нилеаса Арана. Он известен не только выдающимися способностями созидать нескольких элементалей одновременно, но и своим знаменитым рецептом магического игристого сидра.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3373,'Легендарный верховный маг Медив считается наиболее могущественным провидцем нашего времени. С помощью заклинаний он может заглянуть в Дренор, не покидая пределы Азерота. Мы можем только предполагать, насколько далеко простираются его способности.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Легендарный верховный маг Медив считается наиболее могущественным провидцем нашего времени. С помощью заклинаний он может заглянуть в Дренор, не покидая пределы Азерота. Мы можем только предполагать, насколько далеко простираются его способности.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3374,'<Написано рукой верховного мага Ансарема Руноплета>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Написано рукой верховного мага Ансарема Руноплета>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3375,'Наложение чар – это процесс наделения предмета или живого существа магической мощью. Одни чары могут действовать недолго, а другие усиляют предмет навсегда. Обучиться наложению чар непросто, но это одно из самых востребованных магических искусств. Я очень рекомендую всем изучать наложения чар, ибо заклинания этой школы магии крайне редко приводят к несчастным случаям.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наложение чар – это процесс наделения предмета или живого существа магической мощью. Одни чары могут действовать недолго, а другие усиляют предмет навсегда. Обучиться наложению чар непросто, но это одно из самых востребованных магических искусств. Я очень рекомендую всем изучать наложения чар, ибо заклинания этой школы магии крайне редко приводят к несчастным случаям.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3376,'Распыление – это процесс рассеивания магии, способный зачастую обратить вспять катастрофический эффект неверно прочитанного заклинания. С его помощью можно также снять чары с предмета, наделенного вошебной силой, в результате чего энергия превращается в кристаллизированную ману, которую можно использовать для наложения чар на другой предмет. Несмотря на довольно высокую стоимость подобной волшебной пыли, я рекомендую своим студентам использовать ее для практики в наложении чар.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Распыление – это процесс рассеивания магии, способный зачастую обратить вспять катастрофический эффект неверно прочитанного заклинания. С его помощью можно также снять чары с предмета, наделенного вошебной силой, в результате чего энергия превращается в кристаллизированную ману, которую можно использовать для наложения чар на другой предмет. Несмотря на довольно высокую стоимость подобной волшебной пыли, я рекомендую своим студентам использовать ее для практики в наложении чар.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3377,'Несмотря на то, что я уже упоминал принца Кель\'таса Солнечного Скитальца как одного из наиболее известных магов школы ограждения, нельзя не отметить его исключительный дар в наложении чар. Он не только усовершенствовал процесс создания оружия, наделенного магической мощью, но и научился управлять предметами на расстоянии. Таким образом он может сражаться даже с превосходящим по численности противником.  Не правда ли, это впечатляет?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Несмотря на то, что я уже упоминал принца Кель\'таса Солнечного Скитальца как одного из наиболее известных магов школы ограждения, нельзя не отметить его исключительный дар в наложении чар. Он не только усовершенствовал процесс создания оружия, наделенного магической мощью, но и научился управлять предметами на расстоянии. Таким образом он может сражаться даже с превосходящим по численности противником.  Не правда ли, это впечатляет?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3384,'Некромантия – это раздел магии, изучающий смерть и ее последствия. Подобные изыскания незаконны и крайне опасны, и поэтому я упоминаю эту школу только для вашего общего развития. Любой волшебник должен досконально знать, какими видами магии может владеть его противник – а любой маг, практикующий некромантию, должен быть автоматически зачислен в список ваших врагов. Некроманты и их последователи отрицают саму идею жизни, и столкновения с ними лучше избегать любой ценой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Некромантия – это раздел магии, изучающий смерть и ее последствия. Подобные изыскания незаконны и крайне опасны, и поэтому я упоминаю эту школу только для вашего общего развития. Любой волшебник должен досконально знать, какими видами магии может владеть его противник – а любой маг, практикующий некромантию, должен быть автоматически зачислен в список ваших врагов. Некроманты и их последователи отрицают саму идею жизни, и столкновения с ними лучше избегать любой ценой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3385,'Эта магия способна не только оживлять умерших и создавать ходячих мертвецов. Мастера некромантии могут насылать болезни, превращать тени в стрелы обжигающей энергии и даже осквернять живущих прикосновением смерти. А благодаря заклинаниям, возрождающим плоть неживых существ, созданных с помощью этой магии чудовищ крайне тяжело уничтожить.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Эта магия способна не только оживлять умерших и создавать ходячих мертвецов. Мастера некромантии могут насылать болезни, превращать тени в стрелы обжигающей энергии и даже осквернять живущих прикосновением смерти. А благодаря заклинаниям, возрождающим плоть неживых существ, созданных с помощью этой магии чудовищ крайне тяжело уничтожить.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3386,'Наиболее известным последователем некромантии является бывший верховный маг Кел\'Тузад, причастный к распространению Плети и падению Лордерона. В настоящий момент Кел\'Тузад в облике лича правит парящей крепостью Наксрамас и по-прежнему представляет угрозу для всех живых существ.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Наиболее известным последователем некромантии является бывший верховный маг Кел\'Тузад, причастный к распространению Плети и падению Лордерона. В настоящий момент Кел\'Тузад в облике лича правит парящей крепостью Наксрамас и по-прежнему представляет угрозу для всех живых существ.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3387,'<Написано рукой верховного мага Ансарема Руноплета>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Написано рукой верховного мага Ансарема Руноплета>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3388,'Девятая и последняя школа магии занимается преобразованием. Это одна из самых популярных дисциплин, позволяющих магу манипулировать временем и пространством. Наиболее известное заклинание этой школы – Превращение, с помощью которого волшебник может изменить форму любого существа или предмета. К счастью для многих моих учеников, действие этого заклинания легко обратимо. Мне приходилось видеть студентов, случайно превративших себя в овцу, свинью или кое-что похуже – даже не спрашивайте меня, что это значит.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Девятая и последняя школа магии занимается преобразованием. Это одна из самых популярных дисциплин, позволяющих магу манипулировать временем и пространством. Наиболее известное заклинание этой школы – Превращение, с помощью которого волшебник может изменить форму любого существа или предмета. К счастью для многих моих учеников, действие этого заклинания легко обратимо. Мне приходилось видеть студентов, случайно превративших себя в овцу, свинью или кое-что похуже – даже не спрашивайте меня, что это значит.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3389,'Второе и не менее важное изобретение школы преобразования – телепортация (и его базовая разновидность, известная как "скачок"). Это заклинание спасло жизнь не одному магу, столкнувшемуся с превосходящим по силам противником или случайно упавшему со скалы. Однако я не рекомендую вам злоупотреблять такой возможностью – телепортатор, как и сапер, ошибается только раз в жизни.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Второе и не менее важное изобретение школы преобразования – телепортация (и его базовая разновидность, известная как "скачок"). Это заклинание спасло жизнь не одному магу, столкнувшемуся с превосходящим по силам противником или случайно упавшему со скалы. Однако я не рекомендую вам злоупотреблять такой возможностью – телепортатор, как и сапер, ошибается только раз в жизни.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3390,'Перед активированием телепорта убедитесь, что вы точно рассчитали место назначения. Именно по этой причине я рекомендую пользоваться заклинаниями с привязкой к конкретному месту – спонтанные телепортации чаще всего заканчиваются смертью мага, оказавшегося внутри скалы, мебели или другого мага. К сожалению, бывали и такие случаи.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Перед активированием телепорта убедитесь, что вы точно рассчитали место назначения. Именно по этой причине я рекомендую пользоваться заклинаниями с привязкой к конкретному месту – спонтанные телепортации чаще всего заканчиваются смертью мага, оказавшегося внутри скалы, мебели или другого мага. К сожалению, бывали и такие случаи.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3391,'К этой же школе относятся заклинания, управляющие ходом времени – например, известное всем "замедленное падение", способное уберечь мага, сорвавшегося с большой высоты (и гораздо более надежное, чем Скачок). Более опытные волшебники способны значительно замедлить противника. До меня доходили слухи о существовании заклинания, ускоряющего ваши собственные движения, но я никогда не видел ничего подобного на практике.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','К этой же школе относятся заклинания, управляющие ходом времени – например, известное всем "замедленное падение", способное уберечь мага, сорвавшегося с большой высоты (и гораздо более надежное, чем Скачок). Более опытные волшебники способны значительно замедлить противника. До меня доходили слухи о существовании заклинания, ускоряющего ваши собственные движения, но я никогда не видел ничего подобного на практике.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3392,'Леди Джайна Праудмур – наиболее опытная волшебница, посвятившая себя искусству преобразовательной магии. Она разработала эффективную вариацию заклинания массовой телепортации, которая способна переместить значительную часть армии в другое место с минимальной затратой энергии, что делает ее весьма непредсказуемым соперником на поле битвы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Леди Джайна Праудмур – наиболее опытная волшебница, посвятившая себя искусству преобразовательной магии. Она разработала эффективную вариацию заклинания массовой телепортации, которая способна переместить значительную часть армии в другое место с минимальной затратой энергии, что делает ее весьма непредсказуемым соперником на поле битвы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3397,'В современном Азероте нас подстерегает много соблазнов, которые могут побудить вас отказаться от спокойной жизни и ступить на опасную тропу изучения магии. Но мы всегда поможем вам вернуться на путь истинный! Десятки людей уже примкнули к нашему движению и отказались от увлечения магией ради более полезных, духовных альтернатив. Хотите стать одним из нас?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В современном Азероте нас подстерегает много соблазнов, которые могут побудить вас отказаться от спокойной жизни и ступить на опасную тропу изучения магии. Но мы всегда поможем вам вернуться на путь истинный! Десятки людей уже примкнули к нашему движению и отказались от увлечения магией ради более полезных, духовных альтернатив. Хотите стать одним из нас?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3409,'Последствия Второй войны затронули и хрупкий Альянс, затрещавший под гнетом увеличившихся налогов на содержание лагерей для военнопленных. В отсутствии общего врага на первый план снова вышли тонкости политики и мелкие стычки между расами, которые беспокоили азеротские государства еще до вторжения орков с Дренора во время Первой войны.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Последствия Второй войны затронули и хрупкий Альянс, затрещавший под гнетом увеличившихся налогов на содержание лагерей для военнопленных. В отсутствии общего врага на первый план снова вышли тонкости политики и мелкие стычки между расами, которые беспокоили азеротские государства еще до вторжения орков с Дренора во время Первой войны.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3410,'Вдобавок ко всему с севера нагрянула чума. Взявшись за расследование причин возникновения эпидемии, Антонидас обнаружил, что за распространением заболевания стоит бывший член Кирин-Тор, некий Кел\'Тузад, увлекшийся изучением некромантии. Так Антонидас пришел к выводу, что чума может быть магической по происхождению. Возглавляемые верховным магом, правители Даларана решили объявить карантин на зараженных территориях.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вдобавок ко всему с севера нагрянула чума. Взявшись за расследование причин возникновения эпидемии, Антонидас обнаружил, что за распространением заболевания стоит бывший член Кирин-Тор, некий Кел\'Тузад, увлекшийся изучением некромантии. Так Антонидас пришел к выводу, что чума может быть магической по происхождению. Возглавляемые верховным магом, правители Даларана решили объявить карантин на зараженных территориях.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3411,'Опасаясь за последствия такого решения, король Теренас отказался последовать решению совета. И именно в тот момент к верховному магу пожаловал пророк, который предупредил Антонидаса о распространении чумы и предсказал падение Азерота. Он велел Антоидосу собрать своих людей и отправить на запад, в Калимдор, утверждая, что это единственный способ спасти народ Даларана.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Опасаясь за последствия такого решения, король Теренас отказался последовать решению совета. И именно в тот момент к верховному магу пожаловал пророк, который предупредил Антонидаса о распространении чумы и предсказал падение Азерота. Он велел Антоидосу собрать своих людей и отправить на запад, в Калимдор, утверждая, что это единственный способ спасти народ Даларана.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3412,'Антонидасу на тот момент уже минуло семьдесят лет. Он был мудр, но в то же самое время крайне осторожен и упрям. Его ученица, леди Джайна Праудмур, почувствовала великую силу пророка и посоветовала прислушаться к его словам, но верховный маг не принял во внимание ее рекомендации и посчитал старца обычным безумцем.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Антонидасу на тот момент уже минуло семьдесят лет. Он был мудр, но в то же самое время крайне осторожен и упрям. Его ученица, леди Джайна Праудмур, почувствовала великую силу пророка и посоветовала прислушаться к его словам, но верховный маг не принял во внимание ее рекомендации и посчитал старца обычным безумцем.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3413,'Антонидас принял решение продолжить расследование причин возникновения чумы на севере, ибо в этих исследованиях он видел путь к спасению своего города. Результаты этих изысканий можно прочитать в книге "Дневник верховного мага Антонидаса". Известно то, что он привлек к своей работе Дажйну, к которой должен был вскоре присоединиться принц Артас Менетил.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Антонидас принял решение продолжить расследование причин возникновения чумы на севере, ибо в этих исследованиях он видел путь к спасению своего города. Результаты этих изысканий можно прочитать в книге "Дневник верховного мага Антонидаса". Известно то, что он привлек к своей работе Дажйну, к которой должен был вскоре присоединиться принц Артас Менетил.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3432,'8 окт.\r\n\r\nКажется, я уже писал, что мне беспокоит потенциальная угроза, исходящая от заклинаний некоторых школ магии, и сравнительно слабые ограничения на их использование. Более того, углубленное изучение этих дисциплин приводит к снижению уровня академических знаний и повышению количества несчастных случаев среди студентов.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','8 окт.\r\n\r\nКажется, я уже писал, что мне беспокоит потенциальная угроза, исходящая от заклинаний некоторых школ магии, и сравнительно слабые ограничения на их использование. Более того, углубленное изучение этих дисциплин приводит к снижению уровня академических знаний и повышению количества несчастных случаев среди студентов.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3434,'Я делаю все возможное для того, чтобы ограничить доступ учеников к знаниям по магии скверны и некромантии, но меня по-прежнему пугает – и в то же самое время восхищает -потенциал этих направлений. Я отказываюсь верить, что мысли об их эффективности могут заглушить голос разума, который призывает нас к осторожности при работе с чем-то столь ненадежным и зловещим; не хочу даже думать о том, что в этих школах заложен ключ к магическому прогрессу. Однако, наблюдая собственными глазами их непередаваемую мощь, способную уничтожить несколько акров земли один мановением руки, я опасаюсь, что мои убеждения вскоре могут пошатнуться.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я делаю все возможное для того, чтобы ограничить доступ учеников к знаниям по магии скверны и некромантии, но меня по-прежнему пугает – и в то же самое время восхищает -потенциал этих направлений. Я отказываюсь верить, что мысли об их эффективности могут заглушить голос разума, который призывает нас к осторожности при работе с чем-то столь ненадежным и зловещим; не хочу даже думать о том, что в этих школах заложен ключ к магическому прогрессу. Однако, наблюдая собственными глазами их непередаваемую мощь, способную уничтожить несколько акров земли один мановением руки, я опасаюсь, что мои убеждения вскоре могут пошатнуться.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3435,'16 окт.\r\n\r\nВ последнее время я полностью сосредоточился на изучении происхождения эпидемии чумы, возникшей на севере. Я отменил большую часть занятий, не желая отвлекаться от исследования этой чудовищной аномалии. \r\nПриняв беспрецедентные меры предосторожности, я доставил в лабораторию образец зараженного зерна. Простота и смертельная эффективность такого метода распространения заразы одновременно потрясла меня и ужаснула. Зачумленное зерно ничем не отличается от обычного – ни запахом, ни окраской, ни весом.\r\nВо всяком случае, теперь мне достоверно известно, каким образом чума так быстро охватила огромные территории.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','16 окт.\r\n\r\nВ последнее время я полностью сосредоточился на изучении происхождения эпидемии чумы, возникшей на севере. Я отменил большую часть занятий, не желая отвлекаться от исследования этой чудовищной аномалии. \r\nПриняв беспрецедентные меры предосторожности, я доставил в лабораторию образец зараженного зерна. Простота и смертельная эффективность такого метода распространения заразы одновременно потрясла меня и ужаснула. Зачумленное зерно ничем не отличается от обычного – ни запахом, ни окраской, ни весом.\r\nВо всяком случае, теперь мне достоверно известно, каким образом чума так быстро охватила огромные территории.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3437,'Было бы наивно предполагать, что столь эффективный истребитель человеческой расы случайно появился в районах, густо населенных людьми. Хотя чисто теоретически такое совпадение возможно, я принял решение бросить все силы на дальнейшее расследование причин возникновения эпидемии, ибо я беспокоюсь, что за этой чумой может стоять чья-то злая воля. \r\n\r\nОднако, мои изыскания в Даларане подошли к концу. Я должен решить, кто займется исследованиями на месте возникновения чумы.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Было бы наивно предполагать, что столь эффективный истребитель человеческой расы случайно появился в районах, густо населенных людьми. Хотя чисто теоретически такое совпадение возможно, я принял решение бросить все силы на дальнейшее расследование причин возникновения эпидемии, ибо я беспокоюсь, что за этой чумой может стоять чья-то злая воля. \r\n\r\nОднако, мои изыскания в Даларане подошли к концу. Я должен решить, кто займется исследованиями на месте возникновения чумы.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3438,'18 окт.\r\n\r\nЯ натолкнулся на ключевой фактор распространения чумы – столь тщательно скрытый в самой ее сути, что мне пришлось отбросить последние сомнения в том, что эта эпидемия была вызвана с единственной целью – истребить все человечество. Теперь я уверен в том, что за ее распространением стоит некий изощренный в своей жестокости разум. \r\nОказалось, что смерть не является последней стадией заболевания; чума приводит к последующему воскрешению мертвого тела и превращению его в нежить. Изначально этот эффект наблюдался достаточно редко, в связи с чем я счел его незначительным побочным действием, но с течением времени тенденция сохранилась, что натолкнуло меня на ужасающую мысль: что если трупы были предназначены для выполнения какой-то миссии?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','18 окт.\r\n\r\nЯ натолкнулся на ключевой фактор распространения чумы – столь тщательно скрытый в самой ее сути, что мне пришлось отбросить последние сомнения в том, что эта эпидемия была вызвана с единственной целью – истребить все человечество. Теперь я уверен в том, что за ее распространением стоит некий изощренный в своей жестокости разум. \r\nОказалось, что смерть не является последней стадией заболевания; чума приводит к последующему воскрешению мертвого тела и превращению его в нежить. Изначально этот эффект наблюдался достаточно редко, в связи с чем я счел его незначительным побочным действием, но с течением времени тенденция сохранилась, что натолкнуло меня на ужасающую мысль: что если трупы были предназначены для выполнения какой-то миссии?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3439,'В тот момент у меня не было никаких подтверждений этой версии, но я продолжил изыскания в этом направлении. Мне пришлось воспользоваться своими незначительными познаниями в некромантии, чтобы прочитать несколько простых заклинаний над трупом. В тот момент я не намеревался воскрешать несчастного покойника – мне всего лишь хотелось измерить поток энергии, исходивший от мертвеца. Представьте мое удивление, когда покойник внезапно ожил и набросился на меня!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','В тот момент у меня не было никаких подтверждений этой версии, но я продолжил изыскания в этом направлении. Мне пришлось воспользоваться своими незначительными познаниями в некромантии, чтобы прочитать несколько простых заклинаний над трупом. В тот момент я не намеревался воскрешать несчастного покойника – мне всего лишь хотелось измерить поток энергии, исходивший от мертвеца. Представьте мое удивление, когда покойник внезапно ожил и набросился на меня!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3440,'Я, не раздумывая, испепелил его на месте, о чем не раз пожалел в дальнейшем. Но теперь у меня были доказательства того, что трупы жертв чумы действительно ожидали момента, чтобы быть пробужденными чей-то зловещей волей. Очевидно, что в какой-то момент погибшие люди должны были восстать из своих могил, повинуясь велению некоего бесспорно великого некроманта.\r\n\r\n Отныне у меня не осталось сомнений в том, что эта чума – магическая по своей природе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Я, не раздумывая, испепелил его на месте, о чем не раз пожалел в дальнейшем. Но теперь у меня были доказательства того, что трупы жертв чумы действительно ожидали момента, чтобы быть пробужденными чей-то зловещей волей. Очевидно, что в какой-то момент погибшие люди должны были восстать из своих могил, повинуясь велению некоего бесспорно великого некроманта.\r\n\r\n Отныне у меня не осталось сомнений в том, что эта чума – магическая по своей природе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3441,'20 окт.\r\n\r\nЯ решил поручить расследование причин возникновения чумы моей самой талантливой ученице, Джайне Праудмур. Учитывая результаты моих исследований, только она сможет справиться с теми препятствиями, которые могут возникнуть на пути к истине. Она заберет с собой копию этого дневника и прочие документы, связанные с изучением чумы. Разумеется, я намереваюсь их опубликовать. Люди должны знать правду о надвигающейся угрозе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','20 окт.\r\n\r\nЯ решил поручить расследование причин возникновения чумы моей самой талантливой ученице, Джайне Праудмур. Учитывая результаты моих исследований, только она сможет справиться с теми препятствиями, которые могут возникнуть на пути к истине. Она заберет с собой копию этого дневника и прочие документы, связанные с изучением чумы. Разумеется, я намереваюсь их опубликовать. Люди должны знать правду о надвигающейся угрозе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3442,'Признаться, мне хотелось бы самому заняться дальнейшими исследованиями, но Теренас остается предсказуемо глух к моим просьбам. Мне необходимо убедить его ввести карантин на севере – это наиболее важная задача, стоящая перед нами на настоящий момент. В любом случае, я полностью доверяю мудрости Джайны. Если она не сможет довести это расследование до конца, то ее уже никто не заменит.\r\n\r\n-Антонидас-\r\n<Запечатано знаком Совета Шести>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Признаться, мне хотелось бы самому заняться дальнейшими исследованиями, но Теренас остается предсказуемо глух к моим просьбам. Мне необходимо убедить его ввести карантин на севере – это наиболее важная задача, стоящая перед нами на настоящий момент. В любом случае, я полностью доверяю мудрости Джайны. Если она не сможет довести это расследование до конца, то ее уже никто не заменит.\r\n\r\n-Антонидас-\r\n<Запечатано знаком Совета Шести>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3443,'Мы не ставим перед собой цель полностью вытеснить из употребления традиционные методы перемещения – корабли, дирижабли и ездовых животных. Данные виды транспорта дешевы, удобны и безопасны. Однако правильно установленный портал не менее надежен и гораздо более практичен. К сожалению, открытие порталов для общего пользования – крайне энергоемкий процесс. Из всех заклинаний, придуманных и разработанных Кирин-Тором, телепортация наиболее близко подошла к тому, чтобы быть включенной в список чар, используемых только в крайних случаях.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы не ставим перед собой цель полностью вытеснить из употребления традиционные методы перемещения – корабли, дирижабли и ездовых животных. Данные виды транспорта дешевы, удобны и безопасны. Однако правильно установленный портал не менее надежен и гораздо более практичен. К сожалению, открытие порталов для общего пользования – крайне энергоемкий процесс. Из всех заклинаний, придуманных и разработанных Кирин-Тором, телепортация наиболее близко подошла к тому, чтобы быть включенной в список чар, используемых только в крайних случаях.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3444,'Почему это произошло? Прежде всего, из-за того, что силовые линии не растут на деревьях. Чрезмерное использование одного луча изнашивает его структуру по всему Азероту. Поэтому мы устанавливаем фиксированную плату за использование порталов – эти деньги идут на замену оборудования, но все равно не могут покрыть все затраты по ремонту линии.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Почему это произошло? Прежде всего, из-за того, что силовые линии не растут на деревьях. Чрезмерное использование одного луча изнашивает его структуру по всему Азероту. Поэтому мы устанавливаем фиксированную плату за использование порталов – эти деньги идут на замену оборудования, но все равно не могут покрыть все затраты по ремонту линии.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3445,'Помните, что лучше всего окупаются массовые порталы, ибо на перемещение нескольких людей требуется меньше ресурсов силовой линии, чем на создание нового портала. В настоящий момент готовится к одобрению проект программы "Общий портал", которая будет предоставлять налоговые льготы для магов, создающих порталы не меньше, чем для пяти человек. Подробнее об этом законопроекте читайте в последнем выпуске "Вестника Кирин-Тора".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Помните, что лучше всего окупаются массовые порталы, ибо на перемещение нескольких людей требуется меньше ресурсов силовой линии, чем на создание нового портала. В настоящий момент готовится к одобрению проект программы "Общий портал", которая будет предоставлять налоговые льготы для магов, создающих порталы не меньше, чем для пяти человек. Подробнее об этом законопроекте читайте в последнем выпуске "Вестника Кирин-Тора".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3446,'Правильно созданный портал не менее надежен, чем путешествие на дирижабле (а возможно, даже более, учитывая инженерные способности отдельных гоблинов), но нарушение техники безопасности при работе с порталами может привести к серьезным последствиям. Предлагаем вашему вниманию список правил по телепортации:') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правильно созданный портал не менее надежен, чем путешествие на дирижабле (а возможно, даже более, учитывая инженерные способности отдельных гоблинов), но нарушение техники безопасности при работе с порталами может привести к серьезным последствиям. Предлагаем вашему вниманию список правил по телепортации:',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3447,'Правило #1: Не прокладывайте портал за пределы зоны высадки Кирин-Тора. Наибольшая опасность заклинания телепортации заключается в его потенциале. Мы понимаем, насколько велико искушение открыть дверь в любую точку пространства, и поэтому вынуждены назначить крайнюю меру наказания для ограждения магов от подобных действий. \r\nСвободный доступ к открытию порталов имеют владельцы особых прав D-6, но их выдача строго ограничена. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #1: Не прокладывайте портал за пределы зоны высадки Кирин-Тора. Наибольшая опасность заклинания телепортации заключается в его потенциале. Мы понимаем, насколько велико искушение открыть дверь в любую точку пространства, и поэтому вынуждены назначить крайнюю меру наказания для ограждения магов от подобных действий. \r\nСвободный доступ к открытию порталов имеют владельцы особых прав D-6, но их выдача строго ограничена. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3448,'Правило #2: Создавайте портал в отведенном для этого месте и соблюдайте технику безопасности при его использовании. Не открывайте портал под ногами людей. Не задерживайтесь при прохождении портала. Не используйте портал в качестве мусоропровода или щита. Не создавайте портал в качестве защиты от дождя и прочих стихийных явлений.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #2: Создавайте портал в отведенном для этого месте и соблюдайте технику безопасности при его использовании. Не открывайте портал под ногами людей. Не задерживайтесь при прохождении портала. Не используйте портал в качестве мусоропровода или щита. Не создавайте портал в качестве защиты от дождя и прочих стихийных явлений.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3449,'При прохождении портала не высовывайтесь назад и не пытайтесь схватиться за его внутренние или внешние края. Границы портала – это не поручни, и их разрушение может привести к несчастным случаям.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','При прохождении портала не высовывайтесь назад и не пытайтесь схватиться за его внутренние или внешние края. Границы портала – это не поручни, и их разрушение может привести к несчастным случаям.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3450,'Правило #3: Не пытайтесь хитростью или силой заставить другого человека пройти через портал. Это, во-первых, опасно, а во-вторых, пагубно влияет на вашу репутацию. (см правило #2).') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #3: Не пытайтесь хитростью или силой заставить другого человека пройти через портал. Это, во-первых, опасно, а во-вторых, пагубно влияет на вашу репутацию. (см правило #2).',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3451,'Правило #4: К использованию порталов не допускаются лица, сменившие форму, ибо это может привести к взрыву. Подробнее об этом читайте в брошюре "Правила использования заклинания превращения".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #4: К использованию порталов не допускаются лица, сменившие форму, ибо это может привести к взрыву. Подробнее об этом читайте в брошюре "Правила использования заклинания превращения".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3452,'Правило #5: Не исключайте фильтр воды из структуры заклинания. Матрица порталов не пропускает через себя большое количество текущей воды, и поэтому их можно использовать даже под водой. Если вы хотите провести через портал элементаля воды, опустите компонент фильтра, но не забудьте включить его при создании подводного портала! Дабы показать, к каким последствиям могут привести подобные ошибки, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 34-з: "Великий потоп в Приозерье и наводнение в Стальгорне, 24 г. НЭ".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #5: Не исключайте фильтр воды из структуры заклинания. Матрица порталов не пропускает через себя большое количество текущей воды, и поэтому их можно использовать даже под водой. Если вы хотите провести через портал элементаля воды, опустите компонент фильтра, но не забудьте включить его при создании подводного портала! Дабы показать, к каким последствиям могут привести подобные ошибки, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 34-з: "Великий потоп в Приозерье и наводнение в Стальгорне, 24 г. НЭ".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3453,'Правило #6: Стандартные размеры портала – 3 ярда, 1 фут, 3 и 3/4 дюйма в высоту, 2 ярда, 8 футов, 9 и 15/16 дюйма в ширину. Для создания портала двойной ширины требуется получение лицензии Г-16, которая выдается только после 8 лет использования обычных порталов. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.\r\n\r\n<В инструкции еще несколько сотен страниц.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #6: Стандартные размеры портала – 3 ярда, 1 фут, 3 и 3/4 дюйма в высоту, 2 ярда, 8 футов, 9 и 15/16 дюйма в ширину. Для создания портала двойной ширины требуется получение лицензии Г-16, которая выдается только после 8 лет использования обычных порталов. Для получения подобной лицензии обратитесь к мастеру порталов вашего города.\r\n\r\n<В инструкции еще несколько сотен страниц.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3456,'Правило #2: Пользуйтесь стандартным перечнем существ, рекомендованных для превращения. Многие маги выбирают в качестве объекта превращения экзотических тварей, но, чтобы снизить выплаты по страховым полисам, Кирин-Тор вынужден ограничить список рекомендованных для превращения существ. Наиболее подходящая форма для всех случаев – это овца (полный список приведен на страницах последнего выпуска "Вестника Кирин-Тор". Превращение в слизнюков, эфириалов, силитидов и драконов строжайше запрещено и карается по закону".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #2: Пользуйтесь стандартным перечнем существ, рекомендованных для превращения. Многие маги выбирают в качестве объекта превращения экзотических тварей, но, чтобы снизить выплаты по страховым полисам, Кирин-Тор вынужден ограничить список рекомендованных для превращения существ. Наиболее подходящая форма для всех случаев – это овца (полный список приведен на страницах последнего выпуска "Вестника Кирин-Тор". Превращение в слизнюков, эфириалов, силитидов и драконов строжайше запрещено и карается по закону".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3457,'Правило #3: Превращения следует осуществлять в специально отведенных для этого местах. Не выставляйте напоказ чудовищные поганища, возникшие в результате неудачных превращений. Кирин-Тор с пониманием относится к ошибкам во время трансформации, но появление на улицах города волкокитов, мур-эльфов, плавучих воргенов, летающих слизней, грифо-гиппо-виверн, киражских зайцев и печально известных синих желеобразных кубов плохо отражается на нашей репутации.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #3: Превращения следует осуществлять в специально отведенных для этого местах. Не выставляйте напоказ чудовищные поганища, возникшие в результате неудачных превращений. Кирин-Тор с пониманием относится к ошибкам во время трансформации, но появление на улицах города волкокитов, мур-эльфов, плавучих воргенов, летающих слизней, грифо-гиппо-виверн, киражских зайцев и печально известных синих желеобразных кубов плохо отражается на нашей репутации.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3458,'Правило #4: Не превращайте слабых существ в более могущественных. Хотя это кажется очевидным, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 8761-e, "Маг Джон Квинт: сожжен больным оленем, превращенным в ожесточенного оплавленного великана."') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #4: Не превращайте слабых существ в более могущественных. Хотя это кажется очевидным, мы вынуждены порекомендовать вам к прочтению параграф из "Реестра происшествий средней тяжести" под номером 8761-e, "Маг Джон Квинт: сожжен больным оленем, превращенным в ожесточенного оплавленного великана."',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3459,'Правило #5: Не превращайте существо, проходящее через портал – это может привести к взрыву. Подробнее об этом читайте в брошюре "Перемещение с помощью телепортации: памятка по использованию порталов".') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #5: Не превращайте существо, проходящее через портал – это может привести к взрыву. Подробнее об этом читайте в брошюре "Перемещение с помощью телепортации: памятка по использованию порталов".',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3460,'Правило #6: Не превращайте недвижимые объекты! Хотя мы с трудом можем поверить своим глазам, но результат подобного эксперимента рекомендуется к прочтению в новом выпуске "Реестра тяжких происшествий" под номером 1-a, "Пол-царства за коня или сто одна причина, почему не следует превращать государство в лошадь". \r\n<В инструкции еще несколько сотен страниц.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Правило #6: Не превращайте недвижимые объекты! Хотя мы с трудом можем поверить своим глазам, но результат подобного эксперимента рекомендуется к прочтению в новом выпуске "Реестра тяжких происшествий" под номером 1-a, "Пол-царства за коня или сто одна причина, почему не следует превращать государство в лошадь". \r\n<В инструкции еще несколько сотен страниц.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3477,'<Эта листовка была наклеена совсем недавно. Следы клея на камне свидетельствуют о том, что раньше здесь были развешаны другие обращения.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<Эта листовка была наклеена совсем недавно. Следы клея на камне свидетельствуют о том, что раньше здесь были развешаны другие обращения.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3478,'Слушайте меня!\r\n\r\nМагия – это не то, чему вас учили. Исходящая от нее опасность гораздо выше, чем польза! Но у вас еще есть шанс спастись! Познайте пути природы, придите в равновесие с окружающим миром, пока у вас еще есть такая возможность.\r\n\r\n<Эту листовку украшает какая-то неизвестная печать.>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Слушайте меня!\r\n\r\nМагия – это не то, чему вас учили. Исходящая от нее опасность гораздо выше, чем польза! Но у вас еще есть шанс спастись! Познайте пути природы, придите в равновесие с окружающим миром, пока у вас еще есть такая возможность.\r\n\r\n<Эту листовку украшает какая-то неизвестная печать.>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3482,'Милая Реанна!\r\n\r\nКаждая секунда, проведенная вдали от тебя, кажется вечностью. Знала бы ты, как мне хочется вновь ощутить прикосновение твоей ласковой, мохнатой руки.\r\n\r\nДаже если звезды упадут с небес – я не стану их подбирать, ибо давно уже ослеплен сиянием твоих глаз.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Милая Реанна!\r\n\r\nКаждая секунда, проведенная вдали от тебя, кажется вечностью. Знала бы ты, как мне хочется вновь ощутить прикосновение твоей ласковой, мохнатой руки.\r\n\r\nДаже если звезды упадут с небес – я не стану их подбирать, ибо давно уже ослеплен сиянием твоих глаз.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3483,'Милая Реанна!\r\n\r\nЛуна все убывает, и я с трудом могу дождаться новолуния, что укроет нас от всего мира под покровом темноты.\r\n\r\nЯ живу и дышу лишь надеждой на новую встречу с тобой.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Милая Реанна!\r\n\r\nЛуна все убывает, и я с трудом могу дождаться новолуния, что укроет нас от всего мира под покровом темноты.\r\n\r\nЯ живу и дышу лишь надеждой на новую встречу с тобой.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3484,'Милая Реанна!\r\n\r\nВот и настал долгожданный вечер, но только холодный ветер сопровождает меня в этот печальный час. Безмолвные ветви деревьев склонились над рощей, где некогда мы провели столько упоительных часов, и их жесткие листья хлещут меня по лицу, будто наказывая за глупость.\r\n\r\nЯ умираю от желания снова увидеть тебя...') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Милая Реанна!\r\n\r\nВот и настал долгожданный вечер, но только холодный ветер сопровождает меня в этот печальный час. Безмолвные ветви деревьев склонились над рощей, где некогда мы провели столько упоительных часов, и их жесткие листья хлещут меня по лицу, будто наказывая за глупость.\r\n\r\nЯ умираю от желания снова увидеть тебя...',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3485,'Милая Реанна!\r\n\r\nПредставь себе мое удивление, когда почтальон отказался передавать тебе мое письмо! Должно быть, это какая-то ошибка! Я просматриваю копии всех моих предыдущих посланий, но не вижу в них ничего такого, что могло оскорбить твои чувства. Знай же, что я сам доставлю тебе это письмо, раз уж этот проклятый дурак убежден в том, что любовь всей моей жизни не желает больше ничего обо мне слышать!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Милая Реанна!\r\n\r\nПредставь себе мое удивление, когда почтальон отказался передавать тебе мое письмо! Должно быть, это какая-то ошибка! Я просматриваю копии всех моих предыдущих посланий, но не вижу в них ничего такого, что могло оскорбить твои чувства. Знай же, что я сам доставлю тебе это письмо, раз уж этот проклятый дурак убежден в том, что любовь всей моей жизни не желает больше ничего обо мне слышать!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3486,'Уважаемый господин!\r\n\r\nСпешу уведомить вас о том, что леди Реанна высказала свое категорическое нежелание в дальнейшем получать от вас корреспонденцию. Таким образом вам рекомендуется воздержаться от написания писем по ее адресу.\r\n\r\nМиледи также просила вам передать, что инцидент с вашим неожиданным превращением был, безусловно, забавным, но она не желает повторения ничего подобного.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Уважаемый господин!\r\n\r\nСпешу уведомить вас о том, что леди Реанна высказала свое категорическое нежелание в дальнейшем получать от вас корреспонденцию. Таким образом вам рекомендуется воздержаться от написания писем по ее адресу.\r\n\r\nМиледи также просила вам передать, что инцидент с вашим неожиданным превращением был, безусловно, забавным, но она не желает повторения ничего подобного.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3487,'Гид по ресторанам Даларана\r\nВскоре после того, как Инзи открыл свой ресторан "Благодарность за отвагу", в городе воцарились тишина и покой. Местные и приезжие выстраиваются в очередь, чтобы забыть о распрях и ссорах за кружечкой пива и ломтем свежеиспеченного хлеба. Этот ресторан славится низкими ценами, изобилием свободных мест и разнообразием спиртных напитков со всего мира. В такой атмосфере нетрудно представить себя утомленным подвигами героем! Что бы вы ни заказали – оставьте в желудке место для медового карибу!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Гид по ресторанам Даларана\r\nВскоре после того, как Инзи открыл свой ресторан "Благодарность за отвагу", в городе воцарились тишина и покой. Местные и приезжие выстраиваются в очередь, чтобы забыть о распрях и ссорах за кружечкой пива и ломтем свежеиспеченного хлеба. Этот ресторан славится низкими ценами, изобилием свободных мест и разнообразием спиртных напитков со всего мира. В такой атмосфере нетрудно представить себя утомленным подвигами героем! Что бы вы ни заказали – оставьте в желудке место для медового карибу!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3488,'Если же вы желаете отобедать в менее популярном и шумном месте, загляните в "Фокус-Покус", расположенный недалеко от центра города. В этом светлом и уютном баре вас ждут легкие закуски в приятной атмосфере, напоминающей библиотеку. В это место частенько наведываются студенты магической школы, поэтому коронное блюдо сего заведения появляется само по себе и готовится прямо у вас на глазах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Если же вы желаете отобедать в менее популярном и шумном месте, загляните в "Фокус-Покус", расположенный недалеко от центра города. В этом светлом и уютном баре вас ждут легкие закуски в приятной атмосфере, напоминающей библиотеку. В это место частенько наведываются студенты магической школы, поэтому коронное блюдо сего заведения появляется само по себе и готовится прямо у вас на глазах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3489,'А коли вам хочется просто снять комнату, предварительно угостившись в баре, ищите заведение с вывеской "Грязное животное". Непередаваемая атмосфера самого злачного бара в городе буквально притягивает к себе подозрительных личностей и криминальных элементов. Меню изобилует такими деликатесами, как соленый заплесневевший сыр, а для придания жилого вида комнатам понадобится не меньше дюжины зачарованных метел и несколько дней работы. Истинный рай для ордынцев!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','А коли вам хочется просто снять комнату, предварительно угостившись в баре, ищите заведение с вывеской "Грязное животное". Непередаваемая атмосфера самого злачного бара в городе буквально притягивает к себе подозрительных личностей и криминальных элементов. Меню изобилует такими деликатесами, как соленый заплесневевший сыр, а для придания жилого вида комнатам понадобится не меньше дюжины зачарованных метел и несколько дней работы. Истинный рай для ордынцев!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3507,'Запись 42. Мы продолжаем разработку силовых линий, и результаты нас вполне устраивают. С удивлением обнаружили совпадения в структуре лучей Азерота и Дренора, что, возможно, свидетельствует о сходных направлениях эволюции этих миров.\r\nМой напарник Набериус доложил, что клан Веселого Черепа заключил перемирие с силами Альянса. Лично я оркам не доверяю, так что подобный союз может обернуться как благом, так и бедствием.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 42. Мы продолжаем разработку силовых линий, и результаты нас вполне устраивают. С удивлением обнаружили совпадения в структуре лучей Азерота и Дренора, что, возможно, свидетельствует о сходных направлениях эволюции этих миров.\r\nМой напарник Набериус доложил, что клан Веселого Черепа заключил перемирие с силами Альянса. Лично я оркам не доверяю, так что подобный союз может обернуться как благом, так и бедствием.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3508,'Запись 205. Большая часть войск Альянса вернулась на Азерот. Надеюсь, наш подробный отчет, переданный с генералом Туралионом, благополучно достигнет Даларана.\r\nБеспечно воздвигнутые порталы Нер\'зула рвут Фаралон на части, и его зеленые холмы медленно тонут в Круговерти пустоты. Мне надо найти путь обратно!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 205. Большая часть войск Альянса вернулась на Азерот. Надеюсь, наш подробный отчет, переданный с генералом Туралионом, благополучно достигнет Даларана.\r\nБеспечно воздвигнутые порталы Нер\'зула рвут Фаралон на части, и его зеленые холмы медленно тонут в Круговерти пустоты. Мне надо найти путь обратно!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3509,'Запись 1363. Настал 14 год, и Кирин\'Вар все еще держит оборону. Раз в день мы собираемся на обед, который наколдовывает Люминрат, а волшебный клинок Датрика охраняет деревню от незваных гостей. В разрушении Дренора обнаружились некоторые положительные стороны, ибо последовавшие за этим магические процессы оказались чрезвычайно интересными для изучения!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 1363. Настал 14 год, и Кирин\'Вар все еще держит оборону. Раз в день мы собираемся на обед, который наколдовывает Люминрат, а волшебный клинок Датрика охраняет деревню от незваных гостей. В разрушении Дренора обнаружились некоторые положительные стороны, ибо последовавшие за этим магические процессы оказались чрезвычайно интересными для изучения!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3510,'Запись 1969. \r\n<Эта поспешно накарябанная заметка разительно отличается от предыдущих записей, сделанных каллиграфическим почерком.>\r\n\r\nНа нас напали! Это солдаты Кель\'таса, их тысячи!!!\r\nЯ вижу летающие корабли, превосходящие по размерам самые большие дирижабли, повсюду чувствуется чужеродная магическая энергия, взрываются мана-бомбы.\r\nЯ успел оградить башню силовым щитом... не знаю, что случилось с остальными...\r\n\r\n<запись обрывается>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 1969. \r\n<Эта поспешно накарябанная заметка разительно отличается от предыдущих записей, сделанных каллиграфическим почерком.>\r\n\r\nНа нас напали! Это солдаты Кель\'таса, их тысячи!!!\r\nЯ вижу летающие корабли, превосходящие по размерам самые большие дирижабли, повсюду чувствуется чужеродная магическая энергия, взрываются мана-бомбы.\r\nЯ успел оградить башню силовым щитом... не знаю, что случилось с остальными...\r\n\r\n<запись обрывается>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3511,'Запись 1970. Войска Келя застали нас врасплох, в результате чего я оказался запертым в башне Кирин\'Вар. Внизу дверь охраняет магический голем, запрограммированный на атаку любого живого существа. Теперь я могу проштудировать все книги башни – но никогда не смогу ее покинуть!\r\nХотя мания Келя не дает мне связаться с Равандиром, я чувствую, что мой ученик все еще жив.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Запись 1970. Войска Келя застали нас врасплох, в результате чего я оказался запертым в башне Кирин\'Вар. Внизу дверь охраняет магический голем, запрограммированный на атаку любого живого существа. Теперь я могу проштудировать все книги башни – но никогда не смогу ее покинуть!\r\nХотя мания Келя не дает мне связаться с Равандиром, я чувствую, что мой ученик все еще жив.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3535,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Верховный лорд!<br /><br />&lt;имя&gt; успешно &lt;возглавил/возглавила&gt; поход против Плети Плетхольма и &lt;подготовил/подготовила&gt; наше войско к наступлению на Ледник Ледяной Короны.<br /><br />Также благодаря &lt;его/ее&gt; участию каменотесы получили необходимые материалы для возведения Крепости Справедливости в Лесу Хрустальной Песни.<br /><br />Нам осталось решить последнюю задачу – захватить Вершину Рыцарей, ибо именно оттуда я желаю начать наш последний поход. <br /><br />Мы ожидаем только вашего приказа.<br /><br />Да защитит вас Свет, сэр.<br /><br />-Густав') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<P>Верховный лорд!<br /><br />&lt;имя&gt; успешно &lt;возглавил/возглавила&gt; поход против Плети Плетхольма и &lt;подготовил/подготовила&gt; наше войско к наступлению на Ледник Ледяной Короны.<br /><br />Также благодаря &lt;его/ее&gt; участию каменотесы получили необходимые материалы для возведения Крепости Справедливости в Лесу Хрустальной Песни.<br /><br />Нам осталось решить последнюю задачу – захватить Вершину Рыцарей, ибо именно оттуда я желаю начать наш последний поход. <br /><br />Мы ожидаем только вашего приказа.<br /><br />Да защитит вас Свет, сэр.<br /><br />-Густав',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3570,'День первый\r\n\r\nПопал на корабль под названием "Ярость Дреки". Мы везем особый груз в далекое место через весь океан. В мои обязанности входит уборка на корабле во время плавания и разведка после высадки на берег.\r\n\r\nЭто лучше, чем разыскивать разбойников и друидов Альянса в Оргриммаре.\r\n\r\nЕда не слишком хороша, но грог неплох. Дуротар уже скрылся за горизонтом.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День первый\r\n\r\nПопал на корабль под названием "Ярость Дреки". Мы везем особый груз в далекое место через весь океан. В мои обязанности входит уборка на корабле во время плавания и разведка после высадки на берег.\r\n\r\nЭто лучше, чем разыскивать разбойников и друидов Альянса в Оргриммаре.\r\n\r\nЕда не слишком хороша, но грог неплох. Дуротар уже скрылся за горизонтом.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3571,'День второй\r\n\r\nПища и корабельная качка не идут мне на пользу!\r\n\r\nУборки полно, так как многим моим братьям все время дурно. По-моему, это не очень хорошая идея, но если потребуется, мы с радостью последуем за ним хоть на дно моря.\r\n\r\nБудем надеяться, что до этого не дойдет.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День второй\r\n\r\nПища и корабельная качка не идут мне на пользу!\r\n\r\nУборки полно, так как многим моим братьям все время дурно. По-моему, это не очень хорошая идея, но если потребуется, мы с радостью последуем за ним хоть на дно моря.\r\n\r\nБудем надеяться, что до этого не дойдет.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3572,'День третий\r\n\r\nВолны бросают корабль в разные стороны. Капитан приказал спустить паруса. Мы словно детская игрушка в руках гигантского малыша.\r\n\r\nЯ не люблю океан, но сегодня сдержал тошноту, как истинный воин.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День третий\r\n\r\nВолны бросают корабль в разные стороны. Капитан приказал спустить паруса. Мы словно детская игрушка в руках гигантского малыша.\r\n\r\nЯ не люблю океан, но сегодня сдержал тошноту, как истинный воин.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3573,'День четвертый:\r\n\r\nНа горизонте видны два маленьких островка. Капитан говорит, что мы пройдем мимо. Он не хочет там останавливаться. Что-то в его голосе мне не нравится. Это очень похоже на страх.\r\n\r\nПришлось повозиться с... что? Снаружи доносятся звуки взрывов. Пойду на верхнюю палубу, посмотрю, в чем там дело.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День четвертый:\r\n\r\nНа горизонте видны два маленьких островка. Капитан говорит, что мы пройдем мимо. Он не хочет там останавливаться. Что-то в его голосе мне не нравится. Это очень похоже на страх.\r\n\r\nПришлось повозиться с... что? Снаружи доносятся звуки взрывов. Пойду на верхнюю палубу, посмотрю, в чем там дело.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3574,'День ??\r\n\r\nМеня выбросило на каменистый берег острова. Это, должно быть, один из тех двух островов, что я видел раньше. Большинство моих братьев мертвы. От нашего особого груза не осталось и следа. Я опасаюсь худшего и не хочу ни о чем думать.\r\n\r\nНе знаю, сколько дней прошло. Один, возможно, два? Вряд ли больше. Трусы из Альянса напали на нас из засады, спрятавшись за большим из двух островов. Их было слишком много, но один корабль мы потопили.\r\n\r\nЯ видел, как еще одно судно попало в зону битвы и разлетелось на куски. Думаю, это были гоблины. Дураки!') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День ??\r\n\r\nМеня выбросило на каменистый берег острова. Это, должно быть, один из тех двух островов, что я видел раньше. Большинство моих братьев мертвы. От нашего особого груза не осталось и следа. Я опасаюсь худшего и не хочу ни о чем думать.\r\n\r\nНе знаю, сколько дней прошло. Один, возможно, два? Вряд ли больше. Трусы из Альянса напали на нас из засады, спрятавшись за большим из двух островов. Их было слишком много, но один корабль мы потопили.\r\n\r\nЯ видел, как еще одно судно попало в зону битвы и разлетелось на куски. Думаю, это были гоблины. Дураки!',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3575,'День ?? и еще один\r\n\r\nМы разбили подобие лагеря на возвышении острова. Аггра хочет, чтобы я поискал других выживших на западном берегу. Килаг с небольшим отрядом пойдет на другую сторону острова, чтобы разыскать Альянс. Кое-кто из них уже атаковал нас. Они не успокоятся, пока мы их всех не перебьем. Или они нас.\r\n\r\nВдалеке слышны звуки, издаваемые гоблинами, и я вижу остов их разбитого корабля. Шумные ребята. За ними понаблюдаю позже. Я нашел пещеру, из которой раздаются звуки горных работ. Похоже, там есть и животные.\r\n\r\nПойду проверю.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','День ?? и еще один\r\n\r\nМы разбили подобие лагеря на возвышении острова. Аггра хочет, чтобы я поискал других выживших на западном берегу. Килаг с небольшим отрядом пойдет на другую сторону острова, чтобы разыскать Альянс. Кое-кто из них уже атаковал нас. Они не успокоятся, пока мы их всех не перебьем. Или они нас.\r\n\r\nВдалеке слышны звуки, издаваемые гоблинами, и я вижу остов их разбитого корабля. Шумные ребята. За ними понаблюдаю позже. Я нашел пещеру, из которой раздаются звуки горных работ. Похоже, там есть и животные.\r\n\r\nПойду проверю.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3605,'Памяти тех, кто пал от оружия Плети в войне на ледяных пустошах.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Памяти тех, кто пал от оружия Плети в войне на ледяных пустошах.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3611,'Куда отправитесь вы, когда пламя поглотит Азерот?$B$BНикому не хочется думать о грядущем судном часе, и все же о будущем следует позаботиться заранее.$B$BНаши волхвы предвидят, что конец этого мира близок, и спасутся только те, кто успеет подготовиться. Мы поможем вам пройти сквозь бушующий огонь преисподней, который очистит мир от зла. Вы согласны снова обрести душевный покой?') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Куда отправитесь вы, когда пламя поглотит Азерот?$B$BНикому не хочется думать о грядущем судном часе, и все же о будущем следует позаботиться заранее.$B$BНаши волхвы предвидят, что конец этого мира близок, и спасутся только те, кто успеет подготовиться. Мы поможем вам пройти сквозь бушующий огонь преисподней, который очистит мир от зла. Вы согласны снова обрести душевный покой?',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3612,'Вам, конечно, приходилось слышать выражение "Все хорошее когда-нибудь обязательно заканчивается". Скоро вы лично сможете удостовериться в его правдивости... Близится тот час, когда весь Азерот погрузится в пучину хаоса и первородные силы вырвутся на поверхность.$B$BНо вы не должны страшиться грядущих кошмаров, ведь есть надежда на спасение. Мы поможем вам на пути к новой жизни: без потерь, без страха и бессилия, которое присуще всем смертным. Приходите сегодня.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Вам, конечно, приходилось слышать выражение "Все хорошее когда-нибудь обязательно заканчивается". Скоро вы лично сможете удостовериться в его правдивости... Близится тот час, когда весь Азерот погрузится в пучину хаоса и первородные силы вырвутся на поверхность.$B$BНо вы не должны страшиться грядущих кошмаров, ведь есть надежда на спасение. Мы поможем вам на пути к новой жизни: без потерь, без страха и бессилия, которое присуще всем смертным. Приходите сегодня.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3613,'Мы живем в неспокойные времена. Войны, агрессия и голод захлестнули мир. Однако настоящее испытание еще впереди: гибель Азерота!$B$BКак пережить потерю всего, что вам дорого?! Выход кроется в том, что вам, возможно, и не придется страдать. Приходите на одно из наших собраний вместе с семьей и друзьями – и вы узнаете, как с нашей помощью можно пережить апокалипсис вместе.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Мы живем в неспокойные времена. Войны, агрессия и голод захлестнули мир. Однако настоящее испытание еще впереди: гибель Азерота!$B$BКак пережить потерю всего, что вам дорого?! Выход кроется в том, что вам, возможно, и не придется страдать. Приходите на одно из наших собраний вместе с семьей и друзьями – и вы узнаете, как с нашей помощью можно пережить апокалипсис вместе.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3622,'Обворожительная девушка перешла озеро и, помахивая хвостом, плывущей походкой направилась к мужчине, отдыхающему на берегу. При ее появлении он поднялся, его лицо озарилось светом счастья. Голубые руки скользнули по его плечам, а гладкий хвост недвусмысленно обвился вокруг пояса. "Объяснишь, ради чего мне пришлось искать тебя... " В ее речи слышался резкий, но вместе с тем очаровательный акцент.$b$bШироко улыбаясь, он мягко отстранил ее от себя, откровенно любуясь ее чертами в лучах солнца.$b$b"...в этой глуши?" – закончила она гневно, но при этом лукавые огоньки заиграли в ее глазах.$b$bОбезоруживающе пожав плечами, он потянулся к сумке и достал оттуда небольшой мешочек. "Моя прекрасная Соола, я хочу подарить тебе одну вещь," – его слова прозвучали твердо и уверенно.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Обворожительная девушка перешла озеро и, помахивая хвостом, плывущей походкой направилась к мужчине, отдыхающему на берегу. При ее появлении он поднялся, его лицо озарилось светом счастья. Голубые руки скользнули по его плечам, а гладкий хвост недвусмысленно обвился вокруг пояса. "Объяснишь, ради чего мне пришлось искать тебя... " В ее речи слышался резкий, но вместе с тем очаровательный акцент.$b$bШироко улыбаясь, он мягко отстранил ее от себя, откровенно любуясь ее чертами в лучах солнца.$b$b"...в этой глуши?" – закончила она гневно, но при этом лукавые огоньки заиграли в ее глазах.$b$bОбезоруживающе пожав плечами, он потянулся к сумке и достал оттуда небольшой мешочек. "Моя прекрасная Соола, я хочу подарить тебе одну вещь," – его слова прозвучали твердо и уверенно.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3626,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Королева Азшара</H1>\r\n<BR/>\r\n<BR/>\r\n<P>Да будет эта статуя свидетельством нашей бесконечной преданности почтенной королеве Азшаре.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Королева Азшара</H1>\r\n<BR/>\r\n<BR/>\r\n<P>Да будет эта статуя свидетельством нашей бесконечной преданности почтенной королеве Азшаре.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3627,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Великий следопыт Валериан</H1>\r\n<BR/>\r\n<BR/>\r\n<P>В память о прославленном герое Вайш\'ира, великом следопыте Валериане. В своем служении он подарил красоту и спокойствие улицам нашего изысканного города. И он же пожертвовал жизнью, чтобы надолго избавить свой народ от страха и обеспечить ему жизнь без войны. О его подвигах будут помнить вечно.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Великий следопыт Валериан</H1>\r\n<BR/>\r\n<BR/>\r\n<P>В память о прославленном герое Вайш\'ира, великом следопыте Валериане. В своем служении он подарил красоту и спокойствие улицам нашего изысканного города. И он же пожертвовал жизнью, чтобы надолго избавить свой народ от страха и обеспечить ему жизнь без войны. О его подвигах будут помнить вечно.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3628,'<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Лестария Вайш</H1>\r\n<BR/>\r\n<BR/>\r\n<P>Этот памятник возведен в честь нашей возлюбленной – матриарха Лестарии Вайш. В течение сотни лет она вела жителей своего великолепного города Вайш\'ир к эпохе вечного процветания. Пусть же она и ее дочь, сиятельная леди Вайш, освещают путь нашему народу и в грядущие столетия.</P>\r\n</BODY>\r\n</HTML>') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','<HTML>\r\n<BODY>\r\n<BR/>\r\n<H1 align="center">Лестария Вайш</H1>\r\n<BR/>\r\n<BR/>\r\n<P>Этот памятник возведен в честь нашей возлюбленной – матриарха Лестарии Вайш. В течение сотни лет она вела жителей своего великолепного города Вайш\'ир к эпохе вечного процветания. Пусть же она и ее дочь, сиятельная леди Вайш, освещают путь нашему народу и в грядущие столетия.</P>\r\n</BODY>\r\n</HTML>',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3706,'Долина Североземья – опасное место, и навыки выживания, свойственные охотнику, здесь весьма пригодятся. Нечего и говорить о том, что твои успехи в деле защиты долины впечатлили меня, и я с нетерпением жду встречи. Прошу, разыщи меня у входа в аббатство.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Долина Североземья – опасное место, и навыки выживания, свойственные охотнику, здесь весьма пригодятся. Нечего и говорить о том, что твои успехи в деле защиты долины впечатлили меня, и я с нетерпением жду встречи. Прошу, разыщи меня у входа в аббатство.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (3707,'Ваше Святейшество, Чо\'Галл дал нам новый приказ: мы должны стереть ваш собор с лица земли. Когда от духовного центра Штормграда останется лишь кратер, начнется паника и лишенные иллюзий крестьяне потянутся к нашей истинной религии. Я посылаю вам взрывчатку. Во имя Молота! Во имя Смертокрыла! Во имя великих дней, которые скоро наступят! -Самуэльсон') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Ваше Святейшество, Чо\'Галл дал нам новый приказ: мы должны стереть ваш собор с лица земли. Когда от духовного центра Штормграда останется лишь кратер, начнется паника и лишенные иллюзий крестьяне потянутся к нашей истинной религии. Я посылаю вам взрывчатку. Во имя Молота! Во имя Смертокрыла! Во имя великих дней, которые скоро наступят! -Самуэльсон',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (4605,'Дисциплина – не война, которую можно выиграть. Это битва, которая продолжается всю жизнь. Мастер Фэн$b$bПуть Тушуй – это жизнь, подчиненная принципам. Последователи Тушуй верят, что миром правят моральные принципы, и все в жизни делится на правильное и неправильное.$b$bОни без колебаний пожертвуют чем угодно, даже своими жизнями, ради защиты этих непреложных, с их точки зрения, ценностей.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','Дисциплина – не война, которую можно выиграть. Это битва, которая продолжается всю жизнь. Мастер Фэн$b$bПуть Тушуй – это жизнь, подчиненная принципам. Последователи Тушуй верят, что миром правят моральные принципы, и все в жизни делится на правильное и неправильное.$b$bОни без колебаний пожертвуют чем угодно, даже своими жизнями, ради защиты этих непреложных, с их точки зрения, ценностей.',`Text_loc8`);
INSERT INTO `locales_page_text` (`entry`,`Text_loc8`) VALUES (4610,'"Всегда действуй. Всегда сомневайся. Худшее, что можно сделать во имя общего блага, – это не сделать ничего." Мастер Цзужун$b$bИдущие по пути Хоцзинь превыше всего ценят расчетливые и решительные действия. Они также верят, что моральные ценности и идеалы не абсолютны и зависят от обстоятельств.$b$bМастер Хоцзинь должен обладать гибким умом и не останавливаться ни перед чем для достижения общего блага.') ON DUPLICATE KEY UPDATE `Text_loc8`=IF(`Text_loc8` IS NULL OR `Text_loc8`='','"Всегда действуй. Всегда сомневайся. Худшее, что можно сделать во имя общего блага, – это не сделать ничего." Мастер Цзужун$b$bИдущие по пути Хоцзинь превыше всего ценят расчетливые и решительные действия. Они также верят, что моральные ценности и идеалы не абсолютны и зависят от обстоятельств.$b$bМастер Хоцзинь должен обладать гибким умом и не останавливаться ни перед чем для достижения общего блага.',`Text_loc8`);
